@dataclass
class TransitionEventReaderState:
    """Binary cursor for the run-owned append-only transition stream."""

    byte_offset: int = 0
    last_sequence: int = 0
    run_id: str = ""
    integrity_epoch: int = 0
    integrity_poisoned: bool = False
    consumed_prefix_sha256: str = ""


class StructuredTransitionEventReader:
    """Incrementally read and validate one harness run's JSONL event stream.

    The cursor never consumes an unterminated final line. This lets a later
    poll complete a record written by a still-running game without inventing
    proof from a truncated tail. Valid non-committed events are retained as
    diagnostics/context, but the gate evaluator filters them from proof.
    """

    def __init__(self, path: Path, run_id: str, state: Optional[TransitionEventReaderState] = None) -> None:
        self.path = Path(path)
        self.run_id = str(run_id).strip()
        if not self.run_id:
            raise ValueError("structured transition reader requires a run_id")
        self.state = state or TransitionEventReaderState(run_id=self.run_id)
        if self.state.run_id and self.state.run_id != self.run_id:
            raise ValueError("structured transition reader state run_id mismatch")
        self.state.run_id = self.run_id
        self.events: List[Dict[str, Any]] = []
        self.diagnostics: List[Dict[str, Any]] = []

    def watermark(self) -> Dict[str, Any]:
        return {
            "byte_offset": int(self.state.byte_offset),
            "last_sequence": int(self.state.last_sequence),
            "run_id": self.run_id,
            "event_count": len(self.events),
            "integrity_epoch": int(self.state.integrity_epoch),
            "integrity_poisoned": bool(self.state.integrity_poisoned),
            "consumed_prefix_sha256": self.state.consumed_prefix_sha256,
        }

    def poll(self) -> Dict[str, Any]:
        start_offset = int(self.state.byte_offset)
        result = {"events": [], "diagnostics": [], "watermark": self.watermark()}
        try:
            size = self.path.stat().st_size
        except FileNotFoundError:
            result["diagnostics"].append({"kind": "stream_missing", "path": str(self.path)})
            self.diagnostics.extend(result["diagnostics"])
            return result
        except OSError as exc:
            result["diagnostics"].append({"kind": "stream_read_error", "path": str(self.path), "error": str(exc)})
            self.diagnostics.extend(result["diagnostics"])
            return result
        if size < start_offset:
            self.state.integrity_epoch += 1
            self.state.integrity_poisoned = True
            self.events.clear()
            result["diagnostics"].append({
                "kind": "stream_truncated_or_replaced", "byte_offset": start_offset,
                "byte_start": 0, "byte_end": max(start_offset, size), "current_size": size,
                "integrity_epoch": self.state.integrity_epoch, "integrity_poisoned": True,
            })
            result["discard_prior_events"] = True
            self.state.byte_offset = 0
            self.state.last_sequence = 0
            self.state.consumed_prefix_sha256 = ""
            start_offset = 0
        consumed_prefix = b""
        try:
            with self.path.open("rb") as stream:
                if start_offset > 0:
                    consumed_prefix = stream.read(start_offset)
                    observed_prefix_sha256 = hashlib.sha256(consumed_prefix).hexdigest()
                    if (
                        len(consumed_prefix) != start_offset or
                        not self.state.consumed_prefix_sha256 or
                        observed_prefix_sha256 != self.state.consumed_prefix_sha256
                    ):
                        self.state.integrity_epoch += 1
                        self.state.integrity_poisoned = True
                        self.events.clear()
                        result["diagnostics"].append({
                            "kind": "stream_truncated_or_replaced",
                            "replacement_reason": "consumed_prefix_mismatch",
                            "byte_offset": start_offset, "byte_start": 0,
                            "byte_end": start_offset, "current_size": size,
                            "expected_prefix_sha256": self.state.consumed_prefix_sha256,
                            "observed_prefix_sha256": observed_prefix_sha256,
                            "integrity_epoch": self.state.integrity_epoch,
                            "integrity_poisoned": True,
                        })
                        result["discard_prior_events"] = True
                        self.state.byte_offset = 0
                        self.state.last_sequence = 0
                        self.state.consumed_prefix_sha256 = ""
                        start_offset = 0
                        consumed_prefix = b""
                stream.seek(start_offset)
                payload = stream.read()
        except OSError as exc:
            result["diagnostics"].append({"kind": "stream_read_error", "path": str(self.path), "error": str(exc)})
            self.diagnostics.extend(result["diagnostics"])
            return result
        complete_length = payload.rfind(b"\n") + 1
        if complete_length <= 0:
            if payload:
                result["diagnostics"].append({
                    "kind": "truncated_tail", "byte_offset": start_offset, "byte_length": len(payload),
                })
            self.diagnostics.extend(result["diagnostics"])
            result["watermark"] = self.watermark()
            return result
        complete = payload[:complete_length]
        if complete_length < len(payload):
            result["diagnostics"].append({
                "kind": "truncated_tail", "byte_offset": start_offset + complete_length,
                "byte_length": len(payload) - complete_length,
            })
        for raw_line in complete.splitlines(keepends=True):
            line_start = start_offset
            start_offset += len(raw_line)
            line = raw_line.rstrip(b"\r\n")
            if not line.strip():
                continue
            try:
                event = json.loads(line.decode("utf-8"))
            except (UnicodeDecodeError, json.JSONDecodeError) as exc:
                result["diagnostics"].append({
                    "kind": "malformed_record", "byte_start": line_start,
                    "byte_end": start_offset, "error": str(exc),
                })
                continue
            validation = self._validate_event(event, line_start, start_offset)
            if validation is not None:
                result["diagnostics"].append(validation)
                continue
            event["_stream_byte_start"] = line_start
            event["_stream_byte_end"] = start_offset
            self.state.last_sequence = int(event["sequence"])
            self.events.append(event)
            result["events"].append(event)
        self.state.byte_offset = start_offset
        prefix_hasher = hashlib.sha256()
        prefix_hasher.update(consumed_prefix)
        prefix_hasher.update(complete)
        self.state.consumed_prefix_sha256 = prefix_hasher.hexdigest()
        self.diagnostics.extend(result["diagnostics"])
        result["watermark"] = self.watermark()
        return result

    def _validate_event(self, event: Any, byte_start: int, byte_end: int) -> Optional[Dict[str, Any]]:
        if not isinstance(event, dict):
            return {"kind": "malformed_record", "byte_start": byte_start, "byte_end": byte_end, "error": "record is not an object"}
        missing = sorted(TRANSITION_EVENT_REQUIRED_FIELDS - set(event))
        if missing:
            return {"kind": "invalid_record", "byte_start": byte_start, "byte_end": byte_end, "error": "missing_fields", "fields": missing}
        if event.get("schema_version") != TRANSITION_EVENT_SCHEMA_VERSION:
            return {"kind": "invalid_record", "byte_start": byte_start, "byte_end": byte_end, "error": "schema_version", "observed": event.get("schema_version")}
        sequence = event.get("sequence")
        expected_sequence = self.state.last_sequence + 1
        if isinstance(sequence, bool) or not isinstance(sequence, int) or sequence != expected_sequence:
            return {"kind": "invalid_sequence", "byte_start": byte_start, "byte_end": byte_end, "sequence": sequence, "last_sequence": self.state.last_sequence, "expected_sequence": expected_sequence}
        if event.get("run_id") != self.run_id:
            return {"kind": "run_correlation_mismatch", "byte_start": byte_start, "byte_end": byte_end, "sequence": sequence, "run_id": event.get("run_id"), "expected_run_id": self.run_id}
        if isinstance(event.get("game_minutes"), bool) or not isinstance(event.get("game_minutes"), (int, float)):
            return {"kind": "invalid_record", "byte_start": byte_start, "byte_end": byte_end, "error": "game_minutes"}
        for key in ("domain", "transition", "outcome"):
            if not isinstance(event.get(key), str) or not event[key].strip():
                return {"kind": "invalid_record", "byte_start": byte_start, "byte_end": byte_end, "error": key}
        if "actor_ids" in event:
            actor_ids = event["actor_ids"]
            if (not isinstance(actor_ids, list) or not actor_ids or any(
                    isinstance(item, bool) or
                    (not isinstance(item, (int, str))) or
                    (isinstance(item, str) and not item.strip())
                    for item in actor_ids)):
                return {"kind": "invalid_record", "byte_start": byte_start, "byte_end": byte_end, "error": "actor_ids"}
        return None


def read_transition_event_stream(path: Path, run_id: str, state: Optional[TransitionEventReaderState] = None) -> Dict[str, Any]:
    """One-shot convenience API used by focused tests and small integrations."""
    reader = StructuredTransitionEventReader(path, run_id, state)
    return reader.poll()


def _transition_event_value(event: Mapping[str, Any], key: str) -> Any:
    if key == "owner":
        # ``domain`` identifies a stream, not the layer allowed to advance it.
        # Never manufacture an authoritative owner from that unrelated field.
        return event.get("simulation_owner", event.get("owner"))
    if key == "committed":
        return str(event.get("outcome", "")).strip().lower() == "committed"
    return event.get(key)


def _structured_event_matches(event: Mapping[str, Any], predicate: Mapping[str, Any]) -> bool:
    if str(event.get("outcome", "")).strip().lower() != "committed":
        return False
    for key, expected in predicate.items():
        if key in {"identity_fields", "continuity_fields"}:
            if not isinstance(expected, list) or any(
                    field not in event or event.get(field) in (None, "", [], {})
                    for field in expected):
                return False
            continue
        if key == "committed":
            if bool(expected) is not True:
                return False
            continue
        observed = _transition_event_value(event, key)
        if key == "actor_ids" and isinstance(expected, list):
            if observed != expected:
                return False
        elif observed != expected:
            return False
    return True


def audit_structured_transition_event(
    events: Sequence[Mapping[str, Any]], *, run_id: str,
    predicate: Mapping[str, Any], require_exactly_one: bool = False,
) -> Dict[str, Any]:
    """Fail closed unless this run contains the declared committed receipt."""
    matches = [
        dict(event) for event in events
        if event.get("run_id") == run_id and _structured_event_matches(event, predicate)
    ]
    matches.sort(key=lambda event: int(event.get("sequence", 0) or 0))
    count_is_valid = not require_exactly_one or len(matches) == 1
    return {
        "status": "required_state_present" if matches and count_is_valid else "required_state_missing",
        "run_id": run_id,
        "predicate": dict(predicate),
        "require_exactly_one": require_exactly_one,
        "match_count": len(matches),
        "matching_events": matches,
        "missing_required_items": ([] if matches and count_is_valid else [
            "one same-run committed structured transition matching the declared predicate"
        ]),
    }


def classify_structural_member_physical_return_pair(
    events: Sequence[Mapping[str, Any]], *, run_id: str, binding_id: str,
    predicate: Mapping[str, Any],
) -> Dict[str, Any]:
    """Aggregate the two native physical-return receipts into one pair boundary.

    Production records one receipt per returning actor.  The harness may only
    call that a pair boundary when the two receipts are complete, ordered, and
    share the run, bound stream, operation identity, generation, minute, and
    terminal ownership progression.  It deliberately does not accept the
    retired atomic ``local_pair_dematerialization`` spelling.
    """
    required_ids = predicate.get("actor_ids", [])
    expected_owners = predicate.get("owner_progression", [])
    expected_epochs = predicate.get("handoff_epoch_progression", [])
    expected_binding = str(predicate.get("binding_id", binding_id) or "").strip()
    expected_fields = {
        key: predicate.get(key)
        for key in ("domain", "transition", "outcome", "previous_state", "new_state",
                    "site_id", "operation_id", "generation")
        if key in predicate
    }
    failures: List[str] = []
    if not isinstance(required_ids, list) or len(required_ids) != 2 or len({str(value) for value in required_ids}) != 2:
        failures.append("invalid_required_pair")
    if not isinstance(expected_owners, list) or len(expected_owners) != len(required_ids):
        failures.append("invalid_owner_progression")
    if not isinstance(expected_epochs, list) or len(expected_epochs) != len(required_ids):
        failures.append("invalid_epoch_progression")
    if not str(run_id or "").strip():
        failures.append("missing_run_binding")
    if not str(binding_id or "").strip() or not expected_binding or binding_id != expected_binding:
        failures.append("wrong_binding")

    candidates: List[Mapping[str, Any]] = []
    for event in events:
        if not isinstance(event, Mapping):
            failures.append("malformed_receipt")
            continue
        event_ids = event.get("actor_ids")
        if str(event.get("transition", "")) != "structural_member_physical_return" or \
                not isinstance(event_ids, list) or len(event_ids) != 1 or \
                event_ids[0] not in required_ids:
            continue
        if event.get("run_id") != run_id:
            failures.append("stale_or_mixed_run")
            continue
        event_binding = str(event.get("_harness_binding_id", binding_id) or "").strip()
        if event_binding != expected_binding:
            failures.append("stale_or_mixed_binding")
            continue
        candidates.append(event)

    by_actor: Dict[Any, List[Mapping[str, Any]]] = {actor_id: [] for actor_id in required_ids} \
        if isinstance(required_ids, list) else {}
    for event in candidates:
        by_actor[event["actor_ids"][0]].append(event)
    if isinstance(required_ids, list) and [
            event["actor_ids"][0] for event in candidates
    ] != required_ids:
        failures.append("unordered_or_mixed_actor_receipts")
    if any(len(receipts) != 1 for receipts in by_actor.values()):
        failures.append("partial_or_duplicate_pair")
    ordered = [by_actor[actor_id][0] for actor_id in required_ids if len(by_actor[actor_id]) == 1]
    if len(ordered) == len(required_ids):
        sequences = [event.get("sequence") for event in ordered]
        if any(isinstance(value, bool) or not isinstance(value, int) for value in sequences) or \
                sequences != sorted(sequences) or len(set(sequences)) != len(sequences):
            failures.append("unordered_or_duplicate_receipt_sequence")
        minutes = [event.get("game_minutes") for event in ordered]
        if any(isinstance(value, bool) or not isinstance(value, (int, float)) for value in minutes) or \
                len(set(minutes)) != 1:
            failures.append("mixed_return_minute")
        for event in ordered:
            for key, expected in expected_fields.items():
                if _transition_event_value(event, key) != expected:
                    failures.append("mixed_or_wrong_" + key)
        if [event.get("simulation_owner") for event in ordered] != expected_owners:
            failures.append("wrong_owner_progression")
        if [event.get("handoff_epoch") for event in ordered] != expected_epochs:
            failures.append("wrong_epoch_progression")
    failures = list(dict.fromkeys(failures))
    references = [
        {"sequence": event.get("sequence"), "byte_start": event.get("_stream_byte_start"),
         "byte_end": event.get("_stream_byte_end"), "actor_id": event["actor_ids"][0]}
        for event in ordered
    ]
    return {
        "status": "matched" if not failures else "unproved",
        "failures": failures,
        "run_id": run_id,
        "binding_id": binding_id,
        "actor_ids": required_ids,
        "event_references": references,
        "terminal_owner": expected_owners[-1] if isinstance(expected_owners, list) and expected_owners else "",
        "terminal_handoff_epoch": expected_epochs[-1] if isinstance(expected_epochs, list) and expected_epochs else None,
    }


def evaluate_causal_boundary(
    proof_gates: Sequence[Mapping[str, Any]],
    *, gate_id: str, events: Sequence[Mapping[str, Any]], run_id: str,
) -> Dict[str, Any]:
    """Find the first committed receipt for one explicitly selected owner boundary.

    This is deliberately narrower than final proof-gate evaluation: it is an
    execution precondition.  A focused row selects one gate whose structured
    predicate names its owner, and the first same-run receipt matching that
    predicate makes another progression action ineligible.
    """
    selected_id = str(gate_id or "").strip()
    if not selected_id:
        return {"status": "not_declared"}
    gate = next((item for item in proof_gates if str(item.get("id", "")).strip() == selected_id), None)
    if not isinstance(gate, Mapping):
        return {"status": "invalid", "reason": "unknown_gate", "gate_id": selected_id}
    predicates = [
        expectation.get("predicate", {})
        for expectation in gate.get("expectations", [])
        if expectation.get("kind") == "structured_event" and isinstance(expectation.get("predicate"), Mapping)
    ]
    owner_predicates = [
        predicate for predicate in predicates
        if "simulation_owner" in predicate or "owner" in predicate
    ]
    if not owner_predicates:
        return {"status": "invalid", "reason": "owner_predicate_required", "gate_id": selected_id}
    matches = [
        event for event in events
        if event.get("run_id") == run_id
        and any(_structured_event_matches(event, predicate) for predicate in owner_predicates)
    ]
    if not matches:
        return {"status": "pending", "gate_id": selected_id}
    first = min(matches, key=lambda event: int(event.get("sequence", 0) or 0))
    return {
        "status": "matched",
        "gate_id": selected_id,
        "boundary_step": str(gate.get("boundary_step", "")),
        "first_matching_event": {
            "sequence": first.get("sequence"),
            "byte_start": first.get("_stream_byte_start"),
            "byte_end": first.get("_stream_byte_end"),
            "run_id": first.get("run_id"),
            "actor_ids": first.get("actor_ids"),
            "simulation_owner": _transition_event_value(first, "owner"),
        },
    }


def _saved_artifact_matches(artifact: Mapping[str, Any], predicate: Mapping[str, Any], run_id: str) -> bool:
    for key, expected in predicate.items():
        if key == "same_run":
            if expected is True and artifact.get("run_id") != run_id:
                return False
            continue
        if key == "committed":
            if expected is True and not (artifact.get("committed") is True or artifact.get("status") == "required_state_present"):
                return False
            continue
        if key in {"continuity_fields", "identity_fields"}:
            identity = artifact.get("identity") if isinstance(artifact.get("identity"), Mapping) else artifact
            if not isinstance(expected, list) or any(
                    field not in identity or identity.get(field) in (None, "", [], {})
                    for field in expected):
                return False
            continue
        if key == "required_fields":
            observed = artifact.get("required_fields")
            if not isinstance(observed, Mapping) or not isinstance(expected, Mapping) or any(
                    observed.get(field) != value for field, value in expected.items()):
                return False
            continue
        if key.startswith("required_field."):
            field = key.split(".", 1)[1]
            observed_fields = artifact.get("required_fields")
            if not isinstance(observed_fields, Mapping) or observed_fields.get(field) != expected:
                return False
            continue
        if key == "artifact_hash_present":
            if bool(expected) and not str(artifact.get("artifact_sha256", "") or "").strip():
                return False
            continue
        if key == "artifact_kind":
            if artifact.get("artifact_kind") != expected:
                return False
            continue
        if artifact.get(key) != expected:
            return False
    return True


def summarize_transition_diagnostics(diagnostics: Sequence[Mapping[str, Any]]) -> List[Dict[str, Any]]:
    """Compact repeated stream diagnostics while retaining first/last evidence."""
    grouped: Dict[str, Dict[str, Any]] = {}
    for diagnostic in diagnostics:
        identity = json.dumps({
            key: diagnostic.get(key)
            for key in ("kind", "error", "sequence", "run_id", "expected_run_id")
            if key in diagnostic
        }, sort_keys=True, ensure_ascii=False)
        row = grouped.setdefault(identity, {
            "identity": json.loads(identity), "count": 0,
            "first": diagnostic, "last": diagnostic,
        })
        row["count"] += 1
        row["last"] = diagnostic
    return list(grouped.values())


def summarize_noncommitted_transition_events(
    events: Sequence[Mapping[str, Any]],
) -> List[Dict[str, Any]]:
    """Aggregate valid semantic non-commit outcomes without duplicating raw JSONL."""
    grouped: Dict[str, Dict[str, Any]] = {}
    semantic_outcomes = {"rejected", "unchanged", "diagnostic"}
    identity_keys = (
        "domain", "transition", "outcome", "site_id", "operation_id", "generation",
        "handoff_epoch", "actor_ids", "previous_state", "new_state", "reason",
    )
    for event in events:
        outcome = str(event.get("outcome", "") or "").strip().lower()
        if outcome not in semantic_outcomes:
            continue
        identity = {
            key: event.get(key)
            for key in identity_keys
            if key in event
        }
        key = json.dumps(identity, sort_keys=True, ensure_ascii=False)
        reference = {
            "sequence": event.get("sequence"),
            "byte_start": event.get("_stream_byte_start"),
            "byte_end": event.get("_stream_byte_end"),
        }
        row = grouped.setdefault(key, {
            "identity": identity,
            "count": 0,
            "first_reference": reference,
            "last_reference": reference,
        })
        row["count"] += 1
        row["last_reference"] = reference
    return list(grouped.values())


def normalize_saved_artifact_receipt(
    metadata: Mapping[str, Any], artifact_kind: str, *,
    producer_step_label: str = "", producer_step_index: int = 0,
) -> Dict[str, Any]:
    """Bind a saved-state audit to its owner, hash, and normalized identity."""
    receipt = dict(metadata)
    receipt["artifact_kind"] = artifact_kind
    receipt["producer_step_label"] = str(producer_step_label)
    receipt["producer_step_index"] = int(producer_step_index)
    dimension_path = Path(str(metadata.get("dimension_path", "") or ""))
    if dimension_path.exists() and dimension_path.is_file():
        try:
            receipt["artifact_sha256"] = path_sha256(dimension_path)
        except OSError:
            receipt["artifact_sha256"] = ""
    matching_sites = metadata.get("matching_sites", [])
    site = matching_sites[0] if isinstance(matching_sites, list) and matching_sites and isinstance(matching_sites[0], Mapping) else {}
    active_outing = site.get("active_outing", {}) if isinstance(site.get("active_outing"), Mapping) else {}
    hostile_operation = site.get("active_hostile_operation", {}) if isinstance(site.get("active_hostile_operation"), Mapping) else {}
    reservation = hostile_operation.get("reservation", {}) if isinstance(hostile_operation.get("reservation"), Mapping) else {}
    report = site.get("current_scout_report", {}) if isinstance(site.get("current_scout_report"), Mapping) else {}
    local_return_eligibility = active_outing.get("local_return_eligibility", {}) \
        if isinstance(active_outing.get("local_return_eligibility"), Mapping) else {}
    schema_v11_outing = active_outing.get("schema_version") == 11
    authoritative_local_return_outing = bool(
        schema_v11_outing
        and active_outing.get("is_active")
        and active_outing.get("kind") == "structural_sortie"
        and active_outing.get("simulation_owner") == "local"
        and isinstance(active_outing.get("handoff_epoch"), int)
        and active_outing["handoff_epoch"] % 2 == 1
        and active_outing.get("exact_pair_with_leader")
        and active_outing.get("pair_contract_valid")
        and local_return_eligibility.get("valid")
    )
    report_present = bool(report.get("present")) or bool(
        report.get("source_activity_id") and report.get("source_generation")
    )
    if authoritative_local_return_outing:
        actor_ids = active_outing.get("member_ids", [])
        operation_id = active_outing.get("activity_id", "")
        generation = active_outing.get("generation", 0)
        identity_source = "schema11_active_outing_local_return"
    elif schema_v11_outing:
        # A schema-11 outing is the authoritative carrier for the local-return
        # receipt.  Do not let an unrelated report or a replacement operation
        # supply an identity when its receipt is stale, partial, or malformed.
        actor_ids = []
        operation_id = ""
        generation = 0
        identity_source = "invalid_schema11_active_outing"
    elif report_present:
        actor_ids = report.get("carrier_ids", [])
        operation_id = report.get("source_activity_id", "")
        generation = report.get("source_generation", 0)
        identity_source = "current_scout_report"
    else:
        actor_ids = active_outing.get("member_ids", [])
        if not isinstance(actor_ids, list) or not actor_ids:
            actor_ids = active_outing.get("local_handoff", {}).get("member_ids", []) \
                if isinstance(active_outing.get("local_handoff"), Mapping) else []
        if not isinstance(actor_ids, list) or not actor_ids:
            actor_ids = reservation.get("member_ids", [])
        operation_id = active_outing.get("activity_id") or reservation.get("activity_id") or ""
        generation = active_outing.get("generation", 0) or reservation.get("generation", 0)
        identity_source = "active_outing" if active_outing.get("activity_id") else "active_hostile_operation"
    receipt["identity"] = {
        "site_id": site.get("site_id", ""),
        "operation_id": operation_id,
        "generation": generation,
        "actor_ids": actor_ids,
        "source": identity_source,
    }
    # Preserve an owner only when the saved producer actually supplied one.
    # An absent owner is meaningful and remains absent for fail-closed callers.
    owner = (active_outing.get("simulation_owner") or active_outing.get("owner") or
             reservation.get("simulation_owner") or reservation.get("owner"))
    if owner not in (None, ""):
        receipt["identity"]["simulation_owner"] = owner
    handoff_epoch = active_outing.get("handoff_epoch") or reservation.get("handoff_epoch")
    if handoff_epoch not in (None, ""):
        receipt["identity"]["handoff_epoch"] = handoff_epoch
    return receipt


def evaluate_structured_proof_gates(
    proof_gates: Sequence[Mapping[str, Any]],
    *,
    events: Sequence[Mapping[str, Any]],
    watermarks: Mapping[str, Mapping[str, Any]],
    saved_artifacts: Optional[Sequence[Mapping[str, Any]]] = None,
    step_reports: Optional[Sequence[Mapping[str, Any]]] = None,
    diagnostics: Optional[Sequence[Mapping[str, Any]]] = None,
    run_id: str = "",
    binding_id: str = "",
) -> Dict[str, Any]:
    """Evaluate v2 predicates only over each gate's predecessor/current range."""
    artifacts = list(saved_artifacts or [])
    for report in step_reports or []:
        metadata = report.get("metadata") if isinstance(report, Mapping) else None
        if isinstance(metadata, Mapping):
            artifact = dict(metadata)
            artifact.setdefault("producer_step_label", str(report.get("label", "")))
            artifact.setdefault("producer_step_index", int(report.get("index", 0) or 0))
            artifact.setdefault("producer_watermark", report.get("structured_event_watermark", {}))
            artifacts.append(artifact)
    by_id = {str(gate.get("id", "")): gate for gate in proof_gates}
    evidence: List[Dict[str, Any]] = []
    # A saved-artifact gate may be observed after a later transition receipt
    # without owning that receipt.  Keep the event cursor separate from the
    # artifact-step cursor so an artifact-only gate cannot consume a future
    # structured owner's handoff simply because its audit ran later.
    initial_watermark: Mapping[str, Any] = {
        "last_sequence": 0, "byte_offset": 0, "run_id": run_id,
    }
    event_boundaries: Dict[str, Mapping[str, Any]] = {}
    artifact_boundaries: Dict[str, Mapping[str, Any]] = {}
    continuity_context: Dict[str, Any] = {}
    integrity_poisoned = any(
        diagnostic.get("kind") == "stream_truncated_or_replaced" or
        bool(diagnostic.get("integrity_poisoned"))
        for diagnostic in diagnostics or []
    )
    all_green = True
    for gate in proof_gates:
        gate_id = str(gate.get("id", "")).strip()
        predecessor_ids = gate.get("predecessors", [])
        if predecessor_ids:
            predecessor = by_id.get(str(predecessor_ids[-1]), {})
            predecessor_id = str(predecessor.get("id", "")).strip()
            predecessor_event_watermark = event_boundaries.get(
                predecessor_id, initial_watermark,
            )
            predecessor_artifact_watermark = artifact_boundaries.get(
                predecessor_id, initial_watermark,
            )
        else:
            predecessor_event_watermark = initial_watermark
            predecessor_artifact_watermark = initial_watermark
        current_boundary = str(gate.get("boundary_step", ""))
        observed_watermark = watermarks.get(current_boundary, {})
        owns_structured_events = any(
            str(expectation.get("kind", "")) in {
                "structured_event", "structural_member_return_pair", "semantic_state",
            }
            for expectation in gate.get("expectations", [])
            if isinstance(expectation, Mapping)
        )
        # Only a gate which declares structured evidence advances the event
        # partition.  This makes sequence ownership monotone and non-overlap
        # explicit, while preserving the declared artifact-step boundary for
        # artifact expectations.
        current_event_watermark = (
            observed_watermark if owns_structured_events else predecessor_event_watermark
        )
        current_artifact_watermark = observed_watermark
        gate_integrity_poisoned = bool(
            integrity_poisoned or predecessor_event_watermark.get("integrity_poisoned") or
            current_event_watermark.get("integrity_poisoned")
        )
        start_sequence = int(predecessor_event_watermark.get("last_sequence", 0) or 0)
        end_sequence = int(current_event_watermark.get("last_sequence", start_sequence) or start_sequence)
        start_offset = int(predecessor_event_watermark.get("byte_offset", 0) or 0)
        end_offset = int(current_event_watermark.get("byte_offset", start_offset) or start_offset)
        start_step_index = int(predecessor_artifact_watermark.get("step_index", 0) or 0)
        end_step_index = int(current_artifact_watermark.get("step_index", 0) or 0)
        in_range = [
            {
                **event,
                "_harness_binding_id": str(event.get("_harness_binding_id", binding_id) or ""),
            }
            for event in events
            if start_sequence < int(event.get("sequence", 0) or 0) <= end_sequence
            and start_offset <= int(event.get("_stream_byte_start", start_offset) or start_offset) < end_offset
            and event.get("run_id") == run_id
        ]
        integrity_kinds = {
            "malformed_record", "invalid_record", "invalid_sequence",
            "run_correlation_mismatch", "truncated_tail", "stream_truncated_or_replaced",
        }
        range_diagnostics = []
        for diagnostic in diagnostics or []:
            if diagnostic.get("kind") not in integrity_kinds:
                continue
            diagnostic_start = int(diagnostic.get("byte_start", diagnostic.get("byte_offset", 0)) or 0)
            diagnostic_end = int(diagnostic.get("byte_end", diagnostic_start) or diagnostic_start)
            overlaps = diagnostic_start < end_offset and diagnostic_end >= start_offset
            pending_tail_at_boundary = diagnostic.get("kind") == "truncated_tail" and diagnostic_start <= end_offset
            if overlaps or pending_tail_at_boundary:
                range_diagnostics.append(diagnostic)
        expectation_results: List[Dict[str, Any]] = []
        for expectation in gate.get("expectations", []):
            kind = str(expectation.get("kind", ""))
            predicate = expectation.get("predicate", {})
            if not isinstance(predicate, Mapping):
                predicate = {}
            if kind == "structured_event":
                matched = [event for event in in_range if _structured_event_matches(event, predicate)]
                refs = [{"sequence": event.get("sequence"), "byte_start": event.get("_stream_byte_start"), "byte_end": event.get("_stream_byte_end")} for event in matched]
                expectation_results.append({"kind": kind, "predicate": dict(predicate), "matched": bool(matched), "event_references": refs, "_matched_events": matched})
            elif kind == "structural_member_return_pair":
                pair = classify_structural_member_physical_return_pair(
                    in_range, run_id=run_id, binding_id=binding_id, predicate=predicate,
                )
                matched = [
                    event for event in in_range
                    if event.get("sequence") in {
                        reference.get("sequence") for reference in pair["event_references"]
                    }
                ]
                expectation_results.append({
                    "kind": kind, "predicate": dict(predicate),
                    "matched": pair["status"] == "matched",
                    "event_references": pair["event_references"],
                    "pair_boundary": pair,
                    "_matched_events": matched,
                })
            elif kind == "semantic_state":
                semantic = decide_event_facts(
                    in_range,
                    run_id=run_id,
                    expected_destination=predicate.get("expected_destination"),
                    activity_id=predicate.get("activity_id"),
                    previous_progress=predicate.get("previous_progress"),
                )
                expected = {
                    key: value for key, value in predicate.items()
                    if key in {"status", "reason", "traveling", "arrived", "activity", "interrupted", "destination"}
                }
                matched = all(semantic.get(key) == value for key, value in expected.items())
                expectation_results.append({"kind": kind, "predicate": dict(predicate), "matched": matched,
                                            "semantic_state": semantic, "_matched_events": in_range if matched else []})
            elif kind == "saved_artifact":
                matched_artifacts = [
                    artifact for artifact in artifacts
                    if start_step_index < int(artifact.get("producer_step_index", 0) or 0) <= end_step_index
                    and _saved_artifact_matches(artifact, predicate, run_id)
                ]
                refs = [{
                    "artifact_path": artifact.get("artifact_path", artifact.get("metadata_path", "")),
                    "run_id": artifact.get("run_id", ""),
                    "producer_step_label": artifact.get("producer_step_label", ""),
                    "producer_step_index": artifact.get("producer_step_index", 0),
                    "producer_watermark": artifact.get("producer_watermark", {}),
                } for artifact in matched_artifacts]
                expectation_results.append({"kind": kind, "predicate": dict(predicate), "matched": bool(matched_artifacts), "artifact_references": refs, "_matched_artifacts": matched_artifacts})
            else:
                expectation_results.append({"kind": kind, "predicate": dict(predicate), "matched": False, "reason": "unsupported_expectation_kind"})
        identity_expectations = [
            result for result in expectation_results
            if result.get("kind") in {
                "structured_event", "structural_member_return_pair", "saved_artifact",
            }
            and isinstance(result.get("predicate"), Mapping)
            and (result["predicate"].get("continuity_fields") or result["predicate"].get("identity_fields"))
        ]
        identity_fields: List[str] = []
        for result in identity_expectations:
            fields = result["predicate"].get("continuity_fields") or result["predicate"].get("identity_fields", [])
            for field in fields:
                if field not in identity_fields:
                    identity_fields.append(str(field))
        identity_values: Dict[str, Any] = {}
        identity_correlation_ok = True
        identity_events = [
            event for result in identity_expectations
            for event in result.get("_matched_events", [])
        ]
        identity_artifacts = [
            artifact for result in identity_expectations
            for artifact in result.get("_matched_artifacts", [])
        ]
        if identity_expectations and not identity_events and not identity_artifacts:
            identity_correlation_ok = False
        for field in identity_fields:
            observed_values = [event.get(field) for event in identity_events]
            for result in identity_expectations:
                for artifact in result.get("_matched_artifacts", []):
                    identity = artifact.get("identity") if isinstance(artifact.get("identity"), Mapping) else artifact
                    if field in identity:
                        observed_values.append(identity.get(field))
            if not observed_values or any(value != observed_values[0] for value in observed_values[1:]):
                identity_correlation_ok = False
            elif observed_values:
                identity_values[field] = observed_values[0]
            if field in continuity_context and observed_values and observed_values[0] != continuity_context[field]:
                identity_correlation_ok = False
        for result in identity_expectations:
            result["identity_correlation"] = {
                "status": "matched" if identity_correlation_ok else "mismatch",
                "fields": identity_fields,
                "values": identity_values,
            }
        gate_green = bool(expectation_results) and all(result.get("matched") for result in expectation_results) and identity_correlation_ok and not range_diagnostics and not gate_integrity_poisoned
        if identity_correlation_ok and identity_values:
            continuity_context.update(identity_values)
        for result in expectation_results:
            result.pop("_matched_events", None)
            result.pop("_matched_artifacts", None)
        all_green = all_green and gate_green
        evidence.append({
            "id": gate_id, "label": str(gate.get("label", "")), "status": "green" if gate_green else "red",
            "boundary_step": current_boundary,
            "predecessor_watermark": dict(predecessor_event_watermark),
            "watermark": dict(current_event_watermark),
            "observed_watermark": dict(observed_watermark),
            "event_range": {"sequence_start_exclusive": start_sequence, "sequence_end_inclusive": end_sequence, "byte_start": start_offset, "byte_end_exclusive": end_offset},
            "artifact_step_range": {
                "step_index_start_exclusive": start_step_index,
                "step_index_end_inclusive": end_step_index,
            },
            "expectations": expectation_results,
            "identity_correlation": {
                "status": "matched" if identity_correlation_ok else ("not_declared" if not identity_expectations else "mismatch"),
                "fields": identity_fields,
                "values": identity_values,
                "continuity_context": dict(continuity_context),
            },
            "diagnostic_count": len(diagnostics or []),
            "integrity_diagnostics": range_diagnostics,
            "integrity_poisoned": gate_integrity_poisoned,
        })
        event_boundaries[gate_id] = current_event_watermark
        artifact_boundaries[gate_id] = current_artifact_watermark
    return {
        "status": "green" if all_green and evidence else "red", "run_id": run_id,
        "binding_id": binding_id,
        "gates": evidence, "diagnostics": list(diagnostics or []),
        "diagnostic_summary": summarize_transition_diagnostics(diagnostics or []),
    }


def build_first_divergence_diagnostic(
    proof_gates: Sequence[Mapping[str, Any]],
    gate_evidence: Sequence[Mapping[str, Any]],
    *,
    events: Sequence[Mapping[str, Any]] = (),
    saved_artifacts: Sequence[Mapping[str, Any]] = (),
    capsule_candidates: Sequence[Mapping[str, Any]] = (),
    binding_id: str = "",
    run_id: str = "",
    repeated_noncommitted_summary: Sequence[Mapping[str, Any]] = (),
) -> Dict[str, Any]:
    """Build a pure, fail-closed first-divergence diagnostic.

    This deliberately consumes the evaluator's gate evidence rather than
    re-evaluating predicates. It recommends a capsule but does not persist or
    select registry history. A malformed causal chain returns only a rejection
    reason and no diagnostic claims.
    """
    gates = list(proof_gates or [])
    evidence = list(gate_evidence or [])
    if not gates or len(gates) != len(evidence):
        return {"status": "rejected", "reason": "gate_evidence_length_mismatch"}
    ids = [str(gate.get("id", "")).strip() for gate in gates]
    if any(not gate_id for gate_id in ids) or len(set(ids)) != len(ids):
        return {"status": "rejected", "reason": "causal_chain_gate_ids_ambiguous"}
    for index, gate in enumerate(gates):
        predecessors = gate.get("predecessors", [])
        if not isinstance(predecessors, list):
            return {"status": "rejected", "reason": "causal_chain_predecessors_not_a_list"}
        expected = [] if index == 0 else [ids[index - 1]]
        if [str(item) for item in predecessors] != expected:
            return {"status": "rejected", "reason": "causal_chain_predecessor_mismatch", "gate_id": ids[index]}
    evidence_ids = [str(row.get("id", "")).strip() for row in evidence]
    if evidence_ids != ids:
        return {"status": "rejected", "reason": "gate_evidence_order_mismatch"}

    red_index = next((index for index, row in enumerate(evidence) if row.get("status") != "green"), None)
    if red_index is None:
        return {"status": "green", "run_id": run_id, "causal_prefix": ids, "last_green": ids[-1]}
    gate = gates[red_index]
    row = evidence[red_index]
    gate_id = ids[red_index]
    expected_predicates = [
        {"kind": str(expectation.get("kind", "")), "predicate": dict(expectation.get("predicate", {}))}
        for expectation in gate.get("expectations", [])
        if isinstance(expectation, Mapping) and isinstance(expectation.get("predicate", {}), Mapping)
    ]
    event_range = row.get("event_range", {}) if isinstance(row.get("event_range"), Mapping) else {}
    start_sequence = int(event_range.get("sequence_start_exclusive", 0) or 0)
    end_sequence = int(event_range.get("sequence_end_inclusive", 0) or 0)
    in_range_events = [event for event in events if start_sequence < int(event.get("sequence", 0) or 0) <= end_sequence]
    committed_events = [event for event in in_range_events if str(event.get("outcome", "")).lower() == "committed"]
    step_range = row.get("artifact_step_range", {}) if isinstance(row.get("artifact_step_range"), Mapping) else {}
    start_step = int(step_range.get("step_index_start_exclusive", 0) or 0)
    end_step = int(step_range.get("step_index_end_inclusive", 0) or 0)
    in_range_artifacts = [artifact for artifact in saved_artifacts
                          if start_step < int(artifact.get("producer_step_index", 0) or 0) <= end_step]

    identity_keys = ("site_id", "operation_id", "generation", "actor_ids", "handoff_epoch", "simulation_owner", "owner")
    expected_identity: Dict[str, Any] = {}
    for item in expected_predicates:
        predicate = item["predicate"]
        for key in identity_keys:
            if key in predicate:
                expected_identity[key] = predicate[key]
    observed_identity: Dict[str, Any] = {}
    competing_observations: List[Dict[str, Any]] = []
    for event in committed_events:
        identity = {key: event.get(key) for key in identity_keys if event.get(key) not in (None, "", [])}
        competing_observations.append({"kind": "structured_event", "sequence": event.get("sequence"), "identity": identity})
        for key, value in identity.items():
            observed_identity.setdefault(key, value)
    for artifact in in_range_artifacts:
        identity = artifact.get("identity") if isinstance(artifact.get("identity"), Mapping) else artifact
        identity = {key: identity.get(key) for key in identity_keys if identity.get(key) not in (None, "", [])}
        competing_observations.append({"kind": "saved_artifact", "path": artifact.get("artifact_path", artifact.get("metadata_path", "")), "identity": identity})
        for key, value in identity.items():
            observed_identity.setdefault(key, value)
    expected_owner = expected_identity.get("simulation_owner", expected_identity.get("owner"))
    observed_owner = observed_identity.get("simulation_owner", observed_identity.get("owner"))
    owner_mismatch = (expected_owner not in (None, "") and observed_owner not in (None, "") and
                      expected_owner != observed_owner)
    # The observed stream is authoritative for the current owner. Never fill a
    # missing observation from the predicate: that would turn a failed gate
    # into a false green diagnostic.
    owner_state = {
        "value": observed_owner if observed_owner not in (None, "") else None,
        "expected": expected_owner if expected_owner not in (None, "") else None,
        "observed": observed_owner if observed_owner not in (None, "") else None,
        "status": "mismatch" if owner_mismatch else ("known" if observed_owner not in (None, "") else "missing_fail_closed"),
    }
    next_probe = f"probe gate {gate_id} ({str(gate.get('label', '')).strip() or gate_id}) with the declared predicates"
    if owner_state["status"] == "missing_fail_closed":
        next_probe += "; capture the authoritative simulation owner"
    return {
        "status": "red", "run_id": run_id, "first_divergence": {
            "gate_id": gate_id, "label": str(gate.get("label", "")), "index": red_index,
            "expected_predicates": expected_predicates,
            "observed_committed_events": committed_events,
            "observed_saved_receipts": in_range_artifacts,
            "closest_competing_observations": competing_observations,
            "expected_identity": expected_identity, "observed_identity": observed_identity,
            "authoritative_simulation_owner": owner_state,
        },
        "causal_prefix": ids[:red_index + 1], "last_green": ids[red_index - 1] if red_index else None,
        "earliest_first_red": {"gate_id": gate_id, "label": str(gate.get("label", "")), "index": red_index},
        "repeated_noncommitted_summary": list(repeated_noncommitted_summary or []),
        # Capsule compatibility/ranking is deliberately owned by G3. G1 only
        # leaves an explicit, non-selected placeholder for the report shape.
        "capsule_recommendation": {"selected": False, "capsule": None,
                                   "reason": "capsule selection deferred to G3"},
        "smallest_next_probe": next_probe,
    }


# Descriptive alias for callers that work in terms of the structured gate route.
build_structured_failure_diagnostic = build_first_divergence_diagnostic


def diagnostic_registry_path(
    registry_launch_receipt: str = "", certification_registry: str = "",
) -> str:
    """Resolve the registry owner for diagnostics from authoritative inputs only."""
    if str(certification_registry or "").strip():
        return str(certification_registry).strip()
    try:
        receipt = json.loads(str(registry_launch_receipt or ""))
    except (TypeError, ValueError, json.JSONDecodeError):
        return ""
    if not isinstance(receipt, Mapping):
        return ""
    path = receipt.get("registry_path")
    return str(path).strip() if isinstance(path, str) and path.strip() else ""


def attach_first_divergence_diagnostic(
    report: Dict[str, Any], *, proof_gates: Sequence[Mapping[str, Any]],
    gate_evidence: Mapping[str, Any], events: Sequence[Mapping[str, Any]] = (),
    saved_artifacts: Sequence[Mapping[str, Any]] = (),
    repeated_noncommitted_summary: Sequence[Mapping[str, Any]] = (),
    registry_path: str = "", capsule_binding: Optional[Mapping[str, Any]] = None,
) -> Dict[str, Any]:
    """Attach causal failure and a read-only historical capsule recommendation."""
    evidence = gate_evidence.get("gates", ()) if isinstance(gate_evidence, Mapping) else ()
    diagnostic = build_first_divergence_diagnostic(
        proof_gates, evidence, events=events, saved_artifacts=saved_artifacts,
        binding_id=str(report.get("binding_id", "")), run_id=str(report.get("run_id", "")),
        repeated_noncommitted_summary=repeated_noncommitted_summary,
    )
    if diagnostic.get("status") != "red":
        report["first_divergence_diagnostic"] = diagnostic
        return diagnostic
    binding = capsule_binding or report.get("capsule_binding") or report.get("diagnostic_capsule_binding")
    if not isinstance(binding, Mapping):
        round_facts = report.get("certification_round")
        if isinstance(round_facts, Mapping):
            binding = round_facts.get("binding")
    if not registry_path or not isinstance(binding, Mapping):
        report["first_divergence_diagnostic"] = diagnostic
        return diagnostic
    divergence = diagnostic.get("first_divergence", {})
    observed_identity = divergence.get("observed_identity", {})
    declared_identity = divergence.get("expected_identity", {})
    # Selection binds to the failed run's declared identity when the failed
    # gate produced no committed observation; the diagnostic itself remains
    # fail-closed about that missing observation.
    identity = {**declared_identity, **observed_identity}
    failed_run = {
        "run_id": report.get("run_id", diagnostic.get("run_id", "")),
        "binding_id": report.get("binding_id", ""), "binding": binding,
        "site_id": identity.get("site_id", binding.get("site_id")),
        "operation": identity.get("operation", identity.get("operation_id", binding.get("operation"))),
        "generation": identity.get("generation", binding.get("generation")),
        "actor_ids": identity.get("actor_ids", binding.get("actor_ids")),
        "owner": identity.get("owner", identity.get("simulation_owner", binding.get("owner"))),
    }
    try:
        connection = open_registry(registry_path, writable=False)
        try:
            selection = select_diagnostic_capsule_candidate(connection, failed_run=failed_run)
        finally:
            connection.close()
    except Exception as exc:
        selection = {"selected_candidate": None, "selection_reason": "selector_rejected: " + str(exc),
                     "compatible_candidates": (), "rejected_candidates": ()}
    diagnostic["capsule_recommendation"] = {
        "selected": selection.get("selected_candidate") is not None,
        "capsule": selection.get("selected_candidate"),
        "reason": selection.get("selection_reason", ""),
        "compatible_candidates": selection.get("compatible_candidates", ()),
        "rejected_candidates": selection.get("rejected_candidates", ()),
    }
    report["first_divergence_diagnostic"] = diagnostic
    return diagnostic


class _WatermarkedReports(list):
    def __init__(self, reader: Optional[StructuredTransitionEventReader], events: Optional[List[Dict[str, Any]]], diagnostics: Optional[List[Dict[str, Any]]]) -> None:
        super().__init__()
        self.reader = reader
        self.events = events if events is not None else []
        self.diagnostics = diagnostics if diagnostics is not None else []

    def append(self, report: Dict[str, Any]) -> None:
        if self.reader is not None:
            polled = self.reader.poll()
            if polled.get("discard_prior_events"):
                self.events.clear()
            observed_during_wait = report.pop("_integrated_wait_new_events", [])
            if isinstance(observed_during_wait, list):
                self.events.extend(observed_during_wait)
            self.events.extend(polled["events"])
            self.diagnostics.extend(polled["diagnostics"])
            watermark = dict(polled["watermark"])
            watermark["step_index"] = int(report.get("index", 0) or 0)
            watermark["step_label"] = str(report.get("label", ""))
            report["structured_event_watermark"] = watermark
        super().append(report)


def repo_root() -> Path:
    return Path(__file__).resolve().parents[2]


def run_json(
    cmd: List[str],
    check: bool = True,
    *,
    timeout_seconds: Optional[float] = None,
) -> Dict[str, Any]:
    try:
        proc = subprocess.run(cmd, capture_output=True, text=True, timeout=timeout_seconds)
    except subprocess.TimeoutExpired as exc:
        if check:
            raise RuntimeError(
                f"command timed out after {timeout_seconds}s: {' '.join(cmd)}\n"
                f"{exc.stdout or ''}\n{exc.stderr or ''}"
            )
        return {
            "ok": False,
            "timeout": True,
            "stdout": exc.stdout or "",
            "stderr": exc.stderr or "",
        }
    if check and proc.returncode != 0:
        raise RuntimeError(f"command failed ({proc.returncode}): {' '.join(cmd)}\n{proc.stdout}\n{proc.stderr}")
    if not proc.stdout.strip():
        return {}
    return json.loads(proc.stdout)


def subprocess_output_text(value: Any) -> str:
    if value is None:
        return ""
    if isinstance(value, bytes):
        return value.decode("utf-8", errors="replace")
    return str(value)


def peekaboo_binary() -> str:
    configured = os.environ.get(PEEKABOO_BINARY_ENV, "").strip()
    return configured or shutil.which("peekaboo") or "peekaboo"


def peekaboo_command(args: Sequence[str], *, channel: str) -> List[str]:
    """Build a Peekaboo command with explicit input/capture transport policy.

    Input and focus default to the local macOS process because routing those
    operations through a GUI bridge can target the wrong host or leave focus
    unproved. Capture defaults to Peekaboo's bridge-aware routing because an
    SSH-launched harness may not own Screen Recording permission while the
    signed bridge host does. Both choices can be overridden without changing
    scenario files.
    """
    if channel not in {"input", "capture"}:
        raise ValueError(f"unsupported Peekaboo channel: {channel}")
    env_name = PEEKABOO_INPUT_TRANSPORT_ENV if channel == "input" else PEEKABOO_CAPTURE_TRANSPORT_ENV
    default_transport = "local" if channel == "input" else "bridge"
    transport = os.environ.get(env_name, default_transport).strip().lower() or default_transport
    if transport not in {"local", "bridge"}:
        raise ValueError(f"{env_name} must be 'local' or 'bridge', got {transport!r}")

    cmd = [peekaboo_binary(), *[str(arg) for arg in args]]
    if transport == "local":
        cmd.append("--no-remote")
    else:
        bridge_socket = os.environ.get(PEEKABOO_BRIDGE_SOCKET_ENV, "").strip()
        if bridge_socket:
            cmd.extend(["--bridge-socket", bridge_socket])
    return cmd


def sanitize_profile_name(name: str) -> str:
    name = name.strip()
    if not name:
        return "default"
    name = name.replace("/", "_").replace("\\", "_")
    name = re.sub(r"[^A-Za-z0-9_.-]+", "_", name)
    return name or "default"


def current_branch() -> str:
    proc = subprocess.run(
        ["git", "-C", str(repo_root()), "branch", "--show-current"],
        capture_output=True,
        text=True,
        check=False,
    )
    branch = proc.stdout.strip()
    return branch or "detached"


def current_head_short() -> str:
    proc = subprocess.run(
        ["git", "-C", str(repo_root()), "rev-parse", "--short=10", "HEAD"],
        capture_output=True,
        text=True,
        check=False,
    )
    return proc.stdout.strip()


def runtime_relevant_changes_since(captured_head: str) -> Tuple[List[str], str]:
    captured = str(captured_head or "").strip()
    if not captured:
        return [], "captured head is empty"

    commit_check = subprocess.run(
        ["git", "-C", str(repo_root()), "cat-file", "-e", f"{captured}^{{commit}}"],
        capture_output=True,
        text=True,
        check=False,
    )
    if commit_check.returncode != 0:
        detail = (commit_check.stderr or commit_check.stdout).strip()
        return [], detail or f"captured head {captured} is not resolvable"

    proc = subprocess.run(
        [
            "git",
            "-C",
            str(repo_root()),
            "diff",
            "--name-only",
            f"{captured}..HEAD",
            "--",
            *RUNTIME_RELEVANT_PATHS,
        ],
        capture_output=True,
        text=True,
        check=False,
    )
    if proc.returncode != 0:
        detail = (proc.stderr or proc.stdout).strip()
        return [], detail or f"git diff failed for {captured}..HEAD"

    changes = [line.strip() for line in proc.stdout.splitlines() if line.strip()]
    return changes, ""


def runtime_relevant_worktree_changes() -> Tuple[List[str], str]:
    commands = [
        [
            "git",
            "-C",
            str(repo_root()),
            "diff",
            "--name-only",
            "HEAD",
            "--",
            *RUNTIME_RELEVANT_PATHS,
        ],
        [
            "git",
            "-C",
            str(repo_root()),
            "ls-files",
            "--others",
            "--exclude-standard",
            "--",
            *RUNTIME_RELEVANT_PATHS,
        ],
    ]
    changes: set[str] = set()
    for cmd in commands:
        proc = subprocess.run(
            cmd,
            capture_output=True,
            text=True,
            check=False,
        )
        if proc.returncode != 0:
            detail = (proc.stderr or proc.stdout).strip()
            return [], detail or "git worktree comparison failed"
        changes.update(line.strip() for line in proc.stdout.splitlines() if line.strip())
    return sorted(changes), ""


def sha256_file(path: Path) -> Tuple[str, str]:
    """Return a file digest, keeping missing/unreadable evidence explicit."""
    digest = hashlib.sha256()
    try:
        with path.open("rb") as stream:
            for chunk in iter(lambda: stream.read(1024 * 1024), b""):
                digest.update(chunk)
    except OSError as exc:
        return "", str(exc)
    return digest.hexdigest(), ""


def runtime_source_binding() -> Dict[str, Any]:
    """Hash the exact runtime diff plus untracked runtime file content.

    The commit shown by the game window proves the committed baseline.  This
    digest binds the dirty portion to the executable launched for this run,
    including untracked files which ``git diff`` does not report.
    """
    root = repo_root()
    diff_proc = subprocess.run(
        ["git", "-C", str(root), "diff", "--binary", "HEAD", "--", *RUNTIME_RELEVANT_PATHS],
        capture_output=True,
        check=False,
    )
    if diff_proc.returncode != 0:
        detail = (diff_proc.stderr or diff_proc.stdout).decode("utf-8", errors="replace").strip()
        return {"ok": False, "error": detail or "git runtime diff failed"}

    untracked_proc = subprocess.run(
        [
            "git", "-C", str(root), "ls-files", "--others", "--exclude-standard", "-z", "--",
            *RUNTIME_RELEVANT_PATHS,
        ],
        capture_output=True,
        check=False,
    )
    if untracked_proc.returncode != 0:
        detail = (untracked_proc.stderr or untracked_proc.stdout).decode("utf-8", errors="replace").strip()
        return {"ok": False, "error": detail or "git untracked runtime listing failed"}

    untracked_paths = [
        entry.decode("utf-8", errors="surrogateescape")
        for entry in untracked_proc.stdout.split(b"\0")
        if entry
    ]
    source = bytearray(b"caol-runtime-source-binding-v1\0")
    source.extend(diff_proc.stdout)
    unreadable: List[str] = []
    for relative in sorted(untracked_paths):
        path = root / relative
        try:
            content = path.read_bytes()
        except OSError as exc:
            unreadable.append(f"{relative}: {exc}")
            continue
        source.extend(relative.encode("utf-8", errors="surrogateescape"))
        source.extend(b"\0")
        source.extend(content)
        source.extend(b"\0")
    if unreadable:
        return {"ok": False, "error": "unreadable untracked runtime file(s): " + "; ".join(unreadable)}

    changes, changes_error = runtime_relevant_worktree_changes()
    if changes_error:
        return {"ok": False, "error": changes_error}
    return {
        "ok": True,
        "sha256": hashlib.sha256(source).hexdigest(),
        "worktree_changes": changes,
        "untracked_paths": untracked_paths,
    }


def _product_binary_path(relative: str) -> bool:
    """Return whether one repository path can change the compiled game binary."""
    normalized = str(relative).replace("\\", "/").strip("/")
    return any(
        normalized == prefix or normalized.startswith(prefix + "/")
        for prefix in PRODUCT_BINARY_RELEVANT_PATHS
    )


def executable_source_readiness(
    executable: Path,
    *,
    isolated_harness_diagnosis: bool = False,
) -> Dict[str, Any]:
    """Cheaply decide whether a binary can support a current-product run.

    The game already exposes its compiled Git baseline through ``--version``.
    This preflight compares that baseline with committed and dirty binary inputs
    before registry authority can be issued.  A deliberately isolated harness
    diagnosis may proceed provisionally, but it cannot claim the playtest
    outcome until a current binary is revalidated.
    """
    executable_path = Path(executable).resolve()
    version_output = ""
    version_error = ""
    try:
        completed = subprocess.run(
            [str(executable_path), "--version"],
            capture_output=True,
            text=True,
            check=False,
        )
        version_output = "\n".join(
            value for value in (completed.stdout, completed.stderr) if value
        )
        if completed.returncode != 0:
            version_error = f"version command exited {completed.returncode}"
    except OSError as exc:
        version_error = str(exc)

    match = re.search(
        r"(?<![0-9a-f])(?P<head>[0-9a-f]{10,40})(?P<dirty>-dirty)?(?:\+[^\s]+)?",
        version_output,
    )
    captured_head = match.group("head") if match else ""
    committed_changes: List[str] = []
    worktree_changes: List[str] = []
    comparison_error = version_error
    if captured_head:
        committed, committed_error = runtime_relevant_changes_since(captured_head)
        dirty, dirty_error = runtime_relevant_worktree_changes()
        committed_changes = [path for path in committed if _product_binary_path(path)]
        worktree_changes = [path for path in dirty if _product_binary_path(path)]
        comparison_error = "; ".join(
            error for error in (committed_error, dirty_error) if error
        )
    elif not comparison_error:
        comparison_error = "compiled source identity is absent from executable --version output"

    ready = bool(
        captured_head and not comparison_error and
        not committed_changes and not worktree_changes
    )
    if ready:
        status = "ready"
        reason = "source_matching_executable"
        next_action = "continue with the current registry query"
        evidence_ceiling = "requested run ceiling"
    elif isolated_harness_diagnosis:
        status = "provisional_diagnosis_allowed"
        reason = "isolated_harness_diagnosis_does_not_depend_on_current_product_code"
        next_action = (
            "run only the isolated harness diagnosis, label its evidence provisional, then "
            "revalidate the playtest outcome with a source-matching executable"
        )
        evidence_ceiling = "provisional harness diagnosis only"
    else:
        status = "build_required"
        reason = "product_binary_source_is_stale_or_unproved"
        next_action = (
            "build or select a source-matching executable, then repeat the same registry query"
        )
        evidence_ceiling = "none until source-matching executable revalidation"
    return {
        "status": status,
        "reason": reason,
        "next_action": next_action,
        "evidence_ceiling": evidence_ceiling,
        "executable_path": str(executable_path),
        "captured_head": captured_head,
        "repository_head": current_head_short(),
        "binary_relevant_committed_changes": committed_changes,
        "binary_relevant_worktree_changes": worktree_changes,
        "comparison_error": comparison_error,
    }


def build_complete_identity_binding(*, worktree: Any, data_config: Any, world_save: Any,
                                    player: Mapping[str, Any],
                                    actors: Sequence[Mapping[str, Any]]) -> Dict[str, Any]:
    """Canonical identity composition for a future complete round manifest.

    Existing runtime/fixture/profile/save/bandit owners feed these arguments;
    this helper intentionally does not infer or replace any of those owners.
    """
    return complete_identity_binding(
        worktree=worktree,
        data_config=data_config,
        world_save=world_save,
        player=player,
        actors=actors,
    )


def build_authoritative_identity_binding(**kwargs: Any) -> Dict[str, Any]:
    """Expose the explicit installed-input producer to future manifest code."""
    return authoritative_identity_binding(**kwargs)


def build_runtime_binding(executable: Path) -> Dict[str, Any]:
    """Capture the immutable run inputs used by the changed executable."""
    executable_path = executable.resolve()
    executable_sha256, executable_error = sha256_file(executable_path)
    if executable_error:
        return {"ok": False, "error": f"executable digest failed: {executable_error}"}
    source = runtime_source_binding()
    if not source.get("ok"):
        return {"ok": False, "error": str(source.get("error", "runtime source digest failed"))}
    return {
        "ok": True,
        "schema": 1,
        "captured_head": current_head_short(),
        "executable_path": str(executable_path),
        "executable_sha256": executable_sha256,
        "runtime_source_sha256": str(source["sha256"]),
        "runtime_relevant_paths": list(RUNTIME_RELEVANT_PATHS),
        "runtime_relevant_worktree_diff": list(source.get("worktree_changes", [])),
        "untracked_runtime_paths": list(source.get("untracked_paths", [])),
    }


def compare_runtime_binding(binding: Any) -> Dict[str, Any]:
    """Recompute every bound input; no missing field is treated as a match."""
    if not isinstance(binding, dict) or binding.get("schema") != 1:
        return {"status": "unproven", "error": "runtime binding schema is missing or unsupported"}
    expected_path = str(binding.get("executable_path", "")).strip()
    expected_executable_sha256 = str(binding.get("executable_sha256", "")).strip().lower()
    expected_source_sha256 = str(binding.get("runtime_source_sha256", "")).strip().lower()
    if not expected_path or not expected_executable_sha256 or not expected_source_sha256:
        return {"status": "unproven", "error": "runtime binding is missing executable/source digest"}

    executable_path = Path(expected_path).resolve()
    executable_sha256, executable_error = sha256_file(executable_path)
    source = runtime_source_binding()
    mismatches: List[str] = []
    if executable_error:
        mismatches.append(f"executable_digest_error:{executable_error}")
    elif executable_sha256.lower() != expected_executable_sha256:
        mismatches.append("executable_sha256")
    if not source.get("ok"):
        mismatches.append(f"runtime_source_digest_error:{source.get('error', 'unknown error')}")
    elif str(source.get("sha256", "")).lower() != expected_source_sha256:
        mismatches.append("runtime_source_sha256")
    return {
        "status": "mismatch" if mismatches else "matched",
        "error": "; ".join(mismatches),
        "executable_path": str(executable_path),
        "executable_sha256": executable_sha256,
        "runtime_source_sha256": str(source.get("sha256", "")),
        "runtime_relevant_worktree_diff": source.get("worktree_changes", []),
    }


def load_runtime_binding(run_dir: Path) -> Optional[Dict[str, Any]]:
    path = run_dir / RUNTIME_BINDING_FILENAME
    if not path.exists():
        return None
    try:
        value = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, UnicodeError, json.JSONDecodeError):
        return {"schema": 0, "error": f"could not read {path}"}
    return value if isinstance(value, dict) else {"schema": 0, "error": f"invalid {path}"}


def validate_registry_launch_receipt_before_launch(
    raw_receipt: Any,
    executable: Path,
) -> Dict[str, Any]:
    """Recheck one selected registry receipt immediately before process launch."""
    if raw_receipt in (None, ""):
        return {"status": "not_required"}
    if not isinstance(raw_receipt, str):
        return {"status": "rejected", "reason": "receipt_not_text"}
    try:
        receipt = json.loads(raw_receipt)
    except json.JSONDecodeError as exc:
        return {"status": "rejected", "reason": "receipt_invalid_json", "error": str(exc)}
    if not isinstance(receipt, dict) or receipt.get("schema") != 1:
        return {"status": "rejected", "reason": "receipt_schema_invalid"}

    registry_path = str(receipt.get("registry_path", "")).strip()
    token_id = str(receipt.get("token_id", "")).strip()
    source_path = str(receipt.get("source_path", "")).strip()
    runtime_binding = receipt.get("runtime_binding")
    if not registry_path or not token_id or not source_path or not isinstance(runtime_binding, dict):
        return {"status": "rejected", "reason": "receipt_fields_missing"}

    from scenario_registry_store import (
        ScenarioRegistryStoreError,
        open_registry,
        record_selection_token_rejection,
        reload_selection_token_for_launch,
    )

    try:
        connection = open_registry(registry_path)
    except (OSError, sqlite3.Error, ScenarioRegistryStoreError) as exc:
        return {"status": "rejected", "reason": "registry_unavailable", "error": str(exc)}
    try:
        if receipt.get("authority_kind") == "registry_bootstrap_first_compatible_run":
            from scenario_registry_store import reload_bootstrap_token_for_launch

            selection = reload_bootstrap_token_for_launch(connection, token_id, require_claimed=True)
            if not selection.accepted:
                return {
                    "status": "rejected",
                    "reason": f"bootstrap_{selection.reason}",
                    "token_id": token_id,
                }
            if selection.source_path != str(Path(source_path).resolve()):
                return {
                    "status": "rejected",
                    "reason": "bootstrap_source_changed",
                    "token_id": token_id,
                }
            expected_executable = str(runtime_binding.get("executable_path", "")).strip()
            if not expected_executable or Path(expected_executable).resolve() != executable.resolve():
                return {
                    "status": "rejected",
                    "reason": "bootstrap_runtime_executable_changed",
                    "token_id": token_id,
                }
            comparison = compare_runtime_binding(runtime_binding)
            if comparison.get("status") != "matched":
                return {
                    "status": "rejected",
                    "reason": "bootstrap_runtime_binding_changed",
                    "token_id": token_id,
                    "comparison": dict(comparison),
                }
            return {
                "status": "compatible",
                "token_id": token_id,
                "source_path": selection.source_path,
                "runtime_binding": comparison,
            }
        if receipt.get("authority_kind") == "registry_repair_exact_contradiction":
            from scenario_registry_store import (
                record_repair_token_rejection,
                reload_repair_token_for_launch,
            )

            selection = reload_repair_token_for_launch(
                connection, token_id, require_claimed=True,
            )
            if not selection.accepted:
                return {
                    "status": "rejected",
                    "reason": f"repair_{selection.reason}",
                    "token_id": token_id,
                }

            def reject_repair(reason: str, **details: Any) -> Dict[str, Any]:
                record_repair_token_rejection(
                    connection,
                    token_id,
                    reason=reason,
                    details=details,
                )
                return {"status": "rejected", "reason": reason, "token_id": token_id}

            issued = connection.execute(
                "SELECT verification_id FROM token_history "
                "WHERE token_id = ? AND event_kind = 'repair_issued' "
                "ORDER BY token_event_id LIMIT 1",
                (token_id,),
            ).fetchone()
            red_verification_id = str(receipt.get("red_verification_id", "")).strip()
            if (
                issued is None
                or not red_verification_id
                or red_verification_id != str(issued["verification_id"])
            ):
                return reject_repair(
                    "receipt_contradiction_changed",
                    receipt_red_verification_id=red_verification_id,
                )

            if selection.source_path != str(Path(source_path).resolve()):
                return reject_repair(
                    "receipt_source_changed",
                    expected_source_path=source_path,
                    current_source_path=selection.source_path,
                )
            expected_executable = str(runtime_binding.get("executable_path", "")).strip()
            if not expected_executable or Path(expected_executable).resolve() != executable.resolve():
                return reject_repair(
                    "runtime_executable_changed",
                    expected_executable=expected_executable,
                    current_executable=str(executable.resolve()),
                )
            comparison = compare_runtime_binding(runtime_binding)
            if comparison.get("status") != "matched":
                return reject_repair(
                    "runtime_binding_changed",
                    comparison=dict(comparison),
                )
            return {
                "status": "compatible",
                "token_id": token_id,
                "red_verification_id": red_verification_id,
                "source_path": selection.source_path,
                "runtime_binding": comparison,
            }
        selection = reload_selection_token_for_launch(connection, token_id)
        if not selection.accepted:
            return {
                "status": "rejected",
                "reason": f"token_{selection.reason}",
                "token_id": token_id,
            }

        def reject(reason: str, **details: Any) -> Dict[str, Any]:
            record_selection_token_rejection(
                connection,
                token_id,
                reason=reason,
                details=details,
            )
            return {"status": "rejected", "reason": reason, "token_id": token_id}

        if selection.source_path != str(Path(source_path).resolve()):
            return reject(
                "receipt_source_changed",
                expected_source_path=source_path,
                current_source_path=selection.source_path,
            )
        expected_executable = str(runtime_binding.get("executable_path", "")).strip()
        if not expected_executable or Path(expected_executable).resolve() != executable.resolve():
            return reject(
                "runtime_executable_changed",
                expected_executable=expected_executable,
                current_executable=str(executable.resolve()),
            )
        comparison = compare_runtime_binding(runtime_binding)
        if comparison.get("status") != "matched":
            return reject(
                "runtime_binding_changed",
                comparison=dict(comparison),
            )
        return {
            "status": "compatible",
            "token_id": token_id,
            "source_path": selection.source_path,
            "runtime_binding": comparison,
        }
    finally:
        connection.close()


def resolve_profile_name(explicit: str) -> str:
    return sanitize_profile_name(explicit or current_branch())


def userdir_for_profile(profile: str) -> Path:
    return repo_root() / ".userdata" / profile


def save_dir_for_profile(profile: str) -> Path:
    return userdir_for_profile(profile) / "save"


def config_dir_for_profile(profile: str) -> Path:
    return userdir_for_profile(profile) / "config"


def fixtures_root() -> Path:
    return repo_root() / "tools" / "openclaw_harness" / "fixtures" / "saves"


def profile_snapshots_root() -> Path:
    return repo_root() / "tools" / "openclaw_harness" / "fixtures" / "profiles"


def scenarios_root() -> Path:
    return repo_root() / "tools" / "openclaw_harness" / "scenarios"


def profile_config_path(profile: str) -> Path:
    return repo_root() / "tools" / "openclaw_harness" / "profiles" / f"{profile}.json"


def load_profile_config(profile: str) -> Dict[str, Any]:
    defaults: Dict[str, Any] = {
        "profile_name": profile,
        "startup": {
            "play_now_default_sequence": ["n", "d"],
            "debug_popup_ignore_text": "i",
            "initial_wait_seconds": 2.5,
            "post_input_wait_seconds": 1.0,
            "poll_seconds": 2.0,
            "timeout_seconds": 90.0,
            "max_popup_dismissals": 6,
            "post_lastworld_wait_seconds": 0.0,
            "post_lastworld_continue_keys": [],
        },
    }

    merged = dict(defaults)
    merged_startup = dict(defaults["startup"])
    candidate_paths = [profile_config_path("master")]
    if profile != "master":
        candidate_paths.append(profile_config_path(profile))

    for path in candidate_paths:
        if not path.exists():
            continue
        loaded = json.loads(path.read_text(encoding="utf-8"))
        if not isinstance(loaded, dict):
            raise SystemExit(f"Invalid profile config: {path}")
        merged_startup.update(loaded.get("startup", {}))
        merged.update(loaded)

    merged["profile_name"] = profile
    merged["startup"] = merged_startup
    return merged


def resolve_startup_config_profile(scenario: Dict[str, Any], target_profile: str) -> str:
    configured_profile = str(scenario.get("config_profile", "")).strip()
    scenario_profile = str(scenario.get("profile", "")).strip()
    return resolve_profile_name(configured_profile or scenario_profile or target_profile)


def world_save_marker_paths(world_dir: Path) -> List[Path]:
    markers: List[Path] = list(world_dir.glob("*.sav*"))
    for character_dir in sorted(world_dir.glob("*.mm1"), key=lambda p: p.name.lower()):
        if not character_dir.is_dir():
            continue
        payloads = sorted(character_dir.glob("*.zzip"), key=lambda p: p.name.lower())
        markers.extend(payloads if payloads else [character_dir])
    return sorted(markers, key=lambda p: str(p.relative_to(world_dir)).lower())


def world_save_marker_names(world_dir: Path) -> List[str]:
    marker_names = []
    for marker in world_save_marker_paths(world_dir):
        try:
            marker_names.append(str(marker.relative_to(world_dir)))
        except ValueError:
            marker_names.append(marker.name)
    return marker_names


def list_worlds(profile: str) -> List[WorldInfo]:
    save_dir = save_dir_for_profile(profile)
    if not save_dir.exists():
        return []
    worlds: List[WorldInfo] = []
    for path in sorted([p for p in save_dir.iterdir() if p.is_dir()], key=lambda p: p.name.lower()):
        save_files = sorted([p.name for p in path.glob("*.sav*")])
        save_markers = world_save_marker_names(path)
        worlds.append(
            WorldInfo(
                name=path.name,
                path=path,
                has_save=bool(save_markers),
                save_files=save_files,
                save_markers=save_markers,
            )
        )
    return worlds


def read_lastworld(profile: str) -> Dict[str, str]:
    path = config_dir_for_profile(profile) / "lastworld.json"
    if not path.exists():
        return {}
    try:
        data = json.loads(path.read_text(encoding="utf-8"))
    except Exception:
        return {}
    if not isinstance(data, dict):
        return {}
    return {
        "world_name": str(data.get("world_name", "")).strip(),
        "character_name": str(data.get("character_name", "")).strip(),
    }


def load_game_options(profile: str) -> Dict[str, str]:
    path = config_dir_for_profile(profile) / "options.json"
    if not path.exists():
        return {}
    try:
        data = json.loads(path.read_text(encoding="utf-8"))
    except Exception:
        return {}
    if not isinstance(data, list):
        return {}

    options: Dict[str, str] = {}
    for entry in data:
        if not isinstance(entry, dict):
            continue
        name = str(entry.get("name", "")).strip()
        if not name:
            continue
        options[name] = str(entry.get("value", "")).strip()
    return options


def normalize_profile_option_overrides(raw_overrides: Any) -> Dict[str, str]:
    if raw_overrides in (None, {}):
        return {}
    if not isinstance(raw_overrides, dict):
        raise ValueError("profile_option_overrides must be a JSON object")
    overrides: Dict[str, str] = {}
    for raw_name, raw_value in raw_overrides.items():
        name = str(raw_name).strip()
        if not name:
            raise ValueError("profile_option_overrides contains an empty option name")
        overrides[name] = str(raw_value)
    return overrides


def current_harness_platform_key() -> str:
    if os.name == "nt":
        return "windows"
    if sys.platform == "darwin":
        return "macos"
    return "linux"


def resolve_scenario_profile_option_overrides(
    scenario: Dict[str, Any], platform_key: str = ""
) -> Dict[str, str]:
    overrides = normalize_profile_option_overrides(
        scenario.get("profile_option_overrides", {})
    )
    raw_platform_overrides = scenario.get("profile_option_overrides_by_platform", {})
    if raw_platform_overrides in (None, {}):
        return overrides
    if not isinstance(raw_platform_overrides, dict):
        raise ValueError("profile_option_overrides_by_platform must be a JSON object")

    supported_platforms = {"windows", "macos", "linux"}
    unknown_platforms = sorted(set(raw_platform_overrides) - supported_platforms)
    if unknown_platforms:
        raise ValueError(
            "profile_option_overrides_by_platform contains unsupported platform(s): "
            + ", ".join(unknown_platforms)
        )
    selected_platform = platform_key or current_harness_platform_key()
    selected_overrides = normalize_profile_option_overrides(
        raw_platform_overrides.get(selected_platform, {})
    )
    overrides.update(selected_overrides)
    return overrides


def parse_profile_option_args(raw_options: Sequence[str]) -> Dict[str, str]:
    overrides: Dict[str, str] = {}
    for raw_option in raw_options:
        if "=" not in raw_option:
            raise ValueError(f"Profile option override must use NAME=VALUE: {raw_option}")
        raw_name, value = raw_option.split("=", 1)
        name = raw_name.strip()
        if not name:
            raise ValueError(f"Profile option override has an empty name: {raw_option}")
        overrides[name] = value
    return overrides


def apply_option_overrides_to_file(path: Path, overrides: Dict[str, str]) -> Dict[str, Any]:
    normalized = normalize_profile_option_overrides(overrides)
    if not normalized:
        return {"path": str(path), "applied": {}}
    if not path.is_file():
        raise FileNotFoundError(f"Profile options file not found: {path}")
    data = json.loads(path.read_text(encoding="utf-8"))
    if not isinstance(data, list):
        raise ValueError(f"Profile options file must contain a JSON list: {path}")

    applied: Dict[str, str] = {}
    for entry in data:
        if not isinstance(entry, dict):
            continue
        name = str(entry.get("name", "")).strip()
        if name in normalized:
            entry["value"] = normalized[name]
            applied[name] = normalized[name]
    missing = sorted(set(normalized) - set(applied))
    if missing:
        raise ValueError(f"Profile option(s) not found in {path}: {', '.join(missing)}")
    path.write_text(json.dumps(data, indent=2, ensure_ascii=False) + "\n", encoding="utf-8")
    return {"path": str(path), "applied": applied}


def apply_profile_option_overrides(profile: str, overrides: Dict[str, str]) -> Dict[str, Any]:
    return apply_option_overrides_to_file(config_dir_for_profile(profile) / "options.json", overrides)


def resolve_configured_python_command(
    raw_value: str,
    *,
    allow_command_lookup: bool = True,
) -> Tuple[List[str], str]:
    raw = str(raw_value).strip()
    if not raw:
        return [], ""

    is_windows_absolute = re.match(r"^[A-Za-z]:[\\\\/]", raw) is not None
    is_posix_absolute = raw.startswith("/")
    if (os.name == "nt" and is_posix_absolute) or (
        os.name != "nt" and is_windows_absolute
    ):
        return [], ""

    expanded = os.path.expanduser(raw)
    macos_only_roots = (
        "/Applications",
        "/Library",
        "/System",
        "/Users",
        "/Volumes",
    )
    linux_only_roots = (
        "/home",
        "/snap",
    )
    if sys.platform.startswith("linux") and any(
        expanded == root or expanded.startswith(root + "/") for root in macos_only_roots
    ):
        return [], ""
    if sys.platform == "darwin" and any(
        expanded == root or expanded.startswith(root + "/") for root in linux_only_roots
    ):
        return [], ""

    candidates: List[str] = []
    if os.path.isdir(expanded):
        if os.name == "nt":
            candidates = [os.path.join(expanded, "Scripts", "python.exe")]
        else:
            candidates = [
                os.path.join(expanded, "bin", "python3"),
                os.path.join(expanded, "bin", "python"),
            ]
    elif os.path.isfile(expanded):
        candidates = [expanded]

    for candidate in candidates:
        is_executable = os.name == "nt" or os.access(candidate, os.X_OK)
        if os.path.isfile(candidate) and is_executable:
            return [candidate], candidate

    is_path_like = is_windows_absolute or is_posix_absolute or "/" in raw or "\\" in raw
    if is_path_like:
        return [], ""

    if not allow_command_lookup:
        return [], ""
    resolved_command = shutil.which(raw)
    if resolved_command:
        return [resolved_command], resolved_command
    return [], ""


def llm_credential_target(env_name: str) -> str:
    return f"Cataclysm-AOL/LLM/{env_name}"


def read_windows_llm_credential(env_name: str) -> str:
    """Read one generic Windows credential without exposing it to stdout."""

    import ctypes
    from ctypes import wintypes

    class Credential(ctypes.Structure):
        _fields_ = [
            ("Flags", wintypes.DWORD),
            ("Type", wintypes.DWORD),
            ("TargetName", wintypes.LPWSTR),
            ("Comment", wintypes.LPWSTR),
            ("LastWritten", wintypes.FILETIME),
            ("CredentialBlobSize", wintypes.DWORD),
            ("CredentialBlob", ctypes.POINTER(ctypes.c_ubyte)),
            ("Persist", wintypes.DWORD),
            ("AttributeCount", wintypes.DWORD),
            ("Attributes", ctypes.c_void_p),
            ("TargetAlias", wintypes.LPWSTR),
            ("UserName", wintypes.LPWSTR),
        ]

    credential_pointer = ctypes.POINTER(Credential)()
    advapi32 = ctypes.WinDLL("Advapi32.dll")
    advapi32.CredReadW.argtypes = [
        wintypes.LPCWSTR,
        wintypes.DWORD,
        wintypes.DWORD,
        ctypes.POINTER(ctypes.POINTER(Credential)),
    ]
    advapi32.CredReadW.restype = wintypes.BOOL
    advapi32.CredFree.argtypes = [ctypes.c_void_p]
    advapi32.CredFree.restype = None

    if not advapi32.CredReadW(
        llm_credential_target(env_name), 1, 0, ctypes.byref(credential_pointer)
    ):
        return ""
    try:
        credential = credential_pointer.contents
        if credential.CredentialBlobSize <= 0 or not credential.CredentialBlob:
            return ""
        raw = ctypes.string_at(credential.CredentialBlob, credential.CredentialBlobSize)
        return raw.decode("utf-16-le")
    finally:
        advapi32.CredFree(credential_pointer)


def write_windows_llm_credential(env_name: str, secret: str) -> None:
    """Persist one API key in Windows Credential Manager."""

    import ctypes
    from ctypes import wintypes

    class Credential(ctypes.Structure):
        _fields_ = [
            ("Flags", wintypes.DWORD),
            ("Type", wintypes.DWORD),
            ("TargetName", wintypes.LPWSTR),
            ("Comment", wintypes.LPWSTR),
            ("LastWritten", wintypes.FILETIME),
            ("CredentialBlobSize", wintypes.DWORD),
            ("CredentialBlob", ctypes.POINTER(ctypes.c_ubyte)),
            ("Persist", wintypes.DWORD),
            ("AttributeCount", wintypes.DWORD),
            ("Attributes", ctypes.c_void_p),
            ("TargetAlias", wintypes.LPWSTR),
            ("UserName", wintypes.LPWSTR),
        ]

    raw = secret.encode("utf-16-le")
    blob = ctypes.create_string_buffer(raw)
    credential = Credential()
    credential.Type = 1
    credential.TargetName = llm_credential_target(env_name)
    credential.CredentialBlobSize = len(raw)
    credential.CredentialBlob = ctypes.cast(blob, ctypes.POINTER(ctypes.c_ubyte))
    credential.Persist = 2
    credential.UserName = env_name

    advapi32 = ctypes.WinDLL("Advapi32.dll", use_last_error=True)
    advapi32.CredWriteW.argtypes = [ctypes.POINTER(Credential), wintypes.DWORD]
    advapi32.CredWriteW.restype = wintypes.BOOL
    if not advapi32.CredWriteW(ctypes.byref(credential), 0):
        raise OSError(ctypes.get_last_error(), "CredWriteW failed")


def write_macos_llm_credential(env_name: str, secret: str) -> None:
    """Persist one API key through Security.framework without a secret-bearing argv."""

    import ctypes

    err_sec_success = 0
    err_sec_item_not_found = -25300
    security = ctypes.CDLL(
        "/System/Library/Frameworks/Security.framework/Security"
    )
    core_foundation = ctypes.CDLL(
        "/System/Library/Frameworks/CoreFoundation.framework/CoreFoundation"
    )

    security.SecKeychainFindGenericPassword.argtypes = [
        ctypes.c_void_p,
        ctypes.c_uint32,
        ctypes.c_char_p,
        ctypes.c_uint32,
        ctypes.c_char_p,
        ctypes.POINTER(ctypes.c_uint32),
        ctypes.POINTER(ctypes.c_void_p),
        ctypes.POINTER(ctypes.c_void_p),
    ]
    security.SecKeychainFindGenericPassword.restype = ctypes.c_int32
    security.SecKeychainAddGenericPassword.argtypes = [
        ctypes.c_void_p,
        ctypes.c_uint32,
        ctypes.c_char_p,
        ctypes.c_uint32,
        ctypes.c_char_p,
        ctypes.c_uint32,
        ctypes.c_void_p,
        ctypes.POINTER(ctypes.c_void_p),
    ]
    security.SecKeychainAddGenericPassword.restype = ctypes.c_int32
    security.SecKeychainItemModifyAttributesAndData.argtypes = [
        ctypes.c_void_p,
        ctypes.c_void_p,
        ctypes.c_uint32,
        ctypes.c_void_p,
    ]
    security.SecKeychainItemModifyAttributesAndData.restype = ctypes.c_int32
    core_foundation.CFRelease.argtypes = [ctypes.c_void_p]
    core_foundation.CFRelease.restype = None

    service = LLM_API_KEYCHAIN_SERVICE.encode("utf-8")
    account = env_name.encode("utf-8")
    secret_bytes = secret.encode("utf-8")
    secret_buffer = ctypes.create_string_buffer(secret_bytes)
    secret_pointer = ctypes.cast(secret_buffer, ctypes.c_void_p)
    item_ref = ctypes.c_void_p()

    find_status = security.SecKeychainFindGenericPassword(
        None,
        len(service),
        service,
        len(account),
        account,
        None,
        None,
        ctypes.byref(item_ref),
    )
    if find_status == err_sec_success:
        try:
            write_status = security.SecKeychainItemModifyAttributesAndData(
                item_ref,
                None,
                len(secret_bytes),
                secret_pointer,
            )
        finally:
            if item_ref:
                core_foundation.CFRelease(item_ref)
    elif find_status == err_sec_item_not_found:
        write_status = security.SecKeychainAddGenericPassword(
            None,
            len(service),
            service,
            len(account),
            account,
            len(secret_bytes),
            secret_pointer,
            None,
        )
    else:
        raise OSError(find_status, "SecKeychainFindGenericPassword failed")

    if write_status != err_sec_success:
        raise OSError(write_status, "macOS Keychain write failed")


def read_secure_llm_credential(env_name: str) -> Tuple[str, str]:
    if os.name == "nt":
        try:
            return read_windows_llm_credential(env_name), "windows_credential_manager"
        except (OSError, UnicodeError):
            return "", "windows_credential_manager"
    if sys.platform == "darwin":
        try:
            result = subprocess.run(
                [
                    "/usr/bin/security",
                    "find-generic-password",
                    "-a",
                    env_name,
                    "-s",
                    LLM_API_KEYCHAIN_SERVICE,
                    "-w",
                ],
                capture_output=True,
                text=True,
                check=False,
                timeout=LLM_KEYCHAIN_TIMEOUT_SECONDS,
            )
        except subprocess.TimeoutExpired:
            return "", "macos_keychain_timeout"
        if result.returncode == 0:
            return result.stdout.rstrip("\r\n"), "macos_keychain"
        return "", "macos_keychain"
    return "", "unsupported_secure_store"


def store_secure_llm_credential(env_name: str, secret: str) -> str:
    if not env_name or not re.fullmatch(r"[A-Za-z_][A-Za-z0-9_]*", env_name):
        raise ValueError("Credential env name must be a valid environment-variable name.")
    if not secret:
        raise ValueError("Credential secret is empty.")
    if os.name == "nt":
        write_windows_llm_credential(env_name, secret)
        return "windows_credential_manager"
    if sys.platform == "darwin":
        try:
            write_macos_llm_credential(env_name, secret)
        except (OSError, UnicodeError) as error:
            status = error.errno if isinstance(error, OSError) else None
            suffix = f" (OSStatus {status})" if status is not None else ""
            raise RuntimeError(f"macOS Keychain write failed{suffix}") from None
        return "macos_keychain"
    raise RuntimeError("No supported secure credential store is available on this platform.")


def llm_api_mode_enabled(options: Dict[str, str]) -> bool:
    backend = options.get("LLM_INTENT_BACKEND", "").strip().lower()
    use_api = options.get("LLM_INTENT_USE_API", "").strip().lower() == "true"
    enabled = options.get("LLM_INTENT_ENABLE", "").strip().lower() == "true"
    return enabled and (backend == "api" or use_api)


def provision_llm_api_key_environment(
    options: Dict[str, str],
) -> Tuple[Dict[str, str], Dict[str, str]]:
    """Resolve the configured key into a game-child environment overlay.

    The secret is absent from the diagnostic packet and the harness process
    environment is never mutated.
    """

    if not llm_api_mode_enabled(options):
        return {"status": "not_required", "source": "", "env_var": ""}, {}
    env_name = options.get("LLM_INTENT_API_KEY_ENV", "").strip()
    if not env_name:
        return {"status": "missing_env_name", "source": "", "env_var": ""}, {}
    configured_secret = os.environ.get(env_name, "")
    if configured_secret:
        return {
            "status": "ready",
            "source": "configured_environment",
            "env_var": env_name,
        }, {env_name: configured_secret}

    provider = options.get("LLM_INTENT_API_PROVIDER", "").strip().lower() or "openai"
    if provider == "openai":
        for fallback_env in LLM_API_KEY_FALLBACK_ENVS:
            fallback_secret = os.environ.get(fallback_env, "")
            if fallback_secret:
                return {
                    "status": "ready",
                    "source": f"environment:{fallback_env}",
                    "env_var": env_name,
                }, {env_name: fallback_secret}

    secret, source = read_secure_llm_credential(env_name)
    if secret:
        return {
            "status": "ready",
            "source": source,
            "env_var": env_name,
        }, {env_name: secret}
    return {"status": "missing", "source": source, "env_var": env_name}, {}


def run_store_llm_credential(args: argparse.Namespace) -> int:
    env_name = str(args.env_name or "").strip()
    source_env = str(args.from_env or "").strip()
    if args.stdin:
        secret = sys.stdin.read().rstrip("\r\n")
        source = "stdin"
    else:
        secret = os.environ.get(source_env, "")
        source = f"environment:{source_env}"
    if not secret:
        raise SystemExit(f"No API key was available from {source}.")
    store = store_secure_llm_credential(env_name, secret)
    print(json.dumps({
        "ok": True,
        "env_var": env_name,
        "source": source,
        "store": store,
        "secret_logged": False,
    }, indent=2))
    return 0


def resolve_game_runtime_python(options: Dict[str, str]) -> Tuple[List[str], str, str]:
    configured_value = options.get("LLM_INTENT_PYTHON", "").strip()
    if configured_value:
        configured_cmd, configured_label = resolve_configured_python_command(
            configured_value,
            allow_command_lookup=False,
        )
        if configured_cmd:
            return configured_cmd, configured_label, "configured_option"
        return [], configured_value, "configured_option_invalid"

    backend = options.get("LLM_INTENT_BACKEND", "").strip().lower()
    if backend == "api" and sys.platform == "darwin":
        fallback_cmd, fallback_label = resolve_configured_python_command("/Users/josefhorvath/ollama/api_env311")
        if fallback_cmd:
            return fallback_cmd, fallback_label, "api_fallback_venv"

    if backend in {"api", "ollama"}:
        if os.name == "nt":
            return [], "python", f"{backend}_platform_default_invalid"
        platform_default = "/usr/bin/python3"
        platform_cmd, platform_label = resolve_configured_python_command(platform_default)
        if platform_cmd:
            return platform_cmd, platform_label, f"{backend}_platform_default"
        return [], "", f"{backend}_platform_default"

    return [], "", "configured_option"


def probe_runtime_blockers(profile: str, artifact_source: str) -> List[Dict[str, str]]:
    normalized_source = str(artifact_source).strip().lower()
    llm_event_sources = {"llm_events", "llm_intent_events", "llm_intent_events.log"}
    if normalized_source not in {"llm", "llm_intent", "llm_intent.log"} | llm_event_sources:
        return []

    options = load_game_options(profile)
    blockers: List[Dict[str, str]] = []

    if options.get("LLM_INTENT_ENABLE", "").lower() != "true":
        blockers.append({
            "code": "llm_intent_disabled",
            "message": "LLM intent is disabled in profile options.",
            "option": "LLM_INTENT_ENABLE",
        })
    if normalized_source not in llm_event_sources and options.get("DEBUG_LLM_INTENT_LOG", "").lower() != "true":
        blockers.append({
            "code": "llm_intent_log_disabled",
            "message": "LLM intent log capture is disabled in profile options.",
            "option": "DEBUG_LLM_INTENT_LOG",
        })

    python_cmd, python_label, python_source = resolve_game_runtime_python(options)
    if not python_cmd:
        configured_invalid = python_source == "configured_option_invalid"
        blockers.append({
            "code": "llm_python_configured_invalid" if configured_invalid else "llm_python_missing",
            "message": (
                f"Configured LLM runner Python path does not resolve: {python_label}"
                if configured_invalid
                else "LLM runner Python path is empty and no runtime fallback resolved."
            ),
            "option": "LLM_INTENT_PYTHON",
            "python": python_label,
            "python_source": python_source,
        })
    elif llm_api_mode_enabled(options):
        try:
            import_check = subprocess.run(
                python_cmd + ["-c", "import any_llm"],
                capture_output=True,
                text=True,
                check=False,
            )
            detail_text = (import_check.stderr or import_check.stdout).strip()
            detail = detail_text.splitlines()[0] if detail_text else "import any_llm failed"
        except OSError as error:
            import_check = None
            detail = str(error)
        if import_check is None or import_check.returncode != 0:
            blockers.append({
                "code": "llm_python_missing_any_llm",
                "message": f"Resolved LLM runner Python cannot import any_llm ({detail}).",
                "option": "LLM_INTENT_PYTHON",
                "python": python_label,
                "python_source": python_source,
            })

    return blockers


def probe_runtime_warnings(profile: str, artifact_source: str) -> List[Dict[str, str]]:
    normalized_source = str(artifact_source).strip().lower()
    if normalized_source not in {
        "llm", "llm_intent", "llm_intent.log",
        "llm_events", "llm_intent_events", "llm_intent_events.log",
    }:
        return []

    options = load_game_options(profile)
    warnings: List[Dict[str, str]] = []
    python_cmd, python_label, python_source = resolve_game_runtime_python(options)

    if llm_api_mode_enabled(options) and options.get("LLM_INTENT_PYTHON", "").strip() == "" and python_cmd:
        warnings.append({
            "code": "llm_python_option_empty_using_runtime_fallback",
            "message": f"LLM_INTENT_PYTHON is empty; the runtime will fall back to {python_label} ({python_source}).",
            "option": "LLM_INTENT_PYTHON",
            "python": python_label,
            "python_source": python_source,
        })

    if llm_api_mode_enabled(options):
        provision, _ = provision_llm_api_key_environment(options)
        api_key_env = provision["env_var"]
        if provision["status"] == "missing_env_name":
            warnings.append({
                "code": "llm_api_key_env_missing",
                "message": "API backend is selected, but no API key env-var name is configured; prompt logging may still work, but responses will fail.",
                "option": "LLM_INTENT_API_KEY_ENV",
            })
        elif provision["status"] == "missing":
            warnings.append({
                "code": "llm_api_key_env_unset",
                "message": f"API backend is selected, but no credential for '{api_key_env}' is available to the game child; responses will fail.",
                "option": "LLM_INTENT_API_KEY_ENV",
                "env_var": api_key_env,
            })

    return warnings


def pick_target_world(profile: str, explicit_world: str) -> Tuple[str, str, List[WorldInfo]]:
    worlds = list_worlds(profile)
    if explicit_world:
        for world in worlds:
            if world.name == explicit_world:
                return explicit_world, "explicit world requested", worlds
        return "", f"explicit world '{explicit_world}' not found", worlds

    lastworld = read_lastworld(profile)
    last_name = lastworld.get("world_name", "")
    if last_name:
        for world in worlds:
            if world.name == last_name and world.has_save:
                return world.name, "reusing last loaded save world", worlds

    for world in worlds:
        if world.has_save:
            return world.name, "using first world that already has a save", worlds

    return "", "no existing save world found; need Play Now bootstrap", worlds


def choose_strategy(profile: str, explicit_world: str) -> Tuple[str, str, str, List[WorldInfo]]:
    target_world, reason, worlds = pick_target_world(profile, explicit_world)
    if target_world:
        return "autoload_world", reason, target_world, worlds
    return "play_now_default", reason, "", worlds


def validate_harness_new_world(world: str, raw_seed: str) -> Tuple[str, str]:
    """Validate the hidden fresh-world request while preserving the exact seed text."""
    world_name = str(world or "").strip()
    seed_text = str(raw_seed or "").strip()
    if not world_name:
        raise ValueError("harness new-world name cannot be empty")
    if world_name in {".", ".."} or "/" in world_name or "\\" in world_name:
        raise ValueError("harness new-world name must be one path component")
    if not seed_text or not seed_text.isdecimal() or any(char not in "0123456789" for char in seed_text):
        raise ValueError("harness raw seed must be an unsigned decimal integer")
    if int(seed_text, 10) == 0:
        raise ValueError("harness raw seed must be non-zero")
    if int(seed_text, 10) > 0xFFFFFFFF:
        raise ValueError("harness raw seed is outside the uint32 range")
    return world_name, seed_text


def detect_executable() -> Path:
    root = repo_root()
    for name in (
        "Cataclysm-AOL",
        "cataclysm-tlg-tiles",
        "cataclysm-tiles",
        "Cataclysm-AOL.exe",
        "cataclysm-tlg-tiles.exe",
        "cataclysm-tiles.exe",
    ):
        path = root / name
        if path.exists() and os.access(path, os.X_OK):
            return path
    raise SystemExit(
        "Could not find a runnable game executable "
        "(Cataclysm-AOL, cataclysm-tlg-tiles, cataclysm-tiles, Cataclysm-AOL.exe, "
        "cataclysm-tlg-tiles.exe, or cataclysm-tiles.exe)."
    )


def ensure_dir(path: Path) -> None:
    path.mkdir(parents=True, exist_ok=True)


def create_run_dir(profile: str) -> Path:
    # A profile may receive independent registry launches in the same second.
    # Timestamp-only directories merge their reports and native traces, making
    # the later run's scenario identity unknowable.  Keep the readable time
    # prefix, then reserve a unique per-run suffix before any artifact exists.
    run_dir = userdir_for_profile(profile) / "harness_runs" / (
        time.strftime("%Y%m%d_%H%M%S") + "_" + uuid.uuid4().hex
    )
    run_dir.mkdir(parents=True, exist_ok=False)
    return run_dir


def r009_artifact_location_preflight(profile: str) -> Dict[str, Any]:
    """Describe the future witness artifact layout without creating a run."""
    artifact_root = userdir_for_profile(profile) / "harness_runs"
    existing_parent = artifact_root
    while not existing_parent.exists() and existing_parent != existing_parent.parent:
        existing_parent = existing_parent.parent
    writable = existing_parent.exists() and os.access(existing_parent, os.W_OK | os.X_OK)
    return {
        "status": "ready" if writable else "unavailable",
        "root": str(artifact_root),
        "existing_parent": str(existing_parent),
        "future_run_directory": str(artifact_root / "<authorized-run-id>"),
        "required_artifacts": [
            RUNTIME_BINDING_FILENAME,
            "process.json",
            TRANSITION_EVENT_FILENAME,
            "probe.report.json",
        ],
        "reason": "" if writable else "the nearest existing artifact parent is not writable",
        "created": False,
    }


def r009_platform_preflight(profile: str) -> Dict[str, Any]:
    """Verify R-009's portable witness prerequisites without launching a run."""
    contract = r009_preflight_contract()
    binding: Dict[str, Any]
    try:
        executable = detect_executable()
        binding = build_runtime_binding(executable)
    except SystemExit as error:
        executable = None
        binding = {"ok": False, "error": str(error)}

    artifacts = r009_artifact_location_preflight(profile)
    source_bound = bool(binding.get("ok"))
    launch_prerequisites = {
        "executable": {
            "status": "ready" if source_bound else "unavailable",
            "path": str(executable.resolve()) if executable is not None else "",
            "reason": "" if source_bound else str(binding.get("error", "runtime binding failed")),
        },
        "source_and_executable_binding": {
            "status": "matched" if source_bound else "unavailable",
            "binding": binding,
        },
        "artifact_location": artifacts,
        "selected_run_authority": {
            "status": "not_requested",
            "reason": "This preflight never selects or launches a scenario.",
        },
    }
    ready = source_bound and artifacts["status"] == "ready"
    return {
        **contract,
        "host_platform": r009_host_platform(),
        "launch_prerequisites": launch_prerequisites,
        "status": "ready" if ready else "blocked",
        "no_process_started": True,
        "summary": (
            "R-009 preflight verified portable contract and local prerequisites; "
            "it is not a platform witness."
        ),
    }


def build_plan(
    profile: str,
    explicit_world: str,
    fixture: str,
    harness_new_world: str = "",
    harness_raw_seed: str = "",
    harness_bandit_feasibility: bool = False,
) -> StartupPlan:
    plan_harness_world = ""
    plan_harness_seed = ""
    if harness_new_world or harness_raw_seed:
        world_name, seed_text = validate_harness_new_world(harness_new_world, harness_raw_seed)
        if harness_bandit_feasibility and seed_text != R002_PRODUCTION_FEASIBILITY_SEED:
            raise ValueError(
                "bandit feasibility requires raw seed "
                + R002_PRODUCTION_FEASIBILITY_SEED
            )
        if explicit_world or fixture:
            raise ValueError("harness new-world mode cannot be combined with --world or --fixture")
        if (save_dir_for_profile(profile) / world_name).exists():
            raise ValueError(f"harness new-world target already exists: {world_name}")
        strategy = "harness_new_world"
        reason = "fresh named normal world requested by harness"
        target_world = world_name
        worlds = list_worlds(profile)
        plan_harness_world = world_name
        plan_harness_seed = seed_text
    else:
        if harness_bandit_feasibility:
            raise ValueError("bandit feasibility requires harness new-world mode")
        strategy, reason, target_world, worlds = choose_strategy(profile, explicit_world)
    run_dir = create_run_dir(profile)
    plan = StartupPlan(
        profile=profile,
        userdir=str(userdir_for_profile(profile)),
        executable=str(detect_executable()),
        strategy=strategy,
        reason=reason,
        target_world=target_world,
        existing_worlds=[asdict_world(world) for world in worlds],
        fixture=fixture,
        run_dir=str(run_dir),
        harness_new_world=plan_harness_world,
        harness_raw_seed=plan_harness_seed,
        harness_bandit_feasibility=harness_bandit_feasibility,
    )
    return plan


def asdict_world(world: WorldInfo) -> Dict[str, Any]:
    return {
        "name": world.name,
        "path": str(world.path),
        "has_save": world.has_save,
        "save_files": list(world.save_files),
        "save_markers": list(world.save_markers),
    }


def write_json(path: Path, data: Dict[str, Any]) -> None:
    ensure_dir(path.parent)
    path.write_text(json.dumps(data, indent=2, ensure_ascii=False) + "\n", encoding="utf-8")


def missing_peekaboo_capabilities(payload: Dict[str, Any], required_names: Sequence[str]) -> List[Dict[str, Any]]:
    data = payload.get("data", {}) if isinstance(payload.get("data"), dict) else {}
    raw_permissions = data.get("permissions", []) if isinstance(data.get("permissions"), list) else []
    permissions = [entry for entry in raw_permissions if isinstance(entry, dict)]
    by_name = {str(entry.get("name", "")).strip().lower(): entry for entry in permissions}
    missing: List[Dict[str, Any]] = []
    for required_name in required_names:
        permission = by_name.get(str(required_name).strip().lower())
        if permission is None:
            missing.append({"name": required_name, "isGranted": False, "reason": "not_reported"})
        elif not permission.get("isGranted"):
            missing.append(permission)
    return missing


def peekaboo_permission_preflight(channel: str, required_names: Sequence[str]) -> Dict[str, Any]:
    cmd = peekaboo_command(["permissions", "status", "--json"], channel=channel)
    last_error = ""
    payload: Dict[str, Any] = {}
    for attempt in range(2):
        try:
            payload = run_json(cmd, timeout_seconds=5.0)
            last_error = ""
            break
        except RuntimeError as err:
            last_error = str(err)
            if attempt == 0:
                time.sleep(0.5)
    report = {
        "channel": channel,
        "command": cmd,
        "required_capabilities": list(required_names),
        "payload": payload,
        "error": last_error,
        "status": "unavailable" if last_error else "checked",
    }
    if last_error:
        # Permission reporting can wedge even when the real operations work.
        # Focus verification, command return codes, and capture/HUD inspection
        # remain the decisive gates, so preserve this diagnostic as advisory.
        return report
    missing = missing_peekaboo_capabilities(payload, required_names)
    report["missing_capabilities"] = missing
    report["status"] = "missing" if missing else "green"
    if missing:
        details = ", ".join(
            f"{entry.get('name')} ({entry.get('grantInstructions', entry.get('reason', 'not granted'))})"
            for entry in missing
        )
        raise SystemExit(f"Peekaboo {channel} permissions missing: {details}")
    return report


def require_peekaboo_permissions() -> Dict[str, Any]:
    return {
        "input": peekaboo_permission_preflight(
            "input",
            ["Accessibility"],
        ),
        "capture": peekaboo_permission_preflight(
            "capture",
            ["Screen Recording"],
        ),
    }


def peekaboo_switch_app_for_pid(pid: int) -> Dict[str, Any]:
    list_cmd = peekaboo_command(["app", "list", "--json"], channel="input")
    report: Dict[str, Any] = {
        "pid": pid,
        "list_command": list_cmd,
        "switch_command": [],
        "app_name": "",
        "ok": False,
    }
    try:
        before = run_json(list_cmd, timeout_seconds=5.0)
        apps = before.get("data", {}).get("apps", [])
        target = next(
            (
                app for app in apps
                if isinstance(app, dict) and int(app.get("pid", -1)) == pid
            ),
            None,
        )
        if not isinstance(target, dict):
            report["error"] = "target pid was not present in Peekaboo app list"
            return report
        app_name = str(target.get("name", "") or "").strip()
        if not app_name:
            report["error"] = "target pid had no Peekaboo application name"
            return report
        switch_cmd = peekaboo_command(
            ["app", "switch", "--to", app_name, "--json"],
            channel="input",
        )
        report["app_name"] = app_name
        report["switch_command"] = switch_cmd
        report["switch_result"] = run_json(switch_cmd, timeout_seconds=5.0)
        time.sleep(0.1)
        after = run_json(list_cmd, timeout_seconds=5.0)
        after_apps = after.get("data", {}).get("apps", [])
        report["ok"] = any(
            isinstance(app, dict)
            and int(app.get("pid", -1)) == pid
            and bool(app.get("is_active", False))
            for app in after_apps
        )
        if not report["ok"]:
            report["error"] = "Peekaboo app switch returned without making the target pid active"
    except (RuntimeError, TypeError, ValueError) as exc:
        report["error"] = str(exc)
    return report


def peekaboo_focus_pid(pid: int) -> Dict[str, Any]:
    cmd = peekaboo_command(
        ["window", "focus", "--pid", str(pid), "--verify"],
        channel="input",
    )
    try:
        proc = subprocess.run(
            cmd,
            check=False,
            capture_output=True,
            text=True,
            timeout=10.0,
        )
    except subprocess.TimeoutExpired as exc:
        proc = subprocess.CompletedProcess(
            cmd,
            124,
            stdout=subprocess_output_text(exc.stdout),
            stderr=subprocess_output_text(exc.stderr) + "\npeekaboo focus timed out",
        )
    report = {
        "command": cmd,
        "returncode": proc.returncode,
        "ok": proc.returncode == 0,
        "stdout": proc.stdout.strip(),
        "stderr": proc.stderr.strip(),
    }
    if report["ok"]:
        return report
    app_switch = peekaboo_switch_app_for_pid(pid)
    report["app_switch_fallback"] = app_switch
    if app_switch.get("ok"):
        report["returncode"] = 0
        report["ok"] = True
        report["stdout"] = "Peekaboo app switch verified target pid active"
    return report


def peekaboo_focus_pid_with_retry(
    pid: int,
    *,
    max_attempts: int = 2,
    retry_delay_seconds: float = 0.25,
) -> Dict[str, Any]:
    attempts: List[Dict[str, Any]] = []
    for attempt_index in range(max(1, max_attempts)):
        if attempt_index > 0 and retry_delay_seconds > 0:
            time.sleep(retry_delay_seconds)
        result = peekaboo_focus_pid(pid)
        attempts.append(result)
        if result.get("ok"):
            report = dict(result)
            report["attempt_count"] = len(attempts)
            report["attempts"] = attempts
            return report
    report = dict(attempts[-1])
    report["attempt_count"] = len(attempts)
    report["attempts"] = attempts
    return report


def run_peekaboo_interaction(
    pid: int,
    cmd: List[str],
    *,
    retry_delay_seconds: float = 0.15,
    focus_pid: bool = True,
) -> Dict[str, Any]:
    report: Dict[str, Any] = {
        "command": list(cmd),
        "focus_attempts": [],
        "attempts": [],
    }
    for attempt in range(2):
        if focus_pid:
            report["focus_attempts"].append(peekaboo_focus_pid(pid))
        if attempt > 0 and retry_delay_seconds > 0:
            time.sleep(retry_delay_seconds)
        try:
            proc = subprocess.run(
                cmd,
                check=False,
                capture_output=True,
                text=True,
                timeout=10.0,
            )
            command_attempt = {
                "attempt": attempt + 1,
                "returncode": proc.returncode,
                "stdout": proc.stdout,
                "stderr": proc.stderr,
            }
        except subprocess.TimeoutExpired as exc:
            command_attempt = {
                "attempt": attempt + 1,
                "returncode": 124,
                "stdout": subprocess_output_text(exc.stdout),
                "stderr": subprocess_output_text(exc.stderr) + "\npeekaboo interaction timed out",
            }
        report["attempts"].append(command_attempt)
        if command_attempt["returncode"] == 0:
            report["ok"] = True
            return report
    report["ok"] = False
    raise RuntimeError(
        "Peekaboo interaction failed; command diagnostics: "
        + json.dumps(report, ensure_ascii=False)
    )


PEEKABOO_KEY_ALIASES = {
    "esc": "escape",
    "backspace": "delete",
    "enter": "return",
}


def normalize_peekaboo_key(raw_key: Any) -> str:
    key = str(raw_key).strip()
    if not key:
        raise SystemExit("Peekaboo key cannot be empty")
    return PEEKABOO_KEY_ALIASES.get(key.lower(), key)


def is_printable_text_key(key: str) -> bool:
    return len(key) == 1 and key.isprintable() and key not in {"\n", "\r", "\t"}


def peekaboo_hotkey(
    pid: int, keys: str, hold_ms: int = 50, *, focus_pid: bool = True,
) -> None:
    args = ["hotkey", "--keys", keys, "--pid", str(pid), "--hold-duration", str(hold_ms)]
    if not focus_pid:
        args.append("--no-auto-focus")
    cmd = peekaboo_command(args, channel="input")
    run_peekaboo_interaction(pid, cmd, focus_pid=focus_pid)


SHIFT_SYMBOL_HOTKEYS = {
    "!": "shift,1",
    "@": "shift,2",
    "#": "shift,3",
    "$": "shift,4",
    "%": "shift,5",
    "^": "shift,6",
    "&": "shift,7",
    "*": "shift,8",
    "(": "shift,9",
    ")": "shift,0",
    "{": "shift,[",
    "}": "shift,]",
}

# Peekaboo hotkey only accepts its documented physical key names.  It has no
# portable name for the backslash key, so a `shift,\\` request can succeed at
# the driver layer without delivering the `|` character which the game binds
# to the native wait action.  Use its text input path for that declared
# character binding instead.
PEEKABOO_TEXT_INPUT_KEYS = frozenset( { "|" } )

# Peekaboo's press action accepts these named physical keys directly.  Keep
# them explicit so focus-once batches cannot silently fall back to text input.
PHYSICAL_NAMED_KEYS = {
    "escape": "escape",
    "left": "left",
    "right": "right",
    "up": "up",
    "down": "down",
}


def peekaboo_physical_hotkey_for_key(key: str) -> str:
    if key in PEEKABOO_TEXT_INPUT_KEYS:
        return ""
    if key in PHYSICAL_NAMED_KEYS:
        return PHYSICAL_NAMED_KEYS[key]
    if key == "[":
        return key
    if len(key) == 1 and key.isalpha() and key.isupper():
        return f"shift,{key.lower()}"
    return SHIFT_SYMBOL_HOTKEYS.get(key, "")


def peekaboo_press_sequence(
    pid: int,
    keys: List[str],
    delay_ms: int = 200,
    *,
    focus_once: bool = False,
) -> None:
    if not keys:
        return
    if focus_once:
        normalized = [normalize_peekaboo_key(raw_key) for raw_key in keys]
        if all(key == "." for key in normalized):
            focus_report = peekaboo_focus_pid(pid)
            if not focus_report.get("ok"):
                raise RuntimeError("Peekaboo sequence focus failed: " + json.dumps(focus_report, ensure_ascii=False))
            peekaboo_type_text(pid, "".join(normalized), delay_ms=delay_ms, focus_pid=False)
            return
        physical = [peekaboo_physical_hotkey_for_key(key) for key in normalized]
        if any(not key for key in physical):
            raise ValueError("focus_once requires keys with physical key mappings")
        focus_report = peekaboo_focus_pid(pid)
        if not focus_report.get("ok"):
            raise RuntimeError("Peekaboo sequence focus failed: " + json.dumps(focus_report, ensure_ascii=False))
        # ``press`` accepts only individual keys, while uppercase semantic
        # activity choices are modifier chords (for example ``shift,i``).
        # Keep the one verified focus handoff and deliver such chords through
        # the hotkey transport without letting it refocus the game.
        if any("," in key for key in physical):
            for key in physical:
                if "," in key:
                    peekaboo_hotkey(pid, key, hold_ms=max(30, min(delay_ms, 200)), focus_pid=False)
                else:
                    cmd = peekaboo_command(
                        ["press", key, "--pid", str(pid), "--delay", str(delay_ms), "--no-auto-focus"],
                        channel="input",
                    )
                    run_peekaboo_interaction(pid, cmd, focus_pid=False)
            return
        cmd = peekaboo_command(
            ["press", *physical, "--pid", str(pid), "--delay", str(delay_ms), "--no-auto-focus"],
            channel="input",
        )
        run_peekaboo_interaction(pid, cmd, focus_pid=False)
        return
    text_buffer: List[str] = []
    special_key_buffer: List[str] = []

    def flush_text_buffer() -> None:
        if not text_buffer:
            return
        peekaboo_type_text(pid, "".join(text_buffer), delay_ms=max(10, min(delay_ms, 200)))
        text_buffer.clear()

    def flush_special_key_buffer() -> None:
        if not special_key_buffer:
            return
        cmd = peekaboo_command(
            ["press", *special_key_buffer, "--pid", str(pid), "--delay", str(delay_ms)],
            channel="input",
        )
        run_peekaboo_interaction(pid, cmd)
        special_key_buffer.clear()

    for raw_key in keys:
        key = normalize_peekaboo_key(raw_key)
        hotkey = peekaboo_physical_hotkey_for_key(key)
        if hotkey:
            flush_text_buffer()
            flush_special_key_buffer()
            peekaboo_hotkey(pid, hotkey, hold_ms=max(30, min(delay_ms, 200)))
            continue
        if is_printable_text_key(key):
            flush_special_key_buffer()
            if key.isalpha():
                flush_text_buffer()
                peekaboo_hotkey(pid, key, hold_ms=max(30, min(delay_ms, 200)))
            else:
                text_buffer.append(key)
            continue
        flush_text_buffer()
        special_key_buffer.append(key)
    flush_text_buffer()
    flush_special_key_buffer()


def peekaboo_type_text(pid: int, text: str, delay_ms: int = 20, *, focus_pid: bool = True) -> None:
    if not text:
        return
    max_chunk_len = 20
    for start in range(0, len(text), max_chunk_len):
        chunk = text[start:start + max_chunk_len]
        cmd = peekaboo_command(
            ["type", chunk, "--pid", str(pid), "--delay", str(delay_ms), "--profile", "linear"],
            channel="input",
        )
        run_peekaboo_interaction(pid, cmd, focus_pid=focus_pid)


def count_pause_dispatches_since(log_path: Path, start_offset: int) -> int:
    if not log_path.exists():
        return 0
    size = log_path.stat().st_size
    offset = start_offset if 0 <= start_offset <= size else 0
    with log_path.open("rb") as handle:
        handle.seek(offset)
        return handle.read().count(PAUSE_DISPATCH_MARKER)


def wait_for_pause_dispatch_count(
    log_path: Path,
    start_offset: int,
    expected_count: int,
    *,
    timeout_seconds: float = 3.0,
) -> int:
    deadline = time.monotonic() + max(0.0, timeout_seconds)
    observed = count_pause_dispatches_since(log_path, start_offset)
    while observed < expected_count and time.monotonic() < deadline:
        time.sleep(0.05)
        observed = count_pause_dispatches_since(log_path, start_offset)
    return observed


def read_active_eoc_popup_trace(
    log_path: Optional[Path],
    start_offset: int,
) -> Optional[Dict[str, Any]]:
    if log_path is None or not log_path.exists():
        return None
    size = log_path.stat().st_size
    bounded_start = max(start_offset if 0 <= start_offset <= size else 0,
                        size - EOC_POPUP_TRACE_READ_CAP_BYTES)
    with log_path.open("rb") as handle:
        handle.seek(bounded_start)
        body = handle.read(EOC_POPUP_TRACE_READ_CAP_BYTES).decode("utf-8", errors="replace")

    active: Optional[Dict[str, Any]] = None
    for match in EOC_POPUP_TRACE_PATTERN.finditer(body):
        try:
            message = json.loads(match.group(2))
        except (TypeError, ValueError, json.JSONDecodeError):
            continue
        if not isinstance(message, str):
            continue
        event = match.group(1)
        trace = {
            "component": "eoc_popup",
            "event": event,
            "message": message,
            "truncated": match.group(3) == "yes",
            "popup_flag": int(match.group(4)),
            "log_path": str(log_path),
            "start_offset": start_offset,
            "scan_offset": bounded_start,
            "event_offset": bounded_start + len(body[:match.start()].encode("utf-8")),
            "read_truncated": bounded_start > start_offset,
        }
        if event == "open":
            active = trace
        elif active is not None and active.get("message") == message:
            active = None
    return active


def read_scheduler_trace(profile: str, run_id: str) -> List[Dict[str, Any]]:
    """Read only this run's opt-in global-EOC scheduler decisions."""
    trace_run_id = str(run_id).strip()
    if not trace_run_id:
        return []
    log_path = config_dir_for_profile(profile) / "debug.log"
    if not log_path.is_file():
        return []
    try:
        body = log_path.read_text(encoding="utf-8", errors="replace")[-EOC_POPUP_TRACE_READ_CAP_BYTES:]
    except OSError:
        return []
    records: List[Dict[str, Any]] = []
    for match in SCHEDULER_TRACE_PATTERN.finditer(body):
        if match.group("run_id") != trace_run_id:
            continue
        records.append({
            "eoc": match.group("eoc"),
            "due_turn": int(match.group("due_turn")),
            "current_turn": int(match.group("current_turn")),
            "decision": match.group("decision"),
            "outcome": match.group("outcome"),
        })
    return records


def read_active_semantic_ui_trace(
    log_path: Optional[Path],
    start_offset: int,
    *,
    include_progress: bool = False,
    run_id: str = "",
) -> Optional[Dict[str, Any]]:
    """Read the latest bounded authoritative semantic UI context.

    This parser is intentionally independent of screenshot text.  A malformed
    or truncated trace is not converted into an action.
    """
    if log_path is None or not log_path.exists():
        return None
    size = log_path.stat().st_size
    bounded_start = max(start_offset if 0 <= start_offset <= size else 0,
                        size - SEMANTIC_UI_TRACE_READ_CAP_BYTES)
    with log_path.open("rb") as handle:
        handle.seek(bounded_start)
        body = handle.read(SEMANTIC_UI_TRACE_READ_CAP_BYTES).decode("utf-8", errors="replace")
    active: Optional[Dict[str, Any]] = None
    for match in SEMANTIC_UI_TRACE_PATTERN.finditer(body):
        try:
            instance_id = json.loads(match.group(2))
            observed_run_id = json.loads(match.group(3)) if match.group(3) else ""
            intent = json.loads(match.group(4))
            valid_actions = json.loads(match.group(5))
            postcondition = json.loads(match.group(6))
            destination = json.loads(match.group(7)) if match.group(7) else None
        except (TypeError, ValueError, json.JSONDecodeError):
            continue
        if not isinstance(instance_id, str) or not isinstance(observed_run_id, str) or \
                not isinstance(intent, str) or \
                not isinstance(valid_actions, list) or not isinstance(postcondition, str):
            continue
        if run_id and observed_run_id != run_id:
            continue
        trace = {
            "component": "semantic_ui",
            "event": match.group(1),
            "instance_id": instance_id,
            "run_id": observed_run_id,
            "intent": intent,
            "valid_actions": valid_actions,
            "postcondition": postcondition,
            "destination": destination,
            "event_offset": bounded_start + len(body[:match.start()].encode("utf-8")),
            "start_offset": start_offset,
            "read_truncated": bounded_start > start_offset,
        }
        line_start = body.rfind("\n", 0, match.start()) + 1
        timestamp_match = TRACE_TIMESTAMP_PATTERN.search(body, line_start, match.start())
        if timestamp_match is not None:
            trace["timestamp"] = timestamp_match.group("timestamp")
        if match.group(1) == "open":
            active = trace
        elif match.group(1) == "progress":
            active = trace if include_progress else None
        elif active is not None and active["instance_id"] == instance_id:
            active = None
    return active


def read_semantic_ui_trace_events(
    log_path: Optional[Path],
    start_offset: int,
    *,
    run_id: str = "",
) -> List[Dict[str, Any]]:
    """Return every current-run semantic UI receipt with its log timestamp."""
    if log_path is None or not log_path.exists():
        return []
    size = log_path.stat().st_size
    bounded_start = max(start_offset if 0 <= start_offset <= size else 0,
                        size - SEMANTIC_UI_TRACE_READ_CAP_BYTES)
    with log_path.open("rb") as handle:
        handle.seek(bounded_start)
        body = handle.read(SEMANTIC_UI_TRACE_READ_CAP_BYTES).decode("utf-8", errors="replace")
    events: List[Dict[str, Any]] = []
    for match in SEMANTIC_UI_TRACE_PATTERN.finditer(body):
        try:
            instance_id = json.loads(match.group(2))
            observed_run_id = json.loads(match.group(3)) if match.group(3) else ""
            intent = json.loads(match.group(4))
            valid_actions = json.loads(match.group(5))
            postcondition = json.loads(match.group(6))
            destination = json.loads(match.group(7)) if match.group(7) else None
        except (TypeError, ValueError, json.JSONDecodeError):
            continue
        if not isinstance(instance_id, str) or not isinstance(observed_run_id, str) or \
                not isinstance(intent, str) or not isinstance(valid_actions, list) or \
                not isinstance(postcondition, str) or (run_id and observed_run_id != run_id):
            continue
        event: Dict[str, Any] = {
            "component": "semantic_ui",
            "event": match.group(1),
            "instance_id": instance_id,
            "run_id": observed_run_id,
            "intent": intent,
            "valid_actions": valid_actions,
            "postcondition": postcondition,
            "destination": destination,
            "event_offset": bounded_start + len(body[:match.start()].encode("utf-8")),
            "start_offset": start_offset,
            "read_truncated": bounded_start > start_offset,
        }
        line_start = body.rfind("\n", 0, match.start()) + 1
        timestamp_match = TRACE_TIMESTAMP_PATTERN.search(body, line_start, match.start())
        if timestamp_match is not None:
            event["timestamp"] = timestamp_match.group("timestamp")
        events.append(event)
    return events


def native_save_quit_receipt(
    log_path: Optional[Path], start_offset: int, *, run_id: str,
) -> Dict[str, Any]:
    """Require one complete, same-run native save/quit modal receipt."""
    events = [event for event in read_semantic_ui_trace_events(
        log_path, start_offset, run_id=run_id
    ) if event.get("intent") == "save_quit_confirmation"]
    opens = [event for event in events if event.get("event") == "open"]
    returns = [event for event in events if event.get("event") == "return"]
    matching_pairs = []
    for opened in opens:
        for returned in returns:
            if returned.get("instance_id") == opened.get("instance_id"):
                matching_pairs.append({"open": opened, "return": returned})
    if len(matching_pairs) != 1:
        return {
            "status": "missing_or_ambiguous",
            "run_id": run_id,
            "event_count": len(events),
            "matching_pair_count": len(matching_pairs),
            "events": events,
        }
    pair = matching_pairs[0]
    if pair["open"].get("valid_actions") != ["Y"] or \
            pair["return"].get("valid_actions") != ["Y"]:
        return {
            "status": "invalid_actions",
            "run_id": run_id,
            "pair": pair,
        }
    return {"status": "matched", "run_id": run_id, "pair": pair}


def evaluate_semantic_ui_expectation(
    log_path: Optional[Path],
    start_offset: int,
    expectation: Mapping[str, Any],
    *,
    run_id: str = "",
) -> Dict[str, Any]:
    """Require one bounded, active semantic UI instance without using OCR."""
    expected_run_id = str(run_id).strip()
    active = read_active_semantic_ui_trace(log_path, start_offset, run_id=expected_run_id)
    expected_intent = str(expectation.get("intent", "")).strip()
    expected_instance_id = str(expectation.get("instance_id", "")).strip()
    expected_actions = expectation.get("valid_actions", [])
    if isinstance(expected_actions, str):
        expected_actions = [expected_actions]
    if not isinstance(expected_actions, list):
        expected_actions = []
    expected_actions = [str(action).strip() for action in expected_actions if str(action).strip()]
    if not expected_run_id:
        return {
            "status": "blocked",
            "verdict": "blocked_semantic_ui_expectation_missing_run_id",
            "reason": "the semantic UI observation is not bound to a current harness run",
            "provenance": "semantic_ui_trace",
            "expected_run_id": expected_run_id,
        }
    if active is None:
        return {
            "status": "blocked",
            "verdict": "blocked_semantic_ui_expectation_missing",
            "reason": "the authoritative semantic UI trace has no active modal instance",
            "provenance": "semantic_ui_trace",
            "expected_run_id": expected_run_id,
            "expected_intent": expected_intent,
            "expected_instance_id": expected_instance_id,
            "expected_valid_actions": expected_actions,
        }
    observed_actions = [str(action).strip() for action in active.get("valid_actions", [])]
    issues: List[str] = []
    if active.get("event") != "open":
        issues.append("active_event_is_not_open")
    if active.get("run_id") != expected_run_id:
        issues.append("wrong_run")
    if expected_intent and active.get("intent") != expected_intent:
        issues.append("wrong_intent")
    if expected_instance_id and active.get("instance_id") != expected_instance_id:
        issues.append("wrong_instance_id")
    if expected_actions and any(action not in observed_actions for action in expected_actions):
        issues.append("advertised_input_missing")
    if bool(active.get("read_truncated", False)):
        # A modal open retained in the current-run tail is still an authoritative
        # live state.  A matching return in that same tail would clear ``active``;
        # rejecting solely because older, irrelevant bytes fell outside the cap
        # turns a bounded reader into a false terminal-save failure.
        issues.append("trace_read_truncated")
    tail_bound_active = issues == ["trace_read_truncated"] and \
                        str(active.get("event", "")) == "open"
    return {
        "status": "green" if not issues or tail_bound_active else "blocked",
        "verdict": "green_semantic_ui_expectation" if not issues or tail_bound_active else "blocked_semantic_ui_expectation",
        "reason": "active authoritative semantic UI instance and advertised input verified" if not issues
        else "authoritative semantic UI trace did not satisfy the declared modal expectation",
        "provenance": "semantic_ui_trace",
        "expected_run_id": expected_run_id,
        "expected_intent": expected_intent,
        "expected_instance_id": expected_instance_id,
        "expected_valid_actions": expected_actions,
        "observed": active,
        "observed_valid_actions": observed_actions,
        "issues": issues,
        "tail_bound_active": tail_bound_active,
    }


def recover_adaptive_semantic_ui_interruption(
    *, pid: int, run_dir: Path, action_trace_log: Path, trace_start_offset: int,
    recovery: Mapping[str, Any], delay_ms: int,
) -> Dict[str, Any]:
    """Recover one scenario-declared semantic interruption, or leave it untouched."""
    active = read_active_semantic_ui_trace(action_trace_log, trace_start_offset)
    if active is None:
        return {"status": "not_active"}
    expected_intent = str(recovery.get("intent", "")).strip()
    expected_action = str(recovery.get("action", "")).strip()
    expected_postcondition = str(recovery.get("postcondition", "")).strip()
    active_public = {
        key: active.get(key) for key in (
            "instance_id", "intent", "valid_actions", "postcondition", "event_offset",
        )
    }
    if not expected_intent or not expected_action or not expected_postcondition:
        return {"status": "blocked_invalid_declaration", "active_semantic_ui": active_public}
    if active.get("intent") != expected_intent or \
            active.get("postcondition") != expected_postcondition or \
            expected_action not in active.get("valid_actions", []):
        return {
            "status": "blocked_unexpected_semantic_ui",
            "active_semantic_ui": active_public,
            "expected": {
                "intent": expected_intent,
                "action": expected_action,
                "postcondition": expected_postcondition,
            },
        }
    result = acknowledge_blocking_interruptions(
        pid, run_dir, "adaptive_semantic_ui", max_acknowledgements=1,
        delay_ms=delay_ms, stop_on_unknown=True,
        semantic_ui_trace_log=action_trace_log,
        semantic_ui_trace_start_offset=trace_start_offset,
        semantic_ui_expectation={
            "instance_id": str(active.get("instance_id", "")),
            "intent": expected_intent,
            "action": expected_action,
        },
    )
    return {
        "status": "recovered" if result.get("status") == "semantic_recovered"
        else "blocked_recovery_failed",
        "active_semantic_ui": active_public,
        "recovery": result,
    }


def activity_query_effective_trace_start_offset(
    log_path: Optional[Path], start_offset: int,
) -> Optional[int]:
    """Bind an activity query to its current native debug-log generation.

    Cataclysm can truncate ``debug.log`` after the semantic channel records its
    startup cursor.  The semantic-frame reader rebinds that new generation
    when it contains a current semantic frame.  Activity-query recovery must
    make the identical decision: otherwise it observes a real query at byte
    zero but rejects it against an obsolete cursor beyond EOF.
    """
    if log_path is None or not log_path.exists():
        return start_offset
    try:
        size = log_path.stat().st_size
    except OSError:
        return None
    if 0 <= start_offset <= size:
        return start_offset
    try:
        with log_path.open("rb") as handle:
            has_current_semantic_frame = SEMANTIC_STEP_PREFIX.encode("utf-8") in handle.read()
    except OSError:
        return None
    return 0 if has_current_semantic_frame else None


def recover_adaptive_activity_distraction(
    *, pid: int, action_trace_log: Path, trace_start_offset: int, delay_ms: int,
) -> Dict[str, Any]:
    """Resume one native-traced activity distraction only with its bound return."""
    effective_trace_start = activity_query_effective_trace_start_offset(
        action_trace_log, trace_start_offset,
    )
    if effective_trace_start is None:
        return {
            "status": "blocked_activity_distraction_trace_generation_unbound",
            "trace_start_offset": trace_start_offset,
        }
    active = read_active_activity_query_trace( action_trace_log, effective_trace_start )
    if active is None:
        return {"status": "not_active"}
    if active.get("truncated") or active.get("action") != "none" or \
            active.get("type") not in ACTIVITY_QUERY_TRACE_TYPES:
        return {"status": "blocked_activity_distraction_untrusted", "active": active}

    issuing_open_offset = int(active.get("event_offset", -1))
    if issuing_open_offset < effective_trace_start:
        return {"status": "blocked_activity_distraction_unbound", "active": active}
    peekaboo_press_sequence(pid, ["I"], delay_ms=delay_ms)
    receipt = read_latest_activity_query_trace(
        action_trace_log, effective_trace_start, issuing_open_offset,
    )
    if receipt is None or receipt.get("event") != "return" or \
            receipt.get("action") != "IGNORE" or \
            int(receipt.get("issuing_open_offset", -1)) != issuing_open_offset:
        return {
            "status": "blocked_activity_distraction_return_unproved",
            "active": active,
            "receipt": receipt,
        }
    return {
        "status": "recovered",
        "action_id": "activity.ignore",
        "provenance": "native_activity_distraction_query_trace",
        "active": active,
        "receipt": receipt,
    }


def evaluate_rendered_gameplay_hud_identity(
    log_path: Optional[Path],
    run_id: str,
    screen_text_report: Mapping[str, Any],
    screen_summary: Mapping[str, Any],
    expected_labels: Sequence[str],
    startup_overlay_recovery: Any = None,
    trace_start_offset: int = 0,
) -> Dict[str, Any]:
    """Require the native Move/Wield widgets on the currently unobscured HUD.

    The trace is bound to the launched process's run ID.  OCR only establishes
    that the capture is the unobscured gameplay screen; it cannot substitute
    for either required widget.
    """
    expected = [str(label).strip() for label in expected_labels if str(label).strip()]
    issues: List[str] = []
    if expected != ["Move:", "Wield:"]:
        issues.append("unsupported_hud_identity")
    if not run_id:
        issues.append("missing_run_id")
    if log_path is None or not log_path.exists():
        issues.append("missing_hud_trace")
        body = ""
        bounded_start = 0
        read_truncated = False
    else:
        size = log_path.stat().st_size
        bounded_start = trace_start_offset if 0 <= trace_start_offset <= size else -1
        if bounded_start < 0:
            body = ""
            read_truncated = False
            issues.append("invalid_hud_trace_start_offset")
        else:
            read_length = size - bounded_start
            with log_path.open("rb") as handle:
                handle.seek(bounded_start)
                body = handle.read(read_length).decode("utf-8", errors="replace")
            read_truncated = False

    observed: Optional[Dict[str, Any]] = None
    foreign_run_seen = False
    for match in GAMEPLAY_HUD_TRACE_PATTERN.finditer(body):
        try:
            observed_run_id = json.loads(match.group(1))
        except (TypeError, ValueError, json.JSONDecodeError):
            continue
        if not isinstance(observed_run_id, str):
            continue
        candidate = {
            "run_id": observed_run_id,
            "move_widget": match.group(2),
            "wield_widget": match.group(3),
            "event_offset": bounded_start + len(body[:match.start()].encode("utf-8")),
        }
        if observed_run_id != run_id:
            foreign_run_seen = True
            continue
        observed = candidate

    if observed is None:
        issues.append("wrong_run_hud_trace" if foreign_run_seen else "hud_trace_missing")
    else:
        if observed["move_widget"] not in GAMEPLAY_HUD_MOVE_WIDGETS:
            issues.append("wrong_move_widget")
        if observed["wield_widget"] not in GAMEPLAY_HUD_WIELD_WIDGETS:
            issues.append("wrong_wield_widget")

    screen_probe = startup_screen_probe_classification(
        ocr_payload=dict(screen_text_report),
        capture_warnings=screen_summary.get("capture_warnings", []),
        debug_delta_text=body,
        gameplay_hud_run_id=run_id,
    )
    if int(screen_probe.get("ocr_line_count", 0) or 0) > 0 and \
            not screen_probe.get("gameplay_hud_present"):
        issues.append("gameplay_hud_not_visible")
    if screen_probe.get("blocking_overlay_present"):
        issues.append("blocking_overlay_present")
    if not declared_startup_overlay_action_is_satisfied(startup_overlay_recovery):
        issues.append("startup_overlay_recovery_unproven")
    return {
        "status": "green" if not issues else "blocked",
        "verdict": "green_rendered_gameplay_hud_identity" if not issues
        else "blocked_rendered_gameplay_hud_identity",
        "reason": "native Move and Wield widgets rendered on the unobscured gameplay HUD"
        if not issues else "native gameplay HUD identity did not satisfy the fixed Move/Wield expectation",
        "provenance": "native_gameplay_hud_render_trace",
        "expected_labels": expected,
        "observed": observed,
        "screen_probe": screen_probe,
        "trace_path": str(log_path or ""),
        "trace_start_offset": trace_start_offset,
        "trace_read_end_offset": (
            log_path.stat().st_size if log_path is not None and log_path.exists() else 0
        ),
        "trace_read_truncated": read_truncated,
        "issues": issues,
    }


def read_active_activity_query_trace(
    log_path: Optional[Path],
    start_offset: int,
) -> Optional[Dict[str, Any]]:
    if log_path is None or not log_path.exists():
        return None
    size = log_path.stat().st_size
    bounded_start = max(start_offset if 0 <= start_offset <= size else 0,
                        size - EOC_POPUP_TRACE_READ_CAP_BYTES)
    with log_path.open("rb") as handle:
        handle.seek(bounded_start)
        body = handle.read(EOC_POPUP_TRACE_READ_CAP_BYTES).decode("utf-8", errors="replace")

    active: Optional[Dict[str, Any]] = None
    for match in ACTIVITY_QUERY_TRACE_PATTERN.finditer(body):
        try:
            text = json.loads(match.group(4))
        except (TypeError, ValueError, json.JSONDecodeError):
            continue
        if not isinstance(text, str):
            continue
        event = match.group(1)
        distraction_type = match.group(2)
        action = match.group(6)
        trace = {
            "component": "activity_distraction_query",
            "event": event,
            "type": distraction_type,
            "text": text,
            "game_minutes": int(match.group(3)) if match.group(3) is not None else None,
            "truncated": match.group(5) == "yes",
            "action": action,
            "log_path": str(log_path),
            "start_offset": start_offset,
            "scan_offset": bounded_start,
            "event_offset": bounded_start + len(body[:match.start()].encode("utf-8")),
            "read_truncated": bounded_start > start_offset,
        }
        if event == "open" and action == "none":
            active = trace
        elif event == "return" and active is not None and \
                active.get("type") == distraction_type:
            active = None
    return active


def read_latest_activity_query_trace(
    log_path: Optional[Path], start_offset: int,
    issuing_open_offset: Optional[int] = None,
) -> Optional[Dict[str, Any]]:
    """Return the latest native activity query with its issuing-open offset.

    A return is usable as a recovery receipt only when it closes the exact
    interruption opening that advertised the action.  A later world frame is
    an outcome, never evidence that an older interruption input was accepted.
    """
    if log_path is None or not log_path.exists():
        return None
    size = log_path.stat().st_size
    if start_offset < 0 or start_offset > size:
        return None
    if issuing_open_offset is not None:
        # The issuing frame is the receipt's identity.  A moving tail can
        # discard that open before the native return is read, which would turn
        # a real return into a missing receipt.  The return can also arrive
        # after more than the moving-tail capacity of unrelated native log
        # output, so this bound pair must consume the sampled range through
        # its end rather than retain that tail cap.
        if issuing_open_offset < start_offset or issuing_open_offset >= size:
            return None
        bounded_start = issuing_open_offset
    else:
        bounded_start = max(start_offset, size - EOC_POPUP_TRACE_READ_CAP_BYTES)
    with log_path.open("rb") as handle:
        handle.seek(bounded_start)
        body = handle.read(size - bounded_start).decode("utf-8", errors="replace")
    latest: Optional[Dict[str, Any]] = None
    active: Optional[Dict[str, Any]] = None
    for match in ACTIVITY_QUERY_TRACE_PATTERN.finditer(body):
        try:
            text = json.loads(match.group(4))
        except (TypeError, ValueError, json.JSONDecodeError):
            continue
        if not isinstance(text, str):
            continue
        trace = {
            "component": "activity_distraction_query",
            "event": match.group(1),
            "type": match.group(2),
            "text": text,
            "game_minutes": int(match.group(3)) if match.group(3) is not None else None,
            "truncated": match.group(5) == "yes",
            "action": match.group(6),
            "event_offset": bounded_start + len(body[:match.start()].encode("utf-8")),
        }
        if trace["event"] == "open" and trace["action"] == "none" and \
                (issuing_open_offset is None or trace["event_offset"] == issuing_open_offset):
            active = trace
            latest = trace
        elif trace["event"] == "return":
            if active is not None and active.get("type") == trace.get("type"):
                trace["issuing_open_offset"] = active["event_offset"]
                active = None
                if issuing_open_offset is not None:
                    return trace
            latest = trace
    if issuing_open_offset is not None:
        return None
    return latest


def semantic_step_source_trace(profile: str) -> Path:
    return config_dir_for_profile(resolve_profile_name(profile)) / "debug.log"


def compact_semantic_step_channel_event(event: Mapping[str, Any]) -> Dict[str, Any]:
    """Keep the action-relevant native observation inside the bounded channel.

    Native HUD frames include full minimap and overmap render payloads.  The
    semantic action path derives its handles and safety facts from the avatar,
    local visibility, entities, zones, and advertised actions; the full render
    maps are neither an action authority nor evidence consumed by this trace.
    Preserve a small local-map declaration for the cockpit while allowing its
    public fallback to render the same visible-local facts.
    """
    compact = dict(event)
    observation = event.get("observation")
    if str(event.get("event", "")) != "frame" or not isinstance(observation, Mapping):
        return compact
    compact_observation = dict(observation)
    minimap = observation.get("minimap")
    if isinstance(minimap, Mapping):
        compact_observation["minimap"] = {
            key: minimap[key] for key in ("schema", "radius", "coordinate_system")
            if key in minimap
        }
    compact_observation.pop("overmap", None)
    compact["observation"] = compact_observation
    return compact


def refresh_semantic_step_trace(
    *, profile: str, run_dir: Path, run_id: str, start_offset: int,
    event_filter: Optional[Set[str]] = None,
) -> tuple[Path, Path]:
    """Copy only the current run's bounded native trace into its owned artifact."""
    run_dir = Path(run_dir).resolve()
    source = semantic_step_source_trace(profile).resolve()
    size = source.stat().st_size
    if start_offset < 0 or start_offset > size:
        # The game can truncate debug.log after the startup readiness sample,
        # while it is still loading the selected world.  A fresh native frame
        # is bound by run_id when the copied trace is read below, so restart
        # only when this new log generation actually contains semantic data.
        with source.open("rb") as handle:
            if SEMANTIC_STEP_PREFIX.encode("utf-8") not in handle.read():
                raise ValueError("semantic trace start offset is stale")
        start_offset = 0
    marker = SEMANTIC_STEP_PREFIX.encode("utf-8")
    selected = bytearray()
    with source.open("rb") as handle:
        handle.seek(start_offset)
        # ``debug.log`` remains hot while the game renders its HUD.  Iterating
        # the live file can consequently chase appended lines forever and
        # strand the scheduler after an otherwise valid world frame.  Read the
        # byte range sampled above as one immutable snapshot instead.
        snapshot = handle.read(size - start_offset)
        for raw_line in snapshot.splitlines(keepends=True):
            marker_offset = raw_line.find(marker)
            if marker_offset < 0:
                continue
            payload = raw_line[marker_offset + len(marker):].strip()
            try:
                event = json.loads(payload)
            except (TypeError, ValueError, json.JSONDecodeError):
                continue
            if not isinstance(event, Mapping) or str(event.get("run_id", "")) != str(run_id):
                continue
            if event_filter is not None and str(event.get("event", "")) not in event_filter:
                continue
            compact_event = compact_semantic_step_channel_event(event)
            compact_line = (
                SEMANTIC_STEP_PREFIX + json.dumps(compact_event, separators=(",", ":")) + "\n"
            ).encode("utf-8")
            selected.extend(compact_line)
            if len(selected) > SEMANTIC_STEP_MAX_BYTES:
                raise ValueError("semantic events exceed the bounded run channel")
    owned = run_dir / "semantic.native.log"
    owned.write_bytes(selected)
    return source, owned


def semantic_step_effective_source_offset(source: Path, start_offset: int) -> int:
    """Use the current native log generation's coordinate system."""
    try:
        size = source.stat().st_size
    except OSError:
        return start_offset
    return start_offset if 0 <= start_offset <= size else 0


def semantic_step_trace_start_after_launch(
    log_path: Path,
    *,
    prelaunch_size: int,
    prelaunch_identity: Optional[Dict[str, Any]],
) -> int:
    """Keep the semantic channel inside the new game's log generation.

    Cataclysm commonly truncates ``debug.log`` in place during process startup.
    A cursor captured before launch then belongs past EOF, which must not make a
    newly advertised semantic action undispatchable.  Reset only when the log
    generation demonstrably changed; an append-only log retains its old cursor
    and remains fail-closed against prior-run frames.
    """
    try:
        current_size = log_path.stat().st_size
    except OSError:
        return prelaunch_size
    current_identity = log_file_identity(log_path)
    if current_size < prelaunch_size or \
            log_file_identity_changed(prelaunch_identity, current_identity):
        return 0
    return prelaunch_size


def semantic_step_frame_source_offset(
    source: Path,
    *, start_offset: int, frame_id: str,
) -> int:
    """Locate one filtered semantic frame in the original debug-log byte stream."""
    if not frame_id or start_offset < 0:
        return -1
    try:
        size = source.stat().st_size
    except OSError:
        return -1
    if start_offset > size:
        start_offset = 0
    marker = SEMANTIC_STEP_PREFIX.encode("utf-8")
    try:
        with source.open("rb") as handle:
            handle.seek(start_offset)
            cursor = start_offset
            for raw_line in handle.read(size - start_offset).splitlines(keepends=True):
                marker_offset = raw_line.find(marker)
                if marker_offset >= 0:
                    payload = raw_line[marker_offset + len(marker):].strip()
                    try:
                        event = json.loads(payload)
                    except (TypeError, ValueError, json.JSONDecodeError):
                        event = None
                    if isinstance(event, Mapping) and event.get("frame_id") == frame_id:
                        return cursor + marker_offset
                cursor += len(raw_line)
    except OSError:
        return -1
    return -1


def current_semantic_step_frame(
    *, profile: str, run_dir: Path, run_id: str, start_offset: int,
) -> Dict[str, Any]:
    """Return the newest native wait or activity-query frame for adaptive play."""
    source, owned = refresh_semantic_step_trace(
        profile=profile, run_dir=run_dir, run_id=run_id, start_offset=start_offset,
    )
    effective_source_offset = semantic_step_effective_source_offset(source, start_offset)
    events, status = read_semantic_step_trace(owned, Path(run_dir), run_id)
    if status != "ok":
        raise ValueError(f"semantic step trace is unavailable: {status}")
    for event in events:
        event["_event_offset"] = effective_source_offset + int(event.get("_event_offset", 0))
    native = latest_semantic_step_frame(events)
    native_offset = int(native.get("_event_offset", -1)) if native else -1
    if native is not None:
        source_offset = semantic_step_frame_source_offset(
            source, start_offset=start_offset, frame_id=str(native.get("frame_id", "")),
        )
        if source_offset >= 0:
            native_offset = source_offset
            # The activity-query frames use positions in the original native
            # log.  Keep the returned semantic frame in that same coordinate
            # system: the filtered run-owned copy omits intervening native
            # output and therefore cannot prove a fresh activity return.
            native["_event_offset"] = source_offset
    latest_activity = read_latest_activity_query_trace(source, start_offset)
    active_activity = read_active_activity_query_trace(source, start_offset)
    if native is not None and active_activity is not None and \
            native.get("state") == "activity_distraction" and \
            native.get("producer") == "activity_distraction_query" and \
            int(active_activity.get("event_offset", -1)) <= native_offset:
        # The native frame is emitted immediately after the native query-open
        # trace, so it owns the observation and turn.  The trace only supplies
        # the interruption classification; never borrow observation fields
        # from it or from an earlier world frame.
        native["provenance"] = "native_activity_distraction_query"
        native["observation_provenance"] = "native_semantic_step_trace"
        native["activity_type"] = str(active_activity.get("type", ""))
        native["calendar_time_source"] = "native_activity_distraction_query"
        native["activity_query_offset"] = int(active_activity["event_offset"])
        native["_kind"] = "activity"
        return native
    activity_offset = int(latest_activity.get("event_offset", -1)) if latest_activity else -1
    if active_activity is not None and activity_offset >= native_offset:
        event_offset = int(active_activity["event_offset"])
        return {
            "run_id": run_id,
            "frame_id": f"{run_id}:activity:{event_offset}",
            "state": "activity_distraction",
            "observed_turn": None,
            "valid_actions": [
                "activity.stop", "activity.continue", "activity.manage", "activity.ignore",
            ],
            "action_inputs": {
                "activity.stop": "Y", "activity.continue": "N",
                "activity.manage": "M", "activity.ignore": "I",
            },
            "provenance": "native_activity_distraction_query",
            "activity_type": str(active_activity.get("type", "")),
            "game_minutes": active_activity.get("game_minutes"),
            "calendar_time_source": "native_activity_distraction_query"
            if isinstance(active_activity.get("game_minutes"), int) else "",
            "_event_offset": event_offset,
            "_kind": "activity",
        }
    if latest_activity is not None and latest_activity.get("event") == "return" and \
            activity_offset > native_offset and \
            (native is None or native.get("state") != "world"):
        return {
            "run_id": run_id,
            "frame_id": f"{run_id}:activity-return:{activity_offset}",
            "state": "activity_stopped" if latest_activity.get("action") == "YES" else "activity_resumed",
            "observed_turn": None,
            "valid_actions": [],
            "action_inputs": {},
            "provenance": "native_activity_distraction_return",
            "resolved_action": str(latest_activity.get("action", "")),
            "_event_offset": activity_offset,
            "_kind": "activity_return",
        }
    active_semantic_ui = read_active_semantic_ui_trace(
        source, start_offset, run_id=run_id,
    )
    if active_semantic_ui is not None and \
            int(active_semantic_ui.get("event_offset", -1)) >= native_offset:
        semantic_actions = active_semantic_ui.get("valid_actions", [])
        if semantic_actions != ["space"] or \
                active_semantic_ui.get("intent") != "eoc_popup":
            raise ValueError("the active semantic UI has no approved public action")
        event_offset = int(active_semantic_ui["event_offset"])
        return {
            "run_id": run_id,
            "frame_id": f"{run_id}:semantic-ui:{active_semantic_ui['instance_id']}:{event_offset}",
            "state": "semantic_ui",
            "observed_turn": None,
            "valid_actions": ["modal.acknowledge"],
            "action_inputs": {"modal.acknowledge": "space"},
            "provenance": "native_semantic_ui_trace",
            "semantic_ui": active_semantic_ui,
            "keep_watch_safety": {
                "classification": "safe_prompt",
                "monster": False,
                "danger": False,
                "damage": False,
                "action_id": "modal.acknowledge",
                "recovery": {"modal_id": str(active_semantic_ui["instance_id"] )},
            },
            "safe_recovery": {
                "modal_id": str(active_semantic_ui["instance_id"]),
                "actions": ["modal.acknowledge"],
                # The scheduled safe-popup fixture's one EOC interruption
                # opens this native query only after the popup acknowledgement.
                # It is an explicit one-use continuation, not a general
                # permission to resolve activity distractions.
                "activity_bridge": {"type": "eoc", "action_id": "activity.continue"},
            },
            "_event_offset": event_offset,
            "_kind": "semantic_ui",
        }
    if native is None:
        raise ValueError("the current run has not emitted a semantic frame")
    native["provenance"] = "native_semantic_step_trace"
    native["_kind"] = "semantic_step"
    return native


def latest_semantic_game_minutes_marker(
    *, profile: str, run_dir: Path, run_id: str, start_offset: int,
) -> Optional[int]:
    """Read only the bound native semantic frame's explicit calendar marker."""
    _, owned = refresh_semantic_step_trace(
        profile=profile, run_dir=run_dir, run_id=run_id, start_offset=start_offset,
    )
    events, status = read_semantic_step_trace(owned, Path(run_dir), run_id)
    if status != "ok":
        return None
    return latest_semantic_game_minutes(events)


def open_cockpit_game_service(
    *, profile: str, run_dir: Path, run_id: str, trace_start_offset: int,
    pid: Optional[int] = None, session_id: str = "",
    transition_timeout_seconds: float = 10.0, observe_interval_seconds: float = 0.1,
    live_session: bool = False, cleanup_on_finish: bool = True,
    proof_step_label: str = "", proof_step_index: Optional[int] = None,
    r019_timed_entry: Optional[Mapping[str, Any]] = None,
    diagnostic_terminal: Optional[Mapping[str, Any]] = None,
    witness_charter: Optional[Mapping[str, Any]] = None,
    witness_identity: Optional[Mapping[str, Any]] = None,
    witness_evidence_ceiling: str = "focused",
    causal_boundary_precondition: Optional[Callable[[], Mapping[str, Any]]] = None,
    allowed_live_operations: Optional[set[str]] = None,
) -> Any:
    """Open the harness-gated public game observer/actor for one native run."""
    from cockpit import CockpitRunChannel, CockpitService

    # A connected client consumes the frame it has observed.  Keeping that
    # watermark at the native source means a later refresh reads the issuing
    # frame and only its unconsumed successors, rather than re-materializing
    # the whole current-run history on every observation.  The existing cap
    # still rejects an overfull unconsumed window.
    semantic_cursor = {"offset": trace_start_offset}
    latest_frame: Dict[str, Mapping[str, Any]] = {}

    def read_frame() -> Mapping[str, Any]:
        source = semantic_step_source_trace(profile)
        cursor = semantic_step_effective_source_offset(
            source, int(semantic_cursor["offset"]),
        )
        try:
            frame = current_semantic_step_frame(
                profile=profile, run_dir=run_dir, run_id=run_id,
                start_offset=cursor,
            )
        except ValueError as exc:
            # A recipe may take its initial safety frame and then immediately
            # request its action observation.  Until native dispatch creates a
            # successor, the current frame remains the only authoritative
            # state; do not invent a missing-frame failure from that no-op
            # re-observation.
            if str(exc) == "the current run has not emitted a semantic frame" and latest_frame:
                return dict(latest_frame["value"])
            raise
        frame_offset = frame.get("_event_offset")
        if isinstance(frame_offset, int) and frame_offset >= 0:
            # ``current_semantic_step_frame`` locates a frame at the byte that
            # starts its marker.  Resume after the complete native log line:
            # starting within the marker would make the trace reader discard
            # the partial line, while restarting at the marker rematerializes
            # the consumed frame and hides its successor.
            try:
                with source.open("rb") as source_file:
                    source_file.seek(frame_offset)
                    semantic_cursor["offset"] = frame_offset + len(source_file.readline())
            except OSError:
                semantic_cursor["offset"] = frame_offset + 1
        else:
            semantic_cursor["offset"] = cursor
        latest_frame["value"] = dict(frame)
        return frame

    def await_native_completion(activity_frame_id: str) -> None:
        deadline = time.monotonic() + transition_timeout_seconds
        while time.monotonic() <= deadline:
            frame = read_frame()
            if str(frame.get("frame_id", "")) != activity_frame_id:
                return
            time.sleep(observe_interval_seconds)
        raise ValueError("native wait completion did not emit a successor frame")

    dispatch = None
    if pid is not None and pid > 0 and session_id:
        def dispatch(frame: Mapping[str, Any], action_id: str) -> Mapping[str, Any]:
            return execute_semantic_act(
                run_dir=run_dir, profile=profile, run_id=run_id,
                trace_start_offset=int(semantic_cursor["offset"]), pid=pid, session_id=session_id,
                frame_id=str(frame.get("frame_id", "")), action_id=action_id,
                transition_timeout_seconds=transition_timeout_seconds,
                observe_interval_seconds=observe_interval_seconds, observed_frame=frame,
            )

    binding_path = Path( run_dir ) / RUNTIME_BINDING_FILENAME
    binding_id = sha256_file( binding_path )[0] if binding_path.is_file() else ""

    def read_binding_id() -> str:
        return sha256_file( binding_path )[0] if binding_path.is_file() else ""

    def mutate_binding_for_control() -> Mapping[str, Any]:
        """Perform the declared disposable R-019 drift mutation and receipt it."""
        before = read_binding_id()
        if not before:
            return {}
        try:
            binding = json.loads(binding_path.read_text(encoding="utf-8"))
        except (OSError, UnicodeDecodeError, json.JSONDecodeError):
            return {}
        if not isinstance(binding, Mapping):
            return {}
        changed = dict(binding)
        changed["r019_controlled_binding_drift"] = {
            "schema": "caol-r019-supported-binding-drift-v1",
            "run_id": run_id,
            "effect": "disposable_control_only",
        }
        write_json(binding_path, changed)
        after = read_binding_id()
        if not after or after == before:
            return {}
        return {
            "schema": "caol-r019-supported-binding-drift-v1",
            "binding_identity": "runtime_binding",
            "before_hash": before,
            "after_hash": after,
            "effect": "disposable_control_only",
        }

    def read_evidence() -> Mapping[str, Any]:
        return compact_cockpit_live_evidence(
            Path( run_dir ), run_id, profile=profile, pid=pid or 0,
        )

    finalizer = None
    if live_session:
        if pid is None or pid <= 0:
            raise ValueError( "a live cockpit session requires its owned game pid" )

        def finalizer(report: Mapping[str, Any]) -> Mapping[str, Any]:
            return finalize_cockpit_live_session(
                Path( run_dir ), pid, report, cleanup_process=cleanup_on_finish,
            )

    channel = CockpitRunChannel(
        read_frame, dispatch,
        read_evidence=read_evidence,
        binding_id=binding_id,
        read_binding_id=read_binding_id if binding_id else None,
        mutate_binding_for_control=mutate_binding_for_control if binding_id else None,
        finalize_session=finalizer,
        await_native_completion=await_native_completion,
        enforce_continuation_bounds=live_session,
        proof_step_label=proof_step_label,
        proof_step_index=proof_step_index,
        r019_timed_entry=r019_timed_entry,
        diagnostic_terminal=diagnostic_terminal,
        witness_charter=witness_charter,
        witness_identity=witness_identity,
        witness_evidence_ceiling=witness_evidence_ceiling,
        causal_boundary_precondition=causal_boundary_precondition,
    )
    service = CockpitService( run_channel=channel, allowed_live_operations=allowed_live_operations )
    service.live_channel = channel
    return service


def _read_jsonl_objects(path: Path) -> List[Dict[str, Any]]:
    values: List[Dict[str, Any]] = []
    if not path.is_file():
        return values
    for line in path.read_text( encoding="utf-8" ).splitlines():
        try:
            value = json.loads( line )
        except json.JSONDecodeError:
            continue
        if isinstance( value, dict ):
            values.append( value )
    return values


def compact_cockpit_live_evidence(
    run_dir: Path, run_id: str, *, profile: str = "", pid: int = 0,
) -> Dict[str, Any]:
    """Return bounded semantic facts, never raw logs, for one live decision."""
    receipts = [
        item for item in _read_jsonl_objects( run_dir / "semantic.steps.jsonl" )
        if str( item.get( "run_id", "" ) ) == str( run_id )
    ]
    transitions = [
        item for item in _read_jsonl_objects( run_dir / "transition.events.jsonl" )
        if str( item.get( "run_id", "" ) ) == str( run_id )
    ]
    first_rejected = next((item for item in receipts if item.get( "accepted" ) is not True), None)
    latest_receipt = receipts[-1] if receipts else None
    latest_transition = transitions[-1] if transitions else None
    actor_owners: List[Dict[str, Any]] = []
    if isinstance( latest_transition, Mapping ):
        raw_actors = latest_transition.get( "actor_ids", latest_transition.get( "member_ids", [] ) )
        if isinstance( raw_actors, list ):
            owner = str(
                latest_transition.get( "simulation_owner",
                                       latest_transition.get( "next_owner", "unknown" ) )
            )
            actor_owners = [
                {"actor_id": str(actor), "owner": owner} for actor in raw_actors
            ]
    compact_receipt = None
    if isinstance( latest_receipt, Mapping ):
        compact_receipt = {
            "action_id": str( latest_receipt.get( "action_id", "" ) ),
            "accepted": latest_receipt.get( "accepted" ) is True,
            "frame_id": str( latest_receipt.get( "frame_id", "" ) ),
            "next_frame_id": str(
                latest_receipt.get( "next_frame", {} ).get( "frame_id", "" )
                if isinstance( latest_receipt.get( "next_frame" ), Mapping ) else ""
            ),
        }
    compact_transition = None
    if isinstance( latest_transition, Mapping ):
        compact_transition = {
            "sequence": latest_transition.get( "sequence" ),
            "kind": str( latest_transition.get( "kind", latest_transition.get( "event", "" ) ) ),
            "outcome": str( latest_transition.get( "outcome", "" ) ),
            "game_minutes": latest_transition.get( "game_minutes" ),
        }
    contradictory: List[Dict[str, Any]] = []
    if isinstance( first_rejected, Mapping ):
        contradictory.append({
            "kind": "rejected_native_receipt",
            "action_id": str( first_rejected.get( "action_id", "" ) ),
            "reason": str( first_rejected.get( "reason", "" ) ),
        })
    scheduler_trace = read_scheduler_trace(profile, run_id) if profile else []
    child_resources = sample_child_resources(pid) if pid > 0 else {
        "pid": None,
        "platform": r009_host_platform(),
        "cpu_percent": {"status": "unavailable", "value": None,
                        "reason": "the live game pid was unavailable"},
        "resident_memory": {"status": "unavailable", "value": None,
                            "reason": "the live game pid was unavailable"},
    }
    return {
        "receipt_count": len( receipts ),
        "latest_receipt": compact_receipt,
        "first_divergence": contradictory[0] if contradictory else None,
        "contradictory_evidence": contradictory,
        "latest_transition": compact_transition,
        "actor_owners": actor_owners,
        "persistence": (
            "confirmed" if isinstance( latest_transition, Mapping ) and
            latest_transition.get( "persistence_acknowledged" ) is True else "unavailable"
        ),
        "evidence_refs": [
            *( [f"semantic.steps.jsonl#receipt={len( receipts )}"] if receipts else [] ),
            *( [f"transition.events.jsonl#sequence={compact_transition['sequence']}"]
               if compact_transition is not None else [] ),
        ],
        "scheduler_trace": scheduler_trace,
        "child_resources": child_resources,
    }


def finalize_cockpit_live_session(
    run_dir: Path, pid: int, report: Mapping[str, Any], *, cleanup_process: bool = True,
) -> Dict[str, Any]:
    """Persist one immutable terminal report and clean only the bound process."""
    final_path = run_dir / "cockpit.live.final.json"
    if final_path.exists():
        return {"cleanup": {"status": "rejected_existing_final_report"}}
    cleanup = cleanup_game_process( pid ) if cleanup_process else {
        "status": "deferred_to_scenario_terminalization",
        "pid": pid,
    }
    payload = {**dict( report ), "cleanup": cleanup}
    ensure_dir( final_path.parent )
    with final_path.open( "x", encoding="utf-8" ) as stream:
        json.dump( payload, stream, indent=2, ensure_ascii=False )
        stream.write( "\n" )
    return {
        "cleanup": cleanup,
        "final_report_ref": final_path.name,
    }


def serve_cockpit_live(service: Any, input_stream: Any, output_stream: Any) -> int:
    """Serve public live-session requests without a harness-owned time window."""
    finished = False
    for line in input_stream:
        try:
            request = json.loads( line )
        except json.JSONDecodeError as exc:
            result = {"ok": False, "error": f"invalid request json: {exc.msg}"}
        else:
            result = service.call( request ) if isinstance( request, Mapping ) else {
                "ok": False, "error": "request must be an object",
            }
        print( json.dumps( result, ensure_ascii=False ), file=output_stream, flush=True )
        state = service.run_channel.status()
        if state["state"] == "finished":
            finished = True
            break
    if not finished:
        result = service.run_channel.close_unfinished()
        print( json.dumps( result, ensure_ascii=False ), file=output_stream, flush=True )
        return 1
    return 0


def run_cockpit_live(args: argparse.Namespace) -> int:
    """Serve one live worker-owned JSONL session until explicit finish or fail-closed EOF."""
    run_dir = Path( args.run_dir )
    service = open_cockpit_game_service(
        profile=args.profile,
        run_dir=run_dir,
        run_id=args.run_id,
        trace_start_offset=args.trace_start_offset,
        pid=args.pid,
        session_id=args.session_id,
        transition_timeout_seconds=args.transition_timeout_seconds,
        observe_interval_seconds=args.observe_interval_seconds,
        live_session=True,
    )
    return serve_cockpit_live( service, sys.stdin, sys.stdout )


def cockpit_observation_advertises_action(
    observation: Mapping[str, Any], action_id: str,
) -> bool:
    """Read the public cockpit action vocabulary without renaming its field."""
    return action_id in observation.get( "advertised_actions", [] )


def await_cockpit_advertised_action(
    service: Any,
    *,
    action_id: str,
    prior_observation_id: str,
    timeout_seconds: float,
    observe_interval_seconds: float,
) -> Dict[str, Any]:
    """Wait without input for one fresh, native-advertised interruption action."""
    deadline = time.monotonic() + timeout_seconds
    observations = 0
    last_error = ""
    while time.monotonic() <= deadline:
        observed = service.call( {"action": "game.observe"} )
        observations += 1
        if observed.get( "ok" ) is not True:
            last_error = str( observed.get( "error", "native_observation_unavailable" ) )
        else:
            result = observed.get( "result", {} )
            if isinstance( result, Mapping ) and \
                    str( result.get( "observation_id", "" ) ) != prior_observation_id and \
                    cockpit_observation_advertises_action( result, action_id ):
                interruption = result.get( "active_interruption" )
                if isinstance( interruption, Mapping) and \
                        str( interruption.get( "id", "" ) ) == str( result.get( "observation_id", "" ) ) and \
                        str( interruption.get( "type", "" ) ):
                    return {
                        "ok": True,
                        "observation": dict( result ),
                        "interruption": dict( interruption ),
                        "observations": observations,
                    }
                last_error = "advertised_action_has_no_current_native_interruption_identity"
            elif isinstance( result, Mapping ):
                last_error = "expected_final_action_not_advertised"
        time.sleep( observe_interval_seconds )
    return {
        "ok": False,
        "error": last_error or "expected_final_action_not_advertised",
        "observations": observations,
    }


def dispatch_semantic_input(
    pid: int, binding: str, *, delay_ms: int = 200, focus_once: bool = False,
) -> None:
    """Deliver one native semantic binding after its focused text mode is live."""
    # A text-bound action such as the default wait key arrives as an SDL
    # keydown followed by SDL_TEXTINPUT.  Let the focused game process its
    # focus event before the text event, otherwise the keydown can be
    # interpreted by a stale keycode context (for example main menu) and
    # the advertised character reaches the wrong native UI.
    if len(binding) == 1 and is_printable_text_key(binding) and not binding.isalpha():
        focus = peekaboo_focus_pid(pid)
        if not focus.get("ok"):
            raise RuntimeError("Peekaboo semantic text focus failed: " + json.dumps(
                focus, ensure_ascii=False
            ))
        time.sleep(delay_ms / 1000.0)
        peekaboo_type_text(pid, binding, delay_ms=delay_ms, focus_pid=False)
        return
    peekaboo_press_sequence(pid, [binding], delay_ms=delay_ms, focus_once=focus_once)


def run_semantic_observe(args: argparse.Namespace) -> int:
    frame = current_semantic_step_frame(
        profile=args.profile, run_dir=Path(args.run_dir), run_id=args.run_id,
        start_offset=args.trace_start_offset,
    )
    public = {key: value for key, value in frame.items() if not key.startswith("_") and key != "action_inputs"}
    print(json.dumps(public, indent=2, ensure_ascii=False))
    return 0


def execute_semantic_act(
    *, run_dir: Path, profile: str, run_id: str, trace_start_offset: int,
    pid: int, session_id: str, frame_id: str, action_id: str,
    transition_timeout_seconds: float, observe_interval_seconds: float,
    observed_frame: Optional[Mapping[str, Any]] = None,
    delay_ms: int = 200,
) -> Dict[str, Any]:
    """Apply one advertised action from its issuing run-bound frame."""
    run_dir = Path(run_dir).resolve()
    diagnostic_enabled = (
        ( run_dir / WAIT_DIAGNOSTIC_ACTIVATION_FILENAME ).exists() or
        ( run_dir / WAIT_DIAGNOSTIC_RECORDS_FILENAME ).exists()
    ) and action_id.startswith( "wait." )
    diagnostic_request_id = f"cockpit:{session_id}:{frame_id}:{action_id}"
    diagnostic_trace_offset = -1

    if diagnostic_enabled:
        diagnostic_before_input = append_wait_diagnostic_record(
            run_dir,
            wait_diagnostic_request_record(
                run_id=run_id,
                request_id=diagnostic_request_id,
                phase="before_input",
                semantic_frame=frame_id,
                pid=pid,
            ),
        )
        if diagnostic_before_input.get( "status" ) != "retained":
            return {
                "accepted": False,
                "reason": "wait_diagnostic_before_input_unretained",
                "wait_diagnostic_before_input": diagnostic_before_input,
            }

    def read_frame() -> Mapping[str, Any]:
        return current_semantic_step_frame(
            profile=profile, run_dir=run_dir, run_id=run_id,
            start_offset=trace_start_offset,
        )

    before = dict(observed_frame) if observed_frame is not None else dict(read_frame())
    before_offset = int(before.get("_event_offset", -1))
    activity_open_offset = int(before.get("activity_query_offset", before_offset))
    activity_receipt_start_offset = min(trace_start_offset, activity_open_offset)
    expected_activity_actions = {
        "activity.stop": "YES", "activity.continue": "NO",
        "activity.manage": "MANAGER", "activity.ignore": "IGNORE",
    }

    def send_input(binding: str) -> None:
        nonlocal diagnostic_trace_offset
        if diagnostic_enabled:
            source_trace = semantic_step_source_trace(profile)
            try:
                diagnostic_trace_offset = source_trace.stat().st_size
            except OSError:
                diagnostic_trace_offset = 0
        # The activity prompt has a short native lifetime.  Its issuing frame
        # remains the sole authority, so deliver its advertised physical input
        # through one focus handoff rather than a second focus/dispatch round.
        dispatch_semantic_input(
            pid, binding, delay_ms=delay_ms,
            focus_once=before.get("_kind") == "activity",
        )

    def await_transition(frame_id: str, action_id: str) -> Mapping[str, Any]:
        deadline = time.monotonic() + transition_timeout_seconds
        while time.monotonic() <= deadline:
            candidate = dict(read_frame())
            candidate_offset = int(candidate.get("_event_offset", -1))
            if before.get("_kind") == "activity":
                latest = read_latest_activity_query_trace(
                    semantic_step_source_trace(profile), activity_receipt_start_offset,
                    issuing_open_offset=activity_open_offset,
                )
                expected = expected_activity_actions.get(action_id, "")
                if latest is not None and latest.get("event") == "return" and \
                        latest.get("issuing_open_offset") == activity_open_offset and \
                        latest.get("action") == expected and candidate_offset > before_offset:
                    response = {
                        "frame_id": frame_id,
                        "action_id": action_id,
                        "accepted": True,
                        "kind": "activity_distraction_return",
                        "resolved_action": expected,
                        "event_offset": int(latest.get("event_offset", -1)),
                    }
                    return {
                        "native_receipt": {
                            "frame_id": frame_id, "action_id": action_id, "accepted": True,
                            "resolved_action": expected,
                        },
                        "semantic_response": response,
                        "next_frame": candidate,
                    }
            elif before.get("_kind") == "semantic_ui":
                semantic_ui = before.get("semantic_ui", {})
                instance_id = str(semantic_ui.get("instance_id", "")) if isinstance(
                    semantic_ui, Mapping
                ) else ""
                progress = read_active_semantic_ui_trace(
                    semantic_step_source_trace(profile), trace_start_offset,
                    include_progress=True, run_id=run_id,
                )
                if instance_id and progress is not None and \
                        progress.get("event") == "progress" and \
                        progress.get("instance_id") == instance_id and \
                        int(progress.get("event_offset", -1)) > before_offset:
                    response = {
                        "frame_id": frame_id,
                        "action_id": action_id,
                        "accepted": True,
                        "kind": "semantic_ui_progress",
                        "event_offset": int(progress["event_offset"]),
                    }
                    return {
                        "native_receipt": {
                            "frame_id": frame_id,
                            "action_id": action_id,
                            "accepted": True,
                            "semantic_ui_instance_id": instance_id,
                        },
                        "semantic_response": response,
                        "next_frame": candidate,
                    }
            else:
                source, owned = refresh_semantic_step_trace(
                    profile=profile, run_dir=run_dir,
                    run_id=run_id, start_offset=trace_start_offset,
                )
                effective_source_offset = semantic_step_effective_source_offset(
                    source, trace_start_offset,
                )
                events, status = read_semantic_step_trace(owned, run_dir, run_id)
                if status != "ok":
                    raise ValueError(f"semantic step trace is unavailable: {status}")
                for event in events:
                    event["_event_offset"] = effective_source_offset + int(
                        event.get("_event_offset", 0)
                    )
                receipt = next((
                    event for event in events
                    if event.get("event") == "receipt"
                    and event.get("frame_id") == frame_id
                    and event.get("action_id") == action_id
                ), None)
                if receipt is not None and candidate_offset > int(receipt.get("_event_offset", -1)):
                    return {
                        "native_receipt": receipt,
                        "semantic_response": {
                            "frame_id": frame_id,
                            "action_id": action_id,
                            "accepted": receipt.get("accepted") is True,
                            "kind": "semantic_step_receipt",
                            "event_offset": int(receipt.get("_event_offset", -1)),
                        },
                        "next_frame": candidate,
                    }
            time.sleep(observe_interval_seconds)
        return {}

    channel = SemanticStepChannel(
        run_id=run_id, session_id=session_id,
        receipt_path=run_dir / "semantic.steps.jsonl", read_frame=read_frame,
    )
    receipt = channel.act_observed(
        observed_frame=before,
        frame_id=frame_id, action_id=action_id,
        send_input=send_input, await_transition=await_transition,
    )
    if diagnostic_enabled:
        diagnostic_result = append_wait_diagnostic_record(
            run_dir,
            wait_diagnostic_request_record(
                run_id=run_id,
                request_id=diagnostic_request_id,
                phase="result",
                semantic_frame=frame_id,
                pid=pid,
                trace=classify_wait_input_trace(
                    semantic_step_source_trace( profile ),
                    diagnostic_trace_offset if diagnostic_trace_offset >= 0 else trace_start_offset,
                    run_id=run_id,
                ),
            ),
        )
        receipt["wait_diagnostic_before_input"] = diagnostic_before_input
        receipt["wait_diagnostic_result"] = diagnostic_result
        if diagnostic_result.get( "status" ) != "retained":
            receipt["accepted"] = False
            receipt["reason"] = "wait_diagnostic_result_unretained"
    return receipt


def run_semantic_act(args: argparse.Namespace) -> int:
    receipt = execute_semantic_act(
        run_dir=Path(args.run_dir), profile=args.profile, run_id=args.run_id,
        trace_start_offset=args.trace_start_offset, pid=args.pid,
        session_id=args.session_id, frame_id=args.frame_id, action_id=args.action_id,
        transition_timeout_seconds=args.transition_timeout_seconds,
        observe_interval_seconds=args.observe_interval_seconds, delay_ms=args.delay_ms,
    )
    print(json.dumps(receipt, indent=2, ensure_ascii=False))
    return 0 if receipt.get("accepted") else 2


def advance_turns(
    pid: int,
    count: int,
    *,
    run_dir: Optional[Path] = None,
    label: str = "advance_turns",
    action_trace_log: Optional[Path] = None,
    auto_acknowledge_interruptions: bool = True,
    max_acknowledgements: int = DEFAULT_ADVANCE_TURNS_MAX_AUTO_ACKNOWLEDGEMENTS,
    portal_storm_allowed: bool = False,
) -> Dict[str, Any]:
    timing: Dict[str, Any] = {
        "count": max(count, 0),
        "batch_size": 20,
        "batches": [],
        "total_duration_seconds": 0.0,
        "avg_turn_ms": 0.0,
        "max_batch_duration_seconds": 0.0,
        "max_batch_turn_ms": 0.0,
        "status": "completed" if count > 0 else "no_turns_requested",
        "pause_dispatch_verification": bool(action_trace_log),
        "acknowledgement_count": 0,
        "release_blocking": False,
        "contaminating": False,
        "portal_storm_allowed": portal_storm_allowed,
    }
    if count <= 0:
        return timing

    batch_size = timing["batch_size"]
    for start in range(0, count, batch_size):
        batch_count = min(batch_size, count - start)
        batch_log_start = (
            action_trace_log.stat().st_size
            if action_trace_log is not None and action_trace_log.exists()
            else 0
        )
        started_at = time.perf_counter()
        accepted_count = 0
        attempts: List[Dict[str, Any]] = []
        interruption_reports: List[Dict[str, Any]] = []
        while accepted_count < batch_count:
            missing_count = batch_count - accepted_count
            peekaboo_press_sequence(pid, ["."] * missing_count, focus_once=True)
            if action_trace_log is not None:
                observed_count = wait_for_pause_dispatch_count(
                    action_trace_log,
                    batch_log_start,
                    batch_count,
                )
            else:
                observed_count = batch_count
            observed_count = min(observed_count, batch_count)
            accepted_this_attempt = max(0, observed_count - accepted_count)
            accepted_count = observed_count
            attempts.append({
                "sent_count": missing_count,
                "accepted_pause_dispatch_count": accepted_this_attempt,
                "cumulative_accepted_pause_dispatch_count": accepted_count,
            })
            if accepted_count >= batch_count:
                break
            if not auto_acknowledge_interruptions or run_dir is None:
                timing["status"] = "blocked_missing_pause_dispatches"
                break
            if timing["acknowledgement_count"] >= max_acknowledgements:
                timing["status"] = "blocked_acknowledgement_limit"
                break

            dispatches_before_recovery = (
                count_pause_dispatches_since(action_trace_log, batch_log_start)
                if action_trace_log is not None
                else accepted_count
            )
            interruption = acknowledge_blocking_interruptions(
                pid,
                run_dir,
                (
                    f"{label}.batch_{len(timing['batches']) + 1:02d}"
                    f".attempt_{len(attempts):02d}"
                ),
                max_acknowledgements=max_acknowledgements - timing["acknowledgement_count"],
                stop_on_unknown=True,
                continue_after_contaminating=portal_storm_allowed,
                persist_clear_scan=True,
                semantic_ui_trace_log=action_trace_log,
                semantic_ui_trace_start_offset=batch_log_start,
                semantic_ui_expectation={"intent": "eoc_popup", "action": "space"},
            )
            interruption_reports.append(interruption)
            dispatches_after_recovery = (
                count_pause_dispatches_since(action_trace_log, batch_log_start)
                if action_trace_log is not None
                else dispatches_before_recovery
            )
            if dispatches_after_recovery > dispatches_before_recovery:
                interruption["recovery_pause_dispatch_delta"] = (
                    dispatches_after_recovery - dispatches_before_recovery
                )
                timing["status"] = "blocked_recovery_key_reached_gameplay"
                break
            acknowledged = int(interruption.get("acknowledgement_count", 0) or 0)
            timing["acknowledgement_count"] += acknowledged
            timing["release_blocking"] = timing["release_blocking"] or bool(
                interruption.get("release_blocking", False)
            )
            timing["contaminating"] = timing["contaminating"] or bool(
                interruption.get("contaminating", False)
            )
            interruption_status = str(interruption.get("status", "unobservable"))
            if timing["release_blocking"]:
                timing["status"] = "blocked_release_blocking_interruption"
                break
            if timing["contaminating"] and not portal_storm_allowed:
                timing["status"] = "blocked_contaminating_interruption"
                break
            if interruption_status.startswith("blocked_"):
                timing["status"] = interruption_status
                break
            if acknowledged <= 0:
                if interruption_status.startswith("blocked_"):
                    timing["status"] = interruption_status
                elif interruption_status == "clear":
                    timing["status"] = "blocked_unclassified_transient_interruption"
                else:
                    timing["status"] = f"blocked_missing_pause_dispatches_{interruption_status}"
                break

        duration = time.perf_counter() - started_at
        final_batch = start + batch_count >= count
        if timing["status"] == "completed" and final_batch and \
                auto_acknowledge_interruptions and run_dir is not None:
            dispatches_before_boundary = (
                count_pause_dispatches_since(action_trace_log, batch_log_start)
                if action_trace_log is not None
                else accepted_count
            )
            boundary_interruption = acknowledge_blocking_interruptions(
                pid,
                run_dir,
                f"{label}.batch_{len(timing['batches']) + 1:02d}.boundary",
                max_acknowledgements=max_acknowledgements - timing["acknowledgement_count"],
                stop_on_unknown=True,
                continue_after_contaminating=portal_storm_allowed,
                semantic_ui_trace_log=action_trace_log,
                semantic_ui_trace_start_offset=batch_log_start,
                semantic_ui_expectation={"intent": "eoc_popup", "action": "space"},
            )
            interruption_reports.append(boundary_interruption)
            dispatches_after_boundary = (
                count_pause_dispatches_since(action_trace_log, batch_log_start)
                if action_trace_log is not None
                else dispatches_before_boundary
            )
            if dispatches_after_boundary > dispatches_before_boundary:
                boundary_interruption["recovery_pause_dispatch_delta"] = (
                    dispatches_after_boundary - dispatches_before_boundary
                )
                timing["status"] = "blocked_recovery_key_reached_gameplay"
            boundary_acknowledged = int(
                boundary_interruption.get("acknowledgement_count", 0) or 0
            )
            timing["acknowledgement_count"] += boundary_acknowledged
            timing["release_blocking"] = timing["release_blocking"] or bool(
                boundary_interruption.get("release_blocking", False)
            )
            timing["contaminating"] = timing["contaminating"] or bool(
                boundary_interruption.get("contaminating", False)
            )
            boundary_status = str(boundary_interruption.get("status", "unobservable"))
            if timing["status"] == "blocked_recovery_key_reached_gameplay":
                pass
            elif timing["release_blocking"]:
                timing["status"] = "blocked_release_blocking_interruption"
            elif timing["contaminating"] and not portal_storm_allowed:
                timing["status"] = "blocked_contaminating_interruption"
            elif boundary_status.startswith("blocked_"):
                timing["status"] = boundary_status

        batch = {
            "start_turn": start + 1,
            "count": batch_count,
            "accepted_pause_dispatch_count": accepted_count,
            "attempts": attempts,
            "interruption_reports": interruption_reports,
            "duration_seconds": round(duration, 6),
            "per_turn_ms": round((duration / batch_count) * 1000.0, 3),
        }
        timing["batches"].append(batch)
        timing["total_duration_seconds"] += duration
        timing["max_batch_duration_seconds"] = max(timing["max_batch_duration_seconds"], duration)
        timing["max_batch_turn_ms"] = max(timing["max_batch_turn_ms"], batch["per_turn_ms"])
        if timing["status"] != "completed":
            timing["abort"] = {
                "status": timing["status"],
                "batch": len(timing["batches"]),
                "accepted_pause_dispatch_count": accepted_count,
                "requested_pause_dispatch_count": batch_count,
            }
            break
        if start + batch_size < count:
            time.sleep(0.05)

    if timing["status"] != "completed" and "abort" not in timing:
        timing["abort"] = {
            "status": timing["status"],
            "batch": len(timing["batches"]),
            "accepted_pause_dispatch_count": sum(
                int(batch.get("accepted_pause_dispatch_count", 0) or 0)
                for batch in timing["batches"]
            ),
            "requested_pause_dispatch_count": count,
        }

    timing["total_duration_seconds"] = round(timing["total_duration_seconds"], 6)
    accepted_total = sum(int(batch.get("accepted_pause_dispatch_count", 0) or 0) for batch in timing["batches"])
    timing["accepted_pause_dispatch_count"] = accepted_total
    timing["avg_turn_ms"] = round(
        (timing["total_duration_seconds"] / max(1, accepted_total)) * 1000.0,
        3,
    )
    timing["max_batch_duration_seconds"] = round(timing["max_batch_duration_seconds"], 6)
    return timing


LONG_WAIT_MENU_CHOICES = {
    "1": "20s",
    "2": "1m",
    "3": "5m",
    "4": "30m",
    "5": "1h",
    "6": "2h",
    "7": "3h",
    "8": "6h",
    "d": "daylight",
    "n": "noon",
    "k": "night",
    "m": "midnight",
    "W": "weather",
}

PLAYTEST_DANGER_HANDLING_MODES = {
    "stop_on_interruption",
    "handle_classified_non_dangerous",
    "ignore_danger_and_interruptions",
}


def normalize_playtest_danger_handling(value: Any, *, legacy_ignore: Optional[bool] = None) -> str:
    """Return one explicit playtest danger policy; ordinary use stays cautious."""
    if value is None or str(value).strip() == "":
        if legacy_ignore is not None:
            return "ignore_danger_and_interruptions" if legacy_ignore else "stop_on_interruption"
        return "stop_on_interruption"
    mode = str(value).strip()
    if mode not in PLAYTEST_DANGER_HANDLING_MODES:
        raise ValueError(f"unsupported playtest danger handling mode: {mode}")
    return mode


def is_retained_hostile_auto_move_cancelled_hud_message(
    screen_text_report: Dict[str, Any],
) -> bool:
    """Recognize the resolved hostile auto-move message only on a live HUD.

    The game retains this message in the log after the modal has been answered.
    It is not safe-mode UI and must not turn a completed wait into a synthetic
    prompt; a current modal or a HUD-less partial OCR remains fail-closed.
    """
    body = screen_text_body( screen_text_report )
    normalized = re.sub( r"[^a-z0-9]+", " ", body.lower() ).strip()
    has_resolved_message = (
        "hostile" in normalized
        and "survivor" in normalized
        and "spotted" in normalized
        and bool( re.search( r"(?:auto|huto) move", normalized ) )
        and bool( re.search( r"cancel(?:ed|led)?", normalized ) )
    )
    has_hud = all( marker in body for marker in ( "Move:", "Wield:" ) ) and bool(
        re.search( r"(?:activity|.ctivity)", normalized )
    ) and bool( re.search( r"\b(?:none|n(?:one)?)\b", normalized ) )
    has_modal = "cancel auto move" in normalized or "case sensitive" in normalized
    return has_resolved_message and has_hud and not has_modal


def is_hostile_auto_move_cancel_modal( screen_text_report: Dict[str, Any] ) -> bool:
    """Recognize the current case-sensitive hostile auto-move modal.

    OCR commonly separates the prompt over several lines and may label the
    spotted creature generically.  The action prompt and its case-sensitive
    marker are the stable modal contract; a retained cancellation log lacks
    both together.
    """
    normalized = re.sub(
        r"[^a-z0-9]+", " ", screen_text_body( screen_text_report ).lower()
    ).strip()
    return (
        (
            "cancel auto move" in normalized
            and "case" in normalized
            and "sensitive" in normalized
        ) or (
            ("spotted" in normalized or "spott" in normalized)
            and ("zombie" in normalized or "zomb" in normalized)
            and "waiting" not in normalized
        )
    )


def native_travel_stable_hud_markers( screen_text_report: Dict[str, Any] ) -> List[Dict[str, str]]:
    """Recognize the fixture's rendered HUD when labels are OCR-invisible.

    The recovery screenshot consistently exposes the clock and moon phase.
    Depending on the tileset's OCR pass, it also exposes either the right-panel
    status header or an idle activity label.  These markers are accepted only
    as a group and never when the case-sensitive hostile auto-move modal is live.
    """
    body = screen_text_body( screen_text_report )
    normalized = re.sub( r"[^a-z0-9: ]+", " ", body.lower() )
    if is_hostile_auto_move_cancel_modal( screen_text_report ):
        return []
    if "waxing crescent" not in normalized:
        return []
    if not re.search(
            r"\b\d{1,2}\s*[: ]\s*\d{2}(?:\s*[: ]\s*\d{1,2})?\s*(?:am|pm|[ah])\b",
            normalized,
    ):
        return []
    has_right_panel_header = re.search( r"\b\d+\s*\(?w\b", normalized ) or "hors" in normalized
    has_idle_activity = bool( re.search( r"(?:activity|.ctivit[yu])\s+none", normalized ) )
    if not has_right_panel_header and not has_idle_activity:
        return []
    return [
        {"pattern": "HORS", "line": "HORS", "source": "stable_fixture_hud_marker"},
        {"pattern": "waxing crescent", "line": "waxing crescent", "source": "stable_fixture_hud_marker"},
        {"pattern": "clock", "line": "clock", "source": "stable_fixture_hud_marker"},
    ]


def stabilize_native_travel_after_route_confirmation(
    pid: int,
    run_dir: Path,
    label: str,
    *,
    delay_ms: int,
    timeout_seconds: float,
    structured_event_reader: Optional[StructuredTransitionEventReader] = None,
    native_travel_boundary_reader: Optional[Callable[[], Dict[str, Any]]] = None,
    allow_hostile_auto_move_cancel: Optional[bool] = None,
    danger_handling: Optional[str] = None,
) -> Dict[str, Any]:
    """Stabilize native travel under one explicit, receipt-bearing danger policy.

    The default stops on interruption.  Classified mode handles only known
    non-dangerous interruptions.  Ignore mode may answer the exact native
    auto-move cancellation prompt with N and records that choice.  Unknown
    prompts remain terminal in every mode.
    """
    selected_danger_handling = normalize_playtest_danger_handling(
        danger_handling, legacy_ignore=allow_hostile_auto_move_cancel,
    )
    ignore_danger = selected_danger_handling == "ignore_danger_and_interruptions"
    if timeout_seconds < 0:
        raise ValueError("native_travel_stabilization requires nonnegative settle_seconds")
    if timeout_seconds == 0 and native_travel_boundary_reader is None:
        raise ValueError(
            "unbounded native_travel_stabilization requires a native completion boundary"
        )

    def capture_state(suffix: str) -> Tuple[Dict[str, Any], Dict[str, Any]]:
        capture = capture_screenshot(pid, run_dir, f"{label}.native_travel_stabilization.{suffix}")
        return capture, capture_screen_text_artifact(
            run_dir,
            f"{label}.native_travel_stabilization.{suffix}",
            capture,
            tail_lines=64,
        )

    acknowledgement_count = 0
    response_keys: List[str] = []
    handled_interruptions: List[Dict[str, Any]] = []
    observation_count = 0
    deadline = time.monotonic() + timeout_seconds if timeout_seconds > 0 else None

    def activity_none_matches(screen_text: Dict[str, Any]) -> List[Dict[str, str]]:
        matches = find_screen_text_matches(screen_text, ["Activity: None"])
        if matches:
            return matches
        json_path_value = str(screen_text.get("json_path", "")).strip()
        if json_path_value:
            try:
                payload = json.loads(Path(json_path_value).read_text(encoding="utf-8"))
            except Exception:
                payload = {}
            if isinstance(payload, dict):
                for row_text in spatial_ocr_row_texts(payload):
                    normalized_row = re.sub(r"[^a-z0-9]+", " ", row_text.lower()).strip()
                    if re.search(r"(?:activity|.ctivit[yu]) none", normalized_row):
                        return [{
                            "pattern": "Activity: None",
                            "line": row_text,
                            "source": "spatial_normalized_ocr_activity_none",
                        }]
        normalized_body = re.sub(
            r"[^a-z0-9]+", " ", screen_text_body(screen_text).lower()
        ).strip()
        if re.search(r"(?:activity|.ctivit[yu]) none", normalized_body):
            return [{
                "pattern": "Activity: None",
                "line": "Activity: None",
                "source": "normalized_ocr_activity_none",
            }]
        return []

    def is_nonblocking_wilderness_flavor_on_hud(
        interruption: Dict[str, Any], screen_text: Dict[str, Any],
    ) -> bool:
        # These exact classifiers are retained message-log flavor, not modals,
        # when the HUD remains visible.  Never acknowledge them: while travel is
        # active, keep observing; once idle, accept the recovered HUD.  All other
        # unknown or interactive surfaces retain the fail-closed route below.
        return (
            str(interruption.get("classification", "")) in {
                "shadow_warning_wilderness_flavor_popup",
                "partial_lifeless_grass_wilderness_flavor_popup",
            }
            and len(find_screen_text_matches(screen_text, ["Move:", "Wield:"])) == 2
            and not is_hostile_auto_move_cancel_modal(screen_text)
        )

    def is_noninteractive_wilderness_flavor_on_idle_hud(
        interruption: Dict[str, Any], screen_text: Dict[str, Any],
    ) -> bool:
        return is_nonblocking_wilderness_flavor_on_hud(
            interruption, screen_text,
        ) and bool(activity_none_matches(screen_text))

    def wait_for_next_observation() -> bool:
        if deadline is None:
            time.sleep(delay_ms / 1000.0)
            return True
        remaining_seconds = deadline - time.monotonic()
        if remaining_seconds <= 0:
            return False
        time.sleep(min(delay_ms / 1000.0, remaining_seconds))
        return time.monotonic() <= deadline

    wait_for_next_observation()
    before_capture, before_text = capture_state("before")
    observation_count += 1
    before_classification = classify_blocking_interruption(
        before_text, allow_hostile_auto_move_cancel=ignore_danger,
    )
    after_capture = before_capture
    after_text = before_text
    classification = before_classification
    travel_activity_complete = False
    native_travel_boundary: Dict[str, Any] = {}
    while True:
        if not pid_is_alive(pid):
            classification = {
                "status": "process_exited",
                "classification": "process_exited_before_native_travel_completion",
            }
            break
        status = str(classification.get("status", ""))
        classification_name = str(classification.get("classification", ""))
        modal_present = is_hostile_auto_move_cancel_modal(after_text)
        hud_matches = find_screen_text_matches(after_text, ["Move:", "Wield:"])
        stable_hud_matches = native_travel_stable_hud_markers(after_text)
        if len(hud_matches) != 2 and stable_hud_matches:
            hud_matches = stable_hud_matches
        nonblocking_wilderness_flavor_on_hud = \
            is_nonblocking_wilderness_flavor_on_hud( classification, after_text )
        noninteractive_wilderness_flavor_on_idle_hud = \
            is_noninteractive_wilderness_flavor_on_idle_hud( classification, after_text )
        if native_travel_boundary_reader is not None:
            native_travel_boundary = native_travel_boundary_reader()
            if native_travel_boundary.get("status") == "green":
                travel_activity_complete = True
                break
        # A partial or otherwise unknown prompt is the first divergence.  Its
        # corresponding native travel receipt has already been sampled above;
        # do not answer it or advance travel beyond this point.
        if status not in {"clear", "known_prompt"} and \
                not nonblocking_wilderness_flavor_on_hud:
            break
        if status == "known_prompt" and \
                classification_name == "authorized_hostile_auto_move_cancel":
            if deadline is not None and time.monotonic() >= deadline:
                break
            peekaboo_type_text(pid, "N", delay_ms=delay_ms)
            acknowledgement_count += 1
            response_keys.append("N")
            handled_interruptions.append({
                "classification": classification_name,
                "response": "continue_auto_move",
                "response_key": "N",
                "danger_handling": selected_danger_handling,
                "native_boundary": dict(native_travel_boundary),
            })
            if not wait_for_next_observation():
                break
            after_capture, after_text = capture_state(
                f"poll_{acknowledgement_count:02d}"
            )
            observation_count += 1
            classification = classify_blocking_interruption(
                after_text, allow_hostile_auto_move_cancel=ignore_danger,
            )
            continue
        if native_travel_boundary.get("reason") in {
                "hostile_boundary", "hostile_boundary_without_terminal"
        }:
            # The native receipt is the first authoritative hostile boundary.
            # A permissive policy may handle an identified modal before the
            # incomplete boundary becomes terminal, but it cannot authorize
            # polling past a route with no following completion receipt.
            break
        if native_travel_boundary.get("reason") == "post_hostile_boundary_travel" and not ignore_danger:
            break
        hud_recovered = len(hud_matches) == 2 or bool(stable_hud_matches)
        if ( status == "clear" or nonblocking_wilderness_flavor_on_hud ) and \
                hud_recovered and not modal_present:
            travel_activity_complete = bool(activity_none_matches(after_text))
            if travel_activity_complete and native_travel_boundary_reader is None:
                break
            if not wait_for_next_observation():
                break
            after_capture, after_text = capture_state(
                f"travel_poll_{observation_count:02d}"
            )
            observation_count += 1
            classification = classify_blocking_interruption(
                after_text, allow_hostile_auto_move_cancel=allow_hostile_auto_move_cancel,
            )
            continue
        if noninteractive_wilderness_flavor_on_idle_hud and native_travel_boundary_reader is None:
            travel_activity_complete = True
            break
        if native_travel_boundary_reader is not None and wait_for_next_observation():
            after_capture, after_text = capture_state(
                f"native_travel_poll_{observation_count:02d}"
            )
            observation_count += 1
            classification = classify_blocking_interruption(
                after_text, allow_hostile_auto_move_cancel=ignore_danger,
            )
            continue
        break

    hud_matches = find_screen_text_matches(after_text, ["Move:", "Wield:"])
    stable_hud_matches = native_travel_stable_hud_markers(after_text)
    if len(hud_matches) != 2 and stable_hud_matches:
        hud_matches = stable_hud_matches
    activity_matches = activity_none_matches(after_text)
    modal_present = is_hostile_auto_move_cancel_modal(after_text)
    nonblocking_wilderness_flavor_on_hud = \
        is_nonblocking_wilderness_flavor_on_hud( classification, after_text )
    noninteractive_wilderness_flavor_on_idle_hud = \
        is_noninteractive_wilderness_flavor_on_idle_hud( classification, after_text )
    hud_recovered = len(hud_matches) == 2 or bool(stable_hud_matches)
    result: Dict[str, Any] = {
        "danger_handling": selected_danger_handling,
        "response_key": response_keys[-1] if response_keys else "",
        "response_keys": response_keys,
        "handled_interruptions": handled_interruptions,
        "acknowledgement_count": acknowledgement_count,
        "observation_count": observation_count,
        "recognized_prompt": str(before_classification.get("classification", "")),
        "before_classification": before_classification,
        "after_classification": classification,
        "noninteractive_wilderness_flavor_on_idle_hud":
        noninteractive_wilderness_flavor_on_idle_hud,
        "screen_before": before_capture.get("screen_summary", {}),
        "screen_after": after_capture.get("screen_summary", {}),
        "screen_after_text_expectation": {
            "status": "matched" if hud_recovered and travel_activity_complete and not modal_present else "missing",
            "patterns": ["Move:", "Activity: None", "Wield:"],
            "matches": [*hud_matches, *activity_matches],
            "missing": [] if hud_recovered and travel_activity_complete and not modal_present else [
                marker for marker in ("Move:", "Wield:")
                if not any(match.get("pattern") == marker for match in hud_matches)
            ] + ([] if travel_activity_complete else ["Activity: None"]),
            "modal_present": modal_present,
            "source": str(run_dir / f"{label}.native_travel_stabilization.after.screen_text.json"),
        },
    }
    if native_travel_boundary_reader is not None:
        result["native_travel_boundary"] = native_travel_boundary
    if str(classification.get("status", "")) == "process_exited":
        result.update({
            "status": "blocked_native_travel_process_exited",
            "verdict": "blocked_native_travel_process_exited",
            "reason": "game process exited before the native travel completion boundary",
        })
    elif native_travel_boundary.get("reason") == "post_hostile_boundary_travel" and not ignore_danger:
        result.update({
            "status": "blocked_native_travel_post_hostile_boundary_travel",
            "verdict": "blocked_native_travel_post_hostile_boundary_travel",
            "reason": "native travel continued after its first hostile boundary receipt",
        })
    elif native_travel_boundary.get("reason") in {
            "hostile_boundary", "hostile_boundary_without_terminal"
    }:
        result.update({
            "status": "blocked_native_travel_hostile_boundary",
            "verdict": "blocked_native_travel_hostile_boundary",
            "reason": "native travel reached a hostile boundary without a later native completion receipt",
        })
    elif str(classification.get("status", "")) != "clear" and not modal_present and \
            not nonblocking_wilderness_flavor_on_hud:
        result.update({
            "status": "blocked_native_travel_unknown_prompt",
            "verdict": "blocked_native_travel_unknown_prompt",
            "reason": "route travel reached a prompt outside the exact authorized hostile auto-move modal",
        })
    elif native_travel_boundary_reader is not None and native_travel_boundary.get("status") != "green":
        result.update({
            "status": "blocked_native_travel_completion_boundary",
            "verdict": "blocked_native_travel_completion_boundary",
            "reason": str(native_travel_boundary.get("reason", "native travel completion was not proven")),
        })
    elif modal_present:
        result.update({
            "status": "blocked_native_travel_hostile_auto_move_modal_persisted",
            "verdict": "blocked_native_travel_hostile_auto_move_modal_persisted",
            "reason": "the exact hostile auto-move modal remained after the authorized N response",
        })
    elif native_travel_boundary_reader is not None and native_travel_boundary.get("status") == "green":
        # The native completion receipt is authoritative for route completion.
        # OCR may omit the idle HUD labels on the same settled frame; do not
        # turn that presentation gap into a false route failure.  Unknown
        # prompts and hostile modals have already stopped above.
        result.update({
            "status": "green_native_travel_terminal_receipt",
            "verdict": "green_native_travel_stabilized",
            "reason": "native travel completion boundary is green and no blocking modal is present",
        })
    elif not hud_recovered:
        result.update({
            "status": "blocked_native_travel_hud_recovery_missing",
            "verdict": "blocked_native_travel_hud_recovery_missing",
            "reason": "route travel did not return to an unobstructed gameplay HUD",
        })
    elif not travel_activity_complete:
        result.update({
            "status": "blocked_native_travel_completion_timeout",
            "verdict": "blocked_native_travel_completion_timeout",
            "reason": "route travel did not reach an idle HUD before its scenario-owned timeout",
        })
    else:
        result.update({
            "status": (
                "continued_exact_hostile_auto_move_to_hud"
                if acknowledgement_count else "clear_hud_without_hostile_auto_move_prompt"
            ),
            "verdict": "green_native_travel_stabilized",
        })
    return result


def evaluate_native_travel_completion_boundary(
    *, profile: str, run_dir: Path, run_id: str, trace_start_offset: int,
    expected_destination: Sequence[int], allow_handled_hostile_boundaries: bool = False,
) -> Dict[str, Any]:
    """Read the first post-travel native fact boundary, never OCR."""
    if not run_id:
        return {"status": "blocked", "reason": "missing_run_id"}
    try:
        _, owned_trace = refresh_semantic_step_trace(
            profile=profile, run_dir=run_dir, run_id=run_id,
            start_offset=trace_start_offset, event_filter={"travel"},
        )
        events, read_status = read_semantic_step_trace(
            owned_trace, run_dir, run_id, event_filter={"travel"},
        )
    except (OSError, ValueError) as exc:
        return {"status": "blocked", "reason": "native_trace_unavailable", "detail": str(exc)}
    if read_status != "ok":
        return {"status": "blocked", "reason": read_status}
    result = decide_native_travel_boundary(
        events, run_id=run_id, expected_destination=expected_destination,
        allow_handled_hostile_boundaries=allow_handled_hostile_boundaries,
    )
    return {**result, "source": str(owned_trace), "event_count": len(events)}


def persist_native_travel_terminal_receipt(
    stabilization: Mapping[str, Any], *, run_dir: Path, label: str, run_id: str,
) -> Dict[str, Any]:
    """Seal a green native terminal receipt as a run-owned proof artifact."""
    boundary = stabilization.get("native_travel_boundary")
    if not isinstance(boundary, Mapping) or boundary.get("status") != "green":
        return {
            "status": "required_state_missing",
            "artifact_kind": "native_travel_terminal_receipt",
            "run_id": run_id,
            "reason": "native_travel_completion_boundary_not_green",
        }
    source = Path(str(boundary.get("source", "") or ""))
    try:
        source.resolve().relative_to(run_dir.resolve())
        source_sha256 = path_sha256(source)
    except (OSError, ValueError):
        return {
            "status": "required_state_missing",
            "artifact_kind": "native_travel_terminal_receipt",
            "run_id": run_id,
            "reason": "native_travel_receipt_source_not_owned",
        }
    receipt_path = run_dir / f"{label}.native_travel_terminal_receipt.json"
    receipt = {
        "status": "required_state_present",
        "committed": True,
        "artifact_kind": "native_travel_terminal_receipt",
        "run_id": run_id,
        "travel_id": str(boundary.get("travel_id", "")),
        "active_receipt_id": str(boundary.get("active_receipt_id", "")),
        "completion_receipt_id": str(boundary.get("completion_receipt_id", "")),
        "destination": boundary.get("destination"),
        "danger_handling": str(stabilization.get("danger_handling", "")),
        "handled_interruptions": list(stabilization.get("handled_interruptions", [])),
        "handled_hostile_boundaries": list(boundary.get("handled_hostile_boundaries", [])),
        "semantic_trace_path": str(source),
        "semantic_trace_sha256": source_sha256,
        "event_count": int(boundary.get("event_count", 0) or 0),
        "artifact_path": str(receipt_path),
    }
    receipt_path.write_text(json.dumps(receipt, indent=2, ensure_ascii=False), encoding="utf-8")
    receipt["artifact_sha256"] = path_sha256(receipt_path)
    return receipt


def persist_native_travel_hostile_boundary_receipt(
    stabilization: Mapping[str, Any], *, run_dir: Path, label: str, run_id: str,
) -> Dict[str, Any]:
    """Seal a real first-hostile terminal without treating it as arrival."""
    boundary = stabilization.get("native_travel_boundary")
    reason = str(boundary.get("reason", "")) if isinstance(boundary, Mapping) else ""
    if reason not in {"hostile_boundary", "hostile_boundary_without_terminal"}:
        return {
            "status": "required_state_missing",
            "artifact_kind": "native_travel_hostile_boundary_receipt",
            "run_id": run_id,
            "reason": "first_hostile_boundary_not_observed",
        }
    if reason == "hostile_boundary" and stabilization.get("response_keys"):
        return {
            "status": "required_state_missing",
            "artifact_kind": "native_travel_hostile_boundary_receipt",
            "run_id": run_id,
            "reason": "hostile_boundary_prompt_was_answered",
        }
    source = Path(str(boundary.get("source", "") or ""))
    try:
        source.resolve().relative_to(run_dir.resolve())
        source_sha256 = path_sha256(source)
    except (OSError, ValueError):
        return {
            "status": "required_state_missing",
            "artifact_kind": "native_travel_hostile_boundary_receipt",
            "run_id": run_id,
            "reason": "native_travel_receipt_source_not_owned",
        }
    receipt_path = run_dir / f"{label}.native_travel_hostile_boundary_receipt.json"
    receipt = {
        "status": "required_state_present",
        "committed": True,
        "artifact_kind": "native_travel_hostile_boundary_receipt",
        "run_id": run_id,
        "travel_id": str(boundary.get("travel_id", "")),
        "omt": boundary.get("hostile_boundary_omt"),
        "boundary_reason": reason,
        "prompt_responses": list(stabilization.get("response_keys", [])),
        "danger_handling": str(stabilization.get("danger_handling", "")),
        "completed_destination_cleared": False,
        "semantic_trace_path": str(source),
        "semantic_trace_sha256": source_sha256,
        "event_count": int(boundary.get("event_count", 0) or 0),
        "artifact_path": str(receipt_path),
    }
    receipt_path.write_text(json.dumps(receipt, indent=2, ensure_ascii=False), encoding="utf-8")
    receipt["artifact_sha256"] = path_sha256(receipt_path)
    return receipt


def classify_wait_screen_text(
    screen_text_report: Dict[str, Any],
    complete_patterns: List[str],
    interrupt_patterns: List[str],
    preexisting_complete_patterns: Optional[Set[str]] = None,
) -> Dict[str, Any]:
    complete_matches = find_screen_text_matches(screen_text_report, complete_patterns)
    stale_complete_matches = [
        match for match in complete_matches
        if match.get("pattern") in (preexisting_complete_patterns or set())
    ]
    complete_matches = [
        match for match in complete_matches
        if match.get("pattern") not in (preexisting_complete_patterns or set())
    ]
    interrupt_matches = find_screen_text_matches(screen_text_report, interrupt_patterns)
    retained_auto_move_cancel = is_retained_hostile_auto_move_cancelled_hud_message(
        screen_text_report
    )
    ignored_interrupt_matches: List[Dict[str, Any]] = []
    if retained_auto_move_cancel:
        ignored_interrupt_matches = [
            match for match in interrupt_matches
            if str( match.get( "pattern", "" ) ).lower() in {
                "spotted", "hostile spotted"
            }
        ]
        interrupt_matches = [
            match for match in interrupt_matches
            if match not in ignored_interrupt_matches
        ]
    normalized_body = re.sub(r"[^a-z0-9]+", " ", screen_text_body(screen_text_report).lower()).strip()
    activity_is_complete_or_omitted = bool( re.search( r"(?:activity|.ctivity) none", normalized_body ) ) or "activity" not in normalized_body
    completion_persisted_after_wait = bool(stale_complete_matches) and (
        activity_is_complete_or_omitted
    )
    ocr_completion_fragment = bool( re.search( r"\b(?:finish|nish) waiting\b", normalized_body ) ) and activity_is_complete_or_omitted
    if interrupt_matches:
        status = "interrupted_or_prompt_visible"
    elif complete_matches or completion_persisted_after_wait or ocr_completion_fragment:
        status = "completed"
    else:
        status = "unknown_after_wait"
    return {
        "status": status,
        "complete_patterns": complete_patterns,
        "interrupt_patterns": interrupt_patterns,
        "complete_matches": complete_matches,
        "stale_complete_matches_rejected": stale_complete_matches,
        "completion_persisted_after_wait": completion_persisted_after_wait,
        "ocr_completion_fragment": ocr_completion_fragment,
        "interrupt_matches": interrupt_matches,
        "ignored_retained_auto_move_cancel_matches": ignored_interrupt_matches,
    }
def classify_run_bound_native_wait(
    receipt: Mapping[str, Any],
    native_terminal_evidence: Mapping[str, Any],
    *,
    current_run_id: str,
    current_binding_id: str = "",
) -> Dict[str, Any]:
    """Accept only one bound native completion fact for this exact wait."""
    current_run_id = str( current_run_id ).strip()
    current_binding_id = str( current_binding_id ).strip()
    receipt_run_id = str( receipt.get( "run_id", "" ) ).strip()
    receipt_id = str( receipt.get( "receipt_id", "" ) ).strip()
    receipt_binding_id = str( receipt.get( "binding_id", "" ) ).strip()
    evidence_run_id = str( native_terminal_evidence.get( "run_id", "" ) ).strip()
    evidence_receipt_id = str( native_terminal_evidence.get( "receipt_id", "" ) ).strip()
    evidence_binding_id = str( native_terminal_evidence.get( "binding_id", "" ) ).strip()
    start_seconds = receipt.get( "start_seconds_since_midnight" )
    end_seconds = receipt.get( "end_seconds_since_midnight" )
    expected_seconds = receipt.get( "expected_seconds" )
    terminal_kind = str( native_terminal_evidence.get( "kind", "" ) ).strip()
    terminal_source = str( native_terminal_evidence.get( "source", "" ) ).strip()
    failures: List[str] = []
    if not current_run_id or receipt_run_id != current_run_id or evidence_run_id != current_run_id:
        failures.append( "wrong_or_missing_current_run" )
    if not current_binding_id or receipt_binding_id != current_binding_id or \
            evidence_binding_id != current_binding_id:
        failures.append( "wrong_or_missing_current_binding" )
    if not receipt_id or evidence_receipt_id != receipt_id:
        failures.append( "missing_or_mismatched_wait_receipt" )
    if not all( isinstance( value, int ) and not isinstance( value, bool ) for value in
                ( start_seconds, end_seconds, expected_seconds ) ):
        failures.append( "missing_or_invalid_wait_time" )
        observed_seconds = None
    else:
        observed_seconds = ( end_seconds - start_seconds ) % ( 24 * 60 * 60 )
        if observed_seconds != expected_seconds:
            failures.append( "wait_duration_mismatch" )
    if terminal_kind not in {"native_wait_completed", "native_wait_interrupted"}:
        failures.append( "native_wait_termination_unproved" )
    elif terminal_source != "native_semantic_wait_activity_complete":
        failures.append( "native_wait_termination_unproved" )
    if failures:
        return {
            "status": "unproved",
            "verdict": "yellow_run_bound_native_wait_unproved",
            "failures": failures,
            "current_run_id": current_run_id,
            "current_binding_id": current_binding_id,
            "receipt_id": receipt_id,
            "observed_seconds": observed_seconds,
            "expected_seconds": expected_seconds,
        }
    return {
        "status": "completed" if terminal_kind == "native_wait_completed" else "interrupted_or_prompt_visible",
        "verdict": "green_run_bound_native_wait_completed" if terminal_kind == "native_wait_completed"
        else "yellow_run_bound_native_wait_interrupted",
        "failures": [],
        "current_run_id": current_run_id,
        "current_binding_id": current_binding_id,
        "receipt_id": receipt_id,
        "observed_seconds": observed_seconds,
        "expected_seconds": expected_seconds,
        "native_terminal_kind": terminal_kind,
    }


def classify_native_wait_activity_completion(
    events: Sequence[Mapping[str, Any]],
    *,
    run_id: str,
    binding_id: str,
    expected_action: str,
    receipt_id: str,
) -> Dict[str, Any]:
    """Bind one native completion frame to this wait's post-choice trace slice."""
    selected_run_id = str( run_id ).strip()
    selected_binding_id = str( binding_id ).strip()
    selected_action = str( expected_action ).strip()
    selected_receipt_id = str( receipt_id ).strip()
    failures: List[str] = []
    if not selected_run_id:
        failures.append( "missing_current_run" )
    if not selected_binding_id:
        failures.append( "missing_current_binding" )
    if not selected_action or not selected_receipt_id:
        failures.append( "missing_wait_identity" )
    normalized = [dict( event ) for event in events if isinstance( event, Mapping )]
    if len( normalized ) != len( events ) or any(
            str( event.get( "run_id", "" ) ).strip() != selected_run_id
            for event in normalized ):
        failures.append( "mixed_or_stale_run_events" )
    selections = [
        event for event in normalized
        if event.get( "event" ) == "receipt" and event.get( "accepted" ) is True and
        str( event.get( "action_id", "" ) ) == selected_action
    ]
    selection_index = normalized.index( selections[0] ) if len( selections ) == 1 else -1
    if selection_index < 0:
        failures.append( "missing_or_ambiguous_wait_selection" )
    activity_index = -1
    completion_indices: List[int] = []
    interruption_indices: List[int] = []
    if selection_index >= 0:
        for index, event in enumerate( normalized[selection_index + 1:], selection_index + 1 ):
            if event.get( "event" ) != "frame":
                continue
            state = str( event.get( "state", "" ) )
            if state == "wait_activity" and activity_index < 0:
                activity_index = index
            elif state == "activity_distraction":
                interruption_indices.append( index )
            elif state == "wait_activity_complete":
                completion_indices.append( index )
    if activity_index < 0:
        failures.append( "wait_activity_not_observed" )
    if len( completion_indices ) != 1:
        failures.append( "missing_or_ambiguous_wait_activity_complete" )
    elif activity_index >= completion_indices[0]:
        failures.append( "wait_activity_completion_order_invalid" )
    if interruption_indices:
        failures.append( "wait_interrupted_before_native_completion" )
    completion = normalized[completion_indices[0]] if len( completion_indices ) == 1 else {}
    return {
        "run_id": selected_run_id,
        "binding_id": selected_binding_id,
        "receipt_id": selected_receipt_id,
        "source": "native_semantic_wait_activity_complete",
        "kind": "native_wait_completed" if not failures else "native_wait_interrupted"
        if interruption_indices else "",
        "status": "matched" if not failures else "unproved",
        "failures": failures,
        "expected_action": selected_action,
        "selection_frame_id": str( selections[0].get( "frame_id", "" ) ) if selections else "",
        "completion_frame_id": str( completion.get( "frame_id", "" ) ),
        "completion_observed_turn": completion.get( "observed_turn" ),
        "interruption_frame_ids": [
            str( normalized[index].get( "frame_id", "" ) ) for index in interruption_indices
        ],
    }


def observe_bound_native_wait_activity_completion(
    *,
    profile: str,
    run_dir: Path,
    run_id: str,
    trace_start_offset: int,
    binding_id: str,
    expected_action: str,
    receipt_id: str,
) -> Dict[str, Any]:
    """Read only semantic events emitted after this wait's duration key."""
    try:
        _, owned = refresh_semantic_step_trace(
            profile=profile, run_dir=run_dir, run_id=run_id,
            start_offset=trace_start_offset,
        )
        events, read_status = read_semantic_step_trace( owned, run_dir, run_id )
    except ( OSError, ValueError ) as exc:
        return {
            "status": "unproved", "failures": ["native_wait_trace_unavailable"],
            "error": str( exc ), "events": [],
        }
    evidence = classify_native_wait_activity_completion(
        events, run_id=run_id, binding_id=binding_id,
        expected_action=expected_action, receipt_id=receipt_id,
    )
    return {**evidence, "read_status": read_status, "events": events}


def evaluate_native_wait_return_continuation(
    events: Sequence[Mapping[str, Any]],
    *,
    run_id: str,
    transition: str,
    actor_ids: Sequence[Any],
    postcondition: Mapping[str, Any],
    final_postcondition: Optional[Mapping[str, Any]] = None,
) -> Dict[str, Any]:
    """Authorize a native-wait continuation from exact same-run return receipts.

    This is a narrow bridge for a wait whose native finish text is not
    observable.  The transition stream remains authoritative: every required
    actor must have one committed receipt, the stream must be monotone, and the
    final receipt must satisfy the declared ownership/postcondition boundary.
    No screen text or caller-supplied completion label participates in this
    decision.
    """
    selected_run_id = str(run_id or "").strip()
    selected_transition = str(transition or "").strip()
    required_actor_ids = list(actor_ids) if isinstance(actor_ids, Sequence) and \
        not isinstance(actor_ids, (str, bytes, bytearray)) else []
    required_postcondition = dict(postcondition) if isinstance(postcondition, Mapping) else {}
    final_condition = dict(final_postcondition) if isinstance(final_postcondition, Mapping) else {}
    failures: List[str] = []
    if not selected_run_id:
        failures.append("missing_current_run")
    if not selected_transition:
        failures.append("missing_return_transition")
    if not required_actor_ids or len(set(json.dumps(item, sort_keys=True) for item in required_actor_ids)) != len(required_actor_ids):
        failures.append("missing_or_duplicate_required_actor_ids")
    if not required_postcondition:
        failures.append("missing_return_postcondition")

    observed_events = list(events) if isinstance(events, Sequence) and \
        not isinstance(events, (str, bytes, bytearray)) else []
    previous_sequence: Optional[int] = None
    matching: List[Dict[str, Any]] = []
    for event in observed_events:
        if not isinstance(event, Mapping):
            failures.append("malformed_return_receipt")
            continue
        sequence = event.get("sequence")
        if isinstance(sequence, bool) or not isinstance(sequence, int) or \
                (previous_sequence is not None and sequence <= previous_sequence):
            failures.append("non_monotone_sequence")
        elif previous_sequence is None or sequence > previous_sequence:
            previous_sequence = sequence
        if event.get("run_id") != selected_run_id:
            failures.append("wrong_or_stale_run")
            continue
        if str(event.get("transition", "")).strip() != selected_transition or \
                str(event.get("outcome", "")).strip().lower() != "committed":
            continue
        event_actor_ids = event.get("actor_ids")
        if not isinstance(event_actor_ids, list) or len(event_actor_ids) != 1:
            failures.append("missing_or_ambiguous_actor")
            continue
        member_id = event_actor_ids[0]
        if member_id not in required_actor_ids:
            continue
        if not str(_transition_event_value(event, "owner") or "").strip():
            failures.append("missing_return_owner")
        for key, expected in required_postcondition.items():
            observed = _transition_event_value(event, key)
            if observed != expected:
                failures.append(
                    "missing_return_postcondition" if observed in (None, "", [], {})
                    else "return_postcondition_mismatch"
                )
                break
        matching.append(dict(event))

    matches_by_actor: Dict[Any, List[Dict[str, Any]]] = {}
    for event in matching:
        matches_by_actor.setdefault(event.get("actor_ids", [None])[0], []).append(event)
    if any(len(receipts) > 1 for receipts in matches_by_actor.values()):
        failures.append("duplicate_return_receipt")
    missing_actors = [actor_id for actor_id in required_actor_ids if actor_id not in matches_by_actor]
    if missing_actors:
        failures.append("missing_return_actor")
    ordered_matches = sorted(
        (receipts[0] for receipts in matches_by_actor.values() if receipts),
        key=lambda event: int(event.get("sequence", 0)),
    )
    if ordered_matches and final_condition:
        final_event = ordered_matches[-1]
        for key, expected in final_condition.items():
            observed = _transition_event_value(final_event, key)
            if observed != expected:
                failures.append(
                    "missing_return_postcondition" if observed in (None, "", [], {})
                    else "return_postcondition_mismatch"
                )
    failures = list(dict.fromkeys(failures))
    if failures:
        return {
            "status": "unproved",
            "verdict": "red_native_wait_return_continuation_unproved",
            "failures": failures,
            "run_id": selected_run_id,
            "transition": selected_transition,
            "required_actor_ids": required_actor_ids,
            "matched_actor_ids": sorted(matches_by_actor),
        }
    return {
        "status": "matched",
        "verdict": "green_native_wait_return_continuation",
        "failures": [],
        "run_id": selected_run_id,
        "transition": selected_transition,
        "required_actor_ids": required_actor_ids,
        "matched_actor_ids": sorted(matches_by_actor),
        "receipt_sequences": [int(event.get("sequence", 0)) for event in ordered_matches],
        "completion_signal": "same_run_native_return_receipts_and_postcondition",
    }


def screen_text_body( screen_text_report: Dict[str, Any] ) -> str:
    text = screen_text_report.get( "text", "" )
    if isinstance( text, str ) and text:
        return text
    lines = screen_text_report.get( "lines", [] )
    if isinstance( lines, list ) and lines:
        return "\n".join( str( line ) for line in lines )
    json_path_value = str( screen_text_report.get( "json_path", "" ) ).strip()
    if json_path_value:
        try:
            payload = json.loads( Path( json_path_value ).read_text( encoding="utf-8" ) )
        except Exception:
            payload = {}
        if isinstance( payload, dict ):
            payload_text = payload.get( "text", "" )
            if isinstance( payload_text, str ) and payload_text:
                return payload_text
            payload_lines = payload.get( "lines", [] )
            if isinstance( payload_lines, list ):
                return "\n".join( str( line ) for line in payload_lines )
    return ""


def classify_blocking_interruption(
    screen_text_report: Dict[str, Any],
    *,
    allow_map_editor_save_and_quit: bool = False,
    allow_hostile_auto_move_cancel: bool = False,
) -> Dict[str, Any]:
    body = screen_text_body(screen_text_report).strip()
    lowered = body.lower()
    normalized_ocr_body = re.sub(r"[^a-z0-9]+", " ", lowered).strip()
    lines = [line.strip() for line in body.splitlines() if line.strip()]
    base = {
        "text": body,
        "response_key": "",
        "release_blocking": False,
        "contaminating": False,
        "matched_markers": [],
    }
    if not body:
        return {
            **base,
            "status": "unobservable" if not bool(screen_text_report.get("ok", False)) else "clear",
            "classification": "ocr_unavailable" if not bool(screen_text_report.get("ok", False)) else "no_prompt",
        }

    unsafe_markers = [
        marker
        for marker in (
            "save and quit",
            "unable to save, quit anyway",
            "really quit",
            "unsaved changes will be lost",
            "abandon this character",
            "this will kill your character",
            "really delete",
            "crash the game",
        )
        if marker in lowered
    ]
    if unsafe_markers == ["save and quit"] and allow_map_editor_save_and_quit and \
            "map editor" in normalized_ocr_body:
        return {
            **base,
            "status": "clear",
            "classification": "map_editor_save_and_quit_control",
            "matched_markers": unsafe_markers,
            "expected_state_marker": "map editor",
        }
    if unsafe_markers:
        return {
            **base,
            "status": "unsafe_prompt",
            "classification": "unsafe_confirmation_requires_scenario_choice",
            "matched_markers": unsafe_markers,
        }

    debug_markers = [
        marker
        for marker in (
            "an error has occurred",
            "space bar to continue the game",
            "ignore this particular message",
        )
        if marker in lowered
    ]
    if len(debug_markers) == 3:
        return {
            **base,
            "status": "known_prompt",
            "classification": "debug_error_popup",
            "response_key": "space",
            "release_blocking": True,
            "matched_markers": debug_markers,
        }
    if debug_markers:
        return {
            **base,
            "status": "unknown_prompt",
            "classification": "partial_debug_error_popup",
            "release_blocking": True,
            "matched_markers": debug_markers,
        }

    emergency_wait_distraction_markers = []
    if normalized_ocr_body.count("emergency") >= 2:
        emergency_wait_distraction_markers.append("emergency title")
    if "stop" in normalized_ocr_body and "waiting" in normalized_ocr_body:
        emergency_wait_distraction_markers.append("stop waiting")
    if "case" in normalized_ocr_body and re.search(r"\bsensitiv[a-z]*\b", normalized_ocr_body):
        emergency_wait_distraction_markers.append("case sensitive")
    if re.search(r"\b(?:open|upen)\b", normalized_ocr_body) and \
            re.search(r"\b(?:c?m|m)l?anager\b", normalized_ocr_body):
        emergency_wait_distraction_markers.append("open manager")
    if re.search(r"\b(?:i|l|il)gnore\b", normalized_ocr_body) and \
            "distraction" in normalized_ocr_body and "continue" in normalized_ocr_body:
        emergency_wait_distraction_markers.append("ignore distraction and continue")
    if len(emergency_wait_distraction_markers) == 5:
        return {
            **base,
            "status": "known_prompt",
            "classification": "emergency_wait_distraction_prompt",
            "response_key": "I",
            "matched_markers": emergency_wait_distraction_markers,
        }

    activity_markers = []
    if (
        "ignore this distraction and continue" in lowered
        or re.search(r"\S{0,4}gnore this distraction and continue", lowered)
    ):
        activity_markers.append("ignore this distraction and continue")
    if "open manager" in lowered or re.search(r"open\s+\S{0,4}anager", lowered):
        activity_markers.append("open manager")
    # Safe-mode sighting text is retained in the message log after the native
    # modal has already resolved.  Without a live modal/semantic trace, a
    # garbled message-only line must remain inert; sending the advertised
    # letter here can open an unrelated inventory surface.
    if "monster" in normalized_ocr_body and "ignore" in normalized_ocr_body and \
            "spotted" not in normalized_ocr_body and \
            any(token in normalized_ocr_body.split() for token in ("prmsd", "presde", "15o", "itort", "orf")):
        return {
            **base,
            "status": "clear",
            "classification": "retained_safe_mode_hostile_message",
            "matched_markers": ["monster", "ignore"],
        }
    # The activity modal offers I for both harmless flavour and immediate
    # threats.  Continuing through a direct attack, injury, or close-hostile
    # warning leaves the observer unable to act while the game resolves
    # combat.  Preserve the prompt as evidence, but require an explicit
    # scenario-owned recovery instead of treating its advertised I as safe.
    activity_hazard_markers = [
        marker
        for marker in (
            "dangerously close",
            "attacked by",
            "attacked you",
            "something hurts",
            "you are bleeding",
            "your limb breaks",
        )
        if marker in lowered
    ]
    if activity_markers and activity_hazard_markers:
        return {
            **base,
            "status": "unsafe_prompt",
            "classification": "dangerous_activity_distraction_prompt",
            "matched_markers": activity_markers + activity_hazard_markers,
        }
    if len(activity_markers) == 2:
        return {
            **base,
            "status": "known_prompt",
            "classification": "activity_distraction_prompt",
            "response_key": "I",
            "matched_markers": activity_markers,
        }
    # Safe-mode's native hostile-sighting prompt is frequently OCR-garbled
    # (for example, "turn it orf, presde ito ignore").  Keep this narrow:
    # require the monster/sighting noun, both turn/ignore affordances, and
    # advertise only the documented non-contaminating ignore action.
    if "monster" in normalized_ocr_body and "ignore" in normalized_ocr_body and \
            any(token in normalized_ocr_body.split() for token in ("orf", "presde", "ito", "prmsd", "15o", "itort")) and \
            re.search(r"\b(?:turn|urn|eurn)\s+it[a-z]{0,3}\b", normalized_ocr_body) and \
            re.search(r"\b(?:pres[a-z]{0,4}|prmsd)\s+[a-z0-9]{0,3}\s*(?:to|15o)\s+ignore\b", normalized_ocr_body):
        return {
            **base,
            "status": "known_prompt",
            "classification": "safe_mode_spotted_hostile_prompt",
            "response_key": "i",
            "matched_markers": ["monster", "turn it off", "ignore"],
        }
    # During an ordinary wait, OCR can misread "Open manager" while the
    # safe-mode sighting text and the explicit ignore-continuation choice
    # remain legible.  The latter is sufficient to choose the documented
    # non-contaminating continuation.
    if activity_markers and "spotted" in lowered and "waiting" in lowered:
        return {
            **base,
            "status": "known_prompt",
            "classification": "activity_distraction_prompt",
            "response_key": "I",
            "matched_markers": activity_markers + ["spotted", "waiting"],
        }
    if activity_markers:
        return {
            **base,
            "status": "unknown_prompt",
            "classification": "partial_activity_distraction_prompt",
            "matched_markers": activity_markers,
        }

    if "unknown command:" in lowered:
        return {
            **base,
            "status": "unknown_prompt",
            "classification": "unexpected_default_command_input",
            "release_blocking": True,
            "matched_markers": ["unknown command:"],
        }

    if is_retained_hostile_auto_move_cancelled_hud_message( screen_text_report ):
        return {
            **base,
            "status": "clear",
            "classification": "retained_hostile_auto_move_cancelled_hud_message",
            "matched_markers": [
                "hostile survivor spotted",
                "auto move cancelled",
                "gameplay hud",
            ],
        }

    if allow_hostile_auto_move_cancel and is_hostile_auto_move_cancel_modal(
            screen_text_report ):
        return {
            **base,
            "status": "known_prompt",
            "classification": "authorized_hostile_auto_move_cancel",
            "response_key": "Y",
            "matched_markers": ["cancel auto move", "case sensitive"],
        }

    # The retained R-005 route frame has enough text to identify a native
    # hostile auto-move cancellation prompt, but not its case-sensitive choice
    # or actor identity.  It is not safe to infer either from degraded OCR.
    # Keep the route at the first prompt boundary instead of later reporting
    # semantic travel progress without a terminal receipt.
    if "spotted" in normalized_ocr_body and "cancel auto move" in normalized_ocr_body:
        return {
            **base,
            "status": "unknown_prompt",
            "classification": "partial_hostile_auto_move_cancel_prompt",
            "release_blocking": True,
            "matched_markers": ["spotted", "cancel auto move"],
        }

    semantic_safe_mode_markers = [
        marker
        for marker in (
            "safe mode",
            "spotted",
            "press ' to turn it off",
            "off, press",
            "ignore monster",
        )
        if marker in lowered
    ]
    strong_semantic_safe_mode_marker = any(
        marker != "safe mode" for marker in semantic_safe_mode_markers
    )
    shadow_warning_markers = [
        marker
        for marker in (
            "burning cities lighting up the horizon",
            "automatic gunfire winding down into single shots",
            "vague feeling of being watched",
            "something rustles",
            "withered and blackened vegetation",
            "night feels longer than usual",
            "yearn for a beautiful sunrise",
            "wind faintly cries into the night",
            "the wind sure is howling tonight",
            "darkness makes you nervous",
        )
        if marker in lowered
    ]
    garbled_vague_watched_marker = "garbled vague feeling of being watched"
    if re.search(
        r"\bur hove a veuee(?: [a-z0-9]{1,8}){1,4} ueiny satcheu\b",
        normalized_ocr_body,
    ):
        shadow_warning_markers.append(garbled_vague_watched_marker)
    lifeless_grass_markers = [
        marker
        for marker in (
            "almost devoid of life",
            "what happened to the grass",
            "grass coming to life to eat people",
        )
        if marker in normalized_ocr_body
    ]
    safe_mode_markers = [
        marker
        for marker in (
            "safe mode",
            "spotted",
            "press ' to turn it off",
            "off, press",
            "ignore monster",
        )
        if marker in lowered
    ]
    wait_progress_percentage = bool(re.search(r"\b\d{1,3}\s*%", lowered))
    contiguous_wait_activity = bool( re.search( r"\binterrupt\s+waiting\b", lowered ) )
    bounded_fragmented_wait_banner = bool( re.search(
        r"press(?=[\s\S]{0,160}interrupt)[\s\S]{0,64}waiting"
        r"[\s\S]{0,64}\bto\b[\s\S]{0,64}interrupt",
        lowered,
    ) ) or bool( re.search(
        r"waiting(?=[\s\S]{0,160}interrupt)[\s\S]{0,64}press"
        r"[\s\S]{0,64}\bto\b[\s\S]{0,64}interrupt",
        lowered,
    ) )
    native_wait_interrupt_banner = bool( re.search(
        r"press\s*[.5]\s*or\s*[.5]\s*to\s+interrupt",
        lowered,
    ) ) and "waiting" in lowered
    split_wait_words = set( normalized_ocr_body.split() )
    split_wait_progress_banner = (
        "waiting:" in lowered
        and wait_progress_percentage
        and {"press", "or", "5", "to"}.issubset( split_wait_words )
        and bool( re.search( r"\binterrup(?:t(?:ion)?)?\b", normalized_ocr_body ) )
    )
    fragmented_wait_activity = (
        bounded_fragmented_wait_banner
        or native_wait_interrupt_banner
        or split_wait_progress_banner
        or (
            "press" in lowered
            and "waiting" in lowered
            and "interrupt" in lowered
            and wait_progress_percentage
        )
    )
    safe_mode_explicitly_off = (
        "safe mode off" in normalized_ocr_body or
        "safe off" in normalized_ocr_body
    )
    if (
        ("press ' to turn it off" in safe_mode_markers and "ignore monster" in safe_mode_markers)
        or ("off, press" in safe_mode_markers and "ignore monster" in safe_mode_markers)
        or (
            ("safe mode" in lowered and "press" in lowered and "tiles" in lowered)
            and not (
                safe_mode_explicitly_off and
                (contiguous_wait_activity or fragmented_wait_activity)
            )
        )
    ):
        return {
            **base,
            "status": "unknown_prompt",
            "classification": "safe_mode_spotted_hostile_prompt",
            "release_blocking": True,
            "matched_markers": safe_mode_markers,
        }
    if safe_mode_markers and (
        strong_semantic_safe_mode_marker or
        not (contiguous_wait_activity or fragmented_wait_activity) or
        ("safe mode" in semantic_safe_mode_markers and not safe_mode_explicitly_off)
    ):
        return {
            **base,
            "status": "unknown_prompt",
            "classification": "partial_safe_mode_spotted_hostile_prompt",
            "matched_markers": safe_mode_markers,
        }

    portal_yes_markers = [
        marker
        for marker in ("yes, i will", "yes, i must", "yes, i shall")
        if marker in lowered
    ]
    if len(portal_yes_markers) >= 2:
        return {
            **base,
            "status": "known_prompt",
            "classification": "portal_storm_activity_prompt",
            "response_key": "Y",
            "contaminating": True,
            "matched_markers": portal_yes_markers,
        }
    if portal_yes_markers:
        return {
            **base,
            "status": "unknown_prompt",
            "classification": "partial_portal_storm_activity_prompt",
            "contaminating": True,
            "matched_markers": portal_yes_markers,
        }

    portal_notice_markers = [
        marker
        for marker in ("buzzing in your senses", "tiny cataclysm has begun")
        if marker in lowered
    ]
    if len(portal_notice_markers) == 2:
        return {
            **base,
            "status": "known_prompt",
            "classification": "portal_storm_notice",
            "response_key": "space",
            "contaminating": True,
            "matched_markers": portal_notice_markers,
        }
    if portal_notice_markers:
        return {
            **base,
            "status": "unknown_prompt",
            "classification": "partial_portal_storm_notice",
            "contaminating": True,
            "matched_markers": portal_notice_markers,
        }

    continue_markers = [
        marker
        for marker in ("press any key to continue", "space bar to continue")
        if marker in lowered
    ]
    if continue_markers:
        return {
            **base,
            "status": "known_prompt",
            "classification": "continue_popup",
            "response_key": "space",
            "matched_markers": continue_markers,
        }

    if "stop waiting" in lowered and "case sensitive" in normalized_ocr_body:
        return {
            **base,
            "status": "known_prompt",
            "classification": "tired_wait_continue_prompt",
            "response_key": "N",
            "matched_markers": ["stop waiting", "case sensitive"],
        }

    unknown_markers = []
    if "case sensitive" in lowered and any(marker in lowered for marker in ("yes", "no", "ignore")):
        unknown_markers.append("case sensitive confirmation")
    if any(marker in lowered for marker in ("(y/n)", "[y/n]", "yes/no")):
        unknown_markers.append("yes/no confirmation")
    if any(line.lower() == "actions" for line in lines):
        unknown_markers.append("actions overlay")
    if unknown_markers:
        return {
            **base,
            "status": "unknown_prompt",
            "classification": "unhandled_blocking_menu",
            "matched_markers": unknown_markers,
        }

    if shadow_warning_markers:
        return {
            **base,
            "status": "known_prompt",
            "classification": "shadow_warning_wilderness_flavor_popup",
            "response_key": "space",
            "matched_markers": shadow_warning_markers,
        }
    if len(lifeless_grass_markers) >= 2:
        return {
            **base,
            "status": "known_prompt",
            "classification": "shadow_warning_wilderness_flavor_popup",
            "response_key": "space",
            "matched_markers": lifeless_grass_markers,
        }
    if lifeless_grass_markers:
        return {
            **base,
            "status": "unknown_prompt",
            "classification": "partial_lifeless_grass_wilderness_flavor_popup",
            "matched_markers": lifeless_grass_markers,
        }

    if contiguous_wait_activity or fragmented_wait_activity:
        wait_activity_markers = (
            ["interrupt waiting"]
            if contiguous_wait_activity
            else ["waiting", "to interrupt"]
        )
        if wait_progress_percentage:
            wait_activity_markers.append("progress percentage")
        return {
            **base,
            "status": "clear",
            "classification": "wait_activity_in_progress",
            "matched_markers": wait_activity_markers,
        }

    return {
        **base,
        "status": "clear",
        "classification": "no_known_prompt",
    }


def artifact_delta_matches_all_patterns( artifact_report: Optional[Dict[str, Any]] ) -> Dict[str, Any]:
    if not isinstance( artifact_report, dict ):
        return {"matched": False, "patterns": [], "missing_patterns": []}
    patterns = [str( pattern ) for pattern in artifact_report.get( "patterns", [] ) if str( pattern )]
    matches_by_pattern = artifact_report.get( "matches_by_pattern", [] )
    matched_patterns: List[str] = []
    missing_patterns: List[str] = []
    if isinstance( matches_by_pattern, list ):
        for entry in matches_by_pattern:
            if not isinstance( entry, dict ):
                continue
            pattern = str( entry.get( "pattern", "" ) )
            lines = entry.get( "lines", [] )
            if isinstance( lines, list ) and lines:
                matched_patterns.append( pattern )
            elif pattern:
                missing_patterns.append( pattern )
    if patterns:
        known_patterns = set( matched_patterns ) | set( missing_patterns )
        missing_patterns.extend( pattern for pattern in patterns if pattern not in known_patterns )
    return {
        "matched": bool( patterns ) and not missing_patterns,
        "patterns": patterns,
        "matched_patterns": matched_patterns,
        "missing_patterns": missing_patterns,
        "artifact_path": str( artifact_report.get( "path", "" ) ),
        "source_log": str( artifact_report.get( "source_log", "" ) ),
    }


def wait_duration_seconds( duration: str ) -> Optional[int]:
    value = duration.strip().lower()
    if not value:
        return None
    match = re.fullmatch( r"(\d+)\s*s(?:ec(?:ond)?s?)?", value )
    if match:
        return int( match.group( 1 ) )
    match = re.fullmatch( r"(\d+)\s*m(?:in(?:ute)?s?)?", value )
    if match:
        return int( match.group( 1 ) ) * 60
    match = re.fullmatch( r"(\d+)\s*h(?:our)?s?", value )
    if match:
        return int( match.group( 1 ) ) * 60 * 60
    return None


def wait_menu_expected_duration_patterns( expected_duration: str ) -> List[str]:
    seconds = wait_duration_seconds( expected_duration )
    if seconds is None:
        return [expected_duration] if expected_duration else []
    if seconds < 60:
        amount = seconds
        unit = "second" if amount == 1 else "seconds"
    elif seconds < 60 * 60:
        amount = seconds // 60
        unit = "minute" if amount == 1 else "minutes"
    else:
        amount = seconds // ( 60 * 60 )
        unit = "hour" if amount == 1 else "hours"
    return [
        expected_duration,
        f"{amount} {unit}",
        f"{amount}{unit[0]}",
    ]


def validate_native_wait_menu_surface(
    screen_text_report: Dict[str, Any],
    *,
    required_patterns: Sequence[str],
    surface: str,
    require_all: bool = True,
) -> Dict[str, Any]:
    """Require the declared native wait surface before sending its next key.

    A screenshot is not enough when a previous modal, stale OCR, or the wrong
    wait chooser owns the input.  Keep this guard deliberately small: exact
    declared text must be present and the generic interruption classifier must
    not report a blocking overlay.
    """
    body = screen_text_body( screen_text_report )
    lowered = body.lower()
    required = [str(pattern).strip() for pattern in required_patterns if str(pattern).strip()]
    matched = [pattern for pattern in required if pattern.lower() in lowered]
    missing = [pattern for pattern in required if pattern not in matched]
    patterns_satisfied = bool(matched) if not require_all else not missing
    interruption = classify_ordinary_wait_interruption(
        screen_text_report,
        semantic_ui_trace_log=None,
        semantic_ui_trace_start_offset=0,
    )
    blocking = str(interruption.get("status", "")) in {"unknown_prompt", "known_prompt"} and \
        str(interruption.get("classification", "")) not in {"no_known_prompt", ""}
    if "case sensitive" in lowered or "actions" in lowered:
        blocking = True
    status = "matched" if required and patterns_satisfied and not blocking else "blocked"
    return {
        "surface": surface,
        "status": status,
        "required_patterns": required,
        "require_all": require_all,
        "matched_patterns": matched,
        "missing_patterns": missing,
        "blocking_overlay": blocking,
        "interruption": interruption,
        "screen_text": body,
    }


def validate_native_wait_mode_semantic_frame(
    *,
    profile: str,
    run_dir: Path,
    run_id: str,
    start_offset: int,
    prior_frame_id: str,
) -> Dict[str, Any]:
    """Require a fresh same-run parent wait frame before duration-menu input."""
    required_actions = ("wait.duration_menu", "alarm.duration_menu")
    try:
        _, owned = refresh_semantic_step_trace(
            profile=profile, run_dir=Path(run_dir), run_id=run_id,
            start_offset=start_offset,
        )
        events, status = read_semantic_step_trace(owned, Path(run_dir), run_id)
    except (OSError, ValueError):
        events, status = [], "missing_or_unreadable"
    frame = latest_semantic_step_frame(events) if status == "ok" else None
    frame_id = str(frame.get("frame_id", "")) if frame else ""
    actions = frame.get("valid_actions", []) if frame else []
    bindings = frame.get("action_inputs", {}) if frame else {}
    missing_actions = [action for action in required_actions if action not in actions]
    bound_actions = [action for action in required_actions if action in bindings and str(bindings[action]).strip()]
    if not str(prior_frame_id).strip():
        reason = "missing_prior_frame"
    elif status != "ok":
        reason = status
    elif frame is None:
        reason = "missing_frame"
    elif str(frame.get("run_id", "")) != str(run_id):
        reason = "wrong_run"
    elif frame_id == str(prior_frame_id):
        reason = "stale_frame"
    elif str(frame.get("state", "")) != "wait_mode_choice":
        reason = "wrong_state"
    elif missing_actions:
        reason = "incomplete_actions"
    elif len(bound_actions) != len(required_actions):
        reason = "incomplete_action_inputs"
    else:
        reason = "matched"
    return {
        "guard": "native_wait_mode_semantic_frame",
        "status": "matched" if reason == "matched" else "blocked",
        "reason": reason,
        "run_id": str(run_id),
        "frame_id": frame_id,
        "prior_frame_id": str(prior_frame_id),
        "state": str(frame.get("state", "")) if frame else "",
        "required_actions": list(required_actions),
        "advertised_actions": list(actions) if isinstance(actions, list) else [],
        "bound_actions": bound_actions,
        "missing_actions": missing_actions,
        "provenance": "native_semantic_step_trace",
    }


def extract_clock_or_turn_evidence( screen_text_report: Dict[str, Any] ) -> Dict[str, Any]:
    text = screen_text_body( screen_text_report )
    clock_matches: List[Dict[str, Any]] = []
    for match in re.finditer(
        r"\b([0-2]?\d):([0-5]\d)(?::([0-5]\d))?[ \t\r\n]{0,8}([ap][mn])?\b",
        text,
        flags=re.IGNORECASE,
    ):
        hour = int( match.group( 1 ) )
        minute = int( match.group( 2 ) )
        second = int( match.group( 3 ) or 0 )
        meridiem = str( match.group( 4 ) or "" ).lower()
        if not meridiem and 1 <= hour <= 12:
            calendar_label = (
                r"(?:monday|tuesday|wednesday|thursday|friday|saturday|sunday|"
                r"january|february|march|april|may|june|july|august|"
                r"september|october|november|december)"
            )
            split_gap = r"[ \t\r\n]{0,8}"
            split_meridiem = re.match(
                rf"{split_gap}(?:(?:{calendar_label}),?{split_gap}){{0,2}}(am|pm)\b",
                text[match.end():],
                flags=re.IGNORECASE,
            )
            if split_meridiem:
                meridiem = split_meridiem.group( 1 ).lower()
        if meridiem and 1 <= hour <= 12:
            hour = hour % 12 + ( 12 if meridiem == "pm" else 0 )
        if hour <= 23:
            clock_matches.append( {
                "text": match.group( 0 ),
                "display_hour": int( match.group( 1 ) ),
                "meridiem": meridiem,
                "seconds_since_midnight": hour * 3600 + minute * 60 + second,
            } )
    turn_matches: List[Dict[str, Any]] = []
    for match in re.finditer( r"\bturn\s*[:#]?\s*(\d{1,12})\b", text, flags=re.IGNORECASE ):
        turn_matches.append( {"text": match.group( 0 ), "turn": int( match.group( 1 ) )} )
    return {
        "clock_matches": clock_matches[:5],
        "turn_matches": turn_matches[:5],
        "source": str( screen_text_report.get( "source_png", "" ) or screen_text_report.get( "image_path", "" ) ),
    }


def classify_wait_step_ledger(
    *,
    label: str,
    choice_key: str,
    expected_duration: str,
    before_text: Dict[str, Any],
    menu_text: Dict[str, Any],
    after_text: Dict[str, Any],
    wait_classification: Dict[str, Any],
    artifact_after_wait: Optional[Dict[str, Any]] = None,
    allow_artifact_elapsed_without_menu_ocr: bool = False,
    allow_exact_artifact_meridiem_ambiguity: bool = False,
    native_wait_continuation: Optional[Mapping[str, Any]] = None,
) -> Dict[str, Any]:
    expected_seconds = wait_duration_seconds( expected_duration )
    selected_duration = LONG_WAIT_MENU_CHOICES.get( choice_key, "" )
    selected_seconds = wait_duration_seconds( selected_duration )
    duration_patterns = wait_menu_expected_duration_patterns( expected_duration )
    menu_body = screen_text_body( menu_text ).lower()
    menu_expected_matches = [pattern for pattern in duration_patterns if pattern.lower() in menu_body]
    menu_has_wait_prompt = "wait" in menu_body and bool( menu_body.strip() )
    before_clock = extract_clock_or_turn_evidence( before_text )
    after_clock = extract_clock_or_turn_evidence( after_text )
    artifact_elapsed = artifact_delta_matches_all_patterns( artifact_after_wait )
    artifact_status = str(
        artifact_after_wait.get( "status", "" )
        if isinstance( artifact_after_wait, dict ) else ""
    )
    artifact_start_size = (
        artifact_after_wait.get( "start_size" )
        if isinstance( artifact_after_wait, dict ) else None
    )
    artifact_end_size = (
        artifact_after_wait.get( "end_size" )
        if isinstance( artifact_after_wait, dict ) else None
    )
    artifact_has_new_bytes = bool(
        isinstance( artifact_start_size, ( int, float ) ) and
        not isinstance( artifact_start_size, bool ) and
        isinstance( artifact_end_size, ( int, float ) ) and
        not isinstance( artifact_end_size, bool ) and
        artifact_end_size > artifact_start_size
    )
    artifact_patterns = artifact_elapsed["patterns"]
    artifact_has_exact_scheduler_endpoint = any(
        re.fullmatch( r"scheduler_hour=\d+", pattern )
        for pattern in artifact_patterns
    )
    artifact_has_exact_now_endpoint = any(
        re.fullmatch( r"now_minutes=\d+", pattern )
        for pattern in artifact_patterns
    )
    native_continuation_proved = isinstance(native_wait_continuation, Mapping) and \
        native_wait_continuation.get("status") == "matched"
    elapsed: Dict[str, Any] = {
        "status": "not_parsed",
        "expected_seconds": expected_seconds,
    }
    if native_continuation_proved:
        elapsed.update( {
            "status": "native_receipt_postcondition",
            "note": "same-run native return receipts supplied the wait continuation boundary",
        } )
    elif before_clock["turn_matches"] and after_clock["turn_matches"]:
        delta = after_clock["turn_matches"][0]["turn"] - before_clock["turn_matches"][0]["turn"]
        elapsed.update( {"status": "turn_delta_parsed", "delta_turns": delta} )
    elif before_clock["clock_matches"] and after_clock["clock_matches"]:
        before_seconds = before_clock["clock_matches"][0]["seconds_since_midnight"]
        after_match = after_clock["clock_matches"][0]
        after_seconds = after_match["seconds_since_midnight"]
        delta = after_seconds - before_seconds
        if delta < 0:
            delta += 24 * 60 * 60
        elapsed.update( {"status": "clock_delta_parsed", "delta_seconds": delta} )
    elif artifact_elapsed["matched"] and expected_seconds is not None:
        elapsed.update( {
            "status": "artifact_delta_after_bounded_wait",
            "note": "all configured wait artifact patterns appeared after choosing the expected bounded wait duration",
        } )

    wait_status = str( wait_classification.get( "status", "" ) )
    selected_duration_matches_expected = bool(
        expected_seconds is not None and selected_seconds == expected_seconds
    )
    meridiem_ambiguity_confirmed = False
    if elapsed["status"] == "clock_delta_parsed" and expected_seconds is not None and \
            elapsed.get( "delta_seconds" ) != expected_seconds and \
            before_clock["clock_matches"] and after_clock["clock_matches"]:
        before_match = before_clock["clock_matches"][0]
        after_match = after_clock["clock_matches"][0]
        before_display_hour = before_match.get( "display_hour" )
        before_meridiem = str( before_match.get( "meridiem", "" ) )
        before_seconds = before_match.get( "seconds_since_midnight" )
        after_display_hour = after_match.get( "display_hour" )
        after_meridiem = str( after_match.get( "meridiem", "" ) )
        after_seconds = after_match.get( "seconds_since_midnight" )
        before_candidates = [before_seconds]
        after_candidates = [after_seconds]
        if isinstance( before_display_hour, int ) and 1 <= before_display_hour <= 12 and \
                not before_meridiem and isinstance( before_seconds, int ):
            before_candidates.append( ( before_seconds + 12 * 60 * 60 ) % ( 24 * 60 * 60 ) )
        if isinstance( after_display_hour, int ) and 1 <= after_display_hour <= 12 and \
                not after_meridiem and isinstance( after_seconds, int ):
            after_candidates.append( ( after_seconds + 12 * 60 * 60 ) % ( 24 * 60 * 60 ) )
        alternative_delta_seconds = next( (
            ( candidate_after - candidate_before ) % ( 24 * 60 * 60 )
            for candidate_before in before_candidates
            for candidate_after in after_candidates
            if candidate_before != before_seconds or candidate_after != after_seconds
            if ( candidate_after - candidate_before ) % ( 24 * 60 * 60 ) == expected_seconds
        ), None )
        meridiem_ambiguity_confirmed = bool(
            allow_exact_artifact_meridiem_ambiguity and
            selected_duration_matches_expected and
            alternative_delta_seconds == expected_seconds and
            wait_status in {"completed", "unknown_after_wait"} and
            artifact_status == "captured" and
            artifact_has_new_bytes and
            artifact_elapsed["matched"] and
            artifact_has_exact_scheduler_endpoint and
            artifact_has_exact_now_endpoint
        )
        elapsed.update( {
            "raw_delta_seconds": elapsed.get( "delta_seconds" ),
            "alternative_before_seconds_candidates": before_candidates,
            "alternative_after_seconds_candidates": after_candidates,
            "alternative_delta_seconds": alternative_delta_seconds,
        } )
        if meridiem_ambiguity_confirmed:
            elapsed.update( {
                "status": "artifact_confirmed_meridiem_ambiguity",
                "note": (
                    "at least one clock endpoint omitted AM/PM; toggling its 12-hour interpretation matches "
                    "the exact bounded choice and newly captured scheduler_hour/now_minutes endpoints"
                ),
            } )
    effective_wait_status = wait_status
    if wait_status == "unknown_after_wait" and artifact_elapsed["matched"]:
        effective_wait_status = "completed_by_artifact_delta"
    menu_ocr_deferred_to_artifact_delta = bool(
        native_continuation_proved or
        ( allow_artifact_elapsed_without_menu_ocr and artifact_elapsed["matched"] and expected_seconds is not None )
    )
    issues: List[str] = []
    if expected_seconds is not None and selected_seconds != expected_seconds:
        issues.append( "choice_key_does_not_match_expected_duration" )
    if not menu_has_wait_prompt and not menu_ocr_deferred_to_artifact_delta:
        issues.append( "wait_menu_ocr_missing_prompt" )
    if expected_seconds is not None and not menu_expected_matches and not menu_ocr_deferred_to_artifact_delta:
        issues.append( "wait_menu_ocr_missing_expected_duration" )
    if elapsed["status"] == "not_parsed" and not native_continuation_proved:
        issues.append( "before_after_clock_or_turn_not_parsed" )
    elif elapsed["status"] == "turn_delta_parsed" and expected_seconds is not None and \
            elapsed.get( "delta_turns" ) != expected_seconds:
        issues.append( "turn_delta_does_not_match_expected_duration" )
    elif elapsed["status"] == "clock_delta_parsed" and expected_seconds is not None and \
            elapsed.get( "delta_seconds" ) != expected_seconds:
        issues.append( "clock_delta_does_not_match_expected_duration" )
    if effective_wait_status == "interrupted_or_prompt_visible":
        verdict = "blocked_wait_interrupted_or_prompt_visible"
    elif native_continuation_proved:
        effective_wait_status = "completed_by_native_receipt"
        verdict = "green_wait_step_proven" if not issues else "yellow_wait_elapsed_or_menu_not_fully_proven"
    elif effective_wait_status not in {"completed", "completed_by_artifact_delta"}:
        verdict = "yellow_wait_finish_or_interrupt_not_classified"
        issues.append( "missing_finish_or_interruption_signal" )
    elif issues:
        verdict = "yellow_wait_elapsed_or_menu_not_fully_proven"
    else:
        verdict = "green_wait_step_proven"

    return {
        "label": label,
        "choice_key": choice_key,
        "selected_duration": selected_duration,
        "selected_seconds": selected_seconds,
        "expected_duration": expected_duration,
        "expected_seconds": expected_seconds,
        "wait_menu_artifact": f"{label}.wait_menu.png / {label}.wait_menu.screen_text.json",
        "menu_has_wait_prompt": menu_has_wait_prompt,
        "menu_expected_duration_patterns": duration_patterns,
        "menu_expected_matches": menu_expected_matches,
        "menu_ocr_deferred_to_artifact_delta": menu_ocr_deferred_to_artifact_delta,
        "before_clock_or_turn": before_clock,
        "after_clock_or_turn": after_clock,
        "artifact_elapsed_evidence": artifact_elapsed,
        "exact_artifact_meridiem_ambiguity_opt_in": allow_exact_artifact_meridiem_ambiguity,
        "meridiem_ambiguity_confirmed": meridiem_ambiguity_confirmed,
        "elapsed": elapsed,
        "finish_or_interrupt_status": effective_wait_status,
        "native_wait_continuation": dict(native_wait_continuation)
        if isinstance(native_wait_continuation, Mapping) else {},
        "issues": issues,
        "verdict": verdict,
        "review_rule": (
            "Artifact matches alone do not make this wait step green. Green normally requires readable wait-menu OCR, "
            "either a parsed before/after clock or turn delta or all configured post-wait cadence artifacts, "
            "and either a finish signal, classified interruption, or completed-by-artifact delta. A scenario may explicitly "
            "defer noisy wait-menu OCR to bounded choice-key plus matched post-wait cadence artifacts. A separate explicit "
            "opt-in accepts a bare endpoint meridiem ambiguity only when the exact choice, bounded completion status, newly captured "
            "artifact bytes, all configured patterns, and exact scheduler_hour/now_minutes endpoints agree."
        ),
    }


def summarize_wait_step_ledgers( step_reports: List[Dict[str, Any]] ) -> Dict[str, Any]:
    ledgers = [step.get( "wait_step_ledger" ) for step in step_reports if isinstance( step.get( "wait_step_ledger" ), dict )]
    verdicts = [str( ledger.get( "verdict", "" ) ) for ledger in ledgers]
    blocked = [ledger for ledger in ledgers if str( ledger.get( "verdict", "" ) ).startswith( "blocked" )]
    yellow = [ledger for ledger in ledgers if str( ledger.get( "verdict", "" ) ).startswith( "yellow" )]
    green = [ledger for ledger in ledgers if str( ledger.get( "verdict", "" ) ).startswith( "green" )]
    if blocked:
        status = "blocked_wait_step"
    elif yellow:
        status = "yellow_wait_step_unverified"
    elif ledgers and len( green ) == len( ledgers ):
        status = "green_wait_steps_proven"
    else:
        status = "no_wait_steps"
    return {
        "status": status,
        "count": len( ledgers ),
        "green_count": len( green ),
        "yellow_count": len( yellow ),
        "blocked_count": len( blocked ),
        "verdicts": verdicts,
        "non_green_steps": [
            {
                "label": str( ledger.get( "label", "" ) ),
                "verdict": str( ledger.get( "verdict", "" ) ),
                "issues": ledger.get( "issues", [] ),
            }
            for ledger in ledgers if not str( ledger.get( "verdict", "" ) ).startswith( "green" )
        ],
        "review_rule": "Overall artifact verdict must not be green when wait ledgers are yellow or blocked.",
    }


def classify_ordinary_wait_interruption(
    screen_text_report: Dict[str, Any],
    *,
    semantic_ui_trace_log: Optional[Path],
    semantic_ui_trace_start_offset: int,
    declared_hostile_auto_move_continuation: Optional[Mapping[str, str]] = None,
) -> Dict[str, Any]:
    """Treat Save-and-Quit text as blocking only with a live bound modal.

    The ordinary gameplay HUD permanently advertises its Save-and-Quit command.
    OCR cannot tell that command-help text from a confirmation.  The native
    semantic trace is authoritative, and its current-run offset prevents an
    earlier process's popup from blocking this wait.
    """
    # A hostile auto-move answer changes live gameplay.  It is therefore not a
    # generic wait recovery: the scenario must advertise the exact observed
    # dialog, actor identity, and native continuation key before this owner may
    # answer it.  The observed spelling is deliberately separate from the
    # native prompt because the left edge of the modal is clipped in the
    # captured R-005 frame; accepting a broader OCR pattern would lose the
    # identity boundary.
    if declared_hostile_auto_move_continuation is not None:
        observed_prompt = str(
            declared_hostile_auto_move_continuation.get("observed_prompt", "")
        ).strip()
        native_prompt = str(
            declared_hostile_auto_move_continuation.get("native_prompt", "")
        ).strip()
        actor = str(
            declared_hostile_auto_move_continuation.get("actor", "")
        ).strip()
        response_key = str(
            declared_hostile_auto_move_continuation.get("response_key", "")
        ).strip()
        observed = screen_text_body(screen_text_report).strip()
        if observed_prompt and native_prompt and actor and response_key == "N" and \
                observed_prompt in observed:
            return {
                "text": observed,
                "response_key": response_key,
                "release_blocking": False,
                "contaminating": False,
                "matched_markers": [observed_prompt],
                "status": "known_prompt",
                "classification": "declared_hostile_auto_move_continuation",
                "provenance": "scenario_declared_native_auto_move_continuation",
                "continuation_receipt": {
                    "actor": actor,
                    "native_prompt": native_prompt,
                    "observed_prompt": observed_prompt,
                    "response_key": response_key,
                    "observed_text_sha256": hashlib.sha256(
                        observed.encode("utf-8")
                    ).hexdigest(),
                },
            }

    classification = classify_blocking_interruption( screen_text_report )
    if classification.get( "classification" ) != "unsafe_confirmation_requires_scenario_choice" or \
            classification.get( "matched_markers" ) != ["save and quit"]:
        return classification

    active_modal = read_active_semantic_ui_trace(
        semantic_ui_trace_log, semantic_ui_trace_start_offset
    )
    if active_modal is None:
        return {
            **classification,
            "status": "clear",
            "classification": "inactive_save_and_quit_hud_text",
            "provenance": "current_run_semantic_ui_trace",
            "semantic_ui_trace_start_offset": semantic_ui_trace_start_offset,
        }

    expected_actions = {"left", "enter"}
    observed_actions = {
        str( action ).strip() for action in active_modal.get( "valid_actions", [] )
    }
    is_quit_confirmation = (
        active_modal.get( "event" ) == "open" and
        active_modal.get( "intent" ) == "main_menu_quit_confirmation" and
        expected_actions.issubset( observed_actions ) and
        not bool( active_modal.get( "read_truncated", False ) )
    )
    if is_quit_confirmation:
        return {
            **classification,
            "provenance": "current_run_semantic_ui_trace",
            "semantic_ui_trace": active_modal,
        }
    return {
        **classification,
        "status": "unknown_prompt",
        "classification": "save_and_quit_text_with_conflicting_active_semantic_modal",
        "provenance": "current_run_semantic_ui_trace",
        "semantic_ui_trace": active_modal,
    }

def capture_wait_artifact_delta(
    artifact_log: Optional[Path],
    run_dir: Path,
    label: str,
    suffix: str,
    start_size: int,
    patterns: List[str],
    *,
    filter_debug_noise: bool,
) -> Dict[str, Any]:
    if artifact_log is None:
        return {
            "status": "not_configured",
            "source_log": "",
            "start_size": start_size,
            "end_size": start_size,
            "line_count": 0,
            "patterns": patterns,
            "matches_by_pattern": [],
            "matched_lines": [],
            "path": "",
        }
    end_size = artifact_log.stat().st_size if artifact_log.exists() else start_size
    text = read_log_delta(artifact_log, start_size, filter_debug_noise=filter_debug_noise)
    out_path = run_dir / f"{label}.{suffix}.artifacts.log"
    if text:
        out_path.write_text(text, encoding="utf-8")
    matches_by_pattern: List[Dict[str, Any]] = []
    matched_lines: List[str] = []
    for pattern in patterns:
        lines = [line for line in text.splitlines() if pattern in line]
        matches_by_pattern.append({"pattern": pattern, "lines": lines})
        matched_lines.extend(lines)
    return {
        "status": "captured" if text else "no_new_artifacts",
        "source_log": str(artifact_log),
        "start_size": start_size,
        "end_size": end_size,
        "line_count": len(text.splitlines()) if text else 0,
        "patterns": patterns,
        "matches_by_pattern": matches_by_pattern,
        "matched_lines": matched_lines,
        "path": str(out_path) if text else "",
    }


def poll_wait_artifact_completion(
    artifact_log: Path,
    run_dir: Path,
    label: str,
    start_size: int,
    patterns: List[str],
    *,
    timeout_seconds: float,
    poll_seconds: float,
    filter_debug_noise: bool,
    baseline_now_minutes: Optional[int] = None,
    minimum_elapsed_minutes: int = 0,
    interruption_handler: Optional[Callable[[], Dict[str, Any]]] = None,
    continue_after_contaminating: bool = False,
) -> Dict[str, Any]:
    poll_started = time.monotonic()
    poll_attempts = 0
    poll_report: Dict[str, Any] = {}
    interruption_reports: List[Dict[str, Any]] = []
    acknowledgement_count = 0
    response_keys: List[str] = []
    release_blocking = False
    contaminating = False
    aborted = False
    abort_reason = ""

    def observe_completion() -> Dict[str, Any]:
        nonlocal poll_attempts, poll_report
        poll_attempts += 1
        poll_report = capture_wait_artifact_delta(
            artifact_log,
            run_dir,
            label,
            "completion_poll",
            start_size,
            patterns,
            filter_debug_noise=filter_debug_noise,
        )
        poll_match = artifact_delta_matches_all_patterns( poll_report )
        latest_now_minutes = latest_now_minutes_marker(
            artifact_log,
            start_offset=start_size,
        )
        observed_elapsed_minutes = (
            latest_now_minutes - baseline_now_minutes
            if latest_now_minutes is not None and baseline_now_minutes is not None
            else None
        )
        elapsed_minutes_matched = bool(
            minimum_elapsed_minutes <= 0 or
            (
                observed_elapsed_minutes is not None and
                observed_elapsed_minutes >= minimum_elapsed_minutes
            )
        )
        poll_match["artifact_now_minutes"] = {
            "baseline": baseline_now_minutes,
            "latest": latest_now_minutes,
            "observed_elapsed": observed_elapsed_minutes,
            "minimum_elapsed": minimum_elapsed_minutes,
            "matched": elapsed_minutes_matched,
        }
        if not elapsed_minutes_matched:
            poll_match["matched"] = False
            poll_match["missing_patterns"] = list(
                poll_match.get("missing_patterns", [])
            ) + [f"now_minutes_delta>={minimum_elapsed_minutes}"]
        return poll_match

    while True:
        poll_match = observe_completion()
        if poll_match["matched"]:
            break
        if interruption_handler is not None:
            interruption = interruption_handler()
            interruption_reports.append( interruption )
            acknowledgements = interruption.get( "acknowledgements", [] )
            if isinstance( acknowledgements, list ):
                for acknowledgement in acknowledgements:
                    if not isinstance( acknowledgement, dict ):
                        continue
                    response_key = str( acknowledgement.get( "response_key", "" ) )
                    if response_key:
                        response_keys.append( response_key )
            acknowledgement_count += int(
                interruption.get( "acknowledgement_count", len( acknowledgements ) ) or 0
            )
            release_blocking = release_blocking or bool(
                interruption.get( "release_blocking", False )
            )
            contaminating = contaminating or bool(
                interruption.get( "contaminating", False )
            )
            interruption_status = str( interruption.get( "status", "unobservable" ) )
            if release_blocking:
                aborted = True
                abort_reason = "release_blocking_interruption"
            elif contaminating and not continue_after_contaminating:
                aborted = True
                abort_reason = "contaminating_interruption"
            elif interruption_status.startswith( "blocked_" ):
                aborted = True
                abort_reason = interruption_status
            if aborted:
                break
        elapsed_seconds = time.monotonic() - poll_started
        if elapsed_seconds >= timeout_seconds:
            # A producer may append its terminal record while the deadline check is
            # running. Take one last observation at that boundary, but never after
            # an interruption has made the wait unsafe to classify.
            if not aborted:
                poll_match = observe_completion()
            break
        time.sleep( min( max( poll_seconds, 0.05 ), timeout_seconds - elapsed_seconds ) )
    elapsed_seconds = round( time.monotonic() - poll_started, 3 )
    if aborted:
        status = "aborted_interruption"
    elif poll_match["matched"]:
        status = "matched"
    else:
        status = "timed_out"
    return {
        "status": status,
        "aborted": aborted,
        "abort_reason": abort_reason,
        "attempts": poll_attempts,
        "elapsed_seconds": elapsed_seconds,
        "timeout_seconds": timeout_seconds,
        "poll_seconds": poll_seconds,
        "start_size": start_size,
        "match": poll_match,
        "interruption_handling": {
            "status": (
                "aborted_interruption"
                if aborted
                else ( "recovered_known_interruptions" if acknowledgement_count else "clear" )
            ),
            "acknowledgement_count": acknowledgement_count,
            "response_keys": response_keys,
            "release_blocking": release_blocking,
            "contaminating": contaminating,
            "reports": interruption_reports,
        },
    }


def latest_now_minutes_marker(
    artifact_log: Path,
    *,
    start_offset: int = 0,
    end_offset: Optional[int] = None,
    read_cap_bytes: int = 256 * 1024,
) -> Optional[int]:
    if not artifact_log.exists():
        return None
    size = artifact_log.stat().st_size
    bounded_end = max(0, min(size, end_offset)) if end_offset is not None else size
    bounded_start = max(0, min(start_offset, bounded_end), bounded_end - read_cap_bytes)
    with artifact_log.open("rb") as handle:
        handle.seek(bounded_start)
        body = handle.read(bounded_end - bounded_start).decode("utf-8", errors="replace")
    matches = list(re.finditer(r"\bnow_minutes=(\d+)\b", body))
    return int(matches[-1].group(1)) if matches else None


ECOLOGY_INCIDENT_ARTIFACT_PATTERN = re.compile(
    r"^ecology_incident_(?P<turn>\d+)\.(?P<extension>json|png)$"
)
PNG_SIGNATURE = b"\x89PNG\r\n\x1a\n"


def ecology_incident_artifact_baseline(run_dir: Path) -> List[str]:
    """Snapshot direct incident artifacts before the game receives the publish key."""

    if not run_dir.exists():
        return []
    return sorted(
        path.name
        for path in run_dir.iterdir()
        if path.is_file() and path.name.startswith("ecology_incident_")
        and path.suffix.lower() in {".json", ".png"}
    )


def png_header_issue(path: Path) -> str:
    """Reject empty/non-PNG output without introducing an image-decoder dependency."""

    try:
        with path.open("rb") as stream:
            header = stream.read(33)
    except OSError:
        return "png_unreadable"
    if len(header) < 33:
        return "png_truncated"
    if header[:8] != PNG_SIGNATURE:
        return "png_signature_invalid"
    if int.from_bytes(header[8:12], "big") != 13 or header[12:16] != b"IHDR":
        return "png_ihdr_invalid"
    width = int.from_bytes(header[16:20], "big")
    height = int.from_bytes(header[20:24], "big")
    if width <= 0 or height <= 0:
        return "png_dimensions_invalid"
    return ""


def committed_revision_matches(observed: str, expected: str) -> bool:
    version_pattern = re.compile(
        r"^(?P<revision>[0-9a-f]{7,40})(?:-dirty)?(?:\+[A-Za-z0-9][A-Za-z0-9._]*)*$"
    )
    expected_pattern = re.compile(r"^[0-9a-f]{7,40}$")
    observed_match = version_pattern.fullmatch(str(observed or "").strip())
    expected_revision = str(expected or "").strip()
    if observed_match is None or not expected_pattern.fullmatch(expected_revision):
        return False
    observed_revision = observed_match.group("revision")
    return observed_revision.startswith(expected_revision) or expected_revision.startswith(
        observed_revision
    )


def audit_fresh_ecology_incident_pair(
    run_dir: Path,
    *,
    baseline_names: Sequence[str],
    expected_scenario: str,
    expected_commit: str,
    expected_binary: str,
) -> Dict[str, Any]:
    """Require one newly published, identity-bound natural incident pair."""

    baseline = {str(name) for name in baseline_names}
    current_names = ecology_incident_artifact_baseline(run_dir)
    fresh_names = sorted(name for name in current_names if name not in baseline)
    issues: List[str] = []
    fresh_by_stem: Dict[str, Set[str]] = {}
    turns_by_stem: Dict[str, int] = {}
    for name in fresh_names:
        match = ECOLOGY_INCIDENT_ARTIFACT_PATTERN.fullmatch(name)
        if match is None:
            issues.append("fresh_incident_filename_invalid")
            continue
        stem = Path(name).stem
        fresh_by_stem.setdefault(stem, set()).add(match.group("extension"))
        turns_by_stem[stem] = int(match.group("turn"))

    if not fresh_by_stem:
        issues.append("fresh_incident_pair_missing")
    elif len(fresh_by_stem) != 1:
        issues.append("fresh_incident_pair_ambiguous")

    selected_stem = next(iter(fresh_by_stem), "") if len(fresh_by_stem) == 1 else ""
    extensions = fresh_by_stem.get(selected_stem, set())
    if selected_stem and "json" not in extensions:
        issues.append("fresh_incident_json_missing")
    if selected_stem and "png" not in extensions:
        issues.append("fresh_incident_png_missing")

    json_path = run_dir / f"{selected_stem}.json" if selected_stem else Path()
    png_path = run_dir / f"{selected_stem}.png" if selected_stem else Path()
    payload: Dict[str, Any] = {}
    if selected_stem and "json" in extensions:
        try:
            loaded = json.loads(json_path.read_text(encoding="utf-8"))
            if isinstance(loaded, dict):
                payload = loaded
            else:
                issues.append("incident_json_not_object")
        except (OSError, UnicodeError, json.JSONDecodeError):
            issues.append("incident_json_malformed")

    identity = payload.get("identity") if isinstance(payload.get("identity"), dict) else {}
    selected = payload.get("selected") if isinstance(payload.get("selected"), dict) else {}
    token = selected.get("token") if isinstance(selected.get("token"), dict) else {}
    deltas = payload.get("deltas") if isinstance(payload.get("deltas"), dict) else {}
    records = deltas.get("records") if isinstance(deltas.get("records"), list) else []
    interventions = payload.get("interventions")

    if payload:
        if payload.get("schema") != "c-aol.ecology.incident":
            issues.append("incident_schema_invalid")
        if payload.get("version") != 2:
            issues.append("incident_version_invalid")
        if not identity:
            issues.append("incident_identity_missing")
        if identity.get("scenario") != expected_scenario:
            issues.append("incident_scenario_mismatch")
        if identity.get("run_identity") != run_dir.name:
            issues.append("incident_run_identity_mismatch")
        if not committed_revision_matches(str(identity.get("commit", "")), expected_commit):
            issues.append("incident_commit_mismatch")
        if identity.get("binary") != Path(expected_binary).name:
            issues.append("incident_binary_mismatch")
        if selected_stem and identity.get("turn") != turns_by_stem.get(selected_stem):
            issues.append("incident_turn_filename_mismatch")

        selected_id = str(selected.get("id", "")).strip()
        canonical_id = str(token.get("canonical_id", "")).strip()
        if not selected_id or selected_id != canonical_id:
            issues.append("incident_selection_token_mismatch")
        if selected.get("provenance") != "natural":
            issues.append("incident_selection_provenance_not_natural")
        if deltas.get("schema") != "c-aol.ecology.delta" or deltas.get("version") != 1:
            issues.append("incident_delta_schema_invalid")
        if not records:
            issues.append("incident_delta_records_missing")
        for record in records:
            if not isinstance(record, dict):
                issues.append("incident_delta_record_invalid")
                continue
            if record.get("provenance") != "natural":
                issues.append("incident_delta_provenance_not_natural")
            if not selected_id or record.get("entity_id") != selected_id:
                issues.append("incident_delta_entity_mismatch")
        if not isinstance(interventions, list):
            issues.append("incident_interventions_invalid")
        elif interventions:
            issues.append("incident_interventions_present")

    if selected_stem and "png" in extensions:
        png_issue = png_header_issue(png_path)
        if png_issue:
            issues.append(png_issue)

    issues = list(dict.fromkeys(issues))
    return {
        "status": "required_state_present" if not issues else "required_state_missing",
        "run_dir": str(run_dir),
        "baseline_names": sorted(baseline),
        "fresh_names": fresh_names,
        "artifact_path": str(json_path) if selected_stem else "",
        "incident_json": str(json_path) if selected_stem else "",
        "incident_png": str(png_path) if selected_stem else "",
        "expected_scenario": expected_scenario,
        "expected_commit": expected_commit,
        "expected_binary": Path(expected_binary).name,
        "observed_scenario": str(identity.get("scenario", "")),
        "observed_commit": str(identity.get("commit", "")),
        "observed_binary": str(identity.get("binary", "")),
        "observed_run_identity": str(identity.get("run_identity", "")),
        "observed_selected_id": str(selected.get("id", "")),
        "observed_canonical_id": str(token.get("canonical_id", "")),
        "observed_delta_count": len(records),
        "missing_required_fields": issues,
    }


def audit_log_contains(
    run_dir: Path,
    label: str,
    *,
    artifact_log: Optional[Path],
    artifact_baseline: int,
    patterns: List[str],
    required_line_patterns: Optional[List[List[str]]] = None,
    required_any_line_patterns: Optional[List[List[str]]] = None,
    filter_debug_noise: bool = False,
) -> Dict[str, Any]:
    line_pattern_groups = required_line_patterns or []
    any_line_pattern_groups = required_any_line_patterns or []
    any_group_label = " OR ".join(" && ".join(group) for group in any_line_pattern_groups)
    required_items = patterns + [" && ".join(group) for group in line_pattern_groups]
    if any_line_pattern_groups:
        required_items.append(any_group_label)
    if artifact_log is None:
        return {
            "status": "failed",
            "reason": "artifact_log_not_configured",
            "required_items": required_items,
            "missing_required_items": required_items,
            "source_log": "",
        }
    text = read_log_delta(artifact_log, artifact_baseline, filter_debug_noise=filter_debug_noise)
    out_path = run_dir / f"{label}.log_delta.txt"
    if text:
        out_path.write_text(text, encoding="utf-8")
    log_lines = text.splitlines()
    matches_by_pattern: List[Dict[str, Any]] = []
    missing: List[str] = []
    for pattern in patterns:
        lines = [line for line in log_lines if pattern in line]
        matches_by_pattern.append({"pattern": pattern, "lines": lines})
        if not lines:
            missing.append(pattern)
    for group in line_pattern_groups:
        group_label = " && ".join(group)
        lines = [line for line in log_lines if all(pattern in line for pattern in group)]
        matches_by_pattern.append({"pattern": group_label, "line_patterns": group, "lines": lines})
        if not lines:
            missing.append(group_label)
    if any_line_pattern_groups:
        any_lines: List[str] = []
        any_matches: List[Dict[str, Any]] = []
        for group in any_line_pattern_groups:
            group_label = " && ".join(group)
            lines = [line for line in log_lines if all(pattern in line for pattern in group)]
            any_matches.append({"pattern": group_label, "line_patterns": group, "lines": lines})
            any_lines.extend(lines)
        matches_by_pattern.append({
            "pattern": any_group_label,
            "any_line_patterns": any_matches,
            "lines": any_lines,
        })
        if not any_lines:
            missing.append(any_group_label)
    return {
        "status": "required_state_present" if required_items and not missing else ("required_state_missing" if required_items else "scanned"),
        "source_log": str(artifact_log),
        "artifact_path": str(out_path) if text else "",
        "start_size": artifact_baseline,
        "end_size": artifact_log.stat().st_size if artifact_log.exists() else artifact_baseline,
        "required_items": required_items,
        "observed_items": [entry["pattern"] for entry in matches_by_pattern if entry.get("lines")],
        "missing_required_items": missing,
        "matches_by_pattern": matches_by_pattern,
        "matched_lines": [line for entry in matches_by_pattern for line in entry.get("lines", [])],
        "line_count": len(log_lines) if text else 0,
    }


def audit_ordinary_overmap_route_constructor(
    run_dir: Path,
    label: str,
    *,
    artifact_log: Optional[Path],
    artifact_baseline: int,
    origin_omt: Sequence[int],
    destination_omt: Sequence[int],
    filter_debug_noise: bool = False,
    require_native_corridor: bool = False,
    native_preview_segment_start_omt: Optional[Sequence[int]] = None,
    native_preview_receipt_context: Optional[Mapping[str, Any]] = None,
) -> Dict[str, Any]:
    """Verify the real overmap route constructor from entry through preview."""
    def format_omt(value: Sequence[int], field: str) -> str:
        if len(value) != 3:
            raise ValueError(f"{field} must contain exactly three coordinates")
        try:
            return ",".join(str(int(component)) for component in value)
        except (TypeError, ValueError) as exc:
            raise ValueError(f"{field} must contain integer coordinates") from exc

    origin = format_omt(origin_omt, "origin_omt")
    destination = format_omt(destination_omt, "destination_omt")
    requested_start = (
        format_omt(native_preview_segment_start_omt, "native_preview_segment_start_omt")
        if native_preview_segment_start_omt is not None else ""
    )
    required_line_patterns = [
        [
            "openclaw_harness_ui_trace: component=overmap_route_cursor event=entered",
            f"position={origin}",
        ],
        [
            "openclaw_harness_ui_trace: component=overmap_route_cursor event=position",
            f"position={destination}",
        ],
        [
            "openclaw_harness_ui_trace: component=overmap_route_input event=resolved",
            'resolved_action="CHOOSE_DESTINATION"',
        ],
        [
            "openclaw_harness_ui_trace: component=overmap_route event=constructed",
            f"destination={destination}",
            "path_nonempty=true",
        ],
    ]
    metadata = audit_log_contains(
        run_dir,
        label,
        artifact_log=artifact_log,
        artifact_baseline=artifact_baseline,
        patterns=[],
        required_line_patterns=required_line_patterns,
        filter_debug_noise=filter_debug_noise,
    )
    metadata.update({
        "origin_omt": origin,
        "destination_omt": destination,
        "constructor_stages": [
            "overmap_entered",
            "cursor_bound_to_destination",
            "choose_destination_resolved",
            "nonempty_route_constructed",
        ],
    })
    native_corridor = parse_native_planned_corridor(
        metadata.get("matched_lines", []), list(destination_omt),
        requested_start=(list(native_preview_segment_start_omt)
                         if native_preview_segment_start_omt is not None else None),
    )
    metadata["native_planned_corridor"] = native_corridor
    if native_preview_segment_start_omt is not None:
        receipt_context = native_preview_receipt_context or {}
        metadata["native_preview_receipt"] = {
            "requested_start": list(native_preview_segment_start_omt),
            "actual_first": native_corridor.get("actual_first"),
            "requested_end": list(destination_omt),
            "actual_terminal": native_corridor.get("actual_terminal"),
            "exact_native_corridor": native_corridor.get("planned_corridor"),
            "run": str(receipt_context.get("run", "")),
            "scenario": str(receipt_context.get("scenario", "")),
            "source": str(receipt_context.get("source", "")),
            "executable": str(receipt_context.get("executable", "")),
            "world_mutation": native_corridor.get("world_mutation"),
            "status": native_corridor.get("status"),
        }
        metadata["native_preview_segment_start_omt"] = requested_start
        missing_receipt_bindings = [
            key for key in ("run", "scenario", "source", "executable")
            if not metadata["native_preview_receipt"][key]
        ]
        if missing_receipt_bindings:
            metadata["status"] = "required_state_missing"
            metadata["missing_required_items"].extend(
                f"native preview receipt {key}" for key in missing_receipt_bindings
            )
    if require_native_corridor and native_corridor.get("status") != "green":
        metadata["status"] = "required_state_missing"
        metadata["missing_required_items"].append(
            "native overmap route constructor planned corridor"
        )
    return metadata


def parse_structural_route_analyzer_line(line: str) -> Optional[Dict[str, str]]:
    """Parse one normalized owner route-analyzer line, if present."""
    marker = "bandit_live_world structural_route_analyzer "
    normalized = " ".join(str(line).split())
    marker_index = normalized.find(marker)
    if marker_index < 0:
        return None
    fields: Dict[str, str] = {}
    body = normalized[marker_index + len(marker):]
    for token in body.split():
        if "=" not in token:
            continue
        key, value = token.split("=", 1)
        if key in {
                "site", "lead", "target", "selector", "outcome", "watch", "route_cost",
                "corridor", "summary"
        }:
            fields[key] = value
    summary_marker = " summary="
    if summary_marker in body:
        fields["summary"] = body.split( summary_marker, 1 )[1].strip()
    if not fields.get("site") or not fields.get("lead") or not fields.get("target"):
        return None
    outcome = fields.get("outcome", "")
    if not fields.get("summary", "").startswith("live structural route"):
        return None
    if fields.get("selector") not in {"frontier", "non_frontier"}:
        return None
    if outcome == "selected" and (not fields.get("watch") or not fields.get("route_cost")):
        return None
    if outcome not in {"selected", "rejected"}:
        return None
    return fields


def parse_structural_route_analyzer_corridor(value: str) -> Optional[List[List[int]]]:
    """Read an owner-derived closed OMT corridor without imposing coordinates."""
    raw_points = str(value).split(">")
    if len(raw_points) < 2:
        return None
    corridor: List[List[int]] = []
    for raw_point in raw_points:
        matched = re.fullmatch(r"\((-?\d+),(-?\d+),(-?\d+)\)", raw_point)
        if matched is None:
            return None
        corridor.append([int(component) for component in matched.groups()])
    if corridor[0] != corridor[-1]:
        return None
    return corridor


def audit_local_reality_safety_preflight_text(text: str) -> Dict[str, Any]:
    """Fail closed unless one complete, safe local-reality preflight is present."""
    summary_marker = "bandit_live_world local_reality_safety_preflight "
    resident_marker = "bandit_live_world local_reality_safety_resident "
    required_resident_fields = {
        "identity", "type", "position", "senses", "hostile", "visible", "contact",
        "same_z_possible_reach", "attack_target", "goal", "verdict",
    }
    summaries: List[Dict[str, str]] = []
    residents: List[Dict[str, str]] = []
    issues: List[str] = []
    for line in text.splitlines():
        normalized = " ".join(str(line).split())
        marker = ""
        destination: Optional[List[Dict[str, str]]] = None
        if summary_marker in normalized:
            marker = summary_marker
            destination = summaries
        elif resident_marker in normalized:
            marker = resident_marker
            destination = residents
        else:
            continue
        fields = {
            key: value for key, value in
            (token.split("=", 1) for token in normalized.split(marker, 1)[1].split() if "=" in token)
        }
        if destination is summaries:
            if set(fields) != {"observer", "resident_monsters", "outcome"}:
                issues.append("malformed_summary")
            else:
                destination.append(fields)
        elif set(fields) != required_resident_fields:
            issues.append("malformed_resident")
        else:
            destination.append(fields)
    if len(summaries) != 1:
        issues.append("missing_or_multiple_summary")
    if len(summaries) == 1:
        summary = summaries[0]
        try:
            count = int(summary["resident_monsters"])
        except ValueError:
            issues.append("malformed_resident_count")
            count = -1
        if count < 0 or count != len(residents):
            issues.append("resident_count_mismatch")
        if summary["outcome"] != "safe":
            issues.append("unsafe_summary")
    for resident in residents:
        if resident["identity"] != resident["type"] + "@" + resident["position"]:
            issues.append("ambiguous_resident_identity")
        if resident["senses"] not in {"infrared:yes", "infrared:no"}:
            issues.append("malformed_senses")
        if any(resident[field] not in {"yes", "no"} for field in
               {"hostile", "visible", "contact", "same_z_possible_reach"}):
            issues.append("malformed_boolean")
        if resident["verdict"] != "safe":
            issues.append("unsafe_resident")
    return {
        "status": "required_state_present" if not issues else "required_state_missing",
        "issues": sorted(set(issues)),
        "summary_count": len(summaries),
        "resident_count": len(residents),
    }


def audit_structural_route_analyzer(
    run_dir: Path,
    label: str,
    *,
    artifact_log: Optional[Path],
    artifact_baseline: int,
    required_outcomes: List[str],
    required_site: str = "",
    required_target: str = "",
    require_complete_corridor: bool = False,
    filter_debug_noise: bool = False,
) -> Dict[str, Any]:
    required = [outcome for outcome in required_outcomes if outcome in {"selected", "rejected"}]
    if artifact_log is None:
        return {
            "status": "failed",
            "reason": "artifact_log_not_configured",
            "required_outcomes": required,
            "missing_required_outcomes": required,
            "source_log": "",
        }
    text = read_log_delta(artifact_log, artifact_baseline, filter_debug_noise=filter_debug_noise)
    parsed: List[Dict[str, str]] = []
    for line in text.splitlines():
        entry = parse_structural_route_analyzer_line(line)
        if entry is None:
            continue
        if required_site and entry.get("site") != required_site:
            continue
        if required_target and entry.get("target") != required_target:
            continue
        parsed.append(entry)
    observed = {entry["outcome"] for entry in parsed}
    missing = [outcome for outcome in required if outcome not in observed]
    derived_corridors = [
        {
            "site": entry["site"],
            "lead": entry["lead"],
            "target": entry["target"],
            "watch": entry["watch"],
            "corridor": parse_structural_route_analyzer_corridor(entry.get("corridor", "")),
        }
        for entry in parsed
        if entry.get("outcome") == "selected"
        and parse_structural_route_analyzer_corridor(entry.get("corridor", "")) is not None
    ]
    if require_complete_corridor and not derived_corridors:
        missing.append("complete owner-derived corridor")
    artifact_path = run_dir / f"{label}.metadata.json"
    metadata = {
        "status": "required_state_present" if required and not missing else (
            "required_state_missing" if required else "scanned"
        ),
        "source_log": str(artifact_log),
        "artifact_path": str(artifact_path),
        "start_size": artifact_baseline,
        "end_size": artifact_log.stat().st_size if artifact_log.exists() else artifact_baseline,
        "required_outcomes": required,
        "required_site": required_site,
        "required_target": required_target,
        "require_complete_corridor": require_complete_corridor,
        "missing_required_outcomes": missing,
        "matches": parsed,
        "derived_corridors": derived_corridors,
    }
    write_json(artifact_path, metadata)
    return metadata


def audit_log_not_contains(
    run_dir: Path,
    label: str,
    *,
    artifact_log: Optional[Path],
    artifact_baseline: int,
    patterns: List[str],
    forbidden_line_patterns: Optional[List[List[str]]] = None,
    forbidden_any_line_patterns: Optional[List[List[str]]] = None,
    filter_debug_noise: bool = False,
) -> Dict[str, Any]:
    """Read a scenario log delta and require named strings/line groups to be absent."""
    line_pattern_groups = forbidden_line_patterns or []
    any_line_pattern_groups = forbidden_any_line_patterns or []
    forbidden_items = patterns + [" && ".join(group) for group in line_pattern_groups]
    if any_line_pattern_groups:
        forbidden_items.append(" OR ".join(" && ".join(group) for group in any_line_pattern_groups))
    if artifact_log is None:
        return {
            "status": "failed",
            "reason": "artifact_log_not_configured",
            "forbidden_items": forbidden_items,
            "observed_forbidden_items": forbidden_items,
            "missing_required_items": forbidden_items,
            "source_log": "",
        }
    text = read_log_delta(artifact_log, artifact_baseline, filter_debug_noise=filter_debug_noise)
    out_path = run_dir / f"{label}.log_delta.txt"
    if text:
        out_path.write_text(text, encoding="utf-8")
    log_lines = text.splitlines()
    matches_by_pattern: List[Dict[str, Any]] = []
    observed_forbidden: List[str] = []
    for pattern in patterns:
        lines = [line for line in log_lines if pattern in line]
        matches_by_pattern.append({"pattern": pattern, "lines": lines})
        if lines:
            observed_forbidden.append(pattern)
    for group in line_pattern_groups:
        group_label = " && ".join(group)
        lines = [line for line in log_lines if all(pattern in line for pattern in group)]
        matches_by_pattern.append({"pattern": group_label, "line_patterns": group, "lines": lines})
        if lines:
            observed_forbidden.append(group_label)
    if any_line_pattern_groups:
        any_group_label = " OR ".join(" && ".join(group) for group in any_line_pattern_groups)
        any_lines: List[str] = []
        any_matches: List[Dict[str, Any]] = []
        for group in any_line_pattern_groups:
            group_label = " && ".join(group)
            lines = [line for line in log_lines if all(pattern in line for pattern in group)]
            any_matches.append({"pattern": group_label, "line_patterns": group, "lines": lines})
            any_lines.extend(lines)
        matches_by_pattern.append({
            "pattern": any_group_label,
            "any_line_patterns": any_matches,
            "lines": any_lines,
        })
        if any_lines:
            observed_forbidden.append(any_group_label)
    matched_lines = [line for entry in matches_by_pattern for line in entry.get("lines", [])]
    return {
        "status": "required_state_present" if forbidden_items and not observed_forbidden else ("required_state_missing" if forbidden_items else "scanned"),
        "source_log": str(artifact_log),
        "artifact_path": str(out_path) if text else str(run_dir / f"{label}.metadata.json"),
        "start_size": artifact_baseline,
        "end_size": artifact_log.stat().st_size if artifact_log.exists() else artifact_baseline,
        "forbidden_items": forbidden_items,
        "observed_forbidden_items": observed_forbidden,
        "required_items": [f"absent: {item}" for item in forbidden_items],
        "observed_items": [f"absent: {item}" for item in forbidden_items if item not in observed_forbidden],
        "missing_required_items": [f"forbidden present: {item}" for item in observed_forbidden],
        "matches_by_pattern": matches_by_pattern,
        "matched_lines": matched_lines,
        "line_count": len(log_lines) if text else 0,
        "capture_policy": "negative log guard; full delta is stored on disk, chat should cite only forbidden-item summary",
    }


def player_message_log_path(world_dir: Path, player_save: str = "") -> Path:
    selected_player_save = str(player_save or "").strip()
    if selected_player_save:
        if selected_player_save.endswith(".sav.zzip"):
            return world_dir / (selected_player_save[: -len(".sav.zzip")] + ".log")
        return world_dir / (Path(selected_player_save).stem + ".log")
    logs = sorted(world_dir.glob("*.log"))
    if len(logs) == 1:
        return logs[0]
    saves = sorted(world_dir.glob("*.sav.zzip"))
    if len(saves) == 1:
        return world_dir / (saves[0].name[: -len(".sav.zzip")] + ".log")
    raise RuntimeError(f"Expected one player message log in {world_dir}, found {[path.name for path in logs]}")


def audit_player_message_log_contains(
    world_dir: Path,
    run_dir: Path,
    label: str,
    *,
    player_save: str = "",
    changed_since: Optional[Dict[str, Any]] = None,
    patterns: List[str],
    required_line_patterns: Optional[List[List[str]]] = None,
    required_any_line_patterns: Optional[List[List[str]]] = None,
) -> Dict[str, Any]:
    line_pattern_groups = required_line_patterns or []
    any_line_pattern_groups = required_any_line_patterns or []
    any_group_label = " OR ".join(" && ".join(group) for group in any_line_pattern_groups)
    required_items = patterns + [" && ".join(group) for group in line_pattern_groups]
    if any_line_pattern_groups:
        required_items.append(any_group_label)
    log_path = player_message_log_path(world_dir, player_save=player_save)
    baseline = 0
    changed_label = ""
    if changed_since:
        changed_label = str(changed_since.get("label", "") or "")
        try:
            baseline = int(changed_since.get("log_size", 0) or 0)
        except (TypeError, ValueError):
            baseline = 0
    if not log_path.exists():
        return {
            "status": "required_state_missing" if required_items else "baseline_recorded",
            "reason": "player_message_log_not_found",
            "world": world_dir.name,
            "world_dir": str(world_dir),
            "player_save": player_save,
            "source_log": str(log_path),
            "log_size": 0,
            "required_items": required_items,
            "missing_required_items": required_items,
            "changed_since_label": changed_label,
            "changed_since_log_size": baseline,
        }
    raw_bytes = log_path.read_bytes()
    log_size = len(raw_bytes)
    if baseline > log_size:
        delta_bytes = b""
    else:
        delta_bytes = raw_bytes[max(0, baseline):]
    delta = delta_bytes.decode("utf-8", errors="replace")
    log_lines = delta.splitlines()
    matches_by_pattern: List[Dict[str, Any]] = []
    missing: List[str] = []
    for pattern in patterns:
        lines = [line for line in log_lines if pattern in line]
        matches_by_pattern.append({"pattern": pattern, "lines": lines})
        if not lines:
            missing.append(pattern)
    for group in line_pattern_groups:
        group_label = " && ".join(group)
        lines = [line for line in log_lines if all(pattern in line for pattern in group)]
        matches_by_pattern.append({"pattern": group_label, "line_patterns": group, "lines": lines})
        if not lines:
            missing.append(group_label)
    if any_line_pattern_groups:
        any_lines: List[str] = []
        any_matches: List[Dict[str, Any]] = []
        for group in any_line_pattern_groups:
            group_label = " && ".join(group)
            lines = [line for line in log_lines if all(pattern in line for pattern in group)]
            any_matches.append({"pattern": group_label, "line_patterns": group, "lines": lines})
            any_lines.extend(lines)
        matches_by_pattern.append({
            "pattern": any_group_label,
            "any_line_patterns": any_matches,
            "lines": any_lines,
        })
        if not any_lines:
            missing.append(any_group_label)
    matched_lines = [line for entry in matches_by_pattern for line in entry.get("lines", [])]
    matched_path = run_dir / f"{label}.matched_player_messages.txt"
    if matched_lines:
        matched_path.write_text("\n".join(matched_lines).rstrip() + "\n", encoding="utf-8")
    return {
        "status": "required_state_present" if required_items and not missing else ("required_state_missing" if required_items else "baseline_recorded"),
        "world": world_dir.name,
        "world_dir": str(world_dir),
        "player_save": player_save,
        "source_log": str(log_path),
        "artifact_path": str(matched_path) if matched_lines else "",
        "log_size": log_size,
        "changed_since_label": changed_label,
        "changed_since_log_size": baseline,
        "required_items": required_items,
        "observed_items": [entry["pattern"] for entry in matches_by_pattern if entry.get("lines")],
        "missing_required_items": missing,
        "matches_by_pattern": matches_by_pattern,
        "matched_lines": matched_lines,
        "line_count": len(log_lines),
        "capture_policy": "matched decisive player-message lines only; no broad message-log dump",
    }

def execute_long_wait_action(
    pid: int,
    run_dir: Path,
    label: str,
    step: Dict[str, Any],
    *,
    artifact_log: Optional[Path] = None,
    action_trace_log: Optional[Path] = None,
    action_trace_start_offset: int = 0,
    artifact_baseline: int = 0,
    filter_debug_noise: bool = False,
    artifact_patterns: Optional[List[str]] = None,
    portal_storm_allowed: bool = False,
    structured_event_reader: Optional[StructuredTransitionEventReader] = None,
    semantic_profile: str = "",
    semantic_run_id: str = "",
    semantic_trace_start_offset: int = 0,
) -> Dict[str, Any]:
    wait_key = str(step.get("wait_key", "|") or "|")
    choice_key = str(step.get("choice_key", step.get("choice", "3")) or "3")
    expected_duration = str(
        step.get("expected_duration") or LONG_WAIT_MENU_CHOICES.get(choice_key, "unknown")
    )
    delay_ms = int(step.get("delay_ms", 200) or 200)
    pre_menu_choice_key = str(step.get("pre_menu_choice_key", "") or "").strip()
    require_native_wait_menu_guards = bool(
        step.get("require_native_wait_menu_guards", False)
    )
    parent_menu_patterns = normalize_screen_text_patterns(
        step.get("pre_menu_expected_screen_text_contains", ["Wait a while", "Set an alarm"])
    )
    duration_menu_patterns = normalize_screen_text_patterns(
        step.get("duration_menu_expected_screen_text_contains", [])
    )
    menu_settle_seconds = float(step.get("menu_settle_seconds", 0.8) or 0.8)
    pre_menu_settle_seconds = float(step.get("pre_menu_settle_seconds", 0.5) or 0.5)
    after_choice_settle_seconds = float(step.get("after_choice_settle_seconds", 0.5) or 0.5)
    completion_wait_seconds = float(step.get("completion_wait_seconds", 8.0) or 8.0)
    completion_artifact_timeout_seconds = float(
        step.get("completion_artifact_timeout_seconds", 0.0) or 0.0
    )
    completion_artifact_poll_seconds = float(
        step.get("completion_artifact_poll_seconds", 2.0) or 2.0
    )
    completion_artifact_settle_seconds = float(
        step.get("completion_artifact_settle_seconds", 1.0) or 0.0
    )
    minimum_artifact_elapsed_minutes = int(
        step.get("minimum_artifact_elapsed_minutes", 0) or 0
    )
    tail_lines = int(step.get("extract_text_tail_lines", step.get("extract_text_after_capture_tail_lines", 32)) or 32)
    complete_patterns = normalize_screen_text_patterns(
        step.get("wait_complete_text_contains", ["You finish waiting"])
    )
    state_patterns = normalize_string_list(step.get("artifact_state_patterns", artifact_patterns or []))
    interrupt_patterns = normalize_screen_text_patterns(
        step.get("wait_interrupt_text_contains", [
            "Stop moving?",
            "Spotted",
            "hostile spotted",
            "Safe mode is triggered",
            "Ignore",
            "ignore",
            "What do you want to do",
            "Set an alarm",
            "Wait a while",
            "Continue",
            "continue",
            "interrupted",
            "You stop waiting",
            "to interrupt",
        ])
    )
    configured_interrupt_response_key = str(
        step.get("interrupt_response_key", "") or ""
    ).strip()
    max_interrupt_responses = int(step.get("max_interrupt_responses", 6) or 0)
    auto_acknowledge_interruptions = bool(step.get("auto_acknowledge_interruptions", True))
    allow_hostile_auto_move_cancel = bool(
        step.get("allow_hostile_auto_move_cancel", False)
    )
    continue_hostile_auto_move = bool(
        step.get("continue_hostile_auto_move", False)
    )
    declared_hostile_auto_move_continuation = step.get(
        "hostile_auto_move_continuation"
    )
    if declared_hostile_auto_move_continuation is not None:
        if not isinstance(declared_hostile_auto_move_continuation, Mapping):
            raise SystemExit(
                f"Scenario step '{label}' hostile_auto_move_continuation must be an object"
            )
        declared_hostile_auto_move_continuation = {
            key: str(declared_hostile_auto_move_continuation.get(key, "")).strip()
            for key in ("actor", "native_prompt", "observed_prompt", "response_key")
        }
        if not all(declared_hostile_auto_move_continuation.values()) or \
                declared_hostile_auto_move_continuation["response_key"] != "N":
            raise SystemExit(
                f"Scenario step '{label}' hostile_auto_move_continuation must declare "
                "actor, native_prompt, observed_prompt, and native N response_key"
            )
        if not allow_hostile_auto_move_cancel or not continue_hostile_auto_move:
            raise SystemExit(
                f"Scenario step '{label}' hostile_auto_move_continuation requires the "
                "declared hostile auto-move continuation route"
            )
    hostile_response_overrides = (
        {"authorized_hostile_auto_move_cancel": "N"}
        if continue_hostile_auto_move else None
    )
    native_wait_continuation_declaration = step.get("native_wait_continuation")
    if native_wait_continuation_declaration is not None and \
            not isinstance(native_wait_continuation_declaration, Mapping):
        raise SystemExit(
            f"Scenario step '{label}' native_wait_continuation must be an object"
        )
    allow_harmless_flavor_popup_wait_recovery = bool(
        step.get("allow_harmless_flavor_popup_wait_recovery", False)
    )
    require_run_bound_wait_classification = bool(
        step.get( "require_run_bound_wait_classification", bool( semantic_run_id ) )
    )
    report: Dict[str, Any] = {
        "wait_key": wait_key,
        "choice_key": choice_key,
        "pre_menu_choice_key": pre_menu_choice_key,
        "require_native_wait_menu_guards": require_native_wait_menu_guards,
        "pre_menu_expected_screen_text_contains": parent_menu_patterns,
        "duration_menu_expected_screen_text_contains": duration_menu_patterns,
        "expected_duration": expected_duration,
        "delay_ms": delay_ms,
        "menu_settle_seconds": menu_settle_seconds,
        "pre_menu_settle_seconds": pre_menu_settle_seconds,
        "after_choice_settle_seconds": after_choice_settle_seconds,
        "completion_wait_seconds": completion_wait_seconds,
        "completion_artifact_timeout_seconds": completion_artifact_timeout_seconds,
        "completion_artifact_poll_seconds": completion_artifact_poll_seconds,
        "completion_artifact_settle_seconds": completion_artifact_settle_seconds,
        "minimum_artifact_elapsed_minutes": minimum_artifact_elapsed_minutes,
        "proof_rule": (
            "captures before/initial-menu/duration-menu/after screens plus before/after artifact deltas; "
            "does not type through prompts; interruptions remain evidence and must not be classified green by default"
        ),
        "artifact_state_patterns": state_patterns,
        "portal_storm_allowed": portal_storm_allowed,
        "elapsed_time_evidence": {
            "duration_choice_key": choice_key,
            "expected_duration": expected_duration,
            "before_clock_source": f"{label}.before.png / {label}.before.screen_text.json",
            "after_clock_source": f"{label}.after.png / {label}.after.screen_text.json",
            "completion_signal": "wait_complete_text_contains match after choosing the bounded duration",
            "parse_note": "HUD clock/turn evidence is archived in screenshots/OCR; exact OCR parsing may be noisy and is not normalized here.",
        },
    }

    if structured_event_reader is not None:
        structured_event_reader.poll()
        before_events = list(structured_event_reader.events)
        resources_before = sample_child_resources(pid)

    prior_semantic_frame_id = ""
    semantic_parent_menu_confirmed = False
    if require_native_wait_menu_guards and pre_menu_choice_key and semantic_profile and semantic_run_id:
        try:
            prior_semantic_frame_id = str(current_semantic_step_frame(
                profile=semantic_profile, run_dir=run_dir, run_id=semantic_run_id,
                start_offset=semantic_trace_start_offset,
            ).get("frame_id", ""))
        except (OSError, ValueError):
            prior_semantic_frame_id = ""

    wait_start_size = artifact_log.stat().st_size if artifact_log is not None and artifact_log.exists() else artifact_baseline
    report["artifact_before_wait"] = capture_wait_artifact_delta(
        artifact_log,
        run_dir,
        label,
        "before_wait",
        artifact_baseline,
        state_patterns,
        filter_debug_noise=filter_debug_noise,
    )

    before_capture = capture_screenshot(pid, run_dir, f"{label}.before")
    report["screen_before"] = before_capture.get("screen_summary", {})
    before_text = capture_screen_text_artifact(run_dir, f"{label}.before", before_capture, tail_lines=tail_lines)
    report["screen_before_text"] = before_text
    preexisting_complete_patterns = {
        match.get("pattern", "")
        for match in find_screen_text_matches(before_text, complete_patterns)
        if match.get("pattern", "")
    }
    report["preexisting_complete_patterns"] = sorted(preexisting_complete_patterns)
    pre_wait_screen_classification = classify_ordinary_wait_interruption(
        before_text,
        semantic_ui_trace_log=action_trace_log,
        semantic_ui_trace_start_offset=action_trace_start_offset,
    )
    report["pre_wait_screen_classification"] = pre_wait_screen_classification
    if pre_wait_screen_classification.get( "classification" ) == "wait_activity_in_progress":
        report["abort"] = {
            "guard": "pre_wait_activity",
            "status": "blocked_preexisting_wait_activity",
            "verdict": "red_wait_preexisting_activity",
            "reason": "a new bounded wait cannot start while an earlier wait activity is still running",
        }
        report["stop_after_step"] = True
        return report

    trace_run_id = ""
    if action_trace_log is not None:
        try:
            trace_binding = json.loads(
                (run_dir / TRANSITION_EVENT_BINDING_FILENAME).read_text(encoding="utf-8")
            )
        except (OSError, UnicodeDecodeError, json.JSONDecodeError):
            trace_binding = {}
        trace_run_id = str(trace_binding.get("run_id", "")).strip()
    diagnostic_request_id = f"{label}:native_wait"
    if require_native_wait_menu_guards and bool(step.get("require_wait_input_trace", False)):
        receipt = append_wait_diagnostic_record(
            run_dir,
            wait_diagnostic_request_record(
                run_id=trace_run_id,
                request_id=diagnostic_request_id,
                phase="before_input",
                semantic_frame=prior_semantic_frame_id,
                pid=pid,
            ),
        )
        report["wait_diagnostic_before_input"] = receipt
        if receipt.get("status") != "retained":
            report["abort"] = {
                "guard": "native_wait_diagnostic_activation",
                "status": "blocked_native_wait_diagnostic_activation",
                "verdict": "red_wait_diagnostic_activation_unproved",
                "reason": "the immutable run-owned wait diagnostic receipt was not retained before SDL input",
                "receipt": receipt,
            }
            report["stop_after_step"] = True
            return report
    peekaboo_press_sequence(pid, [wait_key], delay_ms=delay_ms)
    if menu_settle_seconds > 0:
        time.sleep(menu_settle_seconds)
    if action_trace_log is not None:
        if trace_run_id:
            report["input_resolution_trace"] = classify_wait_input_trace(
                action_trace_log, action_trace_start_offset, run_id=trace_run_id
            )
    if require_native_wait_menu_guards and bool(step.get("require_wait_input_trace", False)):
        receipt = append_wait_diagnostic_record(
            run_dir,
            wait_diagnostic_request_record(
                run_id=trace_run_id,
                request_id=diagnostic_request_id,
                phase="result",
                semantic_frame=prior_semantic_frame_id,
                pid=pid,
                trace=report.get("input_resolution_trace"),
            ),
        )
        report["wait_diagnostic_result"] = receipt
        if receipt.get("status") != "retained":
            report["abort"] = {
                "guard": "native_wait_diagnostic_retention",
                "status": "blocked_native_wait_diagnostic_retention",
                "verdict": "red_wait_diagnostic_retention_unproved",
                "reason": "the immutable run-owned native wait diagnostic result was not retained",
                "receipt": receipt,
            }
            report["stop_after_step"] = True
            return report
    if require_native_wait_menu_guards and bool(step.get("require_wait_input_trace", False)):
        trace_status = str(report.get("input_resolution_trace", {}).get("status", ""))
        if trace_status != "wait_dispatched":
            report["abort"] = {
                "guard": "native_wait_input_trace",
                "status": "blocked_native_wait_input_trace",
                "verdict": "red_wait_input_trace_stale_or_missing",
                "reason": "the current run did not prove SDL delivery through native wait dispatch before submenu input",
                "observed_status": trace_status or "missing",
            }
            report["stop_after_step"] = True
            return report
    if require_native_wait_menu_guards and pre_menu_choice_key and semantic_profile and semantic_run_id:
        semantic_guard = validate_native_wait_mode_semantic_frame(
            profile=semantic_profile, run_dir=run_dir, run_id=semantic_run_id,
            start_offset=semantic_trace_start_offset, prior_frame_id=prior_semantic_frame_id,
        )
        report["parent_wait_semantic_guard"] = semantic_guard
        if semantic_guard["status"] != "matched":
            report["abort"] = {
                "guard": "native_wait_mode_semantic_frame",
                "status": "blocked_native_wait_mode_semantic_frame",
                "verdict": "red_wait_parent_semantic_frame_unproven",
                "reason": "the current run did not emit a fresh wait_mode_choice frame with both bound menu actions",
                "semantic_guard": semantic_guard,
            }
            report["stop_after_step"] = True
            return report
        semantic_parent_menu_confirmed = True
    initial_menu_capture = capture_screenshot(pid, run_dir, f"{label}.initial_wait_menu")
    report["screen_initial_wait_menu"] = initial_menu_capture.get("screen_summary", {})
    initial_menu_text = capture_screen_text_artifact(
        run_dir, f"{label}.initial_wait_menu", initial_menu_capture, tail_lines=tail_lines
    )
    report["screen_initial_wait_menu_text"] = initial_menu_text

    if pre_menu_choice_key and require_native_wait_menu_guards and not semantic_parent_menu_confirmed:
        parent_guard = validate_native_wait_menu_surface(
            initial_menu_text,
            required_patterns=parent_menu_patterns,
            surface="parent_wait_chooser",
        )
        report["parent_wait_menu_guard"] = parent_guard
        if parent_guard["status"] != "matched":
            report["abort"] = {
                "guard": "native_wait_parent_menu",
                "status": "blocked_native_wait_parent_menu",
                "verdict": "red_wait_parent_chooser_unproven",
                "reason": "the declared native Wait a while parent chooser was not the active unobstructed menu",
                "missing_patterns": parent_guard["missing_patterns"],
            }
            report["stop_after_step"] = True
            return report
    elif semantic_parent_menu_confirmed:
        report["parent_wait_menu_guard"] = {
            "guard": "native_wait_mode_semantic_frame",
            "status": "matched",
            "reason": "fresh_same_run_semantic_frame",
            "ocr_guard_bypassed": True,
        }

    if pre_menu_choice_key:
        peekaboo_press_sequence(pid, [pre_menu_choice_key], delay_ms=delay_ms)
        if pre_menu_settle_seconds > 0:
            time.sleep(pre_menu_settle_seconds)

    menu_capture = capture_screenshot(pid, run_dir, f"{label}.wait_menu")
    report["screen_wait_menu"] = menu_capture.get("screen_summary", {})
    menu_text = capture_screen_text_artifact(run_dir, f"{label}.wait_menu", menu_capture, tail_lines=tail_lines)
    report["screen_wait_menu_text"] = menu_text

    if pre_menu_choice_key and require_native_wait_menu_guards:
        duration_patterns = duration_menu_patterns or wait_menu_expected_duration_patterns(
            expected_duration
        )
        duration_guard = validate_native_wait_menu_surface(
            menu_text,
            required_patterns=duration_patterns,
            surface="duration_wait_chooser",
            require_all=False,
        )
        report["duration_wait_menu_guard"] = duration_guard
        if duration_guard["status"] != "matched":
            report["abort"] = {
                "guard": "native_wait_duration_menu",
                "status": "blocked_native_wait_duration_menu",
                "verdict": "red_wait_duration_chooser_unproven",
                "reason": "the native duration chooser was not active and unobstructed before duration input",
                "missing_patterns": duration_guard["missing_patterns"],
            }
            report["stop_after_step"] = True
            return report

    completion_start_size = (
        artifact_log.stat().st_size
        if artifact_log is not None and artifact_log.exists()
        else wait_start_size
    )
    structured_popup_trace_start_offset = (
        action_trace_log.stat().st_size
        if action_trace_log is not None and action_trace_log.exists()
        else 0
    )
    report["completion_artifact_start_size"] = completion_start_size
    baseline_now_minutes = (
        latest_now_minutes_marker(artifact_log, end_offset=completion_start_size)
        if artifact_log is not None and minimum_artifact_elapsed_minutes > 0
        else None
    )
    report["completion_artifact_baseline_now_minutes"] = baseline_now_minutes
    semantic_wait_trace_start_offset = -1
    semantic_binding_path = run_dir / TRANSITION_EVENT_BINDING_FILENAME
    semantic_binding_id, semantic_binding_error = sha256_file( semantic_binding_path )
    if semantic_run_id and semantic_profile:
        try:
            semantic_wait_trace_start_offset = semantic_step_source_trace(
                semantic_profile
            ).stat().st_size
        except OSError:
            semantic_wait_trace_start_offset = -1
    peekaboo_press_sequence(pid, [choice_key], delay_ms=delay_ms)
    if after_choice_settle_seconds > 0:
        time.sleep(after_choice_settle_seconds)
    native_wait_continuation: Dict[str, Any] = {}
    if structured_event_reader is not None and isinstance(
            native_wait_continuation_declaration, Mapping
    ):
        native_wait_continuation = evaluate_native_wait_return_continuation(
            structured_event_reader.events,
            run_id=semantic_run_id,
            transition=str(native_wait_continuation_declaration.get("transition", "")),
            actor_ids=native_wait_continuation_declaration.get("actor_ids", []),
            postcondition=native_wait_continuation_declaration.get("postcondition", {}),
            final_postcondition=native_wait_continuation_declaration.get(
                "final_postcondition", {}
            ),
        )
        report["native_wait_continuation"] = native_wait_continuation
    continuation_proved = native_wait_continuation.get("status") == "matched"
    if completion_wait_seconds > 0 and not continuation_proved:
        time.sleep(completion_wait_seconds)
    receipt_id = hashlib.sha256(
        f"{semantic_run_id}\0{label}\0{wait_start_size}".encode( "utf-8" )
    ).hexdigest()
    native_terminal_evidence: Dict[str, Any] = {}
    if require_run_bound_wait_classification and semantic_wait_trace_start_offset >= 0 and \
            semantic_binding_id:
        native_terminal_evidence = observe_bound_native_wait_activity_completion(
            profile=semantic_profile, run_dir=run_dir, run_id=semantic_run_id,
            trace_start_offset=semantic_wait_trace_start_offset,
            binding_id=semantic_binding_id,
            expected_action=f"wait.{expected_duration}", receipt_id=receipt_id,
        )
        report["native_wait_activity_completion"] = {
            key: value for key, value in native_terminal_evidence.items() if key != "events"
        }
    elif require_run_bound_wait_classification:
        native_terminal_evidence = {
            "run_id": semantic_run_id,
            "binding_id": semantic_binding_id,
            "receipt_id": receipt_id,
            "source": "native_semantic_wait_activity_complete",
            "kind": "",
            "status": "unproved",
            "failures": ["native_wait_trace_or_binding_unavailable"],
            "binding_error": semantic_binding_error,
        }
        report["native_wait_activity_completion"] = native_terminal_evidence
    native_completion_proved = native_terminal_evidence.get( "status" ) == "matched"
    completion_poll_timed_out = False
    completion_poll_aborted = False
    if not continuation_proved and not native_completion_proved and \
            completion_artifact_timeout_seconds > 0 and \
            (state_patterns or minimum_artifact_elapsed_minutes > 0) and \
            artifact_log is not None:
        poll_acknowledgement_count = 0
        poll_scan_count = 0
        poll_shadow_warning_acknowledged = False

        def handle_poll_interruption() -> Dict[str, Any]:
            nonlocal poll_acknowledgement_count, poll_scan_count
            nonlocal poll_shadow_warning_acknowledged
            poll_scan_count += 1
            remaining_acknowledgements = max(
                0, max_interrupt_responses - poll_acknowledgement_count
            )
            interruption = recover_harmless_wilderness_flavor_wait(
                pid, run_dir, f"{label}.completion_poll_interrupt_{poll_scan_count:02d}",
                delay_ms=delay_ms, action_trace_log=action_trace_log,
                action_trace_start_offset=structured_popup_trace_start_offset,
            ) if allow_harmless_flavor_popup_wait_recovery else acknowledge_blocking_interruptions(
                pid,
                run_dir,
                f"{label}.completion_poll_interrupt_{poll_scan_count:02d}",
                max_acknowledgements=remaining_acknowledgements,
                delay_ms=delay_ms,
                stop_on_unknown=True,
                continue_after_contaminating=portal_storm_allowed,
                suppress_retained_shadow_warning=poll_shadow_warning_acknowledged,
                structured_popup_trace_log=action_trace_log,
                structured_popup_trace_start_offset=structured_popup_trace_start_offset,
                semantic_ui_trace_log=action_trace_log,
                semantic_ui_trace_start_offset=action_trace_start_offset,
                semantic_ui_expectation={"intent": "eoc_popup", "action": "space"},
                ordinary_wait_save_and_quit_guard=True,
                allow_hostile_auto_move_cancel=allow_hostile_auto_move_cancel,
                declared_hostile_auto_move_continuation=
                declared_hostile_auto_move_continuation,
                response_key_overrides=hostile_response_overrides,
            )
            poll_acknowledgement_count += int(
                interruption.get("acknowledgement_count", 0) or 0
            )
            poll_shadow_warning_acknowledged = poll_shadow_warning_acknowledged or any(
                str(acknowledgement.get("classification", {}).get("classification", ""))
                == "shadow_warning_wilderness_flavor_popup"
                for acknowledgement in interruption.get("acknowledgements", [])
                if isinstance(acknowledgement, dict)
            )
            return interruption

        def detect_poll_interruption() -> Dict[str, Any]:
            """Classify a prompt without sending input when auto-ack is disabled."""
            return acknowledge_blocking_interruptions(
                pid,
                run_dir,
                f"{label}.completion_poll_interrupt_detect",
                max_acknowledgements=0,
                delay_ms=delay_ms,
                stop_on_unknown=True,
                continue_after_contaminating=portal_storm_allowed,
                structured_popup_trace_log=action_trace_log,
                structured_popup_trace_start_offset=structured_popup_trace_start_offset,
                semantic_ui_trace_log=action_trace_log,
                semantic_ui_trace_start_offset=action_trace_start_offset,
                semantic_ui_expectation={"intent": "eoc_popup", "action": "space"},
                ordinary_wait_save_and_quit_guard=True,
                allow_hostile_auto_move_cancel=allow_hostile_auto_move_cancel,
                declared_hostile_auto_move_continuation=
                declared_hostile_auto_move_continuation,
                response_key_overrides=hostile_response_overrides,
            )

        report["completion_artifact_poll"] = poll_wait_artifact_completion(
            artifact_log,
            run_dir,
            label,
            completion_start_size,
            state_patterns,
            timeout_seconds=completion_artifact_timeout_seconds,
            poll_seconds=completion_artifact_poll_seconds,
            filter_debug_noise=filter_debug_noise,
            baseline_now_minutes=baseline_now_minutes,
            minimum_elapsed_minutes=minimum_artifact_elapsed_minutes,
            interruption_handler=(
                handle_poll_interruption
                if ( auto_acknowledge_interruptions or allow_harmless_flavor_popup_wait_recovery ) and
                max_interrupt_responses > 0
                else (detect_poll_interruption if max_interrupt_responses > 0 else None)
            ),
            continue_after_contaminating=portal_storm_allowed,
        )
        completion_poll_timed_out = report["completion_artifact_poll"]["status"] == "timed_out"
        completion_poll_aborted = report["completion_artifact_poll"]["status"] == "aborted_interruption"
        if report["completion_artifact_poll"]["status"] == "matched" and \
                completion_artifact_settle_seconds > 0:
            time.sleep( completion_artifact_settle_seconds )
    elif continuation_proved:
        report["completion_artifact_poll"] = {
            "status": "matched_native_receipt_continuation",
            "aborted": False,
            "abort_reason": "",
            "attempts": 0,
            "elapsed_seconds": 0.0,
            "timeout_seconds": 0.0,
            "poll_seconds": 0.0,
            "start_size": completion_start_size,
            "match": {
                "matched": True,
                "patterns": state_patterns,
                "matched_patterns": [],
                "missing_patterns": list(state_patterns),
                "source": "same_run_native_return_receipts",
            },
            "interruption_handling": {
                "status": "clear",
                "acknowledgement_count": 0,
                "response_keys": [],
                "release_blocking": False,
                "contaminating": False,
                "reports": [],
            },
        }
    elif native_completion_proved:
        report["completion_artifact_poll"] = {
            "status": "not_required_bound_native_wait_completion",
            "aborted": False,
            "abort_reason": "",
            "attempts": 0,
            "elapsed_seconds": 0.0,
            "timeout_seconds": 0.0,
            "poll_seconds": 0.0,
            "start_size": completion_start_size,
            "match": {
                "matched": False,
                "patterns": state_patterns,
                "matched_patterns": [],
                "missing_patterns": list( state_patterns ),
                "source": "not_required_bound_native_wait_completion",
            },
            "interruption_handling": {
                "status": "clear",
                "acknowledgement_count": 0,
                "response_keys": [],
                "release_blocking": False,
                "contaminating": False,
                "reports": [],
            },
        }
    after_capture = capture_screenshot(pid, run_dir, f"{label}.after")
    report["screen_after"] = after_capture.get("screen_summary", {})
    after_text = capture_screen_text_artifact(run_dir, f"{label}.after", after_capture, tail_lines=tail_lines)
    report["screen_after_text"] = after_text
    report["artifact_after_wait"] = capture_wait_artifact_delta(
        artifact_log,
        run_dir,
        label,
        "after_wait",
        completion_start_size,
        state_patterns,
        filter_debug_noise=filter_debug_noise,
    )
    classification_text = after_text
    report["wait_classification"] = classify_wait_screen_text(
        classification_text, complete_patterns, interrupt_patterns, preexisting_complete_patterns
    )
    if continuation_proved and report["wait_classification"].get("status") != \
            "interrupted_or_prompt_visible":
        report["wait_classification"] = {
            **report["wait_classification"],
            "status": "completed",
            "screen_status": report["wait_classification"].get("status", ""),
            "completion_signal": "same_run_native_return_receipts_and_postcondition",
        }
    if require_run_bound_wait_classification:
        before_clock_matches = extract_clock_or_turn_evidence( before_text ).get( "clock_matches", [] )
        after_clock_matches = extract_clock_or_turn_evidence( classification_text ).get( "clock_matches", [] )
        expected_seconds = wait_duration_seconds( expected_duration )
        wait_receipt = {
            "run_id": semantic_run_id,
            "receipt_id": receipt_id,
            "binding_id": semantic_binding_id,
            "start_seconds_since_midnight": (
                before_clock_matches[0].get( "seconds_since_midnight" )
                if before_clock_matches else None
            ),
            "end_seconds_since_midnight": (
                after_clock_matches[0].get( "seconds_since_midnight" )
                if after_clock_matches else None
            ),
            "expected_seconds": expected_seconds,
        }
        screen_status = str( report["wait_classification"].get( "status", "" ) )
        report["wait_receipt"] = wait_receipt
        report["run_bound_wait_classification"] = classify_run_bound_native_wait(
            wait_receipt, native_terminal_evidence, current_run_id=semantic_run_id,
            current_binding_id=semantic_binding_id,
        )
        report["wait_classification"] = {
            **report["wait_classification"],
            "screen_status": screen_status,
            "status": report["run_bound_wait_classification"]["status"],
        }

    if configured_interrupt_response_key:
        report["configured_interrupt_response_key_ignored"] = configured_interrupt_response_key
        report["interrupt_response_policy"] = (
            "response keys are selected only by the strict live-screen classifier"
        )

    if not completion_poll_aborted and auto_acknowledge_interruptions:
        responses: List[Dict[str, Any]] = []
        interruption_reports: List[Dict[str, Any]] = []
        response_count = 0
        mid_poll_acknowledgement_count = int(
            report.get("completion_artifact_poll", {}).get(
                "interruption_handling", {}
            ).get("acknowledgement_count", 0) or 0
        )
        first_boundary_scan = True
        while first_boundary_scan or \
                response_count + mid_poll_acknowledgement_count < max_interrupt_responses:
            completed_wait_shadow_message = first_boundary_scan and str(
                report.get("wait_classification", {}).get("status", "")
            ) == "completed"
            first_boundary_scan = False
            mid_poll_shadow_warning_acknowledged = any(
                str(acknowledgement.get("classification", {}).get("classification", ""))
                == "shadow_warning_wilderness_flavor_popup"
                for handler in report.get("completion_artifact_poll", {}).get(
                    "interruption_handling", {}
                ).get("reports", [])
                for acknowledgement in handler.get("acknowledgements", [])
                if isinstance(handler, dict) and isinstance(acknowledgement, dict)
            )
            interruption = recover_harmless_wilderness_flavor_wait(
                pid,
                run_dir,
                f"{label}.interrupt_handler_{len(interruption_reports) + 1:02d}",
                delay_ms=delay_ms,
                action_trace_log=action_trace_log,
                action_trace_start_offset=structured_popup_trace_start_offset,
            ) if allow_harmless_flavor_popup_wait_recovery else acknowledge_blocking_interruptions(
                pid,
                run_dir,
                f"{label}.interrupt_handler_{len(interruption_reports) + 1:02d}",
                max_acknowledgements=(
                    max_interrupt_responses
                    - mid_poll_acknowledgement_count
                    - response_count
                ),
                delay_ms=delay_ms,
                stop_on_unknown=True,
                continue_after_contaminating=portal_storm_allowed,
                suppress_retained_shadow_warning=(
                    mid_poll_shadow_warning_acknowledged
                    or completed_wait_shadow_message
                ),
                structured_popup_trace_log=action_trace_log,
                structured_popup_trace_start_offset=structured_popup_trace_start_offset,
                semantic_ui_trace_log=action_trace_log,
                semantic_ui_trace_start_offset=action_trace_start_offset,
                semantic_ui_expectation={"intent": "eoc_popup", "action": "space"},
                ordinary_wait_save_and_quit_guard=True,
                allow_hostile_auto_move_cancel=allow_hostile_auto_move_cancel,
                declared_hostile_auto_move_continuation=
                declared_hostile_auto_move_continuation,
                response_key_overrides=hostile_response_overrides,
            )
            interruption_reports.append(interruption)
            acknowledged = int(interruption.get("acknowledgement_count", 0) or 0)
            response_count += acknowledged
            release_blocking = any(
                bool(handler.get("release_blocking", False))
                for handler in interruption_reports
            )
            contaminating = any(
                bool(handler.get("contaminating", False))
                for handler in interruption_reports
            )
            interruption_status = str(interruption.get("status", "unobservable"))

            if release_blocking:
                report["abort"] = {
                    "guard": "blocking_interruption",
                    "status": "blocked_release_blocking_interruption",
                    "verdict": "red_wait_release_blocking_interruption",
                    "reason": "a captured debug-error interruption invalidated the playtest row",
                }
                report["stop_after_step"] = True
                break
            if contaminating and not portal_storm_allowed:
                report["status"] = "stopped_by_contaminating_interruption"
                report["verdict"] = "yellow_wait_portal_storm_contamination"
                report["stop_after_step"] = True
                break
            if interruption_status.startswith("blocked_"):
                report["abort"] = {
                    "guard": "blocking_interruption",
                    "status": interruption_status,
                    "verdict": "red_wait_unknown_or_unsafe_interruption",
                    "reason": "the wait reached an unsafe or unrecognized blocking menu",
                }
                report["stop_after_step"] = True
                break
            if acknowledged <= 0:
                break

            response_label = f"{label}.interrupt_response_{response_count}"
            response_wait_seconds = float(
                step.get("interrupt_response_wait_seconds", completion_wait_seconds) or 0.0
            )
            if response_wait_seconds > 0:
                time.sleep(response_wait_seconds)
            response_capture = capture_screenshot(pid, run_dir, response_label)
            response_text = capture_screen_text_artifact(
                run_dir, response_label, response_capture, tail_lines=tail_lines
            )
            response_artifact_after = capture_wait_artifact_delta(
                artifact_log,
                run_dir,
                label,
                f"after_interrupt_response_{response_count}",
                completion_start_size,
                state_patterns,
                filter_debug_noise=filter_debug_noise,
            )
            response_classification = classify_wait_screen_text(
                response_text, complete_patterns, interrupt_patterns, preexisting_complete_patterns
            )
            responses.append({
                "response_index": response_count,
                "response_label": response_label,
                "response_wait_seconds": response_wait_seconds,
                "interruption_handling": interruption,
                "screen_after_response": response_capture.get("screen_summary", {}),
                "screen_after_response_text": response_text,
                "artifact_after_response": response_artifact_after,
                "wait_classification_after_response": response_classification,
            })
            classification_text = response_text
            report["artifact_after_wait"] = response_artifact_after
            report["wait_classification"] = response_classification
            if response_classification.get("status") != "interrupted_or_prompt_visible":
                break

        report["interrupt_responses"] = responses
        mid_poll_handling = report.get("completion_artifact_poll", {}).get(
            "interruption_handling", {}
        )
        mid_poll_reports = mid_poll_handling.get("reports", [])
        if not isinstance(mid_poll_reports, list):
            mid_poll_reports = []
        mid_poll_response_keys = mid_poll_handling.get("response_keys", [])
        if not isinstance(mid_poll_response_keys, list):
            mid_poll_response_keys = []
        total_acknowledgement_count = (
            int(mid_poll_handling.get("acknowledgement_count", 0) or 0)
            + response_count
        )
        final_interruption_status = (
            str(interruption_reports[-1].get("status", "clear"))
            if interruption_reports
            else str(mid_poll_handling.get("status", "clear"))
        )
        if total_acknowledgement_count and final_interruption_status == "clear":
            final_interruption_status = "recovered_known_interruptions"
        report["interruption_handling"] = {
            "status": final_interruption_status,
            "acknowledgement_count": total_acknowledgement_count,
            "response_keys": mid_poll_response_keys + [
                str(acknowledgement.get("response_key", ""))
                for handler in interruption_reports
                for acknowledgement in handler.get("acknowledgements", [])
                if isinstance(acknowledgement, dict)
                and str(acknowledgement.get("response_key", ""))
            ],
            "release_blocking": bool(mid_poll_handling.get("release_blocking", False)) or any(
                bool(handler.get("release_blocking", False))
                for handler in interruption_reports
            ),
            "contaminating": bool(mid_poll_handling.get("contaminating", False)) or any(
                bool(handler.get("contaminating", False))
                for handler in interruption_reports
            ),
            "reports": mid_poll_reports + interruption_reports,
        }

    if "interruption_handling" not in report and "completion_artifact_poll" in report:
        report["interruption_handling"] = report["completion_artifact_poll"].get(
            "interruption_handling", {}
        )

    if require_run_bound_wait_classification:
        final_clock_matches = extract_clock_or_turn_evidence( classification_text ).get(
            "clock_matches", []
        )
        wait_receipt = dict( report["wait_receipt"] )
        wait_receipt["end_seconds_since_midnight"] = (
            final_clock_matches[0].get( "seconds_since_midnight" )
            if final_clock_matches else None
        )
        screen_status = str( report["wait_classification"].get( "status", "" ) )
        if screen_status == "interrupted_or_prompt_visible" or int(
                report.get( "interruption_handling", {} ).get( "acknowledgement_count", 0 ) or 0
        ) > 0:
            native_terminal_evidence = {
                **native_terminal_evidence,
                "kind": "native_wait_interrupted",
                "screen_or_handler_interruption": True,
            }
        report["wait_receipt"] = wait_receipt
        report["run_bound_wait_classification"] = classify_run_bound_native_wait(
            wait_receipt, native_terminal_evidence, current_run_id=semantic_run_id,
            current_binding_id=semantic_binding_id,
        )
        report["wait_classification"] = {
            **report["wait_classification"],
            "screen_status": screen_status,
            "status": report["run_bound_wait_classification"]["status"],
        }

    report["wait_step_ledger"] = classify_wait_step_ledger(
        label=label,
        choice_key=choice_key,
        expected_duration=expected_duration,
        before_text=before_text,
        menu_text=menu_text,
        after_text=classification_text,
        wait_classification=report["wait_classification"],
        artifact_after_wait=report["artifact_after_wait"],
        allow_artifact_elapsed_without_menu_ocr=bool(
            step.get("allow_artifact_elapsed_without_menu_ocr", False)
        ),
        allow_exact_artifact_meridiem_ambiguity=bool(
            step.get("allow_exact_artifact_meridiem_ambiguity", False)
        ),
        native_wait_continuation=native_wait_continuation,
    )
    if report.get("status") == "stopped_by_contaminating_interruption":
        base_wait_verdict = str(report["wait_step_ledger"].get("verdict", ""))
        report["wait_step_ledger"]["base_verdict_before_portal_stop"] = base_wait_verdict
        report["wait_step_ledger"]["verdict"] = "yellow_wait_step_portal_storm_contamination"
        wait_issues = [
            str(issue) for issue in report["wait_step_ledger"].get("issues", [])
        ]
        if "unallowed_portal_storm_interruption" not in wait_issues:
            wait_issues.append("unallowed_portal_storm_interruption")
        report["wait_step_ledger"]["issues"] = wait_issues
    if not report.get("stop_after_step") and bool(step.get("abort_on_interrupt", False)) and \
            report["wait_classification"].get("status") == "interrupted_or_prompt_visible":
        report["status"] = "aborted_by_wait_interruption"
        report["verdict"] = str(step.get("abort_verdict", "inconclusive_wait_interrupted"))
        report["abort_reason"] = str(
            step.get("abort_reason", "wait action was interrupted or showed a prompt")
        )
    if completion_poll_aborted:
        report["abort"] = {
            "guard": "completion_artifact_interruption",
            "status": "blocked_wait_completion_interruption",
            "verdict": "red_wait_mid_poll_interruption",
            "reason": report["completion_artifact_poll"].get(
                "abort_reason", "unsafe or unrecognized interruption during wait completion poll"
            ),
        }
        report["stop_after_step"] = True
    elif completion_poll_timed_out:
        report["abort"] = {
            "guard": "completion_artifact_timeout",
            "status": "blocked_wait_completion_timeout",
            "verdict": "red_wait_completion_artifact_timeout",
            "reason": "the bounded wait did not reach its authoritative post-choice elapsed endpoint before timeout",
            "missing_patterns": report["completion_artifact_poll"]["match"].get(
                "missing_patterns", []
            ),
        }
        report["stop_after_step"] = True
    if structured_event_reader is not None:
        transition_poll = structured_event_reader.poll()
        if transition_poll.get("discard_prior_events"):
            before_events = []
        after_events = list(structured_event_reader.events)
        report["_integrated_wait_new_events"] = list(transition_poll.get("events", []))
        report["integrated_wait_observation"] = observe_integrated_wait(
            label=label,
            before_events=before_events,
            after_events=after_events,
            resources_before=resources_before,
            resources_after=complete_child_resource_interval(
                resources_before, sample_child_resources(pid),
            ),
            wait_completion=report.get("wait_step_ledger", {}),
        )
    return report


def looks_like_inventory_slot(selector: str) -> bool:
    selector = selector.strip()
    return len(selector) == 1 and selector.isprintable() and not selector.isspace()


def drop_item(
    pid: int,
    *,
    query_or_slot: str,
    count: int = 1,
    delay_ms: int = 200,
    type_delay_ms: int = 20,
    menu_settle_seconds: float = 0.35,
    prompt_settle_seconds: float = 0.25,
    exit_menu: bool = True,
    count_selection_mode: str = "type_before_select",
) -> str:
    selector = query_or_slot.strip()
    if not selector:
        raise SystemExit("Drop-item selector cannot be empty")
    if count <= 0:
        raise SystemExit("Drop-item count must be > 0")

    peekaboo_press_sequence(pid, ["d"], delay_ms=delay_ms)
    time.sleep(menu_settle_seconds)

    selection_mode = "slot" if looks_like_inventory_slot(selector) else "filter"
    selection_key = selector if selection_mode == "slot" else "l"
    if selection_mode == "filter":
        apply_uilist_filter(
            pid,
            selector,
            delay_ms=delay_ms,
            type_delay_ms=type_delay_ms,
            settle_seconds=prompt_settle_seconds,
        )

    count_selection_mode = count_selection_mode.strip() or "type_before_select"
    if count_selection_mode not in {"type_before_select", "mark_with_count"}:
        raise SystemExit(f"Unsupported drop-item count_selection_mode: {count_selection_mode}")

    if count > 1 and count_selection_mode == "mark_with_count":
        # MARK_WITH_COUNT applies to the selector's selected entries, not merely the
        # highlighted filtered row.  Prime the filtered/slot row first, then replace
        # that selection with the exact requested count.
        peekaboo_press_sequence(pid, [selection_key], delay_ms=delay_ms)
        time.sleep(prompt_settle_seconds)
        peekaboo_press_sequence(pid, ["!"], delay_ms=delay_ms)
        time.sleep(prompt_settle_seconds)
        fill_numeric_prompt(
            pid,
            count,
            delay_ms=delay_ms,
            type_delay_ms=type_delay_ms,
            settle_seconds=prompt_settle_seconds,
        )
    else:
        if count > 1:
            peekaboo_type_text(pid, str(count), delay_ms=type_delay_ms)
            time.sleep(prompt_settle_seconds)

        peekaboo_press_sequence(pid, [selection_key], delay_ms=delay_ms)
        time.sleep(prompt_settle_seconds)

    if exit_menu:
        peekaboo_press_sequence(pid, ["enter"], delay_ms=delay_ms)
        time.sleep(prompt_settle_seconds)

    return selection_mode


def run_debug_menu_shortcut_path(
    pid: int,
    shortcut_keys: List[str],
    *,
    delay_ms: int = 200,
    menu_settle_seconds: float = 0.35,
) -> None:
    if not shortcut_keys:
        raise SystemExit("Debug menu shortcut path needs at least one key")
    peekaboo_press_sequence(pid, ["}"], delay_ms=delay_ms)
    time.sleep(menu_settle_seconds)
    for key in shortcut_keys:
        peekaboo_press_sequence(pid, [key], delay_ms=delay_ms)
        time.sleep(menu_settle_seconds)


def apply_uilist_filter(
    pid: int,
    query: str,
    *,
    delay_ms: int = 200,
    type_delay_ms: int = 20,
    settle_seconds: float = 0.25,
) -> None:
    query = query.strip()
    if not query:
        raise SystemExit("UI list filter query cannot be empty")
    peekaboo_press_sequence(pid, ["/"], delay_ms=delay_ms)
    time.sleep(settle_seconds)
    peekaboo_type_text(pid, query, delay_ms=type_delay_ms)
    peekaboo_press_sequence(pid, ["enter"], delay_ms=delay_ms)
    time.sleep(settle_seconds)


def fill_numeric_prompt(
    pid: int,
    value: int,
    *,
    delay_ms: int = 200,
    type_delay_ms: int = 20,
    clear_presses: int = 8,
    settle_seconds: float = 0.15,
) -> None:
    if value < 0:
        raise SystemExit("Numeric prompt value cannot be negative")
    peekaboo_press_sequence(pid, ["backspace"] * max(1, clear_presses), delay_ms=max(50, min(delay_ms, 150)))
    time.sleep(settle_seconds)
    peekaboo_type_text(pid, str(value), delay_ms=type_delay_ms)
    peekaboo_press_sequence(pid, ["enter"], delay_ms=delay_ms)
    time.sleep(settle_seconds)


def _r021_native_transaction_records(
    artifact_log: Path, start_offset: int,
) -> tuple[List[Dict[str, Any]], List[Dict[str, Any]]]:
    """Read only this dispatch's native R-021 receipt and creature snapshots."""
    text = read_log_delta(artifact_log, start_offset, filter_debug_noise=False)
    receipts: List[Dict[str, Any]] = []
    snapshots: List[Dict[str, Any]] = []
    for line in text.splitlines():
        if "openclaw_harness_debug_transaction: operation=monster_set_hp" not in line:
            continue
        values = dict(re.findall(r"([a-z_]+)=([^\s]+)", line))
        if values.get("snapshot"):
            position = [int(value) for value in re.findall(
                r"-?\d+", values.get("creature_position", "")
            )]
            snapshots.append({
                "typeid": values.get("creature_type", ""),
                "location_ms": position,
                "hp": int(values.get("creature_hp", "-1")),
                "values": {"caol_fixture_actor_id": values.get("creature_fixture_actor_id", "")},
                "handle": values.get("creature_handle", ""),
                "dead": values.get("creature_dead", "false") == "true",
                "phase": values["snapshot"],
            })
            continue
        receipt: Dict[str, Any] = {
            "accepted": values.get("accepted", "true") == "true",
            "target_fixture_actor_id": values.get("target_fixture_actor_id", ""),
            "target_handle": values.get("target_handle", ""),
            "target_type": values.get("target_type", ""),
            "target_position": [int(value) for value in re.findall(
                r"-?\d+", values.get("target_position", "")
            )],
            "native_setter": values.get("native_setter", ""),
            "cause": values.get("cause", ""),
            "gameplay_credit": values.get("gameplay_credit", ""),
        }
        for key in ("hp_before", "hp_after"):
            if key in values:
                receipt[key] = int(values[key])
        receipts.append(receipt)
    return receipts, snapshots


def execute_r021_direct_hp_setter(
    pid: int, *, declaration: Mapping[str, Any], artifact_log: Path,
    artifact_start: int, run_dir: Path, delay_ms: int = 200,
    type_delay_ms: int = 20, menu_settle_seconds: float = 0.35,
    prompt_settle_seconds: float = 0.25,
) -> Dict[str, Any]:
    """Execute and bind the sole native R-021 menu transaction, fail closed."""
    from r021_direct_hp_transaction import DirectHpTransactionError, bind_direct_hp_transaction

    expected_type = str(declaration.get("expected_typeid", "")).strip()
    selection_query = str(declaration.get("selection_query", expected_type)).strip()
    if not expected_type or not selection_query:
        raise DirectHpTransactionError("R-021 direct HP setter needs expected_typeid")
    # The debug menu's first ``c`` selects the Monster category.  Its second
    # ``c`` selects Edit monster, which is the list containing real creatures.
    # Filtering the category screen leaves the dispatcher there and makes the
    # following Enter a no-op.
    run_debug_menu_shortcut_path(
        pid, ["c", "c"], delay_ms=delay_ms, menu_settle_seconds=menu_settle_seconds,
    )
    apply_uilist_filter(
        pid, selection_query, delay_ms=delay_ms, type_delay_ms=type_delay_ms,
        settle_seconds=prompt_settle_seconds,
    )
    # Selecting the filtered creature opens a second native menu asynchronously.
    # Do not allow its edit shortcut to race that transition: bind the next
    # command to an observed monster-menu surface first.
    peekaboo_press_sequence(pid, ["enter"], delay_ms=delay_ms)
    time.sleep(prompt_settle_seconds)
    submenu_capture = capture_screenshot(
        pid, run_dir, "r021.monster_submenu_settled",
        crop=declaration.get("monster_submenu_crop"),
    )
    submenu_text = capture_screen_text_artifact(
        run_dir, "r021.monster_submenu_settled", submenu_capture, tail_lines=32,
    )
    submenu_observation = evaluate_screen_text_or_rendered_hud_expectation(
        submenu_text, ["Set hit points"], None,
        action_trace_log=None,
        run_id="",
        screen_summary=submenu_capture.get("screen_summary", {}),
        startup_overlay_recovery=None,
    )
    if submenu_observation.get("status") not in {"green", "matched"}:
        raise DirectHpTransactionError(
            "R-021 selected creature did not settle at the monster submenu before HP edit"
        )
    if declaration.get("observe_only") is True:
        peekaboo_press_sequence(pid, ["esc", "esc"], delay_ms=delay_ms)
        time.sleep(prompt_settle_seconds)
        artifact = {
            "artifact_kind": "r021_monster_selector_observation",
            "operation": "r021_monster_selector_observation",
            "fixture_actor_id": str(declaration.get("fixture_actor_id", "")),
            "selection_query": selection_query,
            "monster_submenu_settle": {
                "capture": submenu_capture.get("screen_summary", {}),
                "screen_text": submenu_text,
                "observation": submenu_observation,
            },
            "cleanup_receipt": {"accepted": True, "status": "debug_menu_closed"},
            "evidence_effect": "none_for_debug_fixture_transaction",
            "gameplay_credit": False,
        }
        artifact_path = run_dir / "r021.monster_selector_observation.receipt.json"
        artifact["artifact_path"] = str(artifact_path)
        write_json(artifact_path, artifact)
        return artifact
    peekaboo_press_sequence(pid, ["h"], delay_ms=delay_ms)
    time.sleep(prompt_settle_seconds)
    fill_numeric_prompt(
        pid, int(declaration.get("target_hp", -1)), delay_ms=delay_ms,
        type_delay_ms=type_delay_ms, settle_seconds=prompt_settle_seconds,
    )
    # The HP editor returns to the monster menu; close both owned debug menus
    # before final report cleanup may terminate the game process.
    peekaboo_press_sequence(pid, ["esc", "esc"], delay_ms=delay_ms)
    time.sleep(prompt_settle_seconds)
    receipts, snapshots = _r021_native_transaction_records(artifact_log, artifact_start)
    before = [item for item in snapshots if item.get("phase") == "before"]
    after = [item for item in snapshots if item.get("phase") == "after"]
    # A native set_hp( 0 ) retires a dead monster from all_monsters() before
    # the post-set snapshot loop.  The same dispatch's native receipt is its
    # authoritative after-state in that case; retain it as an explicit dead
    # snapshot rather than misclassifying the direct setter as incidental death.
    if not after and len(receipts) == 1 and receipts[0].get("hp_after") == 0:
        receipt = receipts[0]
        after = [{
            "typeid": receipt.get("target_type", ""),
            "location_ms": receipt.get("target_position", []),
            "hp": receipt["hp_after"],
            "values": {"caol_fixture_actor_id": receipt.get("target_fixture_actor_id", "")},
            "handle": receipt.get("target_handle", ""),
            "dead": True,
            "phase": "after_native_receipt",
        }]
    cleanup = {
        "accepted": True,
        "owner": str(declaration.get("cleanup_owner", "")),
        "status": "debug_menu_closed",
    }
    artifact = bind_direct_hp_transaction(
        declaration, receipts, before, after, cleanup=cleanup,
    )
    artifact["monster_submenu_settle"] = {
        "capture": submenu_capture.get("screen_summary", {}),
        "screen_text": submenu_text,
        "observation": submenu_observation,
    }
    artifact_path = run_dir / "r021.direct_hp_setter.receipt.json"
    artifact["artifact_path"] = str(artifact_path)
    write_json(artifact_path, artifact)
    return artifact


def r021_direct_hp_setter_declaration_for_startup(args: argparse.Namespace) -> Optional[Mapping[str, Any]]:
    """Resolve the declared R-021 fixture binding before the child starts."""
    contract_path = str(getattr(args, "scenario_contract_path", "") or "").strip()
    if not contract_path:
        return None
    try:
        contract = json.loads(Path(contract_path).read_text(encoding="utf-8"))
    except (OSError, UnicodeError, json.JSONDecodeError) as exc:
        raise SystemExit(f"R-021 scenario contract cannot be read: {exc}") from exc
    if not isinstance(contract, Mapping):
        raise SystemExit("R-021 scenario contract must be an object")
    declaration = contract.get("r021_direct_hp_setter")
    return declaration if isinstance(declaration, Mapping) else None


def r022_item_spawn_declaration_for_startup(args: argparse.Namespace) -> Optional[Mapping[str, Any]]:
    """Resolve the separately-declared R-022 live bridge before the child starts."""
    contract_path = str(getattr(args, "scenario_contract_path", "") or "").strip()
    if not contract_path:
        return None
    try:
        contract = json.loads(Path(contract_path).read_text(encoding="utf-8"))
    except (OSError, UnicodeError, json.JSONDecodeError) as exc:
        raise SystemExit(f"R-022 scenario contract cannot be read: {exc}") from exc
    declaration = contract.get("r022_item_spawn") if isinstance(contract, Mapping) else None
    return declaration if isinstance(declaration, Mapping) else None


def _r022_item_spawn_records(artifact_log: Path, start_offset: int, run_id: str) -> tuple[Dict[str, Any], Dict[str, Any]]:
    """Read one exact native bridge transaction and its tag-scoped cleanup."""
    transaction: Dict[str, Any] = {}
    cleanup: Dict[str, Any] = {}
    identities: List[Dict[str, Any]] = []
    for line in read_log_delta(artifact_log, start_offset, filter_debug_noise=False).splitlines():
        if "openclaw_harness_r022_item_spawn:" not in line:
            continue
        values = dict(re.findall(r"([a-z_]+)=([^\s]+)", line))
        if values.get("run_id") != run_id:
            continue
        event = values.get("event", "")
        if event == "transaction":
            transaction = {"accepted": values.get("accepted") in {"true", "1"},
                           "audit_passed": values.get("audit_passed") in {"true", "1"},
                           "zero_credit": values.get("zero_credit") in {"true", "1"},
                           "transaction_id": values.get("transaction_id", ""),
                           "type": values.get("type", ""),
                           "quantity": int(values.get("quantity", "-1")),
                           "charges": int(values.get("charges", "-1")),
                           "damage": int(values.get("damage", "-1")),
                           "owner": values.get("owner", ""),
                           "destination_offset_ms": [int(value) for value in values.get(
                               "destination_offset_ms", "").split(",")] if values.get(
                                   "destination_offset_ms", "") else [],
                           "provenance": "debug_item_spawn_transaction: zero-credit setup mutation"}
        elif event == "identity":
            identities.append({"ordinal": int(values.get("ordinal", "-1")), "type": values.get("type", ""),
                               "charges": int(values.get("charges", "-1")), "damage": int(values.get("damage", "-1")),
                               "owner": values.get("owner", "")})
        elif event == "cleanup":
            cleanup = {"accepted": values.get("accepted") in {"true", "1"},
                       "audit_passed": values.get("audit_passed") in {"true", "1"},
                       "zero_credit": values.get("zero_credit") in {"true", "1"},
                       "transaction_id": values.get("transaction_id", ""), "removed": int(values.get("removed", "-1")),
                       "retained_untagged": int(values.get("retained_untagged", "-1"))}
    transaction["identities"] = identities
    return transaction, cleanup


def execute_r022_item_spawn_bridge(*, declaration: Mapping[str, Any], artifact_log: Path,
                                   artifact_start: int, run_dir: Path,
                                   runtime_binding: Mapping[str, Any], run_id: str) -> Dict[str, Any]:
    """Bind the launched executable's native item transaction, never a bootstrap declaration."""
    from r022_item_spawn_adapter import bind_item_spawn_receipts
    transaction, cleanup = _r022_item_spawn_records(artifact_log, artifact_start, run_id)
    artifact = bind_item_spawn_receipts(declaration, transaction, cleanup, {
        "source": str(runtime_binding.get("runtime_source_sha256", "")),
        "executable": str(runtime_binding.get("executable_sha256", "")),
    })
    artifact["bridge_owner"] = "openclaw_harness_r022_item_spawn_bridge"
    artifact["run_id"] = run_id
    artifact_path = run_dir / "r022.item_spawn_live_validation.receipt.json"
    artifact["artifact_path"] = str(artifact_path)
    write_json(artifact_path, artifact)
    return artifact



def iter_map_triples(value: Any) -> Iterable[Tuple[int, int, Any]]:
    if not isinstance(value, list):
        return
    for entry in value:
        if isinstance(entry, list) and len(entry) >= 3:
            try:
                yield int(entry[0]), int(entry[1]), entry[2]
            except (TypeError, ValueError):
                continue
    for index in range(0, len(value) - 2, 3):
        try:
            yield int(value[index]), int(value[index + 1]), value[index + 2]
        except (TypeError, ValueError):
            continue


def summarize_map_field(payload: Any) -> Dict[str, Any]:
    if isinstance(payload, list) and payload:
        return {
            "field_id": payload[0],
            "intensity": payload[1] if len(payload) > 1 else None,
            "age_turns": payload[2] if len(payload) > 2 else None,
        }
    return {"raw": payload}


def map_item_typeid(item: Any) -> str:
    if isinstance(item, dict):
        return str(item.get("typeid", ""))
    if isinstance(item, list) and len(item) == 2 and isinstance(item[0], dict):
        return str(item[0].get("typeid", ""))
    return str(item)


def summarize_map_items(payload: Any) -> List[str]:
    if not isinstance(payload, list):
        return [map_item_typeid(payload)] if payload else []
    if len(payload) == 2 and isinstance(payload[0], dict):
        typeid = map_item_typeid(payload)
        return [typeid] if typeid else []
    return [typeid for typeid in (map_item_typeid(item) for item in payload) if typeid]


def decode_submap_rle(raw: Any, *, context: str) -> List[Any]:
    """Decode submap terrain/radiation RLE into 144 row-major values."""
    if not isinstance(raw, list):
        return []
    flat: List[Any] = []
    for entry in raw:
        if isinstance(entry, list) and len(entry) >= 2:
            try:
                count = int(entry[1])
            except (TypeError, ValueError):
                raise RuntimeError(f"Submap RLE count is invalid in {context}: {entry!r}")
            if count <= 0:
                raise RuntimeError(f"Submap RLE count must be positive in {context}: {entry!r}")
            flat.extend([entry[0]] * count)
        else:
            flat.append(entry)
    return flat


def encode_submap_rle(values: Sequence[Any]) -> List[List[Any]]:
    if not values:
        return []
    encoded: List[List[Any]] = []
    current = values[0]
    count = 1
    for value in values[1:]:
        if value == current:
            count += 1
            continue
        encoded.append([current, count])
        current = value
        count = 1
    encoded.append([current, count])
    return encoded


def submap_rle_value_at(raw: Any, local: Tuple[int, int, int], *, context: str) -> Any:
    flat = decode_submap_rle(raw, context=context)
    index = int(local[1]) * 12 + int(local[0])
    if index < 0 or index >= len(flat):
        return None
    return flat[index]


def submap_radiation_value_at(raw: Any, local: Tuple[int, int, int], *, context: str) -> Any:
    """Decode saved submap radiation RLE, which is flat strength/count pairs."""
    if not isinstance(raw, list):
        return None
    target_index = int(local[1]) * 12 + int(local[0])
    if target_index < 0:
        return None
    cell_index = 0
    iterator = iter(raw)
    for strength in iterator:
        try:
            count_raw = next(iterator)
        except StopIteration as exc:
            raise RuntimeError(f"Submap radiation RLE has dangling strength in {context}: {raw!r}") from exc
        try:
            count = int(count_raw)
        except (TypeError, ValueError):
            raise RuntimeError(f"Submap radiation RLE count is invalid in {context}: {count_raw!r}")
        if count <= 0:
            raise RuntimeError(f"Submap radiation RLE count must be positive in {context}: {count_raw!r}")
        if cell_index <= target_index < cell_index + count:
            return strength
        cell_index += count
    return None


def parse_map_tile_offsets(raw_offsets: Sequence[Any]) -> List[Tuple[int, int, int]]:
    if not raw_offsets:
        return []
    if len(raw_offsets) % 3 != 0:
        raise ValueError("offset values must be repeated triples: dx dy dz")
    offsets: List[Tuple[int, int, int]] = []
    for index in range(0, len(raw_offsets), 3):
        offsets.append((int(raw_offsets[index]), int(raw_offsets[index + 1]), int(raw_offsets[index + 2])))
    return offsets


def audit_map_tiles_near_player(
    world_dir: Path,
    *,
    player_save: str = "",
    radius: int = 2,
    offsets: Optional[List[Tuple[int, int, int]]] = None,
    required_terrain: Optional[List[str]] = None,
    required_fields: Optional[List[str]] = None,
    required_items: Optional[List[str]] = None,
    required_furniture: Optional[List[str]] = None,
    required_traps: Optional[List[str]] = None,
    required_radiation: Optional[List[int]] = None,
    forbidden_terrain: Optional[List[str]] = None,
    forbidden_fields: Optional[List[str]] = None,
    forbidden_items: Optional[List[str]] = None,
    forbidden_furniture: Optional[List[str]] = None,
    forbidden_traps: Optional[List[str]] = None,
    forbidden_radiation: Optional[List[int]] = None,
) -> Dict[str, Any]:
    """Read-only saved-map audit for terrain/fields/items/furniture/traps/radiation near the saved player."""
    if not world_dir.exists():
        raise FileNotFoundError(f"World dir not found: {world_dir}")
    selected_player_save = player_save.strip()
    if not selected_player_save:
        saves = sorted(path.name for path in world_dir.glob("*.sav.zzip"))
        if len(saves) != 1:
            raise RuntimeError(f"Expected one *.sav.zzip in {world_dir}, found {saves}")
        selected_player_save = saves[0]

    player_abs_omt, player_location = load_player_abs_omt(world_dir, selected_player_save)
    maps_dir = world_dir / "maps"
    explicit_offsets = offsets is not None
    if offsets is None:
        scan_radius = max(0, int(radius))
        offsets = [(dx, dy, 0) for dy in range(-scan_radius, scan_radius + 1) for dx in range(-scan_radius, scan_radius + 1)]

    extracted_packs: set[str] = set()
    preexisting_packs: set[str] = {path.name for path in maps_dir.iterdir() if path.is_dir()} if maps_dir.exists() else set()
    tile_reports: List[Dict[str, Any]] = []

    try:
        for dx, dy, dz in offsets:
            target = [int(player_location[0]) + dx, int(player_location[1]) + dy, int(player_location[2]) + dz]
            abs_sm = (target[0] // 12, target[1] // 12, target[2])
            abs_omt = (target[0] // 24, target[1] // 24, target[2])
            local = (target[0] - abs_sm[0] * 12, target[1] - abs_sm[1] * 12, target[2])
            pack_stem = f"{abs_omt[0] // 32}.{abs_omt[1] // 32}.{abs_omt[2]}"
            pack_dir = maps_dir / pack_stem
            if not pack_dir.exists():
                pack_zzip = maps_dir / f"{pack_stem}.zzip"
                if not pack_zzip.exists():
                    continue
                run_zzip(pack_zzip)
                extracted_packs.add(pack_stem)
            map_path = pack_dir / f"{abs_omt[0]}.{abs_omt[1]}.{abs_omt[2]}.map"
            if not map_path.exists():
                continue
            map_payload = json.loads(map_path.read_text(encoding="utf-8"))
            if not isinstance(map_payload, list):
                continue
            submap = next(
                (
                    sub
                    for sub in map_payload
                    if isinstance(sub, dict) and sub.get("coordinates") == [abs_sm[0], abs_sm[1], abs_sm[2]]
                ),
                None,
            )
            if not isinstance(submap, dict):
                continue
            terrain_raw = submap_rle_value_at(
                submap.get("terrain"),
                local,
                context=f"{map_path}:{abs_sm}:{local}:terrain",
            )
            terrain = str(terrain_raw) if terrain_raw is not None else ""
            radiation_raw = submap_radiation_value_at(
                submap.get("radiation"),
                local,
                context=f"{map_path}:{abs_sm}:{local}:radiation",
            )
            radiation: Optional[int]
            try:
                radiation = int(radiation_raw) if radiation_raw is not None else None
            except (TypeError, ValueError):
                radiation = None
            fields = [summarize_map_field(payload) for x, y, payload in iter_map_triples(submap.get("fields")) if x == local[0] and y == local[1]]
            items: List[str] = []
            for x, y, payload in iter_map_triples(submap.get("items")):
                if x == local[0] and y == local[1]:
                    items.extend(summarize_map_items(payload))
            furniture = [str(payload) for x, y, payload in iter_map_triples(submap.get("furniture")) if x == local[0] and y == local[1]]
            traps = [str(payload) for x, y, payload in iter_map_triples(submap.get("traps")) if x == local[0] and y == local[1]]
            if explicit_offsets or terrain or fields or items or furniture or traps or radiation not in (None, 0):
                tile_reports.append({
                    "offset_ms": [dx, dy, dz],
                    "target_location_ms": target,
                    "target_abs_omt": list(abs_omt),
                    "target_abs_sm": list(abs_sm),
                    "local_ms": [local[0], local[1], local[2]],
                    "terrain": terrain,
                    "fields": fields,
                    "items": items,
                    "furniture": furniture,
                    "traps": traps,
                    "radiation": radiation,
                })
    finally:
        for stem in sorted(extracted_packs):
            if stem not in preexisting_packs:
                pack_dir = maps_dir / stem
                if pack_dir.exists():
                    shutil.rmtree(pack_dir)

    required_terrain = [terrain for terrain in (required_terrain or []) if terrain]
    required_fields = [field for field in (required_fields or []) if field]
    required_items = [item for item in (required_items or []) if item]
    required_furniture = [furn for furn in (required_furniture or []) if furn]
    required_traps = [trap for trap in (required_traps or []) if trap]
    required_radiation = [int(rad) for rad in (required_radiation or [])]
    forbidden_terrain = [terrain for terrain in (forbidden_terrain or []) if terrain]
    forbidden_fields = [field for field in (forbidden_fields or []) if field]
    forbidden_items = [item for item in (forbidden_items or []) if item]
    forbidden_furniture = [furn for furn in (forbidden_furniture or []) if furn]
    forbidden_traps = [trap for trap in (forbidden_traps or []) if trap]
    forbidden_radiation = [int(rad) for rad in (forbidden_radiation or [])]
    observed_terrain = [str(tile.get("terrain")) for tile in tile_reports if str(tile.get("terrain", ""))]
    observed_field_ids = [str(field.get("field_id")) for tile in tile_reports for field in tile.get("fields", []) if isinstance(field, dict)]
    observed_items = [str(item) for tile in tile_reports for item in tile.get("items", [])]
    observed_furniture = [str(furn) for tile in tile_reports for furn in tile.get("furniture", [])]
    observed_traps = [str(trap) for tile in tile_reports for trap in tile.get("traps", [])]
    observed_radiation = [int(rad) for rad in (tile.get("radiation") for tile in tile_reports) if rad is not None]
    missing_required_terrain = [terrain for terrain in required_terrain if terrain not in observed_terrain]
    missing_required_fields = [field for field in required_fields if field not in observed_field_ids]
    missing_required_items = [item for item in required_items if item not in observed_items]
    missing_required_furniture = [furn for furn in required_furniture if furn not in observed_furniture]
    missing_required_traps = [trap for trap in required_traps if trap not in observed_traps]
    missing_required_radiation = [rad for rad in required_radiation if rad not in observed_radiation]
    observed_forbidden_terrain = [terrain for terrain in forbidden_terrain if terrain in observed_terrain]
    observed_forbidden_fields = [field for field in forbidden_fields if field in observed_field_ids]
    observed_forbidden_items = [item for item in forbidden_items if item in observed_items]
    observed_forbidden_furniture = [furn for furn in forbidden_furniture if furn in observed_furniture]
    observed_forbidden_traps = [trap for trap in forbidden_traps if trap in observed_traps]
    observed_forbidden_radiation = [rad for rad in forbidden_radiation if rad in observed_radiation]
    required_count = (
        len(required_terrain)
        + len(required_fields)
        + len(required_items)
        + len(required_furniture)
        + len(required_traps)
        + len(required_radiation)
        + len(forbidden_terrain)
        + len(forbidden_fields)
        + len(forbidden_items)
        + len(forbidden_furniture)
        + len(forbidden_traps)
        + len(forbidden_radiation)
    )
    missing_count = (
        len(missing_required_terrain)
        + len(missing_required_fields)
        + len(missing_required_items)
        + len(missing_required_furniture)
        + len(missing_required_traps)
        + len(missing_required_radiation)
        + len(observed_forbidden_terrain)
        + len(observed_forbidden_fields)
        + len(observed_forbidden_items)
        + len(observed_forbidden_furniture)
        + len(observed_forbidden_traps)
        + len(observed_forbidden_radiation)
    )
    if required_count and missing_count == 0:
        status = "required_state_present"
    elif required_count:
        status = "required_state_missing"
    else:
        status = "scanned"
    return {
        "world": world_dir.name,
        "world_dir": str(world_dir),
        "player_save": selected_player_save,
        "player_location_ms": player_location,
        "player_abs_omt": list(player_abs_omt),
        "scanned_offsets": len(offsets),
        "required_terrain": required_terrain,
        "required_fields": required_fields,
        "required_items": required_items,
        "required_furniture": required_furniture,
        "required_traps": required_traps,
        "required_radiation": required_radiation,
        "forbidden_terrain": forbidden_terrain,
        "forbidden_fields": forbidden_fields,
        "forbidden_items": forbidden_items,
        "forbidden_furniture": forbidden_furniture,
        "forbidden_traps": forbidden_traps,
        "forbidden_radiation": forbidden_radiation,
        "observed_terrain": observed_terrain,
        "observed_field_ids": observed_field_ids,
        "observed_items": observed_items,
        "observed_furniture": observed_furniture,
        "observed_traps": observed_traps,
        "observed_radiation": observed_radiation,
        "observed_forbidden_terrain": observed_forbidden_terrain,
        "observed_forbidden_fields": observed_forbidden_fields,
        "observed_forbidden_items": observed_forbidden_items,
        "observed_forbidden_furniture": observed_forbidden_furniture,
        "observed_forbidden_traps": observed_forbidden_traps,
        "observed_forbidden_radiation": observed_forbidden_radiation,
        "missing_required_terrain": missing_required_terrain,
        "missing_required_fields": missing_required_fields,
        "missing_required_items": missing_required_items,
        "missing_required_furniture": missing_required_furniture,
        "missing_required_traps": missing_required_traps,
        "missing_required_radiation": missing_required_radiation,
        "tiles": tile_reports,
        "status": status,
    }


def audit_saved_map_opaque_tile(
    world_dir: Path,
    *,
    abs_omt: List[int],
    local_ms: List[int],
    required_terrain: str,
    required_flags: Optional[List[str]] = None,
    barrier_local_ms: Optional[List[int]] = None,
    barrier_terrain: str = "",
    barrier_flags: Optional[List[str]] = None,
    require_enclosed: bool = False,
    player_save: str = "",
    opaque_overlays: Optional[List[Dict[str, Any]]] = None,
    require_opaque_neighbors: bool = False,
) -> Dict[str, Any]:
    """Prove an exact saved-map opaque footing from map and terrain layers.

    The overmap terrain is deliberately not used as an opacity proxy: this
    reads the saved submap tile, then resolves the terrain definition and its
    declared blocking flags.
    """
    if len(abs_omt) != 3 or len(local_ms) != 3:
        raise RuntimeError("saved-map opaque tile needs three-dimensional coordinates")
    if any(isinstance(value, bool) or not isinstance(value, int) for value in abs_omt + local_ms):
        raise RuntimeError("saved-map opaque tile coordinates must be integers")
    required_flags = list(required_flags or [])
    barrier_flags = list(barrier_flags or [])
    shielded_avatar = barrier_local_ms is not None
    if not required_terrain or (not required_flags and not shielded_avatar):
        raise RuntimeError("saved-map tile needs terrain and either blocking flags or a shield relation")
    target = [abs_omt[0] * 24 + local_ms[0], abs_omt[1] * 24 + local_ms[1], abs_omt[2] + local_ms[2]]
    abs_sm = (target[0] // 12, target[1] // 12, target[2])
    local = (target[0] - abs_sm[0] * 12, target[1] - abs_sm[1] * 12, target[2])
    maps_dir = world_dir / "maps"
    pack_stem = f"{abs_omt[0] // 32}.{abs_omt[1] // 32}.{abs_omt[2]}"
    pack_dir = maps_dir / pack_stem
    extracted = False
    if not pack_dir.exists():
        pack_path = maps_dir / f"{pack_stem}.zzip"
        if not pack_path.exists():
            raise RuntimeError(f"saved-map opaque tile pack missing: {pack_path}")
        run_zzip(pack_path)
        extracted = True
    map_path = pack_dir / f"{abs_omt[0]}.{abs_omt[1]}.{abs_omt[2]}.map"
    try:
        payload = json.loads(map_path.read_text(encoding="utf-8"))
        submap = next((entry for entry in payload if isinstance(entry, dict) and entry.get("coordinates") == list(abs_sm)), None)
        if not isinstance(submap, dict):
            raise RuntimeError(f"saved-map opaque tile submap missing: {abs_sm}")
        observed_terrain = str(submap_rle_value_at(submap.get("terrain"), local, context=f"{map_path}:{local}"))
        if observed_terrain != required_terrain:
            raise RuntimeError(f"saved-map opaque tile terrain mismatch: {observed_terrain} != {required_terrain}")
        definitions: List[Dict[str, Any]] = []
        for definition_path in (Path(__file__).resolve().parents[2] / "data/json/furniture_and_terrain").glob("*.json"):
            try:
                raw = json.loads(definition_path.read_text(encoding="utf-8"))
            except (OSError, json.JSONDecodeError):
                continue
            values = raw if isinstance(raw, list) else [raw]
            definitions.extend(value for value in values if isinstance(value, dict) and value.get("id") == observed_terrain)
        flags = sorted({str(flag) for definition in definitions for flag in definition.get("flags", [])})
        missing_flags = sorted(set(required_flags) - set(flags))
        if missing_flags:
            raise RuntimeError(f"saved-map opaque tile definition missing flags: {missing_flags}")
        result = {
            "status": "required_state_present",
            "abs_omt": list(abs_omt),
            "local_ms": list(local_ms),
            "target_location_ms": target,
            "submap": list(abs_sm),
            "terrain": observed_terrain,
            "definition_flags": flags,
            "required_flags": sorted(set(required_flags)),
            "opacity_proof": "saved_submap_terrain_definition_flags",
        }
        if shielded_avatar:
            if len(barrier_local_ms or []) != 3 or not barrier_terrain or not barrier_flags:
                raise RuntimeError("shield relation needs barrier coordinates, terrain, and flags")
            if abs(int(barrier_local_ms[0]) - int(local_ms[0])) + abs(int(barrier_local_ms[1]) - int(local_ms[1])) != 1:
                raise RuntimeError("saved-map barrier is disconnected from avatar tile")
            barrier_target = [abs_omt[0] * 24 + barrier_local_ms[0], abs_omt[1] * 24 + barrier_local_ms[1], abs_omt[2] + barrier_local_ms[2]]
            barrier_sm = (barrier_target[0] // 12, barrier_target[1] // 12, barrier_target[2])
            barrier_loc = (barrier_target[0] - barrier_sm[0] * 12, barrier_target[1] - barrier_sm[1] * 12, barrier_target[2])
            barrier_submap = next((entry for entry in payload if isinstance(entry, dict) and entry.get("coordinates") == list(barrier_sm)), None)
            if not isinstance(barrier_submap, dict):
                raise RuntimeError(f"saved-map barrier submap missing: {barrier_sm}")
            observed_barrier = str(submap_rle_value_at(barrier_submap.get("terrain"), barrier_loc, context=f"{map_path}:{barrier_loc}"))
            if observed_barrier != barrier_terrain:
                raise RuntimeError(f"saved-map barrier terrain mismatch: {observed_barrier} != {barrier_terrain}")
            barrier_defs = [definition for definition in definitions if definition.get("id") == observed_barrier]
            if not barrier_defs:
                for definition_path in (Path(__file__).resolve().parents[2] / "data/json/furniture_and_terrain").glob("*.json"):
                    try:
                        raw = json.loads(definition_path.read_text(encoding="utf-8"))
                    except (OSError, json.JSONDecodeError):
                        continue
                    values = raw if isinstance(raw, list) else [raw]
                    barrier_defs.extend(value for value in values if isinstance(value, dict) and value.get("id") == observed_barrier)
            barrier_observed_flags = sorted({str(flag) for definition in barrier_defs for flag in definition.get("flags", [])})
            missing_barrier_flags = sorted(set(barrier_flags) - set(barrier_observed_flags))
            if missing_barrier_flags:
                raise RuntimeError(f"saved-map barrier definition missing flags: {missing_barrier_flags}")
            if "WALL" in flags or "SUPPORTS_ROOF" in flags:
                raise RuntimeError("saved-map avatar tile is not passable")
            result.update({
                "avatar_local_ms": list(local_ms),
                "avatar_terrain": observed_terrain,
                "avatar_definition_flags": flags,
                "barrier_local_ms": list(barrier_local_ms),
                "barrier_terrain": observed_barrier,
                "barrier_definition_flags": barrier_observed_flags,
                "barrier_proof": "passable_avatar_adjacent_to_source_defined_wall",
            })
        if require_enclosed:
            overlay_tiles = {
                (int(entry["local_ms"][0]), int(entry["local_ms"][1])): str(entry["terrain"])
                for entry in (opaque_overlays or [])
                if isinstance(entry, dict) and isinstance(entry.get("local_ms"), list) and len(entry["local_ms"]) >= 2
            }
            source_flags: Dict[str, Set[str]] = {}
            for definition_path in (Path(__file__).resolve().parents[2] / "data/json/furniture_and_terrain").glob("*.json"):
                try:
                    raw = json.loads(definition_path.read_text(encoding="utf-8"))
                except (OSError, json.JSONDecodeError):
                    continue
                values = raw if isinstance(raw, list) else [raw]
                for definition in values:
                    if isinstance(definition, dict) and definition.get("id"):
                        source_flags[str(definition["id"])] = {str(flag) for flag in definition.get("flags", [])}
            for overlay in (opaque_overlays or []):
                overlay_id = str(overlay.get("terrain", "")) if isinstance(overlay, dict) else ""
                if not (source_flags.get(overlay_id, set()) & {"WALL", "SUPPORTS_ROOF", "BLOCK_WIND"}):
                    raise RuntimeError(f"saved-map overlay lacks source-defined opacity: {overlay_id}")
            def tile_is_opaque(x: int, y: int) -> bool:
                if (x, y) in overlay_tiles:
                    return True
                global_x, global_y = abs_omt[0] * 24 + x, abs_omt[1] * 24 + y
                sm = (global_x // 12, global_y // 12, abs_omt[2])
                sm_entry = next(entry for entry in payload if isinstance(entry, dict) and entry.get("coordinates") == list(sm))
                loc = (global_x % 12, global_y % 12, abs_omt[2])
                ids = [str(submap_rle_value_at(sm_entry.get("terrain"), loc, context=f"{map_path}:{loc}"))]
                ids.extend(str(value) for fx, fy, value in iter_map_triples(sm_entry.get("furniture")) if fx == loc[0] and fy == loc[1])
                return any(source_flags.get(tile_id, set()) & {"WALL", "SUPPORTS_ROOF", "BLOCK_WIND"} for tile_id in ids)
            start = (local_ms[0], local_ms[1])
            if not (0 <= start[0] < 24 and 0 <= start[1] < 24) or tile_is_opaque(*start):
                raise RuntimeError("saved-map avatar tile is not a passable topology origin")
            if require_opaque_neighbors:
                neighbors = [(start[0] + dx, start[1] + dy) for dy in (-1, 0, 1) for dx in (-1, 0, 1) if (dx, dy) != (0, 0)]
                missing_neighbors = [list(point) for point in neighbors if not tile_is_opaque(*point)]
                if missing_neighbors:
                    raise RuntimeError(f"saved-map avatar has transparent neighbor gaps: {missing_neighbors}")
            component = {start}; pending = [start]
            while pending:
                x, y = pending.pop()
                for neighbor in ((x + 1, y), (x - 1, y), (x, y + 1), (x, y - 1)):
                    if 0 <= neighbor[0] < 24 and 0 <= neighbor[1] < 24 and neighbor not in component and not tile_is_opaque(*neighbor):
                        component.add(neighbor); pending.append(neighbor)
            boundary = sorted(point for point in component if point[0] in (0, 23) or point[1] in (0, 23))
            if boundary:
                raise RuntimeError(f"saved-map avatar component reaches exterior: {boundary[:8]}")
            hostile_inside: List[Dict[str, Any]] = []
            if player_save:
                save_path = world_dir / player_save
                extracted_save = save_path.with_suffix("")
                run_zzip(save_path)
                try:
                    save_payload = json.loads(extracted_save.read_text(encoding="utf-8"))
                    for actor in save_payload.get("active_monsters", []):
                        location = actor.get("location", []) if isinstance(actor, dict) else []
                        if len(location) >= 3 and int(location[0]) // 24 == abs_omt[0] and int(location[1]) // 24 == abs_omt[1] and (int(location[0]) % 24, int(location[1]) % 24) in component:
                            hostile_inside.append({"typeid": actor.get("typeid", ""), "location_ms": list(location)})
                finally:
                    if extracted_save.exists():
                        extracted_save.unlink()
            if hostile_inside:
                raise RuntimeError(f"saved-map hostile actor inside avatar component: {hostile_inside}")
            result.update({"component_size": len(component), "component_boundary": boundary, "hostile_actors_in_component": hostile_inside, "topology_proof": "closed_passable_component"})
        return result
    finally:
        if extracted and pack_dir.exists():
            shutil.rmtree(pack_dir)


def audit_player_save_mtime(
    world_dir: Path,
    *,
    player_save: str = "",
    changed_since: Optional[Dict[str, Any]] = None,
    wait_for_change_seconds: float = 0.0,
    stable_after_change_seconds: float = 0.0,
    poll_interval_seconds: float = 0.5,
) -> Dict[str, Any]:
    """Read-only saved-player file mtime audit for post-action save/writeback gates."""
    if not world_dir.exists():
        raise FileNotFoundError(f"World dir not found: {world_dir}")
    selected_player_save = player_save.strip()
    if not selected_player_save:
        saves = sorted(path.name for path in world_dir.glob("*.sav.zzip"))
        if len(saves) != 1:
            raise RuntimeError(f"Expected one *.sav.zzip in {world_dir}, found {saves}")
        selected_player_save = saves[0]
    save_path = world_dir / selected_player_save
    if not save_path.exists():
        raise FileNotFoundError(f"Player save not found: {save_path}")

    required_change = changed_since is not None
    baseline_mtime_ns: Optional[int] = None
    baseline_label = ""
    if isinstance(changed_since, dict):
        baseline_label = str(changed_since.get("label", "") or "")
        try:
            baseline_mtime_ns = int(changed_since.get("save_mtime_ns"))
        except (TypeError, ValueError):
            baseline_mtime_ns = None

    wait_started = time.time()
    waited_for_change = False
    stable_observed_seconds = 0.0

    def current_stat() -> os.stat_result:
        return save_path.stat()

    stat = current_stat()
    if required_change and baseline_mtime_ns is not None and wait_for_change_seconds > 0:
        deadline = wait_started + max(0.0, wait_for_change_seconds)
        poll_interval = max(0.05, poll_interval_seconds)
        while int(stat.st_mtime_ns) <= baseline_mtime_ns and time.time() < deadline:
            waited_for_change = True
            time.sleep(min(poll_interval, max(0.0, deadline - time.time())))
            stat = current_stat()

    if required_change and baseline_mtime_ns is not None and int(stat.st_mtime_ns) > baseline_mtime_ns and stable_after_change_seconds > 0:
        stable_target = max(0.0, stable_after_change_seconds)
        poll_interval = max(0.05, poll_interval_seconds)
        stable_started = time.time()
        last_mtime_ns = int(stat.st_mtime_ns)
        while True:
            elapsed = time.time() - stable_started
            if elapsed >= stable_target:
                stable_observed_seconds = elapsed
                break
            time.sleep(min(poll_interval, stable_target - elapsed))
            latest_stat = current_stat()
            latest_mtime_ns = int(latest_stat.st_mtime_ns)
            if latest_mtime_ns != last_mtime_ns:
                stat = latest_stat
                last_mtime_ns = latest_mtime_ns
                stable_started = time.time()
            else:
                stat = latest_stat

    save_mtime_ns = int(stat.st_mtime_ns)
    save_mtime = float(stat.st_mtime)

    if required_change and baseline_mtime_ns is not None and save_mtime_ns > baseline_mtime_ns:
        status = "required_state_present"
    elif required_change:
        status = "required_state_missing"
    else:
        status = "baseline_recorded"

    return {
        "world": world_dir.name,
        "world_dir": str(world_dir),
        "player_save": selected_player_save,
        "save_path": str(save_path),
        "save_mtime": save_mtime,
        "save_mtime_ns": save_mtime_ns,
        "save_mtime_iso": datetime.fromtimestamp(save_mtime).isoformat(timespec="microseconds"),
        "wait_for_change_seconds": wait_for_change_seconds,
        "waited_for_change": waited_for_change,
        "stable_after_change_seconds": stable_after_change_seconds,
        "stable_observed_seconds": stable_observed_seconds,
        "required_change_since_label": baseline_label,
        "required_change_since_mtime_ns": baseline_mtime_ns,
        "mtime_changed_since_required_label": (
            save_mtime_ns > baseline_mtime_ns if baseline_mtime_ns is not None else False
        ),
        "missing_required_items": ["player_save_mtime_changed"] if status == "required_state_missing" else [],
        "status": status,
    }


def load_item_definitions_for(typeids: Iterable[str]) -> Dict[str, Dict[str, Any]]:
    wanted = {str(typeid).strip() for typeid in typeids if str(typeid).strip()}
    found: Dict[str, Dict[str, Any]] = {}
    if not wanted:
        return found
    for path in (repo_root() / "data" / "json").rglob("*.json"):
        try:
            payload = json.loads(path.read_text(encoding="utf-8"))
        except Exception:
            continue
        entries = payload if isinstance(payload, list) else [payload]
        for entry in entries:
            if not isinstance(entry, dict):
                continue
            item_id = str(entry.get("id", "")).strip()
            if item_id in wanted and item_id not in found:
                found[item_id] = entry
        if len(found) == len(wanted):
            break
    return found


def item_display_name_from_definition(entry: Dict[str, Any]) -> str:
    name = entry.get("name")
    if isinstance(name, dict):
        return str(name.get("str") or name.get("str_sp") or name.get("ctxt") or "").strip()
    return str(name or "").strip()


def item_use_action_summary(entry: Dict[str, Any]) -> List[Dict[str, Any]]:
    raw_use_action = entry.get("use_action")
    actions = raw_use_action if isinstance(raw_use_action, list) else [raw_use_action]
    summary: List[Dict[str, Any]] = []
    for action in actions:
        if isinstance(action, str):
            summary.append({"type": action})
        elif isinstance(action, dict):
            row: Dict[str, Any] = {"type": str(action.get("type", "")).strip()}
            if action.get("furn_type"):
                row["furn_type"] = str(action.get("furn_type"))
            if action.get("terrain"):
                row["terrain"] = str(action.get("terrain"))
            summary.append(row)
    return [row for row in summary if row.get("type")]


def iter_saved_item_entries(entry: Any, path: str) -> Iterable[Tuple[str, Dict[str, Any]]]:
    """Yield a saved item and recursive container-pocket contents with stable JSON-ish paths."""
    if not isinstance(entry, dict):
        return
    yield path, entry
    contents_obj = entry.get("contents")
    if not isinstance(contents_obj, dict):
        return
    pockets = contents_obj.get("contents", [])
    if not isinstance(pockets, list):
        return
    for pocket_index, pocket in enumerate(pockets):
        if not isinstance(pocket, dict):
            continue
        pocket_contents = pocket.get("contents", [])
        if not isinstance(pocket_contents, list):
            continue
        for item_index, child in enumerate(pocket_contents):
            child_path = f"{path}/contents/contents[{pocket_index}]/contents[{item_index}]"
            yield from iter_saved_item_entries(child, child_path)


def saved_player_worn_items(player: Dict[str, Any]) -> List[Dict[str, Any]]:
    worn = player.get("worn", {})
    if isinstance(worn, dict):
        worn_items = worn.get("worn", [])
    else:
        worn_items = worn
    return worn_items if isinstance(worn_items, list) else []


def saved_player_item_rows(
    player: Dict[str, Any]
) -> Tuple[List[Tuple[str, Dict[str, Any]]], List[Tuple[str, Dict[str, Any]]]]:
    """Return (live-accessible worn/held rows, legacy top-level inv rows).

    The modern inventory selector walks wielded gear plus worn items and their
    contained items.  It does not expose old top-level ``player.inv`` rows by
    itself, so keep that save bucket separate to avoid treating an inaccessible
    fixture injection as live Use-item proof.
    """
    accessible_rows: List[Tuple[str, Dict[str, Any]]] = []
    weapon = player.get("weapon")
    if isinstance(weapon, dict):
        accessible_rows.extend(iter_saved_item_entries(weapon, "player.weapon"))
    for worn_index, worn_item in enumerate(saved_player_worn_items(player)):
        accessible_rows.extend(
            iter_saved_item_entries(worn_item, f"player.worn.worn[{worn_index}]")
        )

    legacy_rows: List[Tuple[str, Dict[str, Any]]] = []
    inventory = player.get("inv", [])
    if not isinstance(inventory, list):
        raise RuntimeError("Extracted player save has non-list inventory")
    for inv_index, inv_item in enumerate(inventory):
        legacy_rows.extend(iter_saved_item_entries(inv_item, f"player.inv[{inv_index}]"))
    return accessible_rows, legacy_rows


def summarize_saved_item_rows(
    rows: Iterable[Tuple[str, Dict[str, Any]]]
) -> Tuple[Dict[str, int], Dict[str, List[Dict[str, Any]]]]:
    counts: Dict[str, int] = {}
    item_rows: Dict[str, List[Dict[str, Any]]] = {}
    for path, entry in rows:
        typeid = str(entry.get("typeid", "")).strip()
        if not typeid:
            continue
        counts[typeid] = counts.get(typeid, 0) + 1
        item_rows.setdefault(typeid, []).append({
            "typeid": typeid,
            "source_path": path,
            "custom_invlet": str(entry.get("invlet", "") or ""),
            "charges": entry.get("charges"),
            "count_by_charges": entry.get("count_by_charges"),
            "flags": sorted(
                str(flag) for flag in entry.get("item_tags", []) if str(flag).strip()
            ) if isinstance(entry.get("item_tags"), list) else [],
        })
    return counts, item_rows


def saved_item_nested_charge_sum(entry: Any, *, ammo_type: str = "") -> int:
    """Sum charges carried by nested ammo/items inside a saved item payload."""
    total = 0
    if not isinstance(entry, dict):
        return total
    typeid = str(entry.get("typeid", "")).strip()
    if (not ammo_type or typeid == ammo_type) and "charges" in entry:
        try:
            total += int(entry.get("charges") or 0)
        except (TypeError, ValueError):
            pass
    contents_obj = entry.get("contents")
    if not isinstance(contents_obj, dict):
        return total
    pockets = contents_obj.get("contents", [])
    if not isinstance(pockets, list):
        return total
    for pocket in pockets:
        if not isinstance(pocket, dict):
            continue
        pocket_contents = pocket.get("contents", [])
        if not isinstance(pocket_contents, list):
            continue
        for child in pocket_contents:
            total += saved_item_nested_charge_sum(child, ammo_type=ammo_type)
    return total


def audit_saved_player_items(
    world_dir: Path,
    *,
    player_save: str = "",
    required_items: Optional[List[str]] = None,
    required_weapon: str = "",
    required_weapon_ammo_type: str = "",
    required_weapon_ammo_min: int = 0,
) -> Dict[str, Any]:
    """Read-only saved-player inventory/wield audit for exact item type ids plus deploy metadata."""
    if not world_dir.exists():
        raise FileNotFoundError(f"World dir not found: {world_dir}")
    selected_player_save = player_save.strip()
    if not selected_player_save:
        saves = sorted(path.name for path in world_dir.glob("*.sav.zzip"))
        if len(saves) != 1:
            raise RuntimeError(f"Expected one *.sav.zzip in {world_dir}, found {saves}")
        selected_player_save = saves[0]

    player_save_path = world_dir / selected_player_save
    if not player_save_path.exists():
        raise FileNotFoundError(f"Player save not found: {player_save_path}")
    if player_save_path.suffix != ".zzip":
        raise RuntimeError(f"Player inventory audit expects .zzip save path: {player_save_path}")

    extracted_save = player_save_path.with_suffix("")
    run_zzip(player_save_path)
    if not extracted_save.exists():
        raise RuntimeError(f"Player inventory audit did not extract save: {extracted_save}")

    try:
        payload = json.loads(extracted_save.read_text(encoding="utf-8"))
    finally:
        if extracted_save.exists():
            extracted_save.unlink()
    if not isinstance(payload, dict):
        raise RuntimeError(f"Extracted player save is not a JSON object: {extracted_save}")
    player = payload.get("player")
    if not isinstance(player, dict):
        raise RuntimeError(f"Extracted player save is missing player object: {extracted_save}")
    accessible_rows, legacy_rows = saved_player_item_rows(player)
    counts, item_rows = summarize_saved_item_rows(accessible_rows)
    legacy_counts, legacy_item_rows = summarize_saved_item_rows(legacy_rows)
    weapon = player.get("weapon")
    observed_weapon = str(weapon.get("typeid", "")) if isinstance(weapon, dict) else ""
    required_weapon_ammo_type = str(required_weapon_ammo_type or "").strip()
    required_weapon_ammo_min = max(0, int(required_weapon_ammo_min or 0))
    observed_weapon_ammo_remaining = (
        saved_item_nested_charge_sum(weapon, ammo_type=required_weapon_ammo_type)
        if isinstance(weapon, dict)
        else 0
    )

    required = [item for item in (required_items or []) if item]
    required_weapon = str(required_weapon or "").strip()
    interesting_typeids = sorted(set(required) if required else set(counts))
    definitions = load_item_definitions_for(interesting_typeids)
    item_details: Dict[str, Dict[str, Any]] = {}
    for typeid in interesting_typeids:
        definition = definitions.get(typeid, {})
        item_details[typeid] = {
            "count": counts.get(typeid, 0),
            "display_name": item_display_name_from_definition(definition),
            "use_actions": item_use_action_summary(definition),
            "saved_rows": item_rows.get(typeid, []),
            "legacy_top_level_inv_rows": legacy_item_rows.get(typeid, []),
        }

    missing_required_items = [item for item in required if counts.get(item, 0) < 1]
    missing_required_weapon = (
        [required_weapon]
        if required_weapon and observed_weapon != required_weapon
        else []
    )
    missing_required_weapon_ammo = (
        [f"{required_weapon_ammo_type or 'nested_ammo'}>={required_weapon_ammo_min}"]
        if required_weapon_ammo_min and observed_weapon_ammo_remaining < required_weapon_ammo_min
        else []
    )
    required_count = len(required) + (1 if required_weapon else 0) + (1 if required_weapon_ammo_min else 0)
    missing_count = len(missing_required_items) + len(missing_required_weapon) + len(missing_required_weapon_ammo)
    if required_count and not missing_count:
        status = "required_state_present"
    elif required_count:
        status = "required_state_missing"
    else:
        status = "scanned"

    return {
        "world": world_dir.name,
        "world_dir": str(world_dir),
        "player_save": selected_player_save,
        "required_items": required,
        "required_weapon": required_weapon,
        "required_weapon_ammo_type": required_weapon_ammo_type,
        "required_weapon_ammo_min": required_weapon_ammo_min,
        "observed_weapon": observed_weapon,
        "observed_weapon_ammo_remaining": observed_weapon_ammo_remaining,
        "observed_items": sorted(counts),
        "inventory_counts": dict(sorted(counts.items())),
        "live_accessible_counts": dict(sorted(counts.items())),
        "legacy_top_level_inv_counts": dict(sorted(legacy_counts.items())),
        "item_details": item_details,
        "missing_required_items": missing_required_items,
        "missing_required_weapon": missing_required_weapon,
        "missing_required_weapon_ammo": missing_required_weapon_ammo,
        "status": status,
    }


def audit_saved_player_condition(
    world_dir: Path, *, player_save: str, required_needs: Dict[str, int],
    required_traits: List[str], forbidden_traits: List[str],
) -> Dict[str, Any]:
    player_save_path = world_dir / player_save
    extracted_save = player_save_path.with_suffix("")
    run_zzip(player_save_path)
    try:
        payload = json.loads(extracted_save.read_text(encoding="utf-8"))
    finally:
        if extracted_save.exists():
            extracted_save.unlink()
    player = payload.get("player", {}) if isinstance(payload, dict) else {}
    observed_needs = {key: player.get(key) for key in required_needs}
    traits = player.get("traits", []) if isinstance(player, dict) else []
    observed_traits = sorted(str(trait) for trait in traits) if isinstance(traits, list) else []
    missing_needs = [key for key, value in required_needs.items() if observed_needs.get(key) != value]
    missing_traits = [trait for trait in required_traits if trait not in observed_traits]
    observed_forbidden_traits = [trait for trait in forbidden_traits if trait in observed_traits]
    return {
        "world": world_dir.name, "player_save": player_save,
        "required_needs": required_needs, "observed_needs": observed_needs,
        "required_traits": required_traits, "observed_traits": observed_traits,
        "forbidden_traits": forbidden_traits,
        "missing_needs": missing_needs, "missing_traits": missing_traits,
        "observed_forbidden_traits": observed_forbidden_traits,
        "status": "required_state_present" if not missing_needs and not missing_traits and not observed_forbidden_traits else "required_state_missing",
    }


def audit_saved_phase4_shadow_warning_wait_footings(
    world_dir: Path,
    *,
    footings: List[Dict[str, Any]],
    geometry: Dict[str, Any],
) -> Dict[str, Any]:
    """Prove saved non-field/non-forest wait footing and its route geometry.

    ``EOC_LIEUTENANT_SHADOW_WARN`` needs both an outside avatar and one of
    field/forest/forest_thick.  These saved-terrain checks deliberately prove
    the terrain conjunct false, so they do not infer an indoor state from an
    overmap tile.  The geometry checks keep the fixture's loaded/abstract
    boundary explicit rather than treating the safer avatar footing as a
    route or ecology change.
    """
    required_geometry = {"target", "approach", "watch", "camp", "loaded_handoff_radius_sm"}
    if set(geometry) != required_geometry:
        raise RuntimeError(
            "Phase-4 shadow-warning footing geometry must contain exactly "
            f"{sorted(required_geometry)}"
        )
    radius = geometry["loaded_handoff_radius_sm"]
    if isinstance(radius, bool) or not isinstance(radius, int) or radius < 0:
        raise RuntimeError("Phase-4 shadow-warning footing radius must be a non-negative integer")

    route_points: Dict[str, Tuple[int, int, int]] = {}
    for name in ("target", "approach", "watch", "camp"):
        raw_point = geometry[name]
        if not isinstance(raw_point, list) or len(raw_point) != 3 or any(
                isinstance(value, bool) or not isinstance(value, int) for value in raw_point):
            raise RuntimeError(f"Phase-4 shadow-warning footing geometry {name} is invalid")
        route_points[name] = (raw_point[0], raw_point[1], raw_point[2])

    if not isinstance(footings, list) or not footings:
        raise RuntimeError("Phase-4 shadow-warning footing preflight needs at least one footing")
    expected_footing_keys = {"label", "abs_omt", "required_terrain", "expected_loaded"}
    forbidden_shadow_warn_terrains = {"field", "forest", "forest_thick"}
    decoded_layers: Dict[Tuple[int, int, int], List[str]] = {}
    extracted: List[Tuple[Path, bool]] = []
    observations: List[Dict[str, Any]] = []
    issues: List[str] = []
    try:
        for raw_footing in footings:
            if not isinstance(raw_footing, dict) or set(raw_footing) != expected_footing_keys:
                raise RuntimeError(
                    "Phase-4 shadow-warning footing has unexpected schema; expected "
                    f"{sorted(expected_footing_keys)}"
                )
            label = str(raw_footing["label"] or "").strip()
            point_raw = raw_footing["abs_omt"]
            required_terrain = str(raw_footing["required_terrain"] or "").strip()
            expected_loaded = raw_footing["expected_loaded"]
            if not label or not required_terrain:
                raise RuntimeError("Phase-4 shadow-warning footing needs non-empty label and terrain")
            if not isinstance(point_raw, list) or len(point_raw) != 3 or any(
                    isinstance(value, bool) or not isinstance(value, int) for value in point_raw):
                raise RuntimeError(f"Phase-4 shadow-warning footing {label} has invalid abs_omt")
            if not isinstance(expected_loaded, dict) or set(expected_loaded) != set(route_points):
                raise RuntimeError(
                    f"Phase-4 shadow-warning footing {label} needs exact loaded-state keys "
                    f"{sorted(route_points)}"
                )
            if any(not isinstance(value, bool) for value in expected_loaded.values()):
                raise RuntimeError(f"Phase-4 shadow-warning footing {label} has non-boolean loaded state")
            point = (point_raw[0], point_raw[1], point_raw[2])
            overmap_x, overmap_y, local_point = overmap_file_coords_from_abs_omt(point)
            layer_key = (overmap_x, overmap_y, point[2])
            if layer_key not in decoded_layers:
                overmap_path = world_dir / "overmaps" / f"o.{overmap_x}.{overmap_y}.zzip"
                plain_path, _version_line, payload = extract_overmap_payload(overmap_path)
                extracted.append((plain_path, not bool(payload.get("_created_plain", False))))
                layers = payload.get("layers")
                if not isinstance(layers, list):
                    raise RuntimeError(f"Phase-4 shadow-warning footing overmap has no layers: {overmap_path}")
                layer_index = overmap_layer_index(point[2])
                if layer_index >= len(layers):
                    raise RuntimeError(f"Phase-4 shadow-warning footing overmap misses z={point[2]}")
                decoded_layers[layer_key] = decode_overmap_layer(
                    layers[layer_index], context=f"{overmap_path} z={point[2]}"
                )
            observed_terrain = decoded_layers[layer_key][overmap_flat_index(local_point)]
            loaded = {
                name: max(2 * abs(point[0] - route_point[0]), 2 * abs(point[1] - route_point[1])) <= radius
                for name, route_point in route_points.items()
            }
            terrain_blocks_warning = observed_terrain not in forbidden_shadow_warn_terrains
            observation = {
                "label": label,
                "abs_omt": list(point),
                "required_terrain": required_terrain,
                "observed_terrain": observed_terrain,
                "terrain_blocks_shadow_warning": terrain_blocks_warning,
                "outside_state": "not_inferred_terrain_conjunct_false" if terrain_blocks_warning else "terrain_conjunct_may_pass",
                "expected_loaded": expected_loaded,
                "observed_loaded": loaded,
                "is_signal_target": point == route_points["target"],
            }
            observations.append(observation)
            if observed_terrain != required_terrain:
                issues.append(f"{label}:terrain_mismatch")
            if not terrain_blocks_warning:
                issues.append(f"{label}:shadow_warning_terrain_not_blocked")
            if observation["is_signal_target"]:
                issues.append(f"{label}:signal_target_footing_forbidden")
            if loaded != expected_loaded:
                issues.append(f"{label}:loaded_geometry_mismatch")
    finally:
        for plain_path, keep in extracted:
            cleanup_extracted_overmap(plain_path, keep=keep)
    return {
        "world": world_dir.name,
        "footings": observations,
        "geometry": geometry,
        "shadow_warning_location_condition": "false_from_terrain_conjunct",
        "status": "required_state_present" if not issues else "required_state_missing",
        "issues": sorted(issues),
    }


def audit_saved_active_monsters(
    world_dir: Path,
    *,
    player_save: str = "",
    required_monsters: Optional[List[Dict[str, Any]]] = None,
    required_typeids: Optional[List[str]] = None,
    forbidden_typeids: Optional[List[str]] = None,
) -> Dict[str, Any]:
    """Read-only saved-player audit for active monster type/location state.

    Debug-spawned monsters are saved in the player save's ``active_monsters``
    array, not in the submap spawn-point list. Keep this as a same-save
    metadata gate so a completed debug menu macro cannot be credited unless
    the saved game contains the exact monster state the scenario claimed.
    """
    if not world_dir.exists():
        raise FileNotFoundError(f"World dir not found: {world_dir}")
    selected_player_save = player_save.strip()
    if not selected_player_save:
        saves = sorted(path.name for path in world_dir.glob("*.sav.zzip"))
        if len(saves) != 1:
            raise RuntimeError(f"Expected one *.sav.zzip in {world_dir}, found {saves}")
        selected_player_save = saves[0]

    player_save_path = world_dir / selected_player_save
    if not player_save_path.exists():
        raise FileNotFoundError(f"Player save not found: {player_save_path}")
    if player_save_path.suffix != ".zzip":
        raise RuntimeError(f"Active monster audit expects .zzip save path: {player_save_path}")

    extracted_save = player_save_path.with_suffix("")
    run_zzip(player_save_path)
    if not extracted_save.exists():
        raise RuntimeError(f"Active monster audit did not extract save: {extracted_save}")

    try:
        payload = json.loads(extracted_save.read_text(encoding="utf-8"))
    finally:
        if extracted_save.exists():
            extracted_save.unlink()
    if not isinstance(payload, dict):
        raise RuntimeError(f"Extracted player save is not a JSON object: {extracted_save}")
    player = payload.get("player")
    if not isinstance(player, dict):
        raise RuntimeError(f"Extracted player save is missing player object: {extracted_save}")
    player_location_raw = player.get("location", [])
    if not isinstance(player_location_raw, list) or len(player_location_raw) < 3:
        raise RuntimeError(f"Extracted player save is missing player location: {extracted_save}")
    player_location = [int(player_location_raw[0]), int(player_location_raw[1]), int(player_location_raw[2])]
    save_turn = int(payload.get("turn", 0) or 0)

    active_raw = payload.get("active_monsters", [])
    if not isinstance(active_raw, list):
        raise RuntimeError(f"Extracted player save has non-list active_monsters: {extracted_save}")

    monsters: List[Dict[str, Any]] = []
    counts: Dict[str, int] = {}
    for index, monster in enumerate(active_raw):
        if not isinstance(monster, dict):
            continue
        typeid = str(monster.get("typeid", "")).strip()
        location_raw = monster.get("location", [])
        location: List[int] = []
        offset: List[int] = []
        if isinstance(location_raw, list) and len(location_raw) >= 3:
            location = [int(location_raw[0]), int(location_raw[1]), int(location_raw[2])]
            offset = [
                location[0] - player_location[0],
                location[1] - player_location[1],
                location[2] - player_location[2],
            ]
        if typeid:
            counts[typeid] = counts.get(typeid, 0) + 1
        monsters.append({
            "index": index,
            "typeid": typeid,
            "location_ms": location,
            "offset_ms": offset,
            "friendly": monster.get("friendly"),
            "hallucination": monster.get("hallucination"),
            "dead": monster.get("dead"),
            "hp": monster.get("hp"),
            "last_updated": monster.get("last_updated"),
            "last_updated_at_save_turn": monster.get("last_updated") == save_turn,
            "faction": monster.get("faction"),
            "ammo": monster.get("ammo", {}),
            "values": monster.get("values", {}),
            "unique_name": monster.get("unique_name", ""),
            "nickname": monster.get("nickname", ""),
        })

    required: List[Dict[str, Any]] = []
    for typeid in required_typeids or []:
        normalized = str(typeid).strip()
        if normalized:
            required.append({"typeid": normalized})
    for raw in required_monsters or []:
        if not isinstance(raw, dict):
            continue
        typeid = str(raw.get("typeid", raw.get("monster", ""))).strip()
        if not typeid:
            continue
        requirement: Dict[str, Any] = {"typeid": typeid}
        offset_raw = raw.get("offset_ms")
        if isinstance(offset_raw, list) and len(offset_raw) >= 3:
            requirement["offset_ms"] = [int(offset_raw[0]), int(offset_raw[1]), int(offset_raw[2])]
        for key in ("min_distance_to_player", "max_distance_to_player"):
            if key in raw:
                requirement[key] = int(raw[key])
        if isinstance(raw.get("ammo"), dict):
            requirement["ammo"] = {
                str(ammo_type).strip(): int(amount)
                for ammo_type, amount in raw.get("ammo", {}).items()
                if str(ammo_type).strip()
            }
        if isinstance(raw.get("values"), dict):
            requirement["values"] = {
                str(value_key).strip(): value
                for value_key, value in raw.get("values", {}).items()
                if str(value_key).strip()
            }
        if raw.get("last_updated_at_save_turn") is True:
            requirement["last_updated_at_save_turn"] = True
        required.append(requirement)

    forbidden: List[Dict[str, Any]] = []
    for typeid in forbidden_typeids or []:
        normalized = str(typeid).strip()
        if normalized:
            forbidden.append({"typeid": normalized})

    def matches_requirement(monster: Dict[str, Any], requirement: Dict[str, Any]) -> bool:
        if monster.get("typeid") != requirement.get("typeid"):
            return False
        if "offset_ms" in requirement and monster.get("offset_ms") != requirement.get("offset_ms"):
            return False
        offset = monster.get("offset_ms")
        if isinstance(offset, list) and len(offset) >= 2:
            distance_to_player = max(abs(int(offset[0])), abs(int(offset[1])))
        else:
            distance_to_player = None
        if "min_distance_to_player" in requirement and (
            distance_to_player is None or distance_to_player < int(requirement["min_distance_to_player"])
        ):
            return False
        if "max_distance_to_player" in requirement and (
            distance_to_player is None or distance_to_player > int(requirement["max_distance_to_player"])
        ):
            return False
        required_ammo = requirement.get("ammo")
        if isinstance(required_ammo, dict):
            observed_ammo = monster.get("ammo", {})
            if not isinstance(observed_ammo, dict):
                return False
            for ammo_type, amount in required_ammo.items():
                try:
                    if int(observed_ammo.get(ammo_type, 0) or 0) < int(amount):
                        return False
                except (TypeError, ValueError):
                    return False
        required_values = requirement.get("values")
        if isinstance(required_values, dict):
            observed_values = monster.get("values", {})
            if not isinstance(observed_values, dict):
                return False
            for value_key, required_value in required_values.items():
                observed_value = observed_values.get(value_key)
                if isinstance(observed_value, dict) and "str" in observed_value:
                    observed_value = observed_value.get("str")
                if isinstance(required_value, dict) and "str" in required_value:
                    required_value = required_value.get("str")
                if observed_value != required_value:
                    return False
        if requirement.get("last_updated_at_save_turn") is True and \
                monster.get("last_updated_at_save_turn") is not True:
            return False
        return True

    missing_required_monsters = [
        requirement
        for requirement in required
        if not any(matches_requirement(monster, requirement) for monster in monsters)
    ]
    observed_forbidden_monsters = [
        monster
        for monster in monsters
        if any(matches_requirement(monster, requirement) for requirement in forbidden)
    ]
    if observed_forbidden_monsters:
        status = "required_state_missing"
    elif required and not missing_required_monsters:
        status = "required_state_present"
    elif required:
        status = "required_state_missing"
    elif forbidden:
        status = "required_state_present"
    else:
        status = "scanned"

    return {
        "world": world_dir.name,
        "world_dir": str(world_dir),
        "player_save": selected_player_save,
        "player_location_ms": player_location,
        "save_turn": save_turn,
        "required_monsters": required,
        "forbidden_monsters": forbidden,
        "observed_monster_typeids": sorted(counts),
        "active_monster_counts": dict(sorted(counts.items())),
        "active_monsters": monsters,
        "missing_required_monsters": missing_required_monsters,
        "observed_forbidden_monsters": observed_forbidden_monsters,
        "status": status,
    }


def deterministic_free_monster_tile(
    audit: Mapping[str, Any],
    candidate_offsets: Sequence[Sequence[int]],
) -> Dict[str, Any]:
    """Choose the first declared free save tile without waiting for the world.

    The caller supplies the ordered candidate tiles as part of its deterministic
    setup contract.  This owner only confirms that each candidate differs from
    the player and every saved active monster before choosing it.
    """
    player_location = audit.get("player_location_ms")
    monsters = audit.get("active_monsters")
    if not isinstance(player_location, list) or len(player_location) != 3 or not isinstance(monsters, list):
        raise RuntimeError("saved monster audit is incomplete")
    player = tuple(int(value) for value in player_location)
    occupied = {player}
    for monster in monsters:
        location = monster.get("location_ms") if isinstance(monster, Mapping) else None
        if isinstance(location, list) and len(location) == 3:
            occupied.add(tuple(int(value) for value in location))
    for raw_offset in candidate_offsets:
        if not isinstance(raw_offset, Sequence) or isinstance(raw_offset, (str, bytes)) or len(raw_offset) != 3:
            raise RuntimeError("deterministic monster target must contain exactly three integer offsets")
        if any(isinstance(value, bool) or not isinstance(value, int) for value in raw_offset):
            raise RuntimeError("deterministic monster target offsets must be integers")
        offset = [int(value) for value in raw_offset]
        target = tuple(player[index] + offset[index] for index in range(3))
        if target not in occupied:
            return {
                "offset_ms": offset,
                "location_ms": list(target),
                "occupied_locations_ms": [list(location) for location in sorted(occupied)],
            }
    return {"offset_ms": None, "location_ms": None, "occupied_locations_ms": [list(location) for location in sorted(occupied)]}


def prepare_required_monster(
    world_dir: Path,
    *,
    typeid: str,
    candidate_offsets: Sequence[Sequence[int]],
    player_save: str = "",
) -> Dict[str, Any]:
    """Confirm or explicitly manufacture one setup-only monster in one save."""
    requested_typeid = str(typeid).strip()
    if not requested_typeid:
        raise RuntimeError("required monster typeid is missing")
    before = audit_saved_active_monsters(world_dir, player_save=player_save)
    existing = next(
        (
            item for item in before["active_monsters"]
            if item.get("typeid") == requested_typeid and item.get("dead") is not True
        ),
        None,
    )
    if existing is not None:
        return {
            "status": "prepared_existing",
            "operation": "confirm_existing_monster",
            "target": {"typeid": requested_typeid, "location_ms": existing.get("location_ms", [])},
            "native_receipt": {
                "owner": "loaded_save_audit",
                "accepted": True,
                "operation": "confirm_existing_monster",
            },
            "before_facts": before,
            "after_facts": before,
            "evidence_effect": "none_for_manufactured_state",
            "gameplay_credit": False,
        }
    target = deterministic_free_monster_tile(before, candidate_offsets)
    if target["offset_ms"] is None:
        return {
            "status": "unprepared_no_free_declared_tile",
            "operation": "spawn_monster",
            "target": {"typeid": requested_typeid, "location_ms": None},
            "native_receipt": {
                "owner": "fixture_save_transform",
                "accepted": False,
                "reason": "no_free_declared_tile",
            },
            "before_facts": before,
            "after_facts": before,
            "evidence_effect": "none_for_manufactured_state",
            "gameplay_credit": False,
        }
    transform = {
        "kind": "active_monsters_near_player",
        "player_save": before["player_save"],
        "clear_existing": False,
        "monsters": [{"typeid": requested_typeid, "offset_ms": target["offset_ms"]}],
    }
    receipt = apply_active_monsters_near_player_transform(world_dir, transform)
    after = audit_saved_active_monsters(
        world_dir,
        player_save=before["player_save"],
        required_monsters=[{"typeid": requested_typeid, "offset_ms": target["offset_ms"]}],
    )
    accepted = after["status"] == "required_state_present"
    return {
        "status": "prepared_spawned" if accepted else "unprepared_spawn_unconfirmed",
        "operation": "spawn_monster",
        "target": {"typeid": requested_typeid, **target},
        "native_receipt": {
            "owner": "fixture_save_transform",
            "accepted": accepted,
            "operation": "active_monsters_near_player",
            "receipt": receipt,
        },
        "before_facts": before,
        "after_facts": after,
        "evidence_effect": "none_for_manufactured_state",
        "gameplay_credit": False,
    }


def scenario_setup_receipts_from_installed_save(
    world_dir: Path,
    *,
    setup_contract: Mapping[str, Any],
    fixture_install: Mapping[str, Any],
) -> Dict[str, Any]:
    """Bind declared setup facts to the installed save before feature work."""
    required = setup_contract.get("required_monster")
    incidental = str(setup_contract.get("incidental_absent_typeid", "")).strip()
    if not isinstance(required, Mapping):
        raise RuntimeError("scenario setup contract requires one required_monster")
    typeid = str(required.get("typeid", "")).strip()
    offset = required.get("offset_ms")
    if not typeid or not isinstance(offset, list) or len(offset) != 3:
        raise RuntimeError("scenario setup contract required_monster is malformed")
    required_audit = {"typeid": typeid, "offset_ms": offset}
    if required.get("last_updated_at_save_turn") is True:
        required_audit["last_updated_at_save_turn"] = True
    audit = audit_saved_active_monsters(
        world_dir,
        required_monsters=[required_audit],
        forbidden_typeids=[incidental] if incidental else [],
    )
    transforms = fixture_install.get("applied_save_transforms", [])
    transform_receipt = next(
        (
            item for item in reversed(transforms)
            if isinstance(item, Mapping)
            and item.get("kind") == "active_monsters_near_player"
            and any(
                isinstance(monster, Mapping) and monster.get("typeid") == typeid
                and monster.get("offset_ms") == offset
                for monster in item.get("placed_monsters", [])
            )
        ),
        None,
    )
    accepted = (
        audit.get("status") == "required_state_present"
        and transform_receipt is not None
        and all(item.get("free") is True for item in transform_receipt.get("target_free_checks", []))
    )
    intervention = {
        "operation": "fixture_install_and_monster_setup",
        "arguments": {"required_typeid": typeid, "required_offset_ms": list(offset)},
        "target": {"typeid": typeid, "offset_ms": list(offset)},
        "native_receipt": {
            "owner": "fixture_save_transform",
            "accepted": accepted,
            "fixture": str(fixture_install.get("fixture", "")),
            "transform": dict(transform_receipt) if isinstance(transform_receipt, Mapping) else {},
        },
        "before_facts": {
            "target_free_checks": (
                list(transform_receipt.get("target_free_checks", []))
                if isinstance(transform_receipt, Mapping) else []
            ),
        },
        "after_facts": {
            "required_monster_status": audit.get("status"),
            "missing_required_monsters": audit.get("missing_required_monsters", []),
            "observed_forbidden_monsters": audit.get("observed_forbidden_monsters", []),
        },
        "evidence_effect": "none_for_manufactured_state",
        "gameplay_credit": False,
    }
    return {
        "status": "prepared" if accepted else "unprepared",
        "interventions": [intervention],
        "incidental_absent_typeid": incidental,
        "evidence_effect": "none_for_manufactured_state",
        "gameplay_credit": False,
    }


def r008_source_bound_setup_receipts_from_installed_save(
    world_dir: Path,
    *,
    setup_contract: Mapping[str, Any],
    fixture_install: Mapping[str, Any],
) -> Dict[str, Any]:
    """Bind the R-008 fixture-only stabilizer transform to its declared source world."""
    expected_world = str(setup_contract.get("world", "")).strip()
    expected_player_save = str(setup_contract.get("player_save", "")).strip()
    expected_traits = setup_contract.get("stabilizer_traits")
    expected_source = setup_contract.get("source_binding")
    expected_player_abs_omt = setup_contract.get("required_player_abs_omt")
    if not expected_world or not expected_player_save or not isinstance(expected_traits, list) or not expected_traits:
        raise RuntimeError("R-008 setup receipt contract is malformed")
    if not isinstance(expected_source, Mapping):
        raise RuntimeError("R-008 setup receipt source binding is malformed")
    if expected_player_abs_omt is not None and (
            not isinstance(expected_player_abs_omt, list) or len(expected_player_abs_omt) != 3):
        raise RuntimeError("R-008 setup receipt required player OMT is malformed")
    if world_dir.name != expected_world:
        raise RuntimeError("R-008 installed world does not match setup receipt contract")
    selected_save, _save_path, payload, _stat = load_saved_player_payload(world_dir, expected_player_save)
    player = payload.get("player")
    traits = player.get("traits") if isinstance(player, Mapping) else None
    if not isinstance(traits, list):
        raise RuntimeError("R-008 installed player traits are unavailable")
    location = player.get("location") if isinstance(player, Mapping) else None
    player_abs_omt = (
        [int(location[0]) // 24, int(location[1]) // 24, int(location[2])]
        if isinstance(location, list) and len(location) >= 3 else []
    )
    master_path = world_dir / "master.gsav"
    if not master_path.is_file():
        raise RuntimeError("R-008 installed source master.gsav is unavailable")
    master_sha256, _master_error = sha256_file(master_path)
    transforms = fixture_install.get("applied_save_transforms", [])
    transform = next((
        item for item in reversed(transforms) if isinstance(item, Mapping)
        and item.get("kind") == "player_mutations"
        and item.get("player_save") == expected_player_save
    ), None)
    position_transform = next((
        item for item in reversed(transforms) if isinstance(item, Mapping)
        and item.get("kind") == "player_near_overmap_special"
        and item.get("player_save") == expected_player_save
    ), None)
    installed_manifest = fixture_install.get("manifest", {})
    installed_source = installed_manifest.get("source_binding", {}) if isinstance(installed_manifest, Mapping) else {}
    exact_traits = all(str(value) in traits for value in expected_traits)
    exact_transform = isinstance(transform, Mapping) and transform.get("mutations") == list(expected_traits)
    position_required = expected_player_abs_omt is not None
    exact_position = (
        not position_required or (
            player_abs_omt == [int(value) for value in expected_player_abs_omt]
            and isinstance(position_transform, Mapping)
            and position_transform.get("target_omt") == player_abs_omt
        )
    )
    exact_source = dict(installed_source) == dict(expected_source)
    source_hash_matches = master_sha256 == str(expected_source.get("world_master_gsav_sha256", ""))
    accepted = exact_traits and exact_transform and exact_position and exact_source and source_hash_matches
    intervention = {
        "operation": "fixture_install_and_r008_source_bound_stabilizer_setup",
        "arguments": {
            "world": expected_world,
            "player_save": expected_player_save,
            "stabilizer_traits": list(expected_traits),
            **({"required_player_abs_omt": [int(value) for value in expected_player_abs_omt]}
               if position_required else {}),
        },
        "target": {"world": expected_world, "player_save": selected_save},
        "native_receipt": {
            "owner": "fixture_save_transform",
            "accepted": accepted,
            "fixture": str(fixture_install.get("fixture", "")),
            "transform": dict(transform) if isinstance(transform, Mapping) else {},
            "position_transform": dict(position_transform) if isinstance(position_transform, Mapping) else {},
        },
        "before_facts": {"source_binding": dict(installed_source)},
        "after_facts": {
            "source_binding": dict(expected_source),
            "master_gsav_sha256": master_sha256,
            "player_traits": list(traits),
            "player_abs_omt": player_abs_omt,
        },
        "evidence_effect": "none_for_manufactured_state",
        "gameplay_credit": False,
    }
    return {
        "status": "prepared" if accepted else "unprepared",
        "contract_kind": "r008_source_bound_fixture",
        "interventions": [intervention],
        "evidence_effect": "none_for_manufactured_state",
        "gameplay_credit": False,
    }


def r008_withdrawal_free_player_fixture_receipt(
    world_dir: Path,
    *,
    setup_contract: Mapping[str, Any],
    fixture_install: Mapping[str, Any],
) -> Dict[str, Any]:
    """Bind the one-off R-008 withdrawal repair as disposable setup only."""
    world = str(setup_contract.get("world", "") or "").strip()
    player_save = str(setup_contract.get("player_save", "") or "").strip()
    cause = setup_contract.get("withdrawal_cause")
    cleanup_owner = str(setup_contract.get("cleanup_owner", "") or "").strip()
    if world_dir.name != world or not player_save or not isinstance(cause, Mapping) or \
            cleanup_owner != "cleanup_harness_world":
        raise RuntimeError("R-008 withdrawal-free fixture contract is malformed")
    expected = {
        "type": str(cause.get("type", "") or "").strip(),
        "intensity": int(cause.get("intensity", -1)),
        "sated": int(cause.get("sated", -1)),
    }
    _selected, _path, payload, _stat = load_saved_player_payload(world_dir, player_save)
    player = payload.get("player") if isinstance(payload, Mapping) else None
    applied = fixture_install.get("applied_save_transforms", [])
    transform = next((
        item for item in reversed(applied) if isinstance(item, Mapping)
        and item.get("kind") == "player_remove_addiction"
        and item.get("player_save") == player_save
    ), None)
    accepted = (
        isinstance(player, Mapping)
        and player.get("addictions") == []
        and isinstance(transform, Mapping)
        and transform.get("declared_addiction") == expected
        and transform.get("before_addictions") == [expected]
        and transform.get("after_addictions") == []
        and transform.get("removed_addiction") == expected
        and transform.get("declared_mutation_only") is True
        and transform.get("cleanup_owner") == cleanup_owner
        and transform.get("gameplay_credit") is False
    )
    intervention = {
        "operation": "fixture_install_and_r008_withdrawal_cause_removal",
        "arguments": {"world": world, "player_save": player_save, "withdrawal_cause": expected},
        "target": {"world": world, "player_save": player_save},
        "native_receipt": {
            "owner": "fixture_save_transform", "accepted": accepted,
            "transform": dict(transform) if isinstance(transform, Mapping) else {},
        },
        "before_facts": {
            "source_binding": fixture_install.get("binding", {}),
            "player_addictions": transform.get("before_addictions", []) if isinstance(transform, Mapping) else [],
        },
        "after_facts": {
            "source_binding": fixture_install.get("binding", {}),
            "player_addictions": player.get("addictions", []) if isinstance(player, Mapping) else None,
            "cleanup_owner": cleanup_owner,
        },
        "evidence_effect": "none_for_disposable_player_fixture",
        "gameplay_credit": False,
    }
    return {
        "status": "prepared" if accepted else "unprepared",
        "contract_kind": "r008_withdrawal_free_player_fixture",
        "interventions": [intervention],
        "evidence_effect": "none_for_disposable_player_fixture",
        "gameplay_credit": False,
    }


def saved_overmap_terrain_id(world_dir: Path, abs_omt: Sequence[int]) -> str:
    """Read one saved overmap terrain without changing the installed world."""
    if not isinstance(abs_omt, (list, tuple)) or len(abs_omt) != 3 or any(
            isinstance(value, bool) or not isinstance(value, int) for value in abs_omt):
        raise RuntimeError("saved overmap terrain coordinate is malformed")
    point = (int(abs_omt[0]), int(abs_omt[1]), int(abs_omt[2]))
    overmap_x, overmap_y, local_omt = overmap_file_coords_from_abs_omt(point)
    overmap_path = world_dir / "overmaps" / f"o.{overmap_x}.{overmap_y}.zzip"
    if not overmap_path.exists():
        raise RuntimeError(f"saved overmap terrain payload is unavailable: {overmap_path}")
    plain_path, _version_line, payload = extract_overmap_payload(overmap_path)
    try:
        layers = payload.get("layers")
        layer_index = overmap_layer_index(point[2])
        if not isinstance(layers, list) or layer_index >= len(layers):
            raise RuntimeError(f"saved overmap terrain layer is unavailable: {point}")
        layer = decode_overmap_layer(layers[layer_index], context=str(overmap_path))
        return str(layer[overmap_flat_index(local_omt)])
    finally:
        cleanup_extracted_overmap(plain_path, keep=False)


def r005_source_bound_visibility_setup_receipts_from_installed_save(
    world_dir: Path,
    *,
    setup_contract: Mapping[str, Any],
    fixture_install: Mapping[str, Any],
) -> Dict[str, Any]:
    """Prove the disposable R-005 geography bootstrap, never gameplay."""
    expected_world = str(setup_contract.get("world", "")).strip()
    player_save = str(setup_contract.get("player_save", "")).strip()
    camp_site_id = str(setup_contract.get("camp_site_id", "")).strip()
    lead_id = str(setup_contract.get("lead_id", "")).strip()
    target_omt = setup_contract.get("target_omt")
    target_terrain_id = str(setup_contract.get("target_terrain_id", "")).strip()
    candidate_omt = setup_contract.get("candidate_omt")
    player_source_omt = setup_contract.get("player_source_omt")
    player_observation_omt = setup_contract.get("player_observation_omt")
    player_offset_ms = setup_contract.get("player_offset_ms")
    candidate_terrain_id = str(setup_contract.get("candidate_terrain_id", "")).strip()
    candidate_see_cost = setup_contract.get("candidate_see_cost")
    intervening_omts = setup_contract.get("intervening_omts")
    intervening_terrain_ids = setup_contract.get("intervening_terrain_ids")
    intervening_see_costs = setup_contract.get("intervening_see_costs")
    sight_points = setup_contract.get("clear_day_sight_points")
    evidence_ceiling = str(setup_contract.get("evidence_ceiling", "")).strip()
    if not expected_world or not player_save or not camp_site_id or not lead_id or \
            not isinstance(target_omt, list) or len(target_omt) != 3 or \
            not isinstance(candidate_omt, list) or len(candidate_omt) != 3 or \
            not isinstance(player_source_omt, list) or len(player_source_omt) != 3 or \
            not isinstance(player_observation_omt, list) or len(player_observation_omt) != 3 or \
            not isinstance(player_offset_ms, list) or len(player_offset_ms) != 3 or \
            any(isinstance(value, bool) or not isinstance(value, int)
                for value in player_source_omt + player_observation_omt + player_offset_ms) or \
            not target_terrain_id or not candidate_terrain_id or \
            not isinstance(candidate_see_cost, int) or \
            candidate_see_cost <= 0 or not isinstance(intervening_omts, list) or \
            not isinstance(intervening_terrain_ids, list) or \
            len(intervening_omts) != len(intervening_terrain_ids) or \
            not isinstance(intervening_see_costs, list) or \
            len(intervening_see_costs) != len(intervening_omts) or \
            any(isinstance(cost, bool) or not isinstance(cost, int) or cost < 0
                for cost in intervening_see_costs) or \
            not isinstance(sight_points, int) or sight_points < 0 or \
            evidence_ceiling != "zero-credit":
        raise RuntimeError("R-005 visibility setup contract is malformed")
    if world_dir.name != expected_world:
        raise RuntimeError("R-005 visibility setup world identity drifted")

    expected_fixture = "bandit_r005_native_wait_visibility_bootstrap_v0"
    expected_source_fixture = "bandit_r005_natural_hostile_ecology_v0"
    expected_camp_site_id = "overmap_special:bandit_camp@140,51,0"
    expected_lead_id = expected_camp_site_id + "#lead:structural_bounty:forest@138,52,0"
    expected_target_omt = [138, 52, 0]
    expected_candidate_omt = [141, 49, 0]
    expected_player_source_omt = [140, 41, 0]
    expected_player_observation_omt = [141, 49, 0]
    expected_player_offset_ms = [24, 192, 0]
    expected_intervening_omts = [[140, 50, 0], [139, 51, 0]]
    expected_intervening_terrain_ids = ["field", "field"]
    expected_intervening_see_costs = [0, 0]
    expected_candidate_terrain_id = "communitygarden_east"
    expected_candidate_see_cost = 1
    expected_sight_points = 3
    fixture_name = str(fixture_install.get("fixture", "")).strip()
    manifest = fixture_install.get("manifest", {})
    declared_geometry = manifest.get("source_bound_geography") if isinstance(manifest, Mapping) else None
    transform = next((item for item in reversed(fixture_install.get("applied_save_transforms", []))
                      if isinstance(item, Mapping) and item.get("kind") == "overmap_terrain_id_at_abs_omt"
                      and item.get("abs_omt") == candidate_omt and item.get("terrain_id") == candidate_terrain_id), None)
    player_transform = next((item for item in reversed(fixture_install.get("applied_save_transforms", []))
                             if isinstance(item, Mapping) and item.get("kind") == "player_location_offset_ms"
                             and item.get("player_save") == player_save), None)
    _selected_save, _player_save_path, player_payload, _player_stat = load_saved_player_payload(
        world_dir, player_save
    )
    player = player_payload.get("player")
    player_location = player.get("location") if isinstance(player, Mapping) else None
    observed_player_omt = (
        [int(player_location[0]) // 24, int(player_location[1]) // 24, int(player_location[2])]
        if isinstance(player_location, list) and len(player_location) >= 3 else []
    )
    observed: Dict[str, Any] = {
        "target_terrain_id": saved_overmap_terrain_id(world_dir, target_omt),
        "candidate_terrain_id": saved_overmap_terrain_id(world_dir, candidate_omt),
        "intervening_terrain_ids": [saved_overmap_terrain_id(world_dir, point) for point in intervening_omts],
    }
    observed["sight_costs"] = [int(candidate_see_cost)] + [int(cost) for cost in intervening_see_costs]
    observed["sight_cost_total"] = sum(observed["sight_costs"])
    observed["line_of_sight_within_budget"] = observed["sight_cost_total"] <= sight_points
    declared_match = isinstance(declared_geometry, Mapping) and all(
        declared_geometry.get(key) == setup_contract.get(key)
        for key in ("world", "player_save", "camp_site_id", "lead_id", "target_omt",
                    "candidate_omt", "player_source_omt", "player_observation_omt",
                    "player_offset_ms", "candidate_terrain_id", "candidate_see_cost",
                    "intervening_omts", "intervening_terrain_ids", "clear_day_sight_points",
                    "intervening_see_costs", "evidence_ceiling")
    )
    fixed_geometry_match = (
        fixture_name == expected_fixture
        and str(manifest.get("name", "")).strip() == expected_fixture
        and str(manifest.get("source_fixture", "")).strip() == expected_source_fixture
        and expected_world == "McWilliams"
        and player_save == "#Wm9yYWlkYSBWaWNr.sav.zzip"
        and camp_site_id == expected_camp_site_id
        and lead_id == expected_lead_id
        and target_omt == expected_target_omt
        and target_terrain_id == "forest"
        and candidate_omt == expected_candidate_omt
        and player_source_omt == expected_player_source_omt
        and player_observation_omt == expected_player_observation_omt
        and player_offset_ms == expected_player_offset_ms
        and candidate_terrain_id == expected_candidate_terrain_id
        and candidate_see_cost == expected_candidate_see_cost
        and intervening_omts == expected_intervening_omts
        and intervening_terrain_ids == expected_intervening_terrain_ids
        and intervening_see_costs == expected_intervening_see_costs
        and sight_points == expected_sight_points
    )
    geometry_match = (
        observed["target_terrain_id"] == target_terrain_id
        and observed["candidate_terrain_id"] == candidate_terrain_id
        and observed["intervening_terrain_ids"] == intervening_terrain_ids
        and observed["line_of_sight_within_budget"]
    )
    player_position_match = (
        observed_player_omt == player_observation_omt and
        isinstance(player_transform, Mapping) and
        player_transform.get("offset_ms") == player_offset_ms and
        isinstance(player_transform.get("previous_location"), list) and
        len(player_transform["previous_location"]) >= 3 and
        [int(player_transform["previous_location"][0]) // 24,
         int(player_transform["previous_location"][1]) // 24,
         int(player_transform["previous_location"][2])] == player_source_omt and
        player_transform.get("target_location") == player_location
    )
    source_fixture = fixture_name
    source_match = source_fixture == str(setup_contract.get("fixture", source_fixture)).strip()
    identity_audit: Dict[str, Any] = {"status": "not_run"}
    if transform and player_position_match and declared_match and fixed_geometry_match and geometry_match and source_match:
        identity_audit = audit_saved_bandit_live_world_state(
            world_dir,
            required_site_id_contains=expected_camp_site_id,
            required_member_count=14,
            required_ready_at_home_count=14,
            required_wounded_or_unready_count=0,
            required_active_outside_count=0,
            required_active_group_id_exact="",
            required_active_target_id_exact="",
            required_min_leads=1,
            required_lead_kind="structural_bounty",
            required_lead_target_id="forest",
            required_lead_source_contains="fixture_r005_natural_hostile_ecology_forest",
            required_lead_status="scout_confirmed",
            required_lead_bounty=8,
            required_lead_threat=0,
            required_lead_times_harvested=0,
            required_lead_confidence=3,
        )
    accepted = bool(transform and player_position_match and declared_match and fixed_geometry_match and geometry_match
                    and source_match and identity_audit.get("status") == "required_state_present")
    intervention = {
        "operation": "fixture_install_and_r005_visibility_geography_bootstrap",
        "arguments": {key: setup_contract.get(key) for key in (
            "world", "player_save", "camp_site_id", "lead_id", "target_omt", "candidate_omt",
            "player_source_omt", "player_observation_omt", "player_offset_ms",
            "candidate_terrain_id", "candidate_see_cost", "intervening_omts",
            "intervening_terrain_ids", "intervening_see_costs", "clear_day_sight_points",
            "evidence_ceiling")},
        "target": {"world": expected_world, "player_save": player_save, "camp_site_id": camp_site_id,
                   "lead_id": lead_id, "target_omt": list(target_omt),
                   "candidate_omt": list(candidate_omt),
                   "player_observation_omt": list(player_observation_omt)},
        "native_receipt": {"owner": "fixture_save_transform", "accepted": accepted,
                           "fixture": source_fixture,
                           "terrain_transform": dict(transform) if transform else {},
                           "player_transform": dict(player_transform) if player_transform else {}},
        "before_facts": {"source_bound_geography": dict(declared_geometry) if isinstance(declared_geometry, Mapping) else {},
                         "target_terrain_id": observed["target_terrain_id"]},
        "after_facts": {**observed, "player_abs_omt": observed_player_omt,
                        "player_position_match": player_position_match,
                        "camp_lead_identity_audit": identity_audit},
        "evidence_effect": "none_for_manufactured_state",
        "gameplay_credit": False,
    }
    return {"status": "prepared" if accepted else "unprepared",
            "contract_kind": "r005_source_bound_visibility_fixture",
            "interventions": [intervention],
            "evidence_effect": "none_for_manufactured_state", "gameplay_credit": False}


def load_saved_player_payload(world_dir: Path, player_save: str = "") -> Tuple[str, Path, Dict[str, Any], os.stat_result]:
    selected_player_save = player_save.strip()
    if not selected_player_save:
        saves = sorted(path.name for path in world_dir.glob("*.sav.zzip"))
        if len(saves) != 1:
            raise RuntimeError(f"Expected one *.sav.zzip in {world_dir}, found {saves}")
        selected_player_save = saves[0]

    player_save_path = world_dir / selected_player_save
    if not player_save_path.exists():
        raise FileNotFoundError(f"Player save not found: {player_save_path}")
    if player_save_path.suffix != ".zzip":
        raise RuntimeError(f"Player payload audit expects .zzip save path: {player_save_path}")

    stat = player_save_path.stat()
    extracted_save = player_save_path.with_suffix("")
    run_zzip(player_save_path)
    if not extracted_save.exists():
        raise RuntimeError(f"Player payload audit did not extract save: {extracted_save}")
    try:
        payload = json.loads(extracted_save.read_text(encoding="utf-8"))
    finally:
        if extracted_save.exists():
            extracted_save.unlink()
    if not isinstance(payload, dict):
        raise RuntimeError(f"Extracted player save is not a JSON object: {extracted_save}")
    return selected_player_save, player_save_path, payload, stat


def audit_saved_game_turn(
    world_dir: Path,
    *,
    player_save: str = "",
    record_baseline: bool = False,
    baseline_metadata: Optional[Dict[str, Any]] = None,
    required_min_delta_turns: Optional[int] = None,
    required_time_of_day_seconds: Optional[int] = None,
    required_time_tolerance_seconds: int = 0,
    required_player_abs_omt: Optional[List[int]] = None,
) -> Dict[str, Any]:
    """Read-only saved-player turn audit for proving real local turn advancement."""
    if not world_dir.exists():
        raise FileNotFoundError(f"World dir not found: {world_dir}")

    selected_player_save, player_save_path, payload, stat = load_saved_player_payload(world_dir, player_save)
    turn = int(payload.get("turn", 0) or 0)
    time_of_day_seconds = turn % ( 24 * 60 * 60 )
    time_of_day_text = f"{time_of_day_seconds // 3600:02d}:{( time_of_day_seconds % 3600 ) // 60:02d}:{time_of_day_seconds % 60:02d}"
    player = payload.get("player")
    if not isinstance(player, dict):
        raise RuntimeError(f"Extracted player save is missing player object: {player_save_path}")
    location_raw = player.get("location", [])
    player_location: List[int] = []
    player_abs_omt: List[int] = []
    if isinstance(location_raw, list) and len(location_raw) >= 3:
        player_location = [int(location_raw[0]), int(location_raw[1]), int(location_raw[2])]
        player_abs_omt = [player_location[0] // 24, player_location[1] // 24, player_location[2]]

    normalized_required_player_abs_omt: Optional[List[int]] = None
    if required_player_abs_omt is not None:
        if not isinstance(required_player_abs_omt, list) or len(required_player_abs_omt) != 3:
            raise RuntimeError("required_player_abs_omt must be a three-element list")
        normalized_required_player_abs_omt = [int(value) for value in required_player_abs_omt]
    missing_required_player_abs_omt = (
        normalized_required_player_abs_omt is not None and
        player_abs_omt != normalized_required_player_abs_omt
    )

    baseline_turn: Optional[int] = None
    observed_delta_turns: Optional[int] = None
    missing_required_min_delta_turns = False
    normalized_required_time_of_day: Optional[int] = None
    observed_time_of_day_delta_seconds: Optional[int] = None
    missing_required_time_of_day = False
    if baseline_metadata is not None:
        baseline_turn = int(baseline_metadata.get("turn", 0) or 0)
        observed_delta_turns = turn - baseline_turn
        if required_min_delta_turns is not None:
            missing_required_min_delta_turns = observed_delta_turns < int(required_min_delta_turns)

    if required_time_of_day_seconds is not None:
        normalized_required_time_of_day = int(required_time_of_day_seconds) % ( 24 * 60 * 60 )
        forward_delta = ( time_of_day_seconds - normalized_required_time_of_day ) % ( 24 * 60 * 60 )
        backward_delta = ( normalized_required_time_of_day - time_of_day_seconds ) % ( 24 * 60 * 60 )
        observed_time_of_day_delta_seconds = min(forward_delta, backward_delta)
        missing_required_time_of_day = observed_time_of_day_delta_seconds > max(0, int(required_time_tolerance_seconds))

    if record_baseline:
        status = "baseline_recorded"
    elif baseline_metadata is not None and required_min_delta_turns is not None and not missing_required_min_delta_turns:
        status = "required_state_present"
    elif baseline_metadata is not None and required_min_delta_turns is not None:
        status = "required_state_missing"
    elif normalized_required_player_abs_omt is not None and not missing_required_player_abs_omt:
        status = "required_state_present"
    elif normalized_required_player_abs_omt is not None:
        status = "required_state_missing"
    elif required_time_of_day_seconds is not None and not missing_required_time_of_day:
        status = "required_state_present"
    elif required_time_of_day_seconds is not None:
        status = "required_state_missing"
    else:
        status = "scanned"

    return {
        "world": world_dir.name,
        "world_dir": str(world_dir),
        "player_save": selected_player_save,
        "player_save_path": str(player_save_path),
        "player_save_mtime_ns": int(stat.st_mtime_ns),
        "player_save_mtime_iso": datetime.fromtimestamp(float(stat.st_mtime)).isoformat(timespec="microseconds"),
        "turn": turn,
        "time_of_day_seconds": time_of_day_seconds,
        "time_of_day_text": time_of_day_text,
        "required_time_of_day_seconds": normalized_required_time_of_day,
        "required_time_tolerance_seconds": int(required_time_tolerance_seconds),
        "observed_time_of_day_delta_seconds": observed_time_of_day_delta_seconds,
        "missing_required_time_of_day": missing_required_time_of_day,
        "baseline_turn": baseline_turn,
        "observed_delta_turns": observed_delta_turns,
        "required_min_delta_turns": required_min_delta_turns,
        "missing_required_min_delta_turns": missing_required_min_delta_turns,
        "required_player_abs_omt": normalized_required_player_abs_omt,
        "missing_required_player_abs_omt": missing_required_player_abs_omt,
        "player_location_ms": player_location,
        "player_abs_omt": player_abs_omt,
        "status": status,
    }


def audit_saved_overmap_npcs(
    world_dir: Path,
    *,
    player_save: str = "",
    required_npcs: Optional[List[Dict[str, Any]]] = None,
    scan_all_overmaps: bool = False,
    record_baseline: bool = False,
    baseline_metadata: Optional[Dict[str, Any]] = None,
    required_observed_npc_count_delta: Optional[int] = None,
    required_observed_npc_count: Optional[int] = None,
    required_new_npcs: Optional[List[Dict[str, Any]]] = None,
) -> Dict[str, Any]:
    """Read-only saved-overmap audit for NPC/follower target state.

    Debug-spawned follower NPCs are persisted in overmap ``npcs`` records,
    not in the player save's ``unique_npcs`` bucket. Keep this audit as a
    same-save metadata gate after a proven save/writeback so a debug NPC
    primitive cannot be credited from menu navigation alone.
    """
    if not world_dir.exists():
        raise FileNotFoundError(f"World dir not found: {world_dir}")
    selected_player_save = player_save.strip()
    if not selected_player_save:
        saves = sorted(path.name for path in world_dir.glob("*.sav.zzip"))
        if len(saves) != 1:
            raise RuntimeError(f"Expected one *.sav.zzip in {world_dir}, found {saves}")
        selected_player_save = saves[0]

    player_abs_omt, player_location = load_player_abs_omt(world_dir, selected_player_save)
    overmaps_dir = world_dir / "overmaps"
    if not overmaps_dir.exists():
        raise FileNotFoundError(f"Overmaps dir not found: {overmaps_dir}")

    if scan_all_overmaps:
        overmap_paths = sorted(overmaps_dir.glob("o.*.*.zzip"))
    else:
        player_overmap_x = int(player_abs_omt[0]) // OMAPX
        player_overmap_y = int(player_abs_omt[1]) // OMAPY
        candidate = overmaps_dir / f"o.{player_overmap_x}.{player_overmap_y}.zzip"
        overmap_paths = [candidate] if candidate.exists() else []
    if not overmap_paths:
        raise RuntimeError(f"No overmap .zzip files selected for NPC audit in {overmaps_dir}")

    npcs: List[Dict[str, Any]] = []
    scanned_overmaps: List[str] = []
    for overmap_path in overmap_paths:
        plain_path: Optional[Path] = None
        created_plain = False
        try:
            plain_path, _version_line, payload = extract_overmap_payload(overmap_path)
            created_plain = bool(payload.get("_created_plain"))
            scanned_overmaps.append(str(overmap_path.relative_to(world_dir)))
            raw_npcs = payload.get("npcs", [])
            if not isinstance(raw_npcs, list):
                raise RuntimeError(f"Overmap has non-list npcs array: {overmap_path}")
            for index, npc_payload in enumerate(raw_npcs):
                if not isinstance(npc_payload, dict):
                    continue
                location_raw = npc_payload.get("location", [])
                location: List[int] = []
                offset: List[int] = []
                if isinstance(location_raw, list) and len(location_raw) >= 3:
                    location = [int(location_raw[0]), int(location_raw[1]), int(location_raw[2])]
                    offset = [
                        location[0] - player_location[0],
                        location[1] - player_location[1],
                        location[2] - player_location[2],
                    ]
                npcs.append({
                    "overmap": str(overmap_path.relative_to(world_dir)),
                    "index": index,
                    "id": npc_payload.get("id"),
                    "name": str(npc_payload.get("name", "") or ""),
                    "location_ms": location,
                    "offset_ms": offset,
                    "attitude": npc_payload.get("attitude"),
                    "mission": npc_payload.get("mission"),
                    "my_fac": npc_payload.get("my_fac"),
                    "previous_attitude": npc_payload.get("previous_attitude"),
                    "comp_mission_id": npc_payload.get("comp_mission_id"),
                    "rules": npc_payload.get("rules") if isinstance(npc_payload.get("rules"), dict) else {},
                    "op_of_u": npc_payload.get("op_of_u") if isinstance(npc_payload.get("op_of_u"), dict) else {},
                    "chatbin_missions": (
                        npc_payload.get("chatbin", {}).get("missions", [])
                        if isinstance(npc_payload.get("chatbin"), dict)
                        else []
                    ),
                })
        finally:
            if plain_path is not None and created_plain:
                cleanup_extracted_overmap(plain_path, keep=False)

    def normalize_requirement(raw: Dict[str, Any]) -> Dict[str, Any]:
        requirement: Dict[str, Any] = {}
        for key in ("name", "name_contains", "my_fac"):
            value = str(raw.get(key, "") or "").strip()
            if value:
                requirement[key] = value
        for key in ("attitude", "mission"):
            if raw.get(key) is not None and str(raw.get(key)).strip() != "":
                requirement[key] = int(raw.get(key))
        rules_raw = raw.get("rules", raw.get("required_rules", {}))
        if isinstance(rules_raw, dict):
            rules: Dict[str, Any] = {}
            for rule_key, expected in rules_raw.items():
                rule_name = str(rule_key or "").strip()
                if not rule_name:
                    continue
                if isinstance(expected, bool):
                    rules[rule_name] = expected
                elif isinstance(expected, (int, float)):
                    rules[rule_name] = expected
                elif expected is not None:
                    text = str(expected).strip().lower()
                    if text in {"true", "yes", "1", "on"}:
                        rules[rule_name] = True
                    elif text in {"false", "no", "0", "off"}:
                        rules[rule_name] = False
                    else:
                        rules[rule_name] = str(expected)
            if rules:
                requirement["rules"] = rules
        offset_raw = raw.get("offset_ms")
        if isinstance(offset_raw, list) and len(offset_raw) >= 3:
            requirement["offset_ms"] = [int(offset_raw[0]), int(offset_raw[1]), int(offset_raw[2])]
        max_abs_offset_raw = raw.get("max_abs_offset_ms")
        if isinstance(max_abs_offset_raw, list) and len(max_abs_offset_raw) >= 3:
            requirement["max_abs_offset_ms"] = [
                int(max_abs_offset_raw[0]),
                int(max_abs_offset_raw[1]),
                int(max_abs_offset_raw[2]),
            ]
        return requirement

    required: List[Dict[str, Any]] = []
    for raw in required_npcs or []:
        if not isinstance(raw, dict):
            continue
        requirement = normalize_requirement(raw)
        if requirement:
            required.append(requirement)

    required_new: List[Dict[str, Any]] = []
    for raw in required_new_npcs or []:
        if not isinstance(raw, dict):
            continue
        requirement = normalize_requirement(raw)
        if requirement:
            required_new.append(requirement)

    def matches_requirement(npc_row: Dict[str, Any], requirement: Dict[str, Any]) -> bool:
        if "name" in requirement and npc_row.get("name") != requirement.get("name"):
            return False
        if "name_contains" in requirement and requirement["name_contains"] not in str(npc_row.get("name", "")):
            return False
        if "my_fac" in requirement and npc_row.get("my_fac") != requirement.get("my_fac"):
            return False
        if "attitude" in requirement and npc_row.get("attitude") != requirement.get("attitude"):
            return False
        if "mission" in requirement and npc_row.get("mission") != requirement.get("mission"):
            return False
        if "rules" in requirement:
            observed_rules = npc_row.get("rules")
            if not isinstance(observed_rules, dict):
                return False
            for rule_name, expected_value in requirement["rules"].items():
                if observed_rules.get(rule_name) != expected_value:
                    return False
        if "offset_ms" in requirement and npc_row.get("offset_ms") != requirement.get("offset_ms"):
            return False
        if "max_abs_offset_ms" in requirement:
            offset = npc_row.get("offset_ms")
            if not isinstance(offset, list) or len(offset) < 3:
                return False
            max_abs = requirement["max_abs_offset_ms"]
            if any(abs(int(offset[i])) > int(max_abs[i]) for i in range(3)):
                return False
        return True

    missing_required_npcs = [
        requirement
        for requirement in required
        if not any(matches_requirement(npc_row, requirement) for npc_row in npcs)
    ]

    baseline_observed_npc_count: Optional[int] = None
    observed_npc_count_delta: Optional[int] = None
    new_npcs: List[Dict[str, Any]] = []
    missing_required_new_npcs: List[Dict[str, Any]] = []
    missing_required_npc_count_delta = False
    missing_required_npc_count = (
        required_observed_npc_count is not None and len(npcs) != int(required_observed_npc_count)
    )
    if baseline_metadata is not None:
        baseline_observed_npc_count = int(baseline_metadata.get("observed_npc_count", 0) or 0)
        observed_npc_count_delta = len(npcs) - baseline_observed_npc_count
        baseline_ids = {
            str(npc.get("id"))
            for npc in baseline_metadata.get("observed_npcs", [])
            if isinstance(npc, dict) and npc.get("id") is not None
        }
        baseline_fallback = {
            json.dumps({
                "name": npc.get("name", ""),
                "location_ms": npc.get("location_ms", []),
                "my_fac": npc.get("my_fac"),
                "attitude": npc.get("attitude"),
            }, sort_keys=True)
            for npc in baseline_metadata.get("observed_npcs", [])
            if isinstance(npc, dict) and npc.get("id") is None
        }
        for npc in npcs:
            npc_id = npc.get("id")
            if npc_id is not None:
                if str(npc_id) not in baseline_ids:
                    new_npcs.append(npc)
                continue
            fallback = json.dumps({
                "name": npc.get("name", ""),
                "location_ms": npc.get("location_ms", []),
                "my_fac": npc.get("my_fac"),
                "attitude": npc.get("attitude"),
            }, sort_keys=True)
            if fallback not in baseline_fallback:
                new_npcs.append(npc)
        if required_observed_npc_count_delta is not None:
            missing_required_npc_count_delta = observed_npc_count_delta != int(required_observed_npc_count_delta)
        missing_required_new_npcs = [
            requirement
            for requirement in required_new
            if not any(matches_requirement(npc_row, requirement) for npc_row in new_npcs)
        ]

    if record_baseline:
        status = "baseline_recorded"
    elif (
        (not required or not missing_required_npcs)
        and (required_observed_npc_count_delta is None or not missing_required_npc_count_delta)
        and (required_observed_npc_count is None or not missing_required_npc_count)
        and (not required_new or not missing_required_new_npcs)
        and (required or required_observed_npc_count_delta is not None or required_observed_npc_count is not None or required_new)
    ):
        status = "required_state_present"
    elif required or required_observed_npc_count_delta is not None or required_observed_npc_count is not None or required_new:
        status = "required_state_missing"
    else:
        status = "scanned"

    return {
        "world": world_dir.name,
        "world_dir": str(world_dir),
        "player_save": selected_player_save,
        "player_location_ms": player_location,
        "player_abs_omt": list(player_abs_omt),
        "scan_all_overmaps": scan_all_overmaps,
        "scanned_overmaps": scanned_overmaps,
        "required_npcs": required,
        "observed_npc_count": len(npcs),
        "baseline_observed_npc_count": baseline_observed_npc_count,
        "observed_npc_count_delta": observed_npc_count_delta,
        "required_observed_npc_count_delta": required_observed_npc_count_delta,
        "required_observed_npc_count": required_observed_npc_count,
        "missing_required_npc_count_delta": missing_required_npc_count_delta,
        "missing_required_npc_count": missing_required_npc_count,
        "observed_npcs": npcs,
        "new_npcs": new_npcs,
        "required_new_npcs": required_new,
        "missing_required_new_npcs": missing_required_new_npcs,
        "missing_required_npcs": missing_required_npcs,
        "status": status,
    }


def audit_saved_weather_state(
    world_dir: Path,
    *,
    required_weather_id: str = "",
    required_temperature_f: Optional[float] = None,
    temperature_tolerance_f: float = 0.75,
) -> Dict[str, Any]:
    """Read-only saved-world audit for current weather/temperature metadata.

    Weather is saved in ``dimension_data.gsav`` rather than the player save.
    Keep this as an explicit same-save target-state gate so debug weather or
    temperature macros are not credited from keystroke completion alone.
    """
    if not world_dir.exists():
        raise FileNotFoundError(f"World dir not found: {world_dir}")
    dimension_path = world_dir / "dimension_data.gsav"
    if not dimension_path.exists():
        raise FileNotFoundError(f"World dimension data not found: {dimension_path}")

    dimension_text = dimension_path.read_text(encoding="utf-8")
    version_line, sep, payload_text = dimension_text.partition("\n")
    if not sep:
        raise RuntimeError(f"Dimension data missing version header newline: {dimension_path}")
    payload = json.loads(payload_text)
    if not isinstance(payload, dict):
        raise RuntimeError(f"Dimension data is not a JSON object: {dimension_path}")
    weather = payload.get("weather")
    if not isinstance(weather, dict):
        raise RuntimeError(f"Dimension data lacks weather object: {dimension_path}")

    observed_weather_id = str(weather.get("weather_id", "")).strip()
    observed_temperature_raw = weather.get("temperature")
    observed_forced_temperature_raw = weather.get("forced_temperature")
    observed_temperature_f: Optional[float]
    observed_forced_temperature_f: Optional[float]
    try:
        observed_temperature_f = float(observed_temperature_raw)
    except (TypeError, ValueError):
        observed_temperature_f = None
    try:
        observed_forced_temperature_f = float(observed_forced_temperature_raw)
    except (TypeError, ValueError):
        observed_forced_temperature_f = None
    observed_effective_temperature_f = (
        observed_forced_temperature_f
        if observed_forced_temperature_f is not None
        else observed_temperature_f
    )

    required_weather = str(required_weather_id or "").strip()
    required_temperature: Optional[float] = None
    if required_temperature_f is not None:
        required_temperature = float(required_temperature_f)
    tolerance = max(0.0, float(temperature_tolerance_f))

    missing_required_weather: List[str] = []
    if required_weather and observed_weather_id != required_weather:
        missing_required_weather.append(f"weather_id={required_weather}")
    if required_temperature is not None:
        if observed_effective_temperature_f is None:
            missing_required_weather.append(f"effective_temperature_f={required_temperature:g}")
        elif abs(observed_effective_temperature_f - required_temperature) > tolerance:
            missing_required_weather.append(f"effective_temperature_f={required_temperature:g}")

    required_count = int(bool(required_weather)) + int(required_temperature is not None)
    if required_count and not missing_required_weather:
        status = "required_state_present"
    elif required_count:
        status = "required_state_missing"
    else:
        status = "scanned"

    stat = dimension_path.stat()
    return {
        "world": world_dir.name,
        "world_dir": str(world_dir),
        "dimension_path": str(dimension_path),
        "dimension_mtime_ns": int(stat.st_mtime_ns),
        "dimension_mtime_iso": datetime.fromtimestamp(float(stat.st_mtime)).isoformat(timespec="microseconds"),
        "version_line": version_line,
        "required_weather_id": required_weather,
        "required_temperature_f": required_temperature,
        "temperature_tolerance_f": tolerance,
        "observed_weather_id": observed_weather_id,
        "observed_temperature_f": observed_temperature_f,
        "observed_forced_temperature_f": observed_forced_temperature_f,
        "observed_effective_temperature_f": observed_effective_temperature_f,
        "observed_weather": {
            "weather_id": observed_weather_id,
            "next_weather": weather.get("next_weather"),
            "temperature": observed_temperature_raw,
            "forced_temperature": observed_forced_temperature_raw,
            "winddirection": weather.get("winddirection"),
            "windspeed": weather.get("windspeed"),
            "lightning": weather.get("lightning"),
        },
        "missing_required_weather": missing_required_weather,
        "status": status,
    }


def is_portal_storm_weather_id(weather_id: str) -> bool:
    normalized = str(weather_id or "").strip()
    if not normalized:
        return False
    if normalized in PORTAL_STORM_WEATHER_IDS:
        return True
    lowered = normalized.lower()
    return lowered in {value.lower() for value in PORTAL_STORM_WEATHER_IDS} or "portal_storm" in lowered


def portal_storm_policy_from_scenario(scenario: Dict[str, Any]) -> Dict[str, bool]:
    raw_policy = scenario.get("portal_storm", {})
    policy = raw_policy if isinstance(raw_policy, dict) else {}
    allowed = bool(
        scenario.get("allow_portal_storm", False)
        or scenario.get("portal_storm_allowed", False)
        or policy.get("allow", False)
        or policy.get("allowed", False)
    )
    required = bool(
        scenario.get("require_portal_storm", False)
        or scenario.get("portal_storm_required", False)
        or policy.get("require", False)
        or policy.get("required", False)
    )
    if required:
        allowed = True
    return {"allowed": allowed, "required": required}


def collect_weather_audits_from_step_reports(step_reports: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
    audits: List[Dict[str, Any]] = []
    for report in step_reports:
        if not isinstance(report, dict):
            continue
        interruption_handlers: List[Dict[str, Any]] = []
        direct_handler = report.get("interruption_handling")
        if isinstance(direct_handler, dict):
            interruption_handlers.append(direct_handler)
        timing = report.get("timing")
        if isinstance(timing, dict):
            for batch in timing.get("batches", []):
                if isinstance(batch, dict):
                    interruption_handlers.extend(
                        handler
                        for handler in batch.get("interruption_reports", [])
                        if isinstance(handler, dict)
                    )
        if any(bool(handler.get("contaminating", False)) for handler in interruption_handlers):
            audits.append({
                "status": "runtime_prompt_observed",
                "observed_weather_id": "runtime_portal_storm_prompt",
                "source": "blocking_interruption_handler",
                "step": str(report.get("label", "")),
            })
        metadata = report.get("metadata")
        if not isinstance(metadata, dict):
            continue
        if "observed_weather_id" in metadata or "observed_weather" in metadata:
            audits.append(metadata)
    return audits


def read_current_saved_weather_audit(profile: str, world: str) -> Dict[str, Any]:
    world_name = str(world or "").strip()
    if not world_name:
        return {
            "status": "unknown",
            "error": "world_not_configured",
            "world": "",
            "world_dir": "",
        }
    world_dir = save_dir_for_profile(profile) / world_name
    try:
        return audit_saved_weather_state(world_dir)
    except (Exception, SystemExit) as exc:
        return {
            "status": "unknown",
            "error": str(exc),
            "world": world_name,
            "world_dir": str(world_dir),
        }


def build_portal_storm_warning(
    *,
    policy: Dict[str, bool],
    current_audit: Optional[Dict[str, Any]] = None,
    step_weather_audits: Optional[List[Dict[str, Any]]] = None,
) -> Dict[str, Any]:
    allowed = bool(policy.get("allowed", False))
    required = bool(policy.get("required", False))
    audits: List[Dict[str, Any]] = []
    if isinstance(current_audit, dict) and current_audit:
        audits.append(current_audit)
    if step_weather_audits:
        audits.extend(audit for audit in step_weather_audits if isinstance(audit, dict))

    observed_weather_ids: List[str] = []
    current_weather_id = ""
    current_status = str((current_audit or {}).get("status", "")).strip()
    if isinstance(current_audit, dict):
        current_weather_id = str(current_audit.get("observed_weather_id", "")).strip()
    for audit in audits:
        weather_id = str(audit.get("observed_weather_id", "")).strip()
        if weather_id and weather_id not in observed_weather_ids:
            observed_weather_ids.append(weather_id)

    current_active = is_portal_storm_weather_id(current_weather_id)
    observed = any(is_portal_storm_weather_id(weather_id) for weather_id in observed_weather_ids)
    audit_unknown = not audits or any(str(audit.get("status", "")).strip() in {"", "unknown", "failed"} for audit in audits)

    if current_active:
        status = "active"
    elif observed:
        status = "observed"
    elif audit_unknown:
        status = "unknown"
    else:
        status = "not_observed"

    if observed and allowed:
        classification = "expected_allowed"
        summary = PORTAL_STORM_ALLOWED_SUMMARY
    elif observed:
        classification = "contaminating"
        summary = PORTAL_STORM_CONTAMINATION_SUMMARY
    elif required and status == "unknown":
        classification = "required_unknown"
        summary = PORTAL_STORM_REQUIRED_UNKNOWN_SUMMARY
    elif required:
        classification = "required_missing"
        summary = PORTAL_STORM_REQUIRED_MISSING_SUMMARY
    elif status == "unknown":
        classification = "unknown"
        summary = "Portal storm status unknown; saved weather metadata could not be audited."
    else:
        classification = "clear"
        summary = "Portal storm not observed in saved weather metadata."

    return {
        "status": status,
        "summary": summary,
        "classification": classification,
        "allowed": allowed,
        "required": required,
        "observed": observed,
        "contaminates_result": classification == "contaminating",
        "observed_weather_ids": observed_weather_ids,
        "current_weather_id": current_weather_id,
        "audit_status": current_status,
        "current_audit": current_audit or {},
        "step_weather_audit_count": len(step_weather_audits or []),
    }


def portal_storm_step_ledger_rows(portal_storm_warning: Dict[str, Any]) -> List[Dict[str, Any]]:
    classification = str(portal_storm_warning.get("classification", "")).strip()
    if classification == "contaminating":
        verdict = "yellow_step_portal_storm_contamination"
        issues = ["unallowed_portal_storm_observed"]
        next_step_gate = "rerun under controlled non-portal-storm weather unless the scenario explicitly allows portal storms"
    elif classification == "expected_allowed":
        verdict = "green_step_portal_storm_expected_allowed"
        issues = []
        next_step_gate = "portal storm is expected/allowed by this scenario and does not contaminate the proof ledger"
    elif classification in {"required_missing", "required_unknown"}:
        verdict = "red_step_portal_storm_required_missing"
        issues = [classification]
        next_step_gate = "required portal-storm scenario cannot be green until saved weather metadata proves portal storm state"
    else:
        return []
    return [{
        "index": "portal_storm_warning",
        "primitive_step": "portal_storm_warning",
        "kind": "portal_storm_warning",
        "preconditions": "scenario portal-storm policy evaluated against saved dimension weather metadata",
        "action": "read saved weather metadata and classify portal-storm contamination/allowance",
        "expected_immediate_state": str(portal_storm_warning.get("summary", "")),
        "evidence_artifact": "probe.report.json:portal_storm_warning",
        "expected_visible_fact": str(portal_storm_warning.get("summary", "")),
        "screen_text_expectation": {},
        "metadata_expectation": {
            "observed_weather_ids": portal_storm_warning.get("observed_weather_ids", []),
            "current_weather_id": portal_storm_warning.get("current_weather_id", ""),
            "portal_storm_policy": {
                "allowed": bool(portal_storm_warning.get("allowed", False)),
                "required": bool(portal_storm_warning.get("required", False)),
            },
        },
        "proof_deferred_to_label": "",
        "failure_rule": "unallowed portal storm is yellow contamination; missing/unknown required portal storm is red; explicitly allowed portal storm is green",
        "next_step_gate": next_step_gate,
        "issues": issues,
        "verdict": verdict,
    }]


def build_portal_storm_warning_for_report(
    *,
    profile: str,
    world: str,
    scenario: Dict[str, Any],
    step_reports: Optional[List[Dict[str, Any]]] = None,
    extra_weather_audits: Optional[List[Dict[str, Any]]] = None,
) -> Dict[str, Any]:
    step_weather_audits = list(extra_weather_audits or [])
    step_weather_audits.extend(collect_weather_audits_from_step_reports(step_reports or []))
    return build_portal_storm_warning(
        policy=portal_storm_policy_from_scenario(scenario),
        current_audit=read_current_saved_weather_audit(profile, world),
        step_weather_audits=step_weather_audits,
    )


def summarize_bandit_active_outing(site: Dict[str, Any]) -> Dict[str, Any]:
    def integer_field(record: Dict[str, Any], key: str, default: int) -> int:
        value = record.get(key, default)
        return default if value is None else int(value)

    def strict_int(record: Dict[str, Any], key: str) -> Optional[int]:
        value = record.get(key)
        if isinstance(value, bool) or not isinstance(value, int):
            return None
        return value

    raw_outing = site.get("active_outing")
    outing = raw_outing if isinstance(raw_outing, dict) else {}
    activity_id = str(outing.get("activity_id", "") or "")
    kind = str(outing.get("kind", "") or "")
    generation = integer_field(outing, "generation", 0)
    is_active = bool(activity_id and kind not in {"", "none"} and generation > 0)

    member_ids = outing.get("member_ids", [])
    if not isinstance(member_ids, list):
        member_ids = []
    member_id_keys = [str(value) for value in member_ids]
    leader_id = outing.get("leader_id")
    exact_pair = (
        len(member_ids) == 2
        and len(set(member_id_keys)) == 2
        and str(leader_id) in member_id_keys
    )

    shared_route = outing.get("shared_route", [])
    if not isinstance(shared_route, list):
        shared_route = []
    waypoint_index = integer_field(outing, "waypoint_index", -1)
    waypoint_in_route = 0 <= waypoint_index < len(shared_route)
    waypoint_omt = shared_route[waypoint_index] if waypoint_in_route else []
    structural_route_valid = (
        kind == "structural_sortie"
        and 3 <= len(shared_route) <= 5
        and waypoint_in_route
    )

    simulation_owner = str(outing.get("simulation_owner", "") or "")
    handoff_epoch = integer_field(outing, "handoff_epoch", 0)
    last_advanced_minutes = integer_field(outing, "last_advanced_minutes", -1)
    started_minutes = integer_field(outing, "started_minutes", -1)
    local_contact_minutes = integer_field(outing, "local_contact_minutes", -1)
    last_progress_minutes = integer_field(outing, "last_progress_minutes", -1)
    owner_cursor_valid = bool(
        handoff_epoch >= 0
        and (
            (simulation_owner == "abstract" and handoff_epoch % 2 == 0)
            or (simulation_owner == "local" and handoff_epoch % 2 == 1)
        )
        and last_advanced_minutes
        >= max(started_minutes, local_contact_minutes, last_progress_minutes)
    )
    raw_handoff = outing.get("local_handoff")
    handoff = raw_handoff if isinstance(raw_handoff, dict) else {}
    handoff_activity_id = str(handoff.get("activity_id", "") or "")
    handoff_generation = integer_field(handoff, "activity_generation", 0)
    handoff_epoch_value = integer_field(handoff, "handoff_epoch", -1)
    handoff_committed_minutes = integer_field(handoff, "committed_minutes", -1)
    handoff_schema = integer_field(handoff, "schema_version", 0)
    handoff_members = handoff.get("members", [])
    if not isinstance(handoff_members, list):
        handoff_members = []
    handoff_member_rows = [member for member in handoff_members if isinstance(member, dict)]
    handoff_member_ids = [member.get("npc_id") for member in handoff_member_rows]
    handoff_member_keys = [str(value) for value in handoff_member_ids]

    def valid_position(value: Any) -> bool:
        return isinstance(value, list) and len(value) >= 3

    entry_positions = [member.get("entry_position") for member in handoff_member_rows]
    staging_positions = [member.get("staging_position") for member in handoff_member_rows]
    distinct_entries = (
        len(entry_positions) == 2
        and all(valid_position(value) for value in entry_positions)
        and entry_positions[0] != entry_positions[1]
    )
    distinct_staging = (
        len(staging_positions) == 2
        and all(valid_position(value) for value in staging_positions)
        and staging_positions[0] != staging_positions[1]
    )
    entry_staging_separate = (
        len(entry_positions) == 2
        and len(staging_positions) == 2
        and all(
            valid_position(entry_positions[index])
            and valid_position(staging_positions[index])
            and entry_positions[index] != staging_positions[index]
            for index in range(2)
        )
    )
    health_valid = len(handoff_member_rows) == 2 and all(
        (
            bool(member.get("dead", False))
            and int(member.get("hp_percent", -1) or 0) == 0
        )
        or (
            not bool(member.get("dead", False))
            and 0 < int(member.get("hp_percent", 0) or 0) <= 100
        )
        for member in handoff_member_rows
    )
    handoff_exact_pair = (
        len(handoff_members) == 2
        and len(handoff_member_rows) == 2
        and len(set(handoff_member_keys)) == 2
    )
    handoff_member_ids_match_outing = (
        handoff_exact_pair
        and len(member_ids) == 2
        and set(handoff_member_keys) == set(member_id_keys)
    )
    handoff_identity_matches_outing = bool(
        is_active
        and handoff_activity_id == activity_id
        and handoff_generation == generation
        and handoff_epoch_value == handoff_epoch
        and integer_field(handoff, "waypoint_index", -1) == waypoint_index
        and handoff.get("route_position", []) == waypoint_omt
    )
    handoff_cursor_consistent = bool(
        handoff_identity_matches_outing
        and handoff_committed_minutes >= 0
        and handoff_committed_minutes <= last_advanced_minutes
    )
    handoff_state = "empty"
    if handoff_activity_id:
        if handoff_schema in {1, 2, 3, 4} and handoff_epoch_value > 0:
            handoff_state = "local" if handoff_epoch_value % 2 == 1 else "abstract_resume"
        else:
            handoff_state = "malformed"
    handoff_pair_contract_valid = bool(
        handoff_state in {"local", "abstract_resume"}
        and handoff_exact_pair
        and handoff_member_ids_match_outing
        and handoff_identity_matches_outing
        and handoff_cursor_consistent
        and distinct_entries
        and distinct_staging
        and entry_staging_separate
        and health_valid
        and (
            handoff_schema < 3
            or str(handoff.get("cohesion_leader_id")) == str(leader_id)
        )
    )
    handoff_valid_for_owner = (
        handoff_state == "empty"
        if simulation_owner == "abstract"
        else False
    ) or (
        handoff_pair_contract_valid
        and (
            (simulation_owner == "local" and handoff_state == "local")
            or (simulation_owner == "abstract" and handoff_state == "abstract_resume")
        )
    )

    raw_local_return_eligibility = outing.get("local_return_eligibility")
    receipt = raw_local_return_eligibility if isinstance(raw_local_return_eligibility, dict) else {}
    receipt_errors: List[str] = []
    receipt_schema_version = strict_int(receipt, "schema_version")
    receipt_activity_id = receipt.get("activity_id")
    receipt_actor_ids = receipt.get("actor_ids")
    receipt_generation = strict_int(receipt, "generation")
    receipt_owner = receipt.get("owner")
    receipt_handoff_epoch = strict_int(receipt, "handoff_epoch")
    receipt_cohesion_leader_id = strict_int(receipt, "cohesion_leader_id")
    receipt_cohesion_assembled = receipt.get("cohesion_assembled")
    receipt_contact_minutes = strict_int(receipt, "contact_minutes")
    receipt_eligible_minutes = strict_int(receipt, "eligible_minutes")
    receipt_actor_ids_valid = (
        isinstance(receipt_actor_ids, list)
        and bool(receipt_actor_ids)
        and all(isinstance(actor_id, int) and not isinstance(actor_id, bool)
                for actor_id in receipt_actor_ids)
        and len({str(actor_id) for actor_id in receipt_actor_ids}) == len(receipt_actor_ids)
    )
    if not isinstance(raw_local_return_eligibility, dict):
        receipt_errors.append("missing_or_non_object_receipt")
    if integer_field(outing, "schema_version", 0) != 11:
        receipt_errors.append("outing_schema_not_v11")
    if kind != "structural_sortie":
        receipt_errors.append("outing_kind_not_structural_sortie")
    if receipt_schema_version != 1:
        receipt_errors.append("unsupported_schema_version")
    if not isinstance(receipt_activity_id, str) or not receipt_activity_id:
        receipt_errors.append("missing_or_invalid_activity_id")
    elif receipt_activity_id != activity_id:
        receipt_errors.append("activity_id_mismatch")
    if not receipt_actor_ids_valid:
        receipt_errors.append("missing_or_invalid_ordered_actor_ids")
    elif receipt_actor_ids != member_ids:
        receipt_errors.append("ordered_actor_ids_mismatch")
    if receipt_generation is None or receipt_generation <= 0:
        receipt_errors.append("missing_or_invalid_generation")
    elif receipt_generation != generation:
        receipt_errors.append("generation_mismatch")
    if receipt_owner != "local":
        receipt_errors.append("owner_not_local")
    if receipt_handoff_epoch is None or receipt_handoff_epoch < 0 or receipt_handoff_epoch % 2 != 1:
        receipt_errors.append("missing_or_invalid_odd_handoff_epoch")
    elif simulation_owner == "local" and receipt_handoff_epoch != handoff_epoch:
        receipt_errors.append("handoff_epoch_mismatch")
    if receipt_cohesion_leader_id is None or not receipt_actor_ids_valid or receipt_cohesion_leader_id not in receipt_actor_ids:
        receipt_errors.append("missing_or_invalid_cohesion_leader")
    elif simulation_owner == "local" and receipt_cohesion_leader_id != handoff.get("cohesion_leader_id"):
        receipt_errors.append("cohesion_leader_mismatch")
    if not isinstance(receipt_cohesion_assembled, bool):
        receipt_errors.append("missing_or_invalid_cohesion_assembled")
    elif receipt_cohesion_assembled:
        receipt_errors.append("eligibility_receipt_not_pre_cohesion")
    if receipt_contact_minutes is None or receipt_contact_minutes < 0:
        receipt_errors.append("missing_or_invalid_contact_minutes")
    elif receipt_contact_minutes != local_contact_minutes:
        receipt_errors.append("contact_minutes_mismatch")
    if receipt_eligible_minutes is None or receipt_contact_minutes is None or receipt_eligible_minutes != receipt_contact_minutes + 720:
        receipt_errors.append("invalid_eligibility_minutes")

    local_return_eligibility = {
        "present": isinstance(raw_local_return_eligibility, dict),
        "valid": not receipt_errors,
        "validation_errors": receipt_errors,
        "schema_version": receipt_schema_version,
        "activity_id": receipt_activity_id if isinstance(receipt_activity_id, str) else None,
        "actor_ids": receipt_actor_ids if receipt_actor_ids_valid else [],
        "generation": receipt_generation,
        "owner": receipt_owner if isinstance(receipt_owner, str) else None,
        "handoff_epoch": receipt_handoff_epoch,
        "cohesion_leader_id": receipt_cohesion_leader_id,
        "cohesion_assembled": receipt_cohesion_assembled if isinstance(receipt_cohesion_assembled, bool) else None,
        "contact_minutes": receipt_contact_minutes,
        "eligible_minutes": receipt_eligible_minutes,
    }

    return {
        "present": isinstance(raw_outing, dict),
        "is_active": is_active,
        "schema_version": integer_field(outing, "schema_version", 0),
        "kind": kind,
        "activity_id": activity_id,
        "camp_id": str(outing.get("camp_id", "") or ""),
        "generation": generation,
        "member_ids": member_ids,
        "member_count": len(member_ids),
        "leader_id": leader_id,
        "exact_pair_with_leader": exact_pair,
        "shared_route": shared_route,
        "shared_route_count": len(shared_route),
        "waypoint_index": waypoint_index,
        "waypoint_in_route": waypoint_in_route,
        "waypoint_omt": waypoint_omt,
        "structural_route_valid": structural_route_valid,
        "target_id": str(outing.get("target_id", "") or ""),
        "target_omt": outing.get("target_omt", []),
        "target_lead_revision": integer_field(outing, "target_lead_revision", 0),
        "job_type": str(outing.get("job_type", "") or ""),
        "phase": str(outing.get("phase", "") or ""),
        "simulation_owner": simulation_owner,
        "handoff_epoch": handoff_epoch,
        "owner_cursor_valid": owner_cursor_valid,
        "started_minutes": started_minutes,
        "local_contact_minutes": local_contact_minutes,
        "last_progress_minutes": last_progress_minutes,
        "last_advanced_minutes": last_advanced_minutes,
        "local_return_eligibility": local_return_eligibility,
        "simulation_cursor": {
            "activity_id": activity_id,
            "generation": generation,
            "simulation_owner": simulation_owner,
            "handoff_epoch": handoff_epoch,
            "last_advanced_minutes": last_advanced_minutes,
        },
        "pair_contract_valid": bool(
            is_active
            and exact_pair
            and structural_route_valid
            and owner_cursor_valid
            and handoff_valid_for_owner
        ),
        "local_handoff": {
            "present": isinstance(raw_handoff, dict),
            "state": handoff_state,
            "schema_version": handoff_schema,
            "activity_id": handoff_activity_id,
            "activity_generation": handoff_generation,
            "handoff_epoch": handoff_epoch_value,
            "waypoint_index": integer_field(handoff, "waypoint_index", -1),
            "phase": str(handoff.get("phase", "") or ""),
            "cohesion_leader_id": handoff.get("cohesion_leader_id"),
            "cohesion_assembled": bool(handoff.get("cohesion_assembled", False)),
            "cohesion_abort_return": bool(handoff.get("cohesion_abort_return", False)),
            "route_position": handoff.get("route_position", []),
            "committed_minutes": handoff_committed_minutes,
            "member_ids": handoff_member_ids,
            "member_count": len(handoff_members),
            "members": handoff_member_rows,
            "exact_pair": handoff_exact_pair,
            "member_ids_match_outing": handoff_member_ids_match_outing,
            "identity_matches_outing": handoff_identity_matches_outing,
            "cursor_consistent": handoff_cursor_consistent,
            "distinct_entry_positions": distinct_entries,
            "distinct_staging_positions": distinct_staging,
            "entry_staging_positions_separate": entry_staging_separate,
            "member_health_valid": health_valid,
            "pair_contract_valid": handoff_pair_contract_valid,
        },
    }


def summarize_bandit_live_world_site(site: Dict[str, Any]) -> Dict[str, Any]:
    intelligence_map = site.get("intelligence_map")
    leads = []
    lead_entries_valid = False
    if isinstance(intelligence_map, dict):
        raw_leads = intelligence_map.get("leads", [])
        if isinstance(raw_leads, list):
            lead_entries_valid = all(isinstance(lead, dict) for lead in raw_leads)
            for lead in raw_leads:
                if not isinstance(lead, dict):
                    continue
                leads.append({
                    "lead_id": lead.get("lead_id", ""),
                    "kind": lead.get("kind", ""),
                    "origin": lead.get("origin", ""),
                    "status": lead.get("status", ""),
                    "target_id": lead.get("target_id", ""),
                    "omt": lead.get("omt", []),
                    "radius_omt": lead.get("radius_omt", 0),
                    "source_key": lead.get("source_key", ""),
                    "source_summary": lead.get("source_summary", ""),
                    "first_seen_minutes": lead.get("first_seen_minutes", -1),
                    "last_seen_minutes": lead.get("last_seen_minutes", -1),
                    "last_checked_minutes": lead.get("last_checked_minutes", -1),
                    "last_scouted_minutes": lead.get("last_scouted_minutes", -1),
                    "bounty": lead.get("bounty", 0),
                    "threat": lead.get("threat", 0),
                    "confidence": lead.get("confidence", 0),
                    "threat_confirmed": lead.get("threat_confirmed", False),
                    "target_alert": lead.get("target_alert", False),
                    "scout_seen": lead.get("scout_seen", False),
                    "generated_by_this_camp_routine": lead.get("generated_by_this_camp_routine", False),
                    "prior_bandit_losses": lead.get("prior_bandit_losses", 0),
                    "prior_defender_losses": lead.get("prior_defender_losses", 0),
                    "times_checked_empty": lead.get("times_checked_empty", 0),
                    "times_harvested": lead.get("times_harvested", 0),
                    "last_outcome": lead.get("last_outcome", ""),
                })
    active_outing = summarize_bandit_active_outing(site)
    raw_hostile_operation = site.get("active_hostile_operation")
    hostile_operation = raw_hostile_operation if isinstance(raw_hostile_operation, dict) else {}
    raw_hostile_reservation = hostile_operation.get("reservation")
    hostile_reservation = summarize_bandit_active_outing({
        "active_outing": raw_hostile_reservation,
    })
    hostile_operation_kind = str(hostile_operation.get("operation_kind", "") or "")
    hostile_operation_phase = str(hostile_operation.get("phase", "") or "")
    hostile_operation_active = bool(
        hostile_operation_kind in {"shakedown", "raid"}
        and hostile_reservation.get("is_active")
        and hostile_reservation.get("kind") == "hostile_operation"
    )
    active_member_ids = active_outing.get("member_ids", []) if active_outing.get("is_active") else site.get("active_member_ids", [])
    if not isinstance(active_member_ids, list):
        active_member_ids = []
    retired_empty_site = bool(site.get("retired_empty_site", False))
    spawn_tiles = site.get("spawn_tiles", [])
    if not isinstance(spawn_tiles, list):
        spawn_tiles = []
    spawn_tile_headcount = 0
    for spawn_tile in spawn_tiles:
        if not isinstance(spawn_tile, dict):
            continue
        spawn_tile_headcount += max(0, int(spawn_tile.get("headcount", 0) or 0))
    members = site.get("members", [])
    if not isinstance(members, list):
        members = []
    ready_at_home = 0
    home_survivors = 0
    wounded_or_unready = 0
    active_outside_ids = {str(value) for value in active_member_ids}
    member_state_counts: Dict[str, int] = {}
    for member in members:
        if not isinstance(member, dict):
            continue
        state = str(member.get("state", ""))
        member_state_counts[state] = member_state_counts.get(state, 0) + 1
        is_wounded_or_unready = bool(member.get("wounded_or_unready", False))
        if state == "at_home" and not is_wounded_or_unready:
            ready_at_home += 1
        if state == "at_home":
            home_survivors += 1
        if state in {"at_home", "outbound", "local_contact"} and is_wounded_or_unready:
            wounded_or_unready += 1
        if state in {"outbound", "local_contact"}:
            active_outside_ids.add(str(member.get("npc_id", "")))
    active_outside_ids.discard("")
    home_side_signals = ready_at_home + wounded_or_unready + max(0, int(site.get("headcount", 0) or 0)) + spawn_tile_headcount
    empty_retirement_blockers: List[str] = []
    if retired_empty_site:
        empty_retirement_blockers.append("already_retired")
    if str(site.get("site_kind", "")) in {"", "none"}:
        empty_retirement_blockers.append("no_hostile_site_kind")
    if home_side_signals != 0:
        empty_retirement_blockers.append("home_side_present")
    if active_outside_ids:
        empty_retirement_blockers.append("active_outside_present")
    known_recent_marks = site.get("known_recent_marks", [])
    if not isinstance(known_recent_marks, list):
        known_recent_marks = []
    raw_report = site.get("current_scout_report", {})
    if not isinstance(raw_report, dict):
        raw_report = {}
    def persisted_int(owner: Dict[str, Any], key: str, default: int) -> int:
        try:
            return int(owner.get(key, default))
        except (TypeError, ValueError):
            return default

    report_observations = raw_report.get("observations", [])
    if not isinstance(report_observations, list):
        report_observations = []
    scout_report = {
        "present": (
            persisted_int(raw_report, "revision", 0) > 0
            and persisted_int(raw_report, "source_generation", 0) > 0
            and bool(str(raw_report.get("source_activity_id", "") or ""))
            and bool(str(raw_report.get("application_key", "") or ""))
        ),
        "revision": persisted_int(raw_report, "revision", 0),
        "action_policy": str(raw_report.get("action_policy", "") or ""),
        "source_activity_id": str(raw_report.get("source_activity_id", "") or ""),
        "source_generation": persisted_int(raw_report, "source_generation", 0),
        "carrier_ids": raw_report.get("carrier_ids", [])
        if isinstance(raw_report.get("carrier_ids", []), list) else [],
        "source_job_type": str(raw_report.get("source_job_type", "") or ""),
        "target_id": str(raw_report.get("target_id", "") or ""),
        "target_omt": raw_report.get("target_omt", []),
        "target_lead_id": str(raw_report.get("target_lead_id", "") or ""),
        "target_lead_revision": persisted_int(raw_report, "target_lead_revision", 0),
        "application_key": str(raw_report.get("application_key", "") or ""),
        "observation_count": len(report_observations),
        "casualty_count": len(raw_report.get("casualty_ids", []))
        if isinstance(raw_report.get("casualty_ids", []), list) else 0,
        "delivered_minutes": persisted_int(raw_report, "delivered_minutes", -1),
        "provisional": bool(raw_report.get("provisional", False)),
    }
    raw_decision = site.get("camp_decision", {})
    if not isinstance(raw_decision, dict):
        raw_decision = {}
    camp_decision = {
        "state": str(raw_decision.get("state", "") or ""),
        "report_policy": str(raw_decision.get("report_policy", "") or ""),
        "source_report_revision": persisted_int(raw_decision, "source_report_revision", 0),
        "source_report_generation": persisted_int(raw_decision, "source_report_generation", 0),
        "source_report_activity_id": str(raw_decision.get("source_report_activity_id", "") or ""),
        "source_report_application_key": str(raw_decision.get("source_report_application_key", "") or ""),
        "target_id": str(raw_decision.get("target_id", "") or ""),
        "target_omt": raw_decision.get("target_omt", []),
        "target_lead_id": str(raw_decision.get("target_lead_id", "") or ""),
        "target_lead_revision": persisted_int(raw_decision, "target_lead_revision", 0),
        "last_transition_minutes": persisted_int(raw_decision, "last_transition_minutes", -1),
        "next_eligible_minutes": persisted_int(raw_decision, "next_eligible_minutes", -1),
        "transition_reason": str(raw_decision.get("transition_reason", "") or ""),
    }
    report_decision_identity_matches = bool(scout_report["present"]) and all([
        camp_decision["source_report_revision"] == scout_report["revision"],
        camp_decision["source_report_generation"] == scout_report["source_generation"],
        camp_decision["source_report_activity_id"] == scout_report["source_activity_id"],
        camp_decision["source_report_application_key"] == scout_report["application_key"],
        camp_decision["report_policy"] == scout_report["action_policy"],
        camp_decision["target_id"] == scout_report["target_id"],
        camp_decision["target_omt"] == scout_report["target_omt"],
        camp_decision["target_lead_id"] == scout_report["target_lead_id"],
        camp_decision["target_lead_revision"] == scout_report["target_lead_revision"],
    ])
    return {
        "site_id": site.get("site_id", ""),
        "source_kind": site.get("source_kind", ""),
        "site_kind": site.get("site_kind", ""),
        "hostile_profile": site.get("hostile_profile", site.get("profile", "")),
        "anchor": site.get("anchor", []),
        "headcount": site.get("headcount", 0),
        "spawn_tile_headcount": spawn_tile_headcount,
        "home_side_signal_count": home_side_signals,
        "retired_empty_site": retired_empty_site,
        "retirement_summary": site.get("retirement_summary", ""),
        "empty_site_retirement_eligible": not retired_empty_site and not empty_retirement_blockers,
        "empty_site_retirement_blockers": empty_retirement_blockers,
        "member_count": len(members),
        "ready_at_home_count": ready_at_home,
        "home_survivor_count": home_survivors,
        "wounded_or_unready_count": wounded_or_unready,
        "active_outside_count": len(active_outside_ids),
        "member_state_counts": member_state_counts,
        "active_group_id": active_outing.get("activity_id", "") if active_outing.get("is_active") else site.get("active_group_id", ""),
        "active_target_id": active_outing.get("target_id", "") if active_outing.get("is_active") else site.get("active_target_id", ""),
        "active_target_omt": active_outing.get("target_omt", []) if active_outing.get("is_active") else site.get("active_target_omt", []),
        "active_job_type": active_outing.get("job_type", "") if active_outing.get("is_active") else site.get("active_job_type", ""),
        "active_sortie_started_minutes": site.get("active_outing", {}).get("started_minutes", -1) if active_outing.get("is_active") else site.get("active_sortie_started_minutes", -1),
        "active_sortie_local_contact_minutes": site.get("active_outing", {}).get("local_contact_minutes", -1) if active_outing.get("is_active") else site.get("active_sortie_local_contact_minutes", -1),
        "active_member_ids": active_member_ids,
        "active_member_count": len(active_member_ids),
        "active_outing": active_outing,
        "active_hostile_operation": {
            "present": isinstance(raw_hostile_operation, dict),
            "is_active": hostile_operation_active,
            "schema_version": hostile_operation.get("schema_version", 0),
            "operation_kind": hostile_operation_kind,
            "phase": hostile_operation_phase,
            "source_report_revision": persisted_int(hostile_operation, "source_report_revision", 0),
            "source_report_generation": persisted_int(hostile_operation, "source_report_generation", 0),
            "source_report_activity_id": str(hostile_operation.get("source_report_activity_id", "") or ""),
            "source_report_application_key": str(
                hostile_operation.get("source_report_application_key", "") or ""
            ),
            "reservation": hostile_reservation,
        },
        "remembered_target_or_mark": site.get("remembered_target_or_mark", ""),
        "remembered_pressure": site.get("remembered_pressure", ""),
        "known_recent_marks": known_recent_marks,
        "known_recent_mark_count": len(known_recent_marks),
        "current_scout_report": scout_report,
        "camp_decision": camp_decision,
        "report_decision_identity_matches": report_decision_identity_matches,
        "lead_entries_valid": lead_entries_valid,
        "lead_count": len(leads),
        "leads": leads,
    }


def audit_saved_bandit_live_world_state(
    world_dir: Path,
    *,
    required_profile: str = "",
    required_site_id_contains: str = "",
    required_active_group_id_exact: Optional[str] = None,
    required_active_group_id_contains: str = "",
    required_active_target_id_exact: Optional[str] = None,
    required_active_target_id_prefix: str = "",
    required_active_target_id_contains: str = "",
    required_active_job_type: str = "",
    required_active_sortie_started_minutes: Optional[int] = None,
    required_active_sortie_local_contact_minutes: Optional[int] = None,
    required_active_outing_kind: str = "",
    required_active_outing_activity_id_contains: str = "",
    required_active_outing_generation: Optional[int] = None,
    required_active_outing_simulation_owner: str = "",
    required_active_outing_handoff_epoch: Optional[int] = None,
    required_active_outing_phase: str = "",
    required_active_outing_waypoint_index: Optional[int] = None,
    required_active_outing_last_advanced_minutes: Optional[int] = None,
    required_active_outing_exact_pair: Optional[bool] = None,
    required_active_outing_pair_contract: Optional[bool] = None,
    required_active_hostile_operation_kind: str = "",
    required_active_hostile_operation_phase: str = "",
    required_active_hostile_reservation_job_type: str = "",
    required_active_hostile_reservation_target_id_exact: Optional[str] = None,
    required_active_hostile_reservation_simulation_owner: str = "",
    required_active_hostile_reservation_min_member_ids: Optional[int] = None,
    required_local_handoff_state: str = "",
    required_local_handoff_exact_pair: Optional[bool] = None,
    required_local_handoff_pair_contract: Optional[bool] = None,
    required_local_handoff_cohesion_assembled: Optional[bool] = None,
    required_local_return_eligibility_valid: Optional[bool] = None,
    required_local_return_eligibility_cohesion_assembled: Optional[bool] = None,
    required_local_handoff_cohesion_abort_return: Optional[bool] = None,
    required_local_handoff_route_position: Optional[List[int]] = None,
    required_member_count: Optional[int] = None,
    required_ready_at_home_count: Optional[int] = None,
    required_min_ready_at_home_count: Optional[int] = None,
    required_min_home_survivor_count: Optional[int] = None,
    required_wounded_or_unready_count: Optional[int] = None,
    required_active_outside_count: Optional[int] = None,
    required_min_active_member_ids: Optional[int] = None,
    required_active_members_found: bool = False,
    required_active_member_max_abs_offset_ms: Optional[List[int]] = None,
    player_save: str = "",
    required_remembered_target_or_mark_prefix: str = "",
    required_remembered_pressure: str = "",
    required_min_leads: Optional[int] = None,
    required_max_leads: Optional[int] = None,
    required_lead_source_contains: str = "",
    required_lead_kind: str = "",
    required_lead_origin: str = "",
    required_all_lead_origin: str = "",
    required_lead_target_id: str = "",
    required_lead_target_id_prefix: str = "",
    required_lead_bounty: Optional[int] = None,
    required_lead_threat: Optional[int] = None,
    required_lead_times_harvested: Optional[int] = None,
    required_lead_last_checked_minutes_min: Optional[int] = None,
    required_lead_status: str = "",
    required_lead_last_outcome: str = "",
    required_lead_confidence: Optional[int] = None,
    required_known_recent_mark_contains: str = "",
    required_home_side_signal_count: Optional[int] = None,
    required_retired_empty_site: Optional[bool] = None,
    required_retirement_summary_contains: str = "",
    required_empty_retirement_blocker_contains: str = "",
    required_scout_report_present: Optional[bool] = None,
    required_scout_report_provisional: Optional[bool] = None,
    required_scout_report_min_observations: Optional[int] = None,
    required_scout_report_source_activity_id: str = "",
    required_scout_report_source_generation: Optional[int] = None,
    required_scout_report_exact_carrier_ids: Optional[List[int]] = None,
    required_camp_decision_state: str = "",
    required_report_decision_identity_match: Optional[bool] = None,
    required_report_hostile_operation_claim_match: Optional[bool] = None,
) -> Dict[str, Any]:
    """Read-only saved dimension-data audit for persisted bandit_live_world state."""
    if not world_dir.exists():
        raise FileNotFoundError(f"World dir not found: {world_dir}")
    dimension_path = world_dir / "dimension_data.gsav"
    if not dimension_path.exists():
        raise FileNotFoundError(f"World dimension data not found: {dimension_path}")

    dimension_text = dimension_path.read_text(encoding="utf-8")
    version_line, sep, payload_text = dimension_text.partition("\n")
    if not sep:
        raise RuntimeError(f"Dimension data missing version header newline: {dimension_path}")
    payload = json.loads(payload_text)
    if not isinstance(payload, dict):
        raise RuntimeError(f"Dimension data is not a JSON object: {dimension_path}")
    overmapbuffer = payload.get("overmapbuffer")
    if not isinstance(overmapbuffer, dict):
        raise RuntimeError(f"Dimension data lacks overmapbuffer object: {dimension_path}")
    bandit_world = overmapbuffer.get("bandit_live_world")
    if not isinstance(bandit_world, dict):
        raise RuntimeError(f"Dimension data lacks overmapbuffer.bandit_live_world object: {dimension_path}")
    raw_sites = bandit_world.get("sites", [])
    if not isinstance(raw_sites, list):
        raise RuntimeError(f"bandit_live_world.sites is not a list: {dimension_path}")

    observed_sites = [summarize_bandit_live_world_site(site) for site in raw_sites if isinstance(site, dict)]
    raw_hostile_opportunities = bandit_world.get("hostile_target_opportunities", [])
    if not isinstance(raw_hostile_opportunities, list):
        raw_hostile_opportunities = []
    for observed_site in observed_sites:
        report = observed_site.get("current_scout_report", {})
        operation = observed_site.get("active_hostile_operation", {})
        reservation = operation.get("reservation", {}) if isinstance(operation, dict) else {}
        source_identity_matches = bool(
            isinstance(report, dict)
            and isinstance(operation, dict)
            and isinstance(reservation, dict)
            and report.get("present")
            and operation.get("is_active")
            and operation.get("source_report_revision") == report.get("revision")
            and operation.get("source_report_generation") == report.get("source_generation")
            and operation.get("source_report_activity_id") == report.get("source_activity_id")
            and operation.get("source_report_application_key") == report.get("application_key")
            and reservation.get("target_id") == report.get("target_id")
            and reservation.get("target_omt") == report.get("target_omt")
            and reservation.get("target_lead_revision") == report.get("target_lead_revision")
        )
        claim_matches = source_identity_matches and any(
            isinstance(opportunity, dict)
            and opportunity.get("target_id") == reservation.get("target_id")
            and opportunity.get("target_omt") == reservation.get("target_omt")
            and opportunity.get("consumed_operation_id") == reservation.get("activity_id")
            and opportunity.get("consumed_report_key") == operation.get("source_report_application_key")
            and opportunity.get("consumed_generation") == reservation.get("generation")
            for opportunity in raw_hostile_opportunities
        )
        observed_site["report_hostile_operation_identity_matches"] = source_identity_matches
        observed_site["report_hostile_operation_claim_matches"] = claim_matches

    selected_player_save = str(player_save or "").strip()
    player_location_ms: List[int] = []
    player_abs_omt: List[int] = []
    active_member_scan_error = ""
    active_member_npcs_by_id: Dict[str, Dict[str, Any]] = {}
    should_scan_active_members = bool(required_active_members_found or required_active_member_max_abs_offset_ms is not None)
    if should_scan_active_members:
        try:
            selected_player_save, _player_save_path, player_payload, _player_stat = load_saved_player_payload(world_dir, selected_player_save)
            player = player_payload.get("player")
            if not isinstance(player, dict):
                raise RuntimeError("Extracted player save is missing player object")
            location_raw = player.get("location", [])
            if not isinstance(location_raw, list) or len(location_raw) < 3:
                raise RuntimeError("Extracted player save is missing player location")
            player_location_ms = [int(location_raw[0]), int(location_raw[1]), int(location_raw[2])]
            player_abs_omt = [player_location_ms[0] // 24, player_location_ms[1] // 24, player_location_ms[2]]
            overmaps_dir = world_dir / "overmaps"
            if not overmaps_dir.exists():
                raise RuntimeError(f"Overmaps dir not found: {overmaps_dir}")
            for overmap_path in sorted(overmaps_dir.glob("o.*.*.zzip")):
                plain_path: Optional[Path] = None
                created_plain = False
                try:
                    plain_path, _version_line, overmap_payload = extract_overmap_payload(overmap_path)
                    created_plain = bool(overmap_payload.get("_created_plain"))
                    raw_npcs = overmap_payload.get("npcs", [])
                    if not isinstance(raw_npcs, list):
                        continue
                    for index, npc_payload in enumerate(raw_npcs):
                        if not isinstance(npc_payload, dict):
                            continue
                        npc_id = npc_payload.get("id")
                        if npc_id is None:
                            continue
                        location_raw = npc_payload.get("location", [])
                        location_ms: List[int] = []
                        offset_ms: List[int] = []
                        if isinstance(location_raw, list) and len(location_raw) >= 3:
                            location_ms = [int(location_raw[0]), int(location_raw[1]), int(location_raw[2])]
                            offset_ms = [
                                location_ms[0] - player_location_ms[0],
                                location_ms[1] - player_location_ms[1],
                                location_ms[2] - player_location_ms[2],
                            ]
                        active_member_npcs_by_id[str(npc_id)] = {
                            "id": npc_id,
                            "overmap": str(overmap_path.relative_to(world_dir)),
                            "index": index,
                            "name": str(npc_payload.get("name", "") or ""),
                            "location_ms": location_ms,
                            "offset_ms": offset_ms,
                            "attitude": npc_payload.get("attitude"),
                            "mission": npc_payload.get("mission"),
                            "my_fac": npc_payload.get("my_fac"),
                            "dead": npc_payload.get("dead"),
                        }
                finally:
                    if plain_path is not None and created_plain:
                        cleanup_extracted_overmap(plain_path, keep=False)
        except Exception as exc:
            active_member_scan_error = str(exc)
            if required_active_members_found or required_active_member_max_abs_offset_ms is not None:
                raise

    normalized_max_abs_offset: Optional[List[int]] = None
    if required_active_member_max_abs_offset_ms is not None:
        if len(required_active_member_max_abs_offset_ms) < 3:
            raise RuntimeError("required_active_member_max_abs_offset_ms needs [x,y,z]")
        normalized_max_abs_offset = [
            int(required_active_member_max_abs_offset_ms[0]),
            int(required_active_member_max_abs_offset_ms[1]),
            int(required_active_member_max_abs_offset_ms[2]),
        ]

    for site in observed_sites:
        lookups: List[Dict[str, Any]] = []
        active_ids = site.get("active_member_ids", [])
        if not isinstance(active_ids, list):
            active_ids = []
        for member_id in active_ids:
            found = active_member_npcs_by_id.get(str(member_id))
            if found is None:
                lookups.append({"id": member_id, "found_in_saved_overmap": False})
                continue
            row = dict(found)
            row["found_in_saved_overmap"] = True
            if normalized_max_abs_offset is not None:
                offset = row.get("offset_ms", [])
                row["within_required_max_abs_offset_ms"] = (
                    isinstance(offset, list)
                    and len(offset) >= 3
                    and all(abs(int(offset[i])) <= normalized_max_abs_offset[i] for i in range(3))
                )
            lookups.append(row)
        site["active_member_saved_lookup"] = lookups
        site["active_members_all_found_in_saved_overmap"] = bool(active_ids) and all(
            bool(row.get("found_in_saved_overmap")) for row in lookups
        )
        if normalized_max_abs_offset is not None:
            site["active_members_within_required_max_abs_offset_ms"] = bool(active_ids) and all(
                bool(row.get("within_required_max_abs_offset_ms")) for row in lookups
            )
        site["position_exposure_footing"] = {
            "player_location_ms": player_location_ms,
            "player_abs_omt": player_abs_omt,
            "active_member_offsets_ms": [row.get("offset_ms", []) for row in lookups if row.get("found_in_saved_overmap")],
            "named_footing": "saved active members are cross-referenced against overmap NPC records near the loaded player position before visible-turn sight-avoid proof",
        }

    required_profile = str(required_profile or "").strip()
    required_site_id_contains = str(required_site_id_contains or "").strip()
    normalized_active_group_id_exact = None if required_active_group_id_exact is None else str(required_active_group_id_exact)
    required_active_group_id_contains = str(required_active_group_id_contains or "").strip()
    normalized_active_target_id_exact = None if required_active_target_id_exact is None else str(required_active_target_id_exact)
    required_active_target_id_prefix = str(required_active_target_id_prefix or "").strip()
    required_active_target_id_contains = str(required_active_target_id_contains or "").strip()
    required_active_job_type = str(required_active_job_type or "").strip()
    required_active_outing_kind = str(required_active_outing_kind or "").strip()
    required_active_outing_activity_id_contains = str(
        required_active_outing_activity_id_contains or ""
    ).strip()
    required_active_outing_simulation_owner = str(
        required_active_outing_simulation_owner or ""
    ).strip()
    required_active_outing_phase = str(required_active_outing_phase or "").strip()
    required_active_hostile_operation_kind = str(
        required_active_hostile_operation_kind or ""
    ).strip()
    required_active_hostile_operation_phase = str(
        required_active_hostile_operation_phase or ""
    ).strip()
    required_active_hostile_reservation_job_type = str(
        required_active_hostile_reservation_job_type or ""
    ).strip()
    normalized_active_hostile_reservation_target_id_exact = (
        None
        if required_active_hostile_reservation_target_id_exact is None
        else str(required_active_hostile_reservation_target_id_exact)
    )
    required_active_hostile_reservation_simulation_owner = str(
        required_active_hostile_reservation_simulation_owner or ""
    ).strip()
    required_local_handoff_state = str(required_local_handoff_state or "").strip()
    required_scout_report_source_activity_id = str(
        required_scout_report_source_activity_id or ""
    ).strip()
    normalized_scout_report_carrier_ids = (
        [int(value) for value in required_scout_report_exact_carrier_ids]
        if required_scout_report_exact_carrier_ids is not None else None
    )
    normalized_local_handoff_route_position: Optional[List[int]] = None
    if required_local_handoff_route_position is not None:
        if len(required_local_handoff_route_position) < 3:
            raise RuntimeError("required_local_handoff_route_position needs [x,y,z]")
        normalized_local_handoff_route_position = [
            int(required_local_handoff_route_position[0]),
            int(required_local_handoff_route_position[1]),
            int(required_local_handoff_route_position[2]),
        ]
    required_remembered_target_or_mark_prefix = str(required_remembered_target_or_mark_prefix or "").strip()
    required_remembered_pressure = str(required_remembered_pressure or "").strip()
    required_lead_source_contains = str(required_lead_source_contains or "").strip()
    required_lead_kind = str(required_lead_kind or "").strip()
    required_lead_origin = str(required_lead_origin or "").strip()
    required_all_lead_origin = str(required_all_lead_origin or "").strip()
    required_lead_target_id = str(required_lead_target_id or "").strip()
    required_lead_target_id_prefix = str(required_lead_target_id_prefix or "").strip()
    required_lead_status = str(required_lead_status or "").strip()
    required_lead_last_outcome = str(required_lead_last_outcome or "").strip()
    required_known_recent_mark_contains = str(required_known_recent_mark_contains or "").strip()
    required_retirement_summary_contains = str(required_retirement_summary_contains or "").strip()
    required_empty_retirement_blocker_contains = str(required_empty_retirement_blocker_contains or "").strip()
    required_camp_decision_state = str(required_camp_decision_state or "").strip()

    def site_matches(site: Dict[str, Any]) -> bool:
        if required_profile and site.get("hostile_profile") != required_profile:
            return False
        if required_site_id_contains and required_site_id_contains not in str(site.get("site_id", "")):
            return False
        if normalized_active_group_id_exact is not None and str(site.get("active_group_id", "")) != normalized_active_group_id_exact:
            return False
        if required_active_group_id_contains and required_active_group_id_contains not in str(site.get("active_group_id", "")):
            return False
        if normalized_active_target_id_exact is not None and str(site.get("active_target_id", "")) != normalized_active_target_id_exact:
            return False
        if required_active_target_id_prefix and not str(site.get("active_target_id", "")).startswith(required_active_target_id_prefix):
            return False
        if required_active_target_id_contains and required_active_target_id_contains not in str(site.get("active_target_id", "")):
            return False
        if required_active_job_type and site.get("active_job_type") != required_active_job_type:
            return False
        if required_active_sortie_started_minutes is not None and int(site.get("active_sortie_started_minutes", -1) or -1) != required_active_sortie_started_minutes:
            return False
        if required_active_sortie_local_contact_minutes is not None and int(site.get("active_sortie_local_contact_minutes", -1) or -1) != required_active_sortie_local_contact_minutes:
            return False
        active_outing = site.get("active_outing", {})
        if not isinstance(active_outing, dict):
            active_outing = {}
        local_handoff = active_outing.get("local_handoff", {})
        if not isinstance(local_handoff, dict):
            local_handoff = {}
        local_return_eligibility = active_outing.get("local_return_eligibility", {})
        if not isinstance(local_return_eligibility, dict):
            local_return_eligibility = {}
        if required_active_outing_kind and str(active_outing.get("kind", "")) != required_active_outing_kind:
            return False
        if required_active_outing_activity_id_contains and required_active_outing_activity_id_contains not in str(active_outing.get("activity_id", "")):
            return False
        if required_active_outing_generation is not None and int(active_outing.get("generation", 0)) != required_active_outing_generation:
            return False
        if required_active_outing_simulation_owner and str(active_outing.get("simulation_owner", "")) != required_active_outing_simulation_owner:
            return False
        if required_active_outing_handoff_epoch is not None and int(active_outing.get("handoff_epoch", 0)) != required_active_outing_handoff_epoch:
            return False
        if required_active_outing_phase and str(active_outing.get("phase", "")) != required_active_outing_phase:
            return False
        if required_active_outing_waypoint_index is not None and int(active_outing.get("waypoint_index", -1)) != required_active_outing_waypoint_index:
            return False
        if required_active_outing_last_advanced_minutes is not None and int(active_outing.get("last_advanced_minutes", -1)) != required_active_outing_last_advanced_minutes:
            return False
        if required_active_outing_exact_pair is not None and bool(active_outing.get("exact_pair_with_leader", False)) != required_active_outing_exact_pair:
            return False
        if required_active_outing_pair_contract is not None and bool(active_outing.get("pair_contract_valid", False)) != required_active_outing_pair_contract:
            return False
        active_hostile_operation = site.get("active_hostile_operation", {})
        if not isinstance(active_hostile_operation, dict):
            active_hostile_operation = {}
        hostile_reservation = active_hostile_operation.get("reservation", {})
        if not isinstance(hostile_reservation, dict):
            hostile_reservation = {}
        if required_active_hostile_operation_kind and str(
                active_hostile_operation.get("operation_kind", "")) != required_active_hostile_operation_kind:
            return False
        if required_active_hostile_operation_phase and str(
                active_hostile_operation.get("phase", "")) != required_active_hostile_operation_phase:
            return False
        if required_active_hostile_reservation_job_type and str(
                hostile_reservation.get("job_type", "")) != required_active_hostile_reservation_job_type:
            return False
        if normalized_active_hostile_reservation_target_id_exact is not None and str(
                hostile_reservation.get("target_id", "")) != normalized_active_hostile_reservation_target_id_exact:
            return False
        if required_active_hostile_reservation_simulation_owner and str(
                hostile_reservation.get("simulation_owner", "")) != required_active_hostile_reservation_simulation_owner:
            return False
        if required_active_hostile_reservation_min_member_ids is not None and int(
                hostile_reservation.get("member_count", 0) or 0) < required_active_hostile_reservation_min_member_ids:
            return False
        if required_local_handoff_state and str(local_handoff.get("state", "")) != required_local_handoff_state:
            return False
        if required_local_handoff_exact_pair is not None and bool(local_handoff.get("exact_pair", False)) != required_local_handoff_exact_pair:
            return False
        if required_local_handoff_pair_contract is not None and bool(local_handoff.get("pair_contract_valid", False)) != required_local_handoff_pair_contract:
            return False
        if required_local_handoff_cohesion_assembled is not None and bool(
                local_handoff.get("cohesion_assembled", False)) != required_local_handoff_cohesion_assembled:
            return False
        if required_local_return_eligibility_valid is not None and bool(
                local_return_eligibility.get("valid", False)) != required_local_return_eligibility_valid:
            return False
        if required_local_return_eligibility_cohesion_assembled is not None and bool(
                local_return_eligibility.get("cohesion_assembled", False)) != \
                required_local_return_eligibility_cohesion_assembled:
            return False
        if required_local_handoff_cohesion_abort_return is not None and bool(
                local_handoff.get("cohesion_abort_return", False)) != required_local_handoff_cohesion_abort_return:
            return False
        if normalized_local_handoff_route_position is not None and list(
                local_handoff.get("route_position", [])) != normalized_local_handoff_route_position:
            return False
        if required_member_count is not None and int(site.get("member_count", 0) or 0) != required_member_count:
            return False
        if required_ready_at_home_count is not None and int(site.get("ready_at_home_count", 0) or 0) != required_ready_at_home_count:
            return False
        if required_min_ready_at_home_count is not None and int(site.get("ready_at_home_count", 0) or 0) < required_min_ready_at_home_count:
            return False
        if required_min_home_survivor_count is not None and int(site.get("home_survivor_count", 0) or 0) < required_min_home_survivor_count:
            return False
        if required_wounded_or_unready_count is not None and int(site.get("wounded_or_unready_count", 0) or 0) != required_wounded_or_unready_count:
            return False
        if required_active_outside_count is not None and int(site.get("active_outside_count", 0) or 0) != required_active_outside_count:
            return False
        if required_home_side_signal_count is not None and int(site.get("home_side_signal_count", 0) or 0) != required_home_side_signal_count:
            return False
        if required_retired_empty_site is not None and bool(site.get("retired_empty_site", False)) != required_retired_empty_site:
            return False
        if required_retirement_summary_contains and required_retirement_summary_contains not in str(site.get("retirement_summary", "")):
            return False
        if required_empty_retirement_blocker_contains:
            blockers = site.get("empty_site_retirement_blockers", [])
            if not isinstance(blockers, list) or required_empty_retirement_blocker_contains not in [str(blocker) for blocker in blockers]:
                return False
        scout_report = site.get("current_scout_report", {})
        if not isinstance(scout_report, dict):
            scout_report = {}
        if required_scout_report_present is not None and bool(scout_report.get("present", False)) != required_scout_report_present:
            return False
        if required_scout_report_provisional is not None and bool(scout_report.get("provisional", False)) != required_scout_report_provisional:
            return False
        if required_scout_report_min_observations is not None and int(scout_report.get("observation_count", 0) or 0) < required_scout_report_min_observations:
            return False
        if required_scout_report_source_activity_id and str(
                scout_report.get("source_activity_id", "")) != required_scout_report_source_activity_id:
            return False
        if required_scout_report_source_generation is not None and int(
                scout_report.get("source_generation", 0) or 0) != required_scout_report_source_generation:
            return False
        if normalized_scout_report_carrier_ids is not None and list(
                scout_report.get("carrier_ids", [])) != normalized_scout_report_carrier_ids:
            return False
        camp_decision = site.get("camp_decision", {})
        if not isinstance(camp_decision, dict):
            camp_decision = {}
        if required_camp_decision_state and str(camp_decision.get("state", "")) != required_camp_decision_state:
            return False
        if required_report_decision_identity_match is not None and bool(site.get("report_decision_identity_matches", False)) != required_report_decision_identity_match:
            return False
        if required_report_hostile_operation_claim_match is not None and bool(
                site.get("report_hostile_operation_claim_matches", False)) != required_report_hostile_operation_claim_match:
            return False
        if required_min_active_member_ids is not None and int(site.get("active_member_count", 0) or 0) < required_min_active_member_ids:
            return False
        if required_active_members_found and not bool(site.get("active_members_all_found_in_saved_overmap")):
            return False
        if normalized_max_abs_offset is not None and not bool(site.get("active_members_within_required_max_abs_offset_ms")):
            return False
        if required_remembered_target_or_mark_prefix and not str(site.get("remembered_target_or_mark", "")).startswith(required_remembered_target_or_mark_prefix):
            return False
        if required_remembered_pressure and str(site.get("remembered_pressure", "")) != required_remembered_pressure:
            return False
        lead_entries_required = any([
            required_min_leads is not None,
            required_max_leads is not None,
            required_all_lead_origin,
            required_lead_source_contains,
            required_lead_kind,
            required_lead_origin,
            required_lead_target_id,
            required_lead_target_id_prefix,
            required_lead_bounty is not None,
            required_lead_threat is not None,
            required_lead_times_harvested is not None,
            required_lead_last_checked_minutes_min is not None,
            required_lead_status,
            required_lead_last_outcome,
            required_lead_confidence is not None,
        ])
        if lead_entries_required and not bool(site.get("lead_entries_valid", False)):
            return False
        if required_min_leads is not None and int(site.get("lead_count", 0) or 0) < required_min_leads:
            return False
        if required_max_leads is not None and int(site.get("lead_count", 0) or 0) > required_max_leads:
            return False
        if required_all_lead_origin:
            leads = site.get("leads", [])
            if not isinstance(leads, list) or not leads or any(
                not isinstance(lead, dict)
                or str(lead.get("origin", "")) != required_all_lead_origin
                for lead in leads
            ):
                return False
        lead_requirements_present = any([
            required_lead_source_contains,
            required_lead_kind,
            required_lead_origin,
            required_lead_target_id,
            required_lead_target_id_prefix,
            required_lead_bounty is not None,
            required_lead_threat is not None,
            required_lead_times_harvested is not None,
            required_lead_last_checked_minutes_min is not None,
            required_lead_status,
            required_lead_last_outcome,
            required_lead_confidence is not None,
        ])
        if lead_requirements_present:
            leads = site.get("leads", [])

            def lead_matches(lead: Dict[str, Any]) -> bool:
                if required_lead_source_contains and not (
                    required_lead_source_contains in str(lead.get("source_key", ""))
                    or required_lead_source_contains in str(lead.get("source_summary", ""))
                    or required_lead_source_contains in str(lead.get("lead_id", ""))
                ):
                    return False
                if required_lead_kind and str(lead.get("kind", "")) != required_lead_kind:
                    return False
                if required_lead_origin and str(lead.get("origin", "")) != required_lead_origin:
                    return False
                if required_lead_target_id and str(lead.get("target_id", "")) != required_lead_target_id:
                    return False
                if required_lead_target_id_prefix and not str(lead.get("target_id", "")).startswith(required_lead_target_id_prefix):
                    return False
                if required_lead_bounty is not None and int(lead.get("bounty", 0) or 0) != required_lead_bounty:
                    return False
                if required_lead_threat is not None and int(lead.get("threat", 0) or 0) != required_lead_threat:
                    return False
                if required_lead_times_harvested is not None and int(lead.get("times_harvested", 0) or 0) != required_lead_times_harvested:
                    return False
                if required_lead_last_checked_minutes_min is not None and int(lead.get("last_checked_minutes", -1) or -1) < required_lead_last_checked_minutes_min:
                    return False
                if required_lead_status and str(lead.get("status", "")) != required_lead_status:
                    return False
                if required_lead_last_outcome and str(lead.get("last_outcome", "")) != required_lead_last_outcome:
                    return False
                if required_lead_confidence is not None and int(lead.get("confidence", 0) or 0) != required_lead_confidence:
                    return False
                return True

            if not isinstance(leads, list) or not any(
                lead_matches(lead) for lead in leads if isinstance(lead, dict)
            ):
                return False
        if required_known_recent_mark_contains:
            marks = site.get("known_recent_marks", [])
            if not isinstance(marks, list) or not any(
                required_known_recent_mark_contains in str(mark) for mark in marks
            ):
                return False
        return True

    required_fields = {
        "required_profile": required_profile,
        "required_site_id_contains": required_site_id_contains,
        "required_active_group_id_exact": normalized_active_group_id_exact,
        "required_active_group_id_contains": required_active_group_id_contains,
        "required_active_target_id_exact": normalized_active_target_id_exact,
        "required_active_target_id_prefix": required_active_target_id_prefix,
        "required_active_target_id_contains": required_active_target_id_contains,
        "required_active_job_type": required_active_job_type,
        "required_active_sortie_started_minutes": required_active_sortie_started_minutes,
        "required_active_sortie_local_contact_minutes": required_active_sortie_local_contact_minutes,
        "required_active_outing_kind": required_active_outing_kind,
        "required_active_outing_activity_id_contains": required_active_outing_activity_id_contains,
        "required_active_outing_generation": required_active_outing_generation,
        "required_active_outing_simulation_owner": required_active_outing_simulation_owner,
        "required_active_outing_handoff_epoch": required_active_outing_handoff_epoch,
        "required_active_outing_phase": required_active_outing_phase,
        "required_active_outing_waypoint_index": required_active_outing_waypoint_index,
        "required_active_outing_last_advanced_minutes": required_active_outing_last_advanced_minutes,
        "required_active_outing_exact_pair": required_active_outing_exact_pair,
        "required_active_outing_pair_contract": required_active_outing_pair_contract,
        "required_active_hostile_operation_kind": required_active_hostile_operation_kind,
        "required_active_hostile_operation_phase": required_active_hostile_operation_phase,
        "required_active_hostile_reservation_job_type": required_active_hostile_reservation_job_type,
        "required_active_hostile_reservation_target_id_exact": normalized_active_hostile_reservation_target_id_exact,
        "required_active_hostile_reservation_simulation_owner": required_active_hostile_reservation_simulation_owner,
        "required_active_hostile_reservation_min_member_ids": required_active_hostile_reservation_min_member_ids,
        "required_local_handoff_state": required_local_handoff_state,
        "required_local_handoff_exact_pair": required_local_handoff_exact_pair,
        "required_local_handoff_pair_contract": required_local_handoff_pair_contract,
        "required_local_handoff_cohesion_assembled": required_local_handoff_cohesion_assembled,
        "required_local_return_eligibility_valid": required_local_return_eligibility_valid,
        "required_local_return_eligibility_cohesion_assembled":
        required_local_return_eligibility_cohesion_assembled,
        "required_local_handoff_cohesion_abort_return": required_local_handoff_cohesion_abort_return,
        "required_local_handoff_route_position": normalized_local_handoff_route_position,
        "required_scout_report_source_activity_id": required_scout_report_source_activity_id,
        "required_scout_report_source_generation": required_scout_report_source_generation,
        "required_scout_report_exact_carrier_ids": normalized_scout_report_carrier_ids,
        "required_member_count": required_member_count,
        "required_ready_at_home_count": required_ready_at_home_count,
        "required_min_ready_at_home_count": required_min_ready_at_home_count,
        "required_min_home_survivor_count": required_min_home_survivor_count,
        "required_wounded_or_unready_count": required_wounded_or_unready_count,
        "required_active_outside_count": required_active_outside_count,
        "required_min_active_member_ids": required_min_active_member_ids,
        "required_active_members_found": required_active_members_found,
        "required_active_member_max_abs_offset_ms": normalized_max_abs_offset,
        "required_remembered_target_or_mark_prefix": required_remembered_target_or_mark_prefix,
        "required_remembered_pressure": required_remembered_pressure,
        "required_min_leads": required_min_leads,
        "required_max_leads": required_max_leads,
        "required_lead_source_contains": required_lead_source_contains,
        "required_lead_kind": required_lead_kind,
        "required_lead_origin": required_lead_origin,
        "required_all_lead_origin": required_all_lead_origin,
        "required_lead_target_id": required_lead_target_id,
        "required_lead_target_id_prefix": required_lead_target_id_prefix,
        "required_lead_bounty": required_lead_bounty,
        "required_lead_threat": required_lead_threat,
        "required_lead_times_harvested": required_lead_times_harvested,
        "required_lead_last_checked_minutes_min": required_lead_last_checked_minutes_min,
        "required_lead_status": required_lead_status,
        "required_lead_last_outcome": required_lead_last_outcome,
        "required_lead_confidence": required_lead_confidence,
        "required_known_recent_mark_contains": required_known_recent_mark_contains,
        "required_home_side_signal_count": required_home_side_signal_count,
        "required_retired_empty_site": required_retired_empty_site,
        "required_retirement_summary_contains": required_retirement_summary_contains,
        "required_empty_retirement_blocker_contains": required_empty_retirement_blocker_contains,
        "required_scout_report_present": required_scout_report_present,
        "required_scout_report_provisional": required_scout_report_provisional,
        "required_scout_report_min_observations": required_scout_report_min_observations,
        "required_camp_decision_state": required_camp_decision_state,
        "required_report_decision_identity_match": required_report_decision_identity_match,
        "required_report_hostile_operation_claim_match": required_report_hostile_operation_claim_match,
    }
    has_requirement = any(value not in (None, "", []) for value in required_fields.values())
    matching_sites = [site for site in observed_sites if site_matches(site)]
    missing_required_fields = [] if matching_sites or not has_requirement else [
        key for key, value in required_fields.items() if value not in (None, "", [])
    ]
    if has_requirement and matching_sites:
        status = "required_state_present"
    elif has_requirement:
        status = "required_state_missing"
    else:
        status = "scanned"

    stat = dimension_path.stat()
    return {
        "world": world_dir.name,
        "world_dir": str(world_dir),
        "dimension_path": str(dimension_path),
        "dimension_mtime_ns": int(stat.st_mtime_ns),
        "dimension_mtime_iso": datetime.fromtimestamp(float(stat.st_mtime)).isoformat(timespec="microseconds"),
        "version_line": version_line,
        "required_fields": required_fields,
        "player_save": selected_player_save,
        "player_location_ms": player_location_ms,
        "player_abs_omt": player_abs_omt,
        "active_member_scan_error": active_member_scan_error,
        "observed_site_count": len(observed_sites),
        "observed_matching_site_count": len(matching_sites),
        "matching_sites": matching_sites,
        "observed_sites": observed_sites,
        "missing_required_fields": missing_required_fields,
        "status": status,
    }



def debug_selection_key_moves_highlight(selection_key: str) -> bool:
    normalized = str(selection_key or "").strip().lower()
    return normalized in {
        "up",
        "down",
        "left",
        "right",
        "pageup",
        "pagedown",
        "home",
        "end",
    }


def debug_spawn_item(
    pid: int,
    *,
    item_query: str,
    count: int = 1,
    selection_key: str = "enter",
    delay_ms: int = 200,
    type_delay_ms: int = 20,
    menu_settle_seconds: float = 0.35,
    prompt_settle_seconds: float = 0.25,
    exit_menu: bool = True,
) -> None:
    if count <= 0:
        raise SystemExit("Item spawn count must be > 0")
    chosen_selection_key = str(selection_key or "enter").strip() or "enter"
    run_debug_menu_shortcut_path(
        pid,
        ["s", "w"],
        delay_ms=delay_ms,
        menu_settle_seconds=menu_settle_seconds,
    )
    apply_uilist_filter(
        pid,
        item_query,
        delay_ms=delay_ms,
        type_delay_ms=type_delay_ms,
        settle_seconds=prompt_settle_seconds,
    )
    peekaboo_press_sequence(pid, [chosen_selection_key], delay_ms=delay_ms)
    time.sleep(prompt_settle_seconds)

    if debug_selection_key_moves_highlight( chosen_selection_key ):
        peekaboo_press_sequence(pid, ["enter"], delay_ms=delay_ms)
        time.sleep(prompt_settle_seconds)

    if count == 1:
        peekaboo_press_sequence(pid, ["enter"], delay_ms=delay_ms)
        time.sleep(prompt_settle_seconds)
    else:
        fill_numeric_prompt(
            pid,
            count,
            delay_ms=delay_ms,
            type_delay_ms=type_delay_ms,
        )
    if exit_menu:
        peekaboo_press_sequence(pid, ["esc"], delay_ms=delay_ms)
        time.sleep(prompt_settle_seconds)


def debug_spawn_monster(
    pid: int,
    *,
    monster_query: str,
    target_keys: Optional[List[str]] = None,
    group_radius: int = 0,
    friendly: bool = False,
    hallucination: bool = False,
    delay_ms: int = 200,
    type_delay_ms: int = 20,
    menu_settle_seconds: float = 0.35,
    prompt_settle_seconds: float = 0.25,
    initial_settle_seconds: float = 5.0,
    exit_menu: bool = True,
) -> None:
    if group_radius < 0:
        raise SystemExit("Monster group radius cannot be negative")
    if initial_settle_seconds > 0:
        time.sleep(initial_settle_seconds)
    run_debug_menu_shortcut_path(
        pid,
        ["s", "m"],
        delay_ms=delay_ms,
        menu_settle_seconds=menu_settle_seconds,
    )
    apply_uilist_filter(
        pid,
        monster_query,
        delay_ms=delay_ms,
        type_delay_ms=type_delay_ms,
        settle_seconds=prompt_settle_seconds,
    )
    if friendly:
        peekaboo_press_sequence(pid, ["f"], delay_ms=delay_ms)
        time.sleep(prompt_settle_seconds)
    if hallucination:
        peekaboo_press_sequence(pid, ["h"], delay_ms=delay_ms)
        time.sleep(prompt_settle_seconds)
    if group_radius > 0:
        peekaboo_press_sequence(pid, ["i"] * group_radius, delay_ms=delay_ms)
        time.sleep(prompt_settle_seconds)
    peekaboo_press_sequence(pid, ["enter"], delay_ms=delay_ms)
    time.sleep(prompt_settle_seconds)
    if target_keys:
        peekaboo_press_sequence(pid, target_keys, delay_ms=delay_ms)
        time.sleep(prompt_settle_seconds)
    peekaboo_press_sequence(pid, ["enter"], delay_ms=delay_ms)
    time.sleep(prompt_settle_seconds)
    if exit_menu:
        peekaboo_press_sequence(pid, ["esc"], delay_ms=delay_ms)
        time.sleep(prompt_settle_seconds)


def debug_spawn_monster_intervention_receipt(
    *, creature_id: str, target_offset: Sequence[int], target_keys: Sequence[str],
    group_radius: int, friendly: bool, hallucination: bool, run_id: str,
    registry_authority: Mapping[str, Any], run_dir: Path,
) -> Dict[str, Any]:
    """Seal one zero-credit native debug-spawn setup intervention.

    This records the exact declared native menu transaction.  It deliberately
    does not turn setup into gameplay evidence; the later interruption receipt
    still has to prove the native result in this same run.
    """
    offset = list(target_offset)
    if not creature_id or len(offset) != 3 or any(not isinstance(value, int) for value in offset):
        raise SystemExit("debug_spawn_monster receipt needs an exact creature_id and integer target_offset")
    if group_radius != 0 or friendly or hallucination:
        raise SystemExit("exact hostile setup receipt requires one non-friendly, non-hallucinated native spawn")
    authority = dict(registry_authority) if isinstance(registry_authority, Mapping) else {}
    if authority.get("authority") != "registry" or not str(authority.get("authority_id", "")).strip():
        raise SystemExit("debug_spawn_monster setup receipt requires registry transaction authority")
    if not run_id:
        raise SystemExit("debug_spawn_monster setup receipt requires the current semantic run id")
    return {
        "artifact_kind": "native_debug_setup_intervention",
        "schema": "caol-native-debug-spawn-monster-receipt-v1",
        "run_id": run_id,
        "gameplay_credit": False,
        "intervention": "debug_spawn_monster",
        "creature_id": creature_id,
        "target_offset": offset,
        "spawn_count": 1,
        "native_receipt": {
            "accepted": True,
            "menu_path": ["}", "s", "m"],
            "target_keys": list(target_keys),
            "group_radius": group_radius,
            "friendly": friendly,
            "hallucination": hallucination,
        },
        "transaction_authority": {
            "authority": authority["authority"],
            "authority_id": str(authority["authority_id"]),
            "binding_id": str(authority.get("binding_id", "")),
            "source_sha256": str(authority.get("source_sha256", "")),
        },
        "cleanup_link": {
            "owner": "finalize_scenario_report",
            "run_dir": str(run_dir),
            "required": True,
        },
    }


