def assign_nearby_npc_to_camp_dialog(
    pid: int,
    *,
    npc_selector: str,
    interaction_keys: Optional[List[str]] = None,
    lets_talk_key: str = "b",
    assignment_keys: Optional[List[str]] = None,
    exit_dialog_keys: Optional[List[str]] = None,
    delay_ms: int = 200,
    stage_settle_seconds: float = 0.8,
) -> None:
    interaction_path = interaction_keys or ["C", "t"]
    lets_talk_path = [lets_talk_key] if lets_talk_key.strip() else []
    assignment_path = assignment_keys or ["d", "n", "a"]
    exit_path = exit_dialog_keys or ["q", "c"]

    for keys in [
        interaction_path,
        [npc_selector],
        lets_talk_path,
        assignment_path,
        exit_path,
    ]:
        if not keys:
            continue
        peekaboo_press_sequence(pid, keys, delay_ms=delay_ms)
        time.sleep(stage_settle_seconds)


def drive_native_follower_camp_dialog(
    pid: int,
    *,
    artifact_log: Optional[Path],
    delay_ms: int = 200,
    stage_settle_seconds: float = 1.0,
) -> Dict[str, Any]:
    """Drive only the lawful native follower-to-camp dialogue path.

    Random debug followers can open either the urgent mission greeting or the
    ordinary follower greeting.  Read the native topic trace after opening the
    conversation so the harness selects the matching response path instead of
    sending a fixed sequence into the wrong dialogue state.
    """
    def last_topic() -> str:
        if artifact_log is None or not artifact_log.exists():
            return ""
        try:
            lines = artifact_log.read_text(encoding="utf-8", errors="replace").splitlines()
        except OSError:
            return ""
        for line in reversed(lines):
            marker = "avatar::talk_to: opt topic="
            if marker in line:
                return line.split(marker, 1)[1].strip()
        return ""

    def send(keys: List[str]) -> None:
        peekaboo_press_sequence(pid, keys, delay_ms=delay_ms)
        time.sleep(stage_settle_seconds)

    send(["C"])
    send(["t"])
    root_topic = last_topic()
    mission_path = root_topic == "TALK_MISSION_DESCRIBE_URGENT"
    if mission_path:
        send(["b"])
        send(["a"])
    send(["d"])
    send(["n"])
    send(["a"])
    return {
        "root_topic": root_topic,
        "mission_repair_applied": mission_path,
        "dialog_path": ["C", "t"] + (["b", "a"] if mission_path else []) + ["d", "n", "a"],
        "artifact_log": str(artifact_log) if artifact_log is not None else "",
    }


def copy_file_if_exists(src: Path, dst: Path) -> None:
    if src.exists():
        ensure_dir(dst.parent)
        shutil.copy2(src, dst)


def filter_debug_log_text(text: str) -> str:
    lines = text.splitlines(keepends=True)
    filtered_lines: List[str] = []
    index = 0
    while index < len(lines):
        line = lines[index]
        if BACKTRACE_PREAMBLE_TEXT_PATTERN.search(line):
            continuation_index = index + 1
            while (
                continuation_index < len(lines)
                and not BACKTRACE_CONTINUATION_TEXT_PATTERN.search(lines[continuation_index])
            ):
                continuation_index += 1
            if continuation_index < len(lines):
                continuation = lines[continuation_index]
                if any(pattern.search(continuation) for pattern in IGNORABLE_DEBUG_LOG_PATTERNS):
                    index = continuation_index + 1
                    continue
                filtered_lines.extend(lines[index:continuation_index + 1])
                index = continuation_index + 1
                continue
            # An incomplete record is never silently ignored.  Streaming
            # callers retain it until a continuation arrives; final callers
            # preserve it as error evidence.
            filtered_lines.extend(lines[index:])
            break
        if any(pattern.search(line) for pattern in IGNORABLE_DEBUG_LOG_PATTERNS):
            index += 1
            continue
        filtered_lines.append(line)
        index += 1
    return "".join(filtered_lines)


def read_log_delta_chunk(
    src: Path,
    start_size: int,
    *,
    filter_debug_noise: bool = False,
    include_incomplete_line: bool = True,
) -> Dict[str, Any]:
    """Read a byte-offset log delta without losing split, unit-buffered lines.

    Cataclysm's debug stream may flush the severity, class, colon, and message
    through separate insertions.  Polling must therefore advance only through
    the last complete line.  Otherwise a split ``ERROR ... : message`` can be
    divided into two individually harmless-looking chunks and escape the gate.
    """

    report: Dict[str, Any] = {
        "text": "",
        "previous_size": max(0, int(start_size or 0)),
        "current_size": max(0, int(start_size or 0)),
        "raw_current_size": max(0, int(start_size or 0)),
        "unclassified_trailing_bytes": 0,
        "unclassified_trailing_text": "",
        "truncated": False,
    }
    if not src.exists():
        return report
    size = src.stat().st_size
    start_offset = max(0, int(start_size or 0))
    report["raw_current_size"] = size
    if size == start_offset:
        return report
    if size < start_offset:
        start_offset = 0
        report["previous_size"] = 0
        report["truncated"] = True
    with src.open("rb") as fh:
        # debug.log is rewritten/truncated on some live GUI restarts.  When that
        # happens the previous byte offset points past EOF; read the new file
        # from the beginning instead of silently returning an empty delta.
        fh.seek(start_offset)
        raw_data = fh.read()

    last_line_end = raw_data.rfind(b"\n")
    complete_length = last_line_end + 1 if last_line_end >= 0 else 0
    complete_data = raw_data[:complete_length]
    backtrace_preambles = list(BACKTRACE_PREAMBLE_BYTES_PATTERN.finditer(complete_data))
    if backtrace_preambles:
        last_preamble = backtrace_preambles[-1]
        if BACKTRACE_CONTINUATION_BYTES_PATTERN.search(complete_data, last_preamble.end()) is None:
            # Keep the entire record pending.  Whether a backtrace is ignorable
            # can only be decided from its eventual continued error line.
            complete_length = last_preamble.start()
    report["current_size"] = start_offset + complete_length
    report["unclassified_trailing_bytes"] = len(raw_data) - complete_length
    trailing_text = raw_data[complete_length:].decode("utf-8", errors="replace")
    if filter_debug_noise:
        trailing_text = filter_debug_log_text(trailing_text)
    report["unclassified_trailing_text"] = trailing_text
    selected = raw_data if include_incomplete_line else raw_data[:complete_length]
    data = selected.decode("utf-8", errors="replace")
    if filter_debug_noise:
        data = filter_debug_log_text(data)
    report["text"] = data
    return report


def read_log_delta(src: Path, start_size: int, *, filter_debug_noise: bool = False) -> str:
    return str(read_log_delta_chunk(
        src,
        start_size,
        filter_debug_noise=filter_debug_noise,
        include_incomplete_line=True,
    )["text"])


def read_filtered_log_delta(src: Path, start_size: int) -> str:
    return read_log_delta(src, start_size, filter_debug_noise=True)


def copy_filtered_debug_log_delta_if_exists(src: Path, start_size: int, dst: Path) -> None:
    data = read_filtered_log_delta(src, start_size)
    if not data:
        return
    ensure_dir(dst.parent)
    dst.write_text(data, encoding="utf-8")


def startup_error_log_lines(text: str) -> List[str]:
    return [
        line.strip()
        for line in text.splitlines()
        if STARTUP_ERROR_LOG_PATTERN.search(line)
    ]


def classify_unterminated_debug_tail(text: str) -> str:
    """Classify a no-newline debug tail without mistaking benign records for races."""

    if not text:
        return "none"
    if startup_error_log_lines(text):
        return "error_or_debug"
    tail_lines = [line.strip() for line in text.splitlines() if line.strip()]
    if tail_lines and all(BENIGN_DEBUG_LOG_PREFIX_PATTERN.search(line) for line in tail_lines):
        return "benign_info_or_warning"
    return "ambiguous_prefix"


def log_file_identity(path: Path) -> Dict[str, int]:
    try:
        stat = path.stat()
    except OSError:
        return {}
    return {
        "device": int(stat.st_dev),
        "inode": int(stat.st_ino),
    }


def log_file_identity_changed(expected: Optional[Dict[str, Any]], current: Dict[str, int]) -> bool:
    if not isinstance(expected, dict) or not expected or not current:
        return False
    try:
        return (
            int(expected.get("device", -1)) != current["device"]
            or int(expected.get("inode", -1)) != current["inode"]
        )
    except (TypeError, ValueError):
        return True


def parse_patrol_coords(raw: str) -> List[Dict[str, int]]:
    coords: List[Dict[str, int]] = []
    for x, y, z in PATROL_COORD_RE.findall(raw or ""):
        coords.append({"x": int(x), "y": int(y), "z": int(z)})
    return coords


def parse_patrol_clusters(raw: str) -> List[Dict[str, Any]]:
    clusters: List[Dict[str, Any]] = []
    for chunk in [part.strip() for part in str(raw or "").split(";") if part.strip()]:
        match = re.match(r"(?P<index>\d+)=\[(?P<body>.*)\]$", chunk)
        if not match:
            continue
        tiles = parse_patrol_coords(match.group("body"))
        clusters.append({
            "index": int(match.group("index")),
            "tile_count": len(tiles),
            "tiles": tiles,
        })
    return clusters


def summarize_patrol_artifacts(scenario_name: str, matched_lines: List[str]) -> Optional[Dict[str, Any]]:
    cache_summary: Optional[Dict[str, Any]] = None
    runtime_entries: List[Dict[str, Any]] = []

    for line in matched_lines:
        cache_match = PATROL_CACHE_RE.search(line)
        if cache_match and cache_summary is None:
            clusters = parse_patrol_clusters(cache_match.group("clusters"))
            cache_summary = {
                "camp": cache_match.group("camp"),
                "shift": cache_match.group("shift"),
                "alarm": cache_match.group("alarm") or "unknown",
                "workers": int(cache_match.group("workers")),
                "roster": int(cache_match.group("roster")),
                "active": int(cache_match.group("active")),
                "reserve": int(cache_match.group("reserve")),
                "cluster_count": len(clusters),
                "cluster_tile_count": sum(cluster["tile_count"] for cluster in clusters),
                "clusters": clusters,
                "raw_line": line,
            }
            continue

        runtime_match = PATROL_RUNTIME_RE.search(line)
        if runtime_match:
            route = parse_patrol_coords(runtime_match.group("route"))
            positions = parse_patrol_coords(runtime_match.group("pos"))
            targets = parse_patrol_coords(runtime_match.group("target"))
            runtime_entries.append({
                "worker": runtime_match.group("worker"),
                "behavior": runtime_match.group("behavior"),
                "position": positions[0] if positions else {},
                "target": targets[0] if targets else {},
                "route_length": len(route),
                "route": route,
                "raw_line": line,
            })

    if cache_summary is None and not runtime_entries:
        return None

    notes: List[str] = []
    if cache_summary is not None:
        workers = cache_summary["workers"]
        roster = cache_summary["roster"]
        active = cache_summary["active"]
        shift = cache_summary["shift"]
        alarm = cache_summary.get("alarm", "unknown")
        reserve = cache_summary["reserve"]
        cluster_count = cache_summary["cluster_count"]
        cluster_tile_count = cache_summary["cluster_tile_count"]
        off_shift = max(0, workers - roster)
        singleton_clusters = cluster_count > 0 and all(cluster["tile_count"] == 1 for cluster in cache_summary["clusters"])

        if singleton_clusters:
            notes.append(
                f"This fixture paints {cluster_count} disconnected one-tile patrol posts, so a lone active guard must circulate instead of occupying them all at once."
            )
        elif cluster_count == 1 and cluster_tile_count > 1:
            notes.append(
                f"This fixture paints one connected patrol cluster with {cluster_tile_count} patrol tiles, so multiple active guards can hold distinct squares inside the same cluster."
            )

        if off_shift > 0:
            notes.append(
                f"{workers} patrol-enabled worker(s) exist, but only {roster} are rostered on the {shift} shift, so {off_shift} remain off-shift before reserve is even counted."
            )
        else:
            notes.append(
                f"All {workers} patrol-enabled worker(s) are rostered on the {shift} shift for this packet."
            )

        if alarm == "true":
            notes.append(
                "Camp patrol alarm is active in this packet, so patrol-enabled workers may be pulled into the roster outside the normal shift split."
            )

        if reserve > 0:
            notes.append(
                f"{reserve} rostered guard(s) are in reserve for the current shift, which is why they are not expected to occupy a patrol tile unless an active guard drops out."
            )

        if active < cluster_count:
            notes.append(
                f"Only {active} active guard(s) cover {cluster_count} patrol post/group(s), so uncovered posts are expected between visits in this snapshot."
            )

    loop_workers = [entry for entry in runtime_entries if entry.get("behavior") == "loop"]
    if loop_workers:
        unique_loop_names = list(dict.fromkeys(entry["worker"] for entry in loop_workers))
        loop_names = ", ".join(unique_loop_names)
        loop_verb = "walks" if len(unique_loop_names) == 1 else "walk"
        longest_route = max(entry.get("route_length", 0) for entry in loop_workers)
        if longest_route > 0:
            notes.append(
                f"Loop behavior is live here: {loop_names} {loop_verb} a fixed {longest_route}-tile patrol route, so the paired runtime crops should show motion one dwell later."
            )
        else:
            notes.append(
                f"Loop behavior is live here: {loop_names} should move between the paired runtime crops instead of holding a single square."
            )

    hold_workers = [entry for entry in runtime_entries if entry.get("behavior") == "hold"]
    if hold_workers:
        unique_hold_names = list(dict.fromkeys(entry["worker"] for entry in hold_workers))
        hold_names = ", ".join(unique_hold_names)
        hold_verb = "keeps" if len(unique_hold_names) == 1 else "keep"
        notes.append(
            f"Hold behavior is live here: {hold_names} {hold_verb} their assigned patrol squares, so the paired runtime crops should stay visually unchanged apart from UI noise."
        )

    return {
        "kind": "camp_patrol_summary",
        "scenario": scenario_name,
        "cache": cache_summary,
        "runtime_workers": runtime_entries,
        "player_legibility_notes": notes,
    }


def write_patrol_summary(run_dir: Path, patrol_summary: Dict[str, Any]) -> Dict[str, Any]:
    cache_summary = patrol_summary.get("cache") or {}
    runtime_workers = patrol_summary.get("runtime_workers") or []
    lines = [
        f"Patrol packet explainer: {patrol_summary.get('scenario', '')}",
        "",
    ]

    if cache_summary:
        shift = cache_summary.get("shift", "?")
        alarm = cache_summary.get("alarm", "unknown")
        workers = int(cache_summary.get("workers", 0))
        roster = int(cache_summary.get("roster", 0))
        active = int(cache_summary.get("active", 0))
        reserve = int(cache_summary.get("reserve", 0))
        off_shift = max(0, workers - roster)
        cluster_count = int(cache_summary.get("cluster_count", 0))
        cluster_tile_count = int(cache_summary.get("cluster_tile_count", 0))
        lines.extend([
            f"- shift: {shift}",
            f"- alarm active: {alarm}",
            f"- patrol-enabled workers: {workers}",
            f"- this-shift roster: {roster} total = {active} active + {reserve} reserve + {off_shift} off-shift",
            f"- patrol layout: {cluster_count} cluster(s) across {cluster_tile_count} painted patrol tile(s)",
            "",
        ])

    if runtime_workers:
        lines.append("Runtime workers:")
        for entry in runtime_workers:
            target = entry.get("target") or {}
            lines.append(
                f"- {entry.get('worker', '?')}: {entry.get('behavior', '?')} target=({target.get('x', '?')},{target.get('y', '?')},{target.get('z', '?')}) route_len={entry.get('route_length', 0)}"
            )
        lines.append("")

    lines.append("Read this packet as:")
    for note in patrol_summary.get("player_legibility_notes", []):
        lines.append(f"- {note}")

    summary_path = run_dir / "probe.patrol_summary.txt"
    summary_path.write_text("\n".join(lines).rstrip() + "\n", encoding="utf-8")
    return {
        "kind": "camp_patrol_summary",
        "path": str(summary_path),
        "summary": patrol_summary,
    }


def resolve_artifact_source(profile: str, source: str) -> Tuple[Path, bool, str]:
    normalized = source.strip().lower() if source else "debug.log"
    if normalized in {"debug", "debug.log"}:
        return config_dir_for_profile(profile) / "debug.log", True, "debug.log"
    if normalized in {"llm", "llm_intent", "llm_intent.log"}:
        return repo_root() / "config" / "llm_intent.log", False, "llm_intent.log"
    if normalized in {"llm_events", "llm_intent_events", "llm_intent_events.log"}:
        return repo_root() / "config" / "llm_intent_events.log", False, "llm_intent_events.log"
    raise SystemExit(f"Unsupported artifact source: {source}")


def capture_debug_delta(
    profile: str,
    start_size: int,
    run_dir: Path,
    serial: int,
    *,
    include_incomplete_line: bool = False,
    artifact_name: str = "",
    expected_identity: Optional[Dict[str, Any]] = None,
) -> Dict[str, Any]:
    debug_log = config_dir_for_profile(profile) / "debug.log"
    current_identity = log_file_identity(debug_log)
    identity_changed = log_file_identity_changed(expected_identity, current_identity)
    effective_start_size = 0 if identity_changed else start_size
    report: Dict[str, Any] = {
        "previous_size": effective_start_size,
        "current_size": effective_start_size,
        "raw_current_size": effective_start_size,
        "unclassified_trailing_bytes": 0,
        "unclassified_trailing_text": "",
        "tail_classification": "none",
        "artifact_path": "",
        "error_evidence_lines": [],
        "expected_identity": expected_identity or {},
        "current_identity": current_identity,
        "identity_changed": identity_changed,
    }
    if not debug_log.exists():
        return report
    chunk = read_log_delta_chunk(
        debug_log,
        effective_start_size,
        filter_debug_noise=True,
        include_incomplete_line=include_incomplete_line,
    )
    report.update({
        "previous_size": int(chunk.get("previous_size", effective_start_size) or 0),
        "current_size": int(chunk.get("current_size", effective_start_size) or 0),
        "raw_current_size": int(chunk.get("raw_current_size", effective_start_size) or 0),
        "unclassified_trailing_bytes": int(chunk.get("unclassified_trailing_bytes", 0) or 0),
        "unclassified_trailing_text": str(chunk.get("unclassified_trailing_text", "")),
        "truncated": bool(chunk.get("truncated", False)),
    })
    data = str(chunk.get("text", ""))
    report["tail_classification"] = classify_unterminated_debug_tail(
        report["unclassified_trailing_text"]
    )
    if not data:
        return report
    out = run_dir / (artifact_name or f"debug_delta_{serial:02d}.log")
    out.write_text(data, encoding="utf-8")
    report["artifact_path"] = str(out)
    report["error_evidence_lines"] = startup_error_log_lines(data)
    return report


def capture_stable_final_debug_delta(
    profile: str,
    start_size: int,
    run_dir: Path,
    serial: int,
    *,
    artifact_name: str,
    max_attempts: int = 20,
    retry_seconds: float = 0.05,
    expected_identity: Optional[Dict[str, Any]] = None,
) -> Dict[str, Any]:
    """Boundedly resolve an ambiguous unit-buffered final log prefix."""

    attempts = max(1, int(max_attempts))
    report: Dict[str, Any] = {}
    for attempt in range(1, attempts + 1):
        report = capture_debug_delta(
            profile,
            start_size,
            run_dir,
            serial,
            include_incomplete_line=True,
            artifact_name=artifact_name,
            expected_identity=expected_identity,
        )
        tail_classification = str(report.get("tail_classification", "none"))
        report["stable_tail_attempts"] = attempt
        if tail_classification != "ambiguous_prefix":
            report["tail_classified"] = True
            if tail_classification in {"none", "benign_info_or_warning"}:
                report["current_size"] = int(report.get("raw_current_size", start_size) or 0)
            return report
        if attempt < attempts and retry_seconds > 0:
            time.sleep(retry_seconds)
    report["tail_classified"] = False
    report["tail_classification"] = "ambiguous_after_retry"
    return report


def extract_window_build_info(window_title: str) -> Dict[str, Any]:
    info: Dict[str, Any] = {
        "window_title": window_title,
        "captured_head": "",
        "captured_dirty": False,
    }
    match = re.search(r" - ([0-9a-f]{10,40})(-dirty)?(?:\+[^ ]+)?$", window_title or "")
    if not match:
        return info
    info["captured_head"] = match.group(1)
    info["captured_dirty"] = bool(match.group(2))
    return info


def populate_runtime_version_comparison(
    summary: Dict[str, Any],
    *,
    runtime_binding: Optional[Dict[str, Any]] = None,
) -> None:
    captured_head = str(summary.get("captured_head", "") or "").strip()
    repo_head = str(summary.get("repo_head", "") or "").strip()
    summary["runtime_relevant_diff_since_capture"] = []
    summary["runtime_relevant_worktree_diff"] = []
    summary["runtime_compare_error"] = ""
    summary["runtime_worktree_compare_error"] = ""
    summary["runtime_binding_status"] = "not_requested"
    summary["runtime_binding_error"] = ""
    if not captured_head:
        summary["runtime_compare_error"] = "captured head is missing from the window title"
        return

    summary["version_matches_repo_head"] = bool(
        repo_head and captured_head.startswith(repo_head)
    )
    runtime_changes, runtime_error = runtime_relevant_changes_since(captured_head)
    worktree_changes, worktree_error = runtime_relevant_worktree_changes()
    summary["runtime_relevant_diff_since_capture"] = runtime_changes
    summary["runtime_relevant_worktree_diff"] = worktree_changes
    summary["runtime_compare_error"] = runtime_error
    summary["runtime_worktree_compare_error"] = worktree_error
    if runtime_error or worktree_error:
        return
    if runtime_binding is not None:
        binding_result = compare_runtime_binding(runtime_binding)
        summary["runtime_binding_status"] = binding_result["status"]
        summary["runtime_binding_error"] = binding_result.get("error", "")
        summary["runtime_binding_observed"] = binding_result
        # The title identifies the executable's compiled product baseline.  A
        # current harness may legitimately be ahead of that baseline when no
        # product-binary input changed; the executable-source readiness check
        # keeps that case bound to the actual product paths instead of making
        # the title's older commit look like a route failure.
        expected_head = str(runtime_binding.get("captured_head", "") or "").strip()
        title_matches_binding_head = bool(
            expected_head and captured_head and expected_head.startswith(captured_head)
        )
        executable_path = Path(str(runtime_binding.get("executable_path", "")).strip())
        source_readiness = executable_source_readiness(executable_path) if executable_path else {}
        summary["source_executable_readiness"] = source_readiness
        summary["version_matches_runtime_paths"] = bool(
            binding_result["status"] == "matched" and
            (title_matches_binding_head or source_readiness.get("status") == "ready")
        )
    else:
        # A dirty executable is never trusted from the title alone.  It needs
        # the per-run binding above; clean source/binary remains the legacy
        # title-plus-Git path comparison.
        summary["version_matches_runtime_paths"] = bool(
            not summary.get("captured_dirty") and not (runtime_changes or worktree_changes)
        )


def window_area(window: Dict[str, Any]) -> int:
    bounds = window.get("bounds")
    if not isinstance(bounds, list) or len(bounds) != 2:
        return 0
    top_left, size = bounds
    if not isinstance(top_left, list) or not isinstance(size, list) or len(size) != 2:
        return 0
    try:
        width = max(0, int(size[0]))
        height = max(0, int(size[1]))
    except (TypeError, ValueError):
        return 0
    return width * height


def list_windows_for_pid(pid: int) -> List[Dict[str, Any]]:
    payload = run_json(
        peekaboo_command(
            ["list", "windows", "--json", "--app", f"PID:{pid}"],
            channel="capture",
        ),
        check=False,
        timeout_seconds=5.0,
    )
    if not isinstance(payload, dict):
        return []
    if payload.get("timeout"):
        return []
    data = payload.get("data", {}) if isinstance(payload.get("data"), dict) else {}
    windows = data.get("windows", [])
    if not isinstance(windows, list):
        return []
    return [window for window in windows if isinstance(window, dict)]


def choose_capture_window(pid: int) -> Dict[str, Any]:
    windows = list_windows_for_pid(pid)
    if not windows:
        return {}

    def capture_rank(window: Dict[str, Any]) -> Tuple[int, int, int, int, int]:
        title = str(window.get("title", "")).strip()
        return (
            1 if bool(window.get("isOnScreen", False)) else 0,
            1 if not bool(window.get("isMinimized", False)) else 0,
            1 if title else 0,
            1 if "cataclysm" in title.lower() else 0,
            window_area(window),
        )

    return max(windows, key=capture_rank)


def peekaboo_capture_diagnostics(payload: Dict[str, Any]) -> Dict[str, Any]:
    warnings: List[str] = []
    data = payload.get("data", {}) if isinstance(payload.get("data"), dict) else {}
    observations = data.get("observations", []) if isinstance(data.get("observations"), list) else []
    for observation in observations:
        if not isinstance(observation, dict):
            continue
        raw_warnings = observation.get("warnings", [])
        if not isinstance(raw_warnings, list):
            continue
        for warning in raw_warnings:
            text = str(warning).strip()
            if text and text not in warnings:
                warnings.append(text)

    debug_logs = [
        str(entry).strip()
        for entry in payload.get("debug_logs", [])
        if str(entry).strip()
    ] if isinstance(payload.get("debug_logs"), list) else []
    runtime_host = next(
        (entry for entry in debug_logs if "Runtime host:" in entry),
        "",
    )
    return {
        "capture_warnings": warnings,
        "peekaboo_debug_logs": debug_logs,
        "peekaboo_runtime_host": runtime_host,
    }


def summarize_peekaboo_image_capture(
    stdout: str,
    png_path: Path,
    json_path: Path,
    capture_target: Optional[Dict[str, Any]] = None,
    *,
    stderr: str = "",
    command: Optional[Sequence[str]] = None,
    returncode: int = 0,
) -> Dict[str, Any]:
    repo_head = current_head_short()
    summary: Dict[str, Any] = {
        "png_path": str(png_path),
        "peekaboo_json": str(json_path),
        "repo_head": repo_head,
        "peekaboo_success": False,
        "window_title": "",
        "window_id": 0,
        "window_index": None,
        "captured_head": "",
        "captured_dirty": False,
        "version_matches_repo_head": None,
        "version_matches_runtime_paths": None,
        "runtime_relevant_paths": list(RUNTIME_RELEVANT_PATHS),
        "runtime_relevant_diff_since_capture": [],
        "runtime_relevant_worktree_diff": [],
        "runtime_compare_error": "",
        "runtime_worktree_compare_error": "",
        "parse_error": "",
        "peekaboo_command": list(command or []),
        "peekaboo_returncode": returncode,
        "peekaboo_stderr": stderr,
        "capture_warnings": [],
        "peekaboo_debug_logs": [],
        "peekaboo_runtime_host": "",
    }
    if not stdout.strip():
        summary["parse_error"] = "peekaboo produced no JSON stdout"
        return summary
    try:
        payload = json.loads(stdout)
    except Exception as exc:
        summary["parse_error"] = str(exc)
        return summary
    if not isinstance(payload, dict):
        summary["parse_error"] = "peekaboo stdout was not a JSON object"
        return summary

    data = payload.get("data", {}) if isinstance(payload.get("data"), dict) else {}
    files = data.get("files", []) if isinstance(data.get("files"), list) else []
    first_file = files[0] if files and isinstance(files[0], dict) else {}
    summary["peekaboo_success"] = bool(payload.get("success"))
    summary["window_title"] = str(
        first_file.get("window_title")
        or (capture_target or {}).get("title", "")
    ).strip()
    try:
        summary["window_id"] = int(first_file.get("window_id") or (capture_target or {}).get("window_id") or 0)
    except (TypeError, ValueError):
        summary["window_id"] = 0
    summary["window_index"] = first_file.get("window_index", (capture_target or {}).get("index"))
    error_info = payload.get("error", {}) if isinstance(payload.get("error"), dict) else {}
    if not summary["peekaboo_success"] and error_info.get("message"):
        summary["parse_error"] = str(error_info.get("message", "")).strip()
    summary.update(peekaboo_capture_diagnostics(payload))
    build_info = extract_window_build_info(summary["window_title"])
    summary.update(build_info)
    populate_runtime_version_comparison(summary)
    return summary


def normalize_capture_crop(raw_crop: Any) -> Optional[Dict[str, int]]:
    if not isinstance(raw_crop, dict):
        return None
    try:
        height = int(raw_crop.get("height", raw_crop.get("pixels_h", 0)) or 0)
        width = int(raw_crop.get("width", raw_crop.get("pixels_w", 0)) or 0)
        offset_y = int(raw_crop.get("offset_y", raw_crop.get("top", raw_crop.get("y", 0))) or 0)
        offset_x = int(raw_crop.get("offset_x", raw_crop.get("left", raw_crop.get("x", 0))) or 0)
    except (TypeError, ValueError):
        return None
    if height <= 0 or width <= 0 or offset_y < 0 or offset_x < 0:
        return None
    return {
        "height": height,
        "width": width,
        "offset_y": offset_y,
        "offset_x": offset_x,
    }


def screen_capture_succeeded(screen_summary: Dict[str, Any]) -> bool:
    return bool(screen_summary.get("capture_success") or screen_summary.get("peekaboo_success"))


def fallback_screencapture(
    png_path: Path,
    capture_target: Optional[Dict[str, Any]] = None,
) -> Dict[str, Any]:
    screencapture_cmd = shutil.which("screencapture") or "/usr/sbin/screencapture"
    target = capture_target or {}
    attempts: List[Dict[str, Any]] = []
    command_variants: List[List[str]] = []
    if target.get("window_id"):
        command_variants.append([screencapture_cmd, "-x", "-l", str(target["window_id"]), str(png_path)])
    command_variants.append([screencapture_cmd, "-x", str(png_path)])

    for cmd in command_variants:
        proc = subprocess.run(
            cmd,
            capture_output=True,
            text=True,
            check=False,
        )
        attempt = {
            "command": cmd,
            "returncode": proc.returncode,
            "stdout": proc.stdout,
            "stderr": proc.stderr,
            "png_exists": png_path.exists(),
        }
        attempts.append(attempt)
        if proc.returncode == 0 and png_path.exists():
            return {
                "ok": True,
                "backend": "screencapture_window" if "-l" in cmd else "screencapture_fullscreen",
                "command": cmd,
                "attempts": attempts,
            }

    return {
        "ok": False,
        "backend": "screencapture",
        "attempts": attempts,
        "error": (attempts[-1].get("stderr") or attempts[-1].get("stdout") or "screencapture failed").strip() if attempts else "screencapture not attempted",
    }


def summarize_screencapture_image_capture(
    png_path: Path,
    fallback_report: Dict[str, Any],
    capture_target: Optional[Dict[str, Any]] = None,
) -> Dict[str, Any]:
    repo_head = current_head_short()
    summary: Dict[str, Any] = {
        "png_path": str(png_path),
        "peekaboo_json": "",
        "repo_head": repo_head,
        "peekaboo_success": False,
        "capture_success": bool(fallback_report.get("ok")),
        "capture_backend": str(fallback_report.get("backend", "screencapture")),
        "window_title": str((capture_target or {}).get("title", "")).strip(),
        "window_id": int((capture_target or {}).get("window_id") or 0),
        "window_index": (capture_target or {}).get("index"),
        "captured_head": "",
        "captured_dirty": False,
        "version_matches_repo_head": None,
        "version_matches_runtime_paths": None,
        "runtime_relevant_paths": list(RUNTIME_RELEVANT_PATHS),
        "runtime_relevant_diff_since_capture": [],
        "runtime_relevant_worktree_diff": [],
        "runtime_compare_error": "",
        "runtime_worktree_compare_error": "",
        "parse_error": str(fallback_report.get("error", "")),
        "peekaboo_command": [],
        "peekaboo_returncode": None,
        "peekaboo_stderr": "",
        "capture_warnings": [],
        "peekaboo_debug_logs": [],
        "peekaboo_runtime_host": "",
    }
    build_info = extract_window_build_info(summary["window_title"])
    summary.update(build_info)
    populate_runtime_version_comparison(summary)
    return summary


def crop_png_with_sips(source_path: Path, output_path: Path, crop: Dict[str, int]) -> Dict[str, Any]:
    cmd = [
        "sips",
        "-c",
        str(crop["height"]),
        str(crop["width"]),
        "--cropOffset",
        str(crop["offset_y"]),
        str(crop["offset_x"]),
        str(source_path),
        "--out",
        str(output_path),
    ]
    try:
        proc = subprocess.run(
            cmd,
            capture_output=True,
            text=True,
            check=False,
            timeout=10.0,
        )
    except subprocess.TimeoutExpired as exc:
        proc = subprocess.CompletedProcess(
            cmd,
            124,
            stdout=subprocess_output_text(exc.stdout),
            stderr=subprocess_output_text(exc.stderr) + "\nsips crop timed out",
        )
    return {
        "ok": proc.returncode == 0,
        "command": cmd,
        "returncode": proc.returncode,
        "stdout": proc.stdout,
        "stderr": proc.stderr,
        "source_png_path": str(source_path),
        "output_png_path": str(output_path),
        "crop": dict(crop),
    }


def capture_screenshot(
    pid: int,
    run_dir: Path,
    label: str,
    crop: Optional[Dict[str, int]] = None,
) -> Dict[str, Any]:
    png_path = run_dir / f"{label}.png"
    json_path = run_dir / f"{label}.peekaboo.json"
    capture_target = choose_capture_window(pid)
    cmd_args = ["image", "--json", "--path", str(png_path)]
    if capture_target.get("window_id"):
        cmd_args.extend(["--window-id", str(capture_target["window_id"])])
    else:
        cmd_args.extend(["--pid", str(pid)])
    cmd = peekaboo_command(cmd_args, channel="capture")
    try:
        proc = subprocess.run(
            cmd,
            capture_output=True,
            text=True,
            check=False,
            timeout=10.0,
        )
    except subprocess.TimeoutExpired as exc:
        proc = subprocess.CompletedProcess(
            cmd,
            124,
            stdout=subprocess_output_text(exc.stdout),
            stderr=subprocess_output_text(exc.stderr) + "\npeekaboo image timed out",
        )
    fallback_report: Optional[Dict[str, Any]] = None
    capture_ok = proc.returncode == 0 and png_path.exists()
    if not capture_ok:
        fallback_report = fallback_screencapture(png_path, capture_target=capture_target)
        capture_ok = bool(fallback_report.get("ok"))

    crop_request = normalize_capture_crop(crop)
    crop_report: Optional[Dict[str, Any]] = None
    if capture_ok and crop_request:
        full_png_path = run_dir / f"{label}.full.png"
        shutil.copy2(png_path, full_png_path)
        crop_report = crop_png_with_sips(full_png_path, png_path, crop_request)
        if not crop_report.get("ok"):
            shutil.copy2(full_png_path, png_path)
    if fallback_report and fallback_report.get("ok"):
        screen_summary = summarize_screencapture_image_capture(
            png_path,
            fallback_report,
            capture_target=capture_target,
        )
    else:
        screen_summary = summarize_peekaboo_image_capture(
            proc.stdout,
            png_path,
            json_path,
            capture_target=capture_target,
            stderr=proc.stderr,
            command=cmd,
            returncode=proc.returncode,
        )
        screen_summary["capture_success"] = bool(screen_summary.get("peekaboo_success"))
        screen_summary["capture_backend"] = "peekaboo"
    runtime_binding = load_runtime_binding(run_dir)
    if runtime_binding is not None:
        populate_runtime_version_comparison(screen_summary, runtime_binding=runtime_binding)
    # The semantic HUD verdict is attached to this exact capture target, never
    # merely to a same-run image that could have been taken before relaunch.
    screen_summary["capture_process_pid"] = pid
    screen_summary["peekaboo_command"] = list(cmd)
    screen_summary["peekaboo_returncode"] = proc.returncode
    screen_summary["peekaboo_stderr"] = proc.stderr
    if crop_report:
        screen_summary["crop_requested"] = crop_request
        screen_summary["crop_applied"] = bool(crop_report.get("ok"))
        screen_summary["source_png_path"] = str(crop_report.get("source_png_path", ""))
        if not crop_report.get("ok"):
            screen_summary["crop_error"] = str(crop_report.get("stderr", "")).strip()
    payload = {
        "label": label,
        "command": cmd,
        "capture_target": capture_target,
        "returncode": proc.returncode,
        "stdout": proc.stdout,
        "stderr": proc.stderr,
        "fallback": fallback_report,
        "crop": crop_report,
        "screen_summary": screen_summary,
    }
    json_path.write_text(json.dumps(payload, indent=2, ensure_ascii=False) + "\n", encoding="utf-8")
    return payload


def captured_window_identity(screen: Mapping[str, Any]) -> Dict[str, Any]:
    summary = screen.get("screen_summary", {}) if isinstance(screen, Mapping) else {}
    if not isinstance(summary, Mapping):
        return {}
    try:
        window_id = int(summary.get("window_id", 0) or 0)
    except (TypeError, ValueError):
        return {}
    title = str(summary.get("window_title", "") or "").strip()
    if not window_id or not title:
        return {}
    return {"window_id": window_id, "window_title": title}


def wait_for_remote_window_discovery(
    pid: int,
    run_dir: Path,
    *,
    deadline: float,
    poll_seconds: float,
    label: str,
) -> Dict[str, Any]:
    """Capture until the remote bridge identifies the new process's window."""
    attempts: List[Dict[str, Any]] = []
    serial = 1
    while True:
        screen = capture_screenshot(pid, run_dir, f"{label}.{serial}")
        identity = captured_window_identity(screen)
        attempts.append({"label": f"{label}.{serial}", "identity": identity})
        if identity:
            return {
                "ok": True,
                "screen": screen,
                "identity": identity,
                "attempts": attempts,
            }
        remaining_seconds = deadline - time.monotonic()
        if remaining_seconds <= 0:
            return {
                "ok": False,
                "screen": screen,
                "identity": {},
                "attempts": attempts,
                "error": "remote_window_identity_missing_before_startup_deadline",
            }
        time.sleep(min(poll_seconds, remaining_seconds))
        serial += 1


def reacquire_local_focus_after_remote_window_discovery(
    pid: int,
    run_dir: Path,
    remote_screen: Mapping[str, Any],
    *,
    label: str,
) -> Dict[str, Any]:
    """Require local PID focus only after the remote capture has named its window."""
    discovered = captured_window_identity(remote_screen)
    report: Dict[str, Any] = {
        "pid": pid,
        "remote_discovery": discovered,
        "focus": {},
        "reacquired_screen": {},
        "ok": False,
    }
    if not discovered:
        report["error"] = "remote_window_identity_missing"
        return report
    focus = peekaboo_focus_pid_with_retry(pid)
    report["focus"] = focus
    if not focus.get("ok"):
        report["error"] = "local_focus_after_remote_discovery_failed"
        return report
    reacquired_screen = capture_screenshot(pid, run_dir, label)
    observed = captured_window_identity(reacquired_screen)
    report["reacquired_screen"] = observed
    if observed != discovered:
        report["error"] = "remote_window_identity_changed_after_local_focus"
        return report
    report["ok"] = True
    return report


def run_screen_ocr(image_path: Path) -> Dict[str, Any]:
    script_path = repo_root() / "tools" / "openclaw_harness" / "ocr_image.swift"
    if not script_path.exists():
        return {
            "ok": False,
            "error": f"OCR helper script not found: {script_path}",
            "image_path": str(image_path),
        }

    swift_cmd = shutil.which("swift")
    if not swift_cmd:
        return {
            "ok": False,
            "error": "swift executable not found in PATH",
            "image_path": str(image_path),
        }

    cmd = [swift_cmd, str(script_path), "--image", str(image_path)]
    try:
        proc = subprocess.run(
            cmd,
            capture_output=True,
            text=True,
            check=False,
            timeout=30.0,
        )
    except subprocess.TimeoutExpired as exc:
        return {
            "ok": False,
            "error": "OCR helper timed out after 30 seconds",
            "image_path": str(image_path),
            "stdout": subprocess_output_text(exc.stdout),
            "stderr": subprocess_output_text(exc.stderr),
        }
    if proc.returncode != 0:
        return {
            "ok": False,
            "error": (proc.stderr or proc.stdout).strip() or f"swift exited with {proc.returncode}",
            "image_path": str(image_path),
        }

    try:
        payload = json.loads(proc.stdout)
    except Exception as exc:
        return {
            "ok": False,
            "error": f"failed to parse OCR JSON: {exc}",
            "image_path": str(image_path),
            "stdout": proc.stdout,
        }

    if not isinstance(payload, dict):
        return {
            "ok": False,
            "error": "OCR helper did not return a JSON object",
            "image_path": str(image_path),
        }
    return payload


def startup_screen_probe_classification(
    *,
    ocr_payload: Dict[str, Any],
    capture_warnings: Sequence[str],
    debug_delta_text: str,
    gameplay_hud_run_id: str = "",
) -> Dict[str, Any]:
    raw_lines = ocr_payload.get("lines", []) if isinstance(ocr_payload, dict) else []
    lines = [str(line).strip() for line in raw_lines if str(line).strip()] if isinstance(raw_lines, list) else []
    screen_text = "\n".join(lines)

    error_markers = [
        pattern.pattern
        for pattern in STARTUP_ERROR_SCREEN_PATTERNS
        if pattern.search(screen_text)
    ]
    body_markers = [
        line
        for line in lines
        if any(pattern.search(line) for pattern in STARTUP_HUD_BODY_PATTERNS)
    ]
    status_markers = [
        line
        for line in lines
        if any(pattern.search(line) for pattern in STARTUP_HUD_STATUS_PATTERNS)
    ]
    body_marker_types = [
        pattern.pattern
        for pattern in STARTUP_HUD_BODY_PATTERNS
        if pattern.search(screen_text)
    ]
    status_marker_types = [
        pattern.pattern
        for pattern in STARTUP_HUD_STATUS_PATTERNS
        if pattern.search(screen_text)
    ]
    if (not body_marker_types and re.search(r"\bhctivitu\s*:", screen_text, re.IGNORECASE)
            and re.search(r"\bvery\s+thirsty\b", screen_text, re.IGNORECASE)):
        # OCR can retain only the activity/status column at this scale; the
        # paired visible need-state line is still a concrete gameplay HUD.
        body_marker_types.append("hud_activity_need_state_fallback")
    if not body_marker_types:
        rendered_hud = False
        expected_run_id = str(gameplay_hud_run_id).strip()
        for match in GAMEPLAY_HUD_TRACE_PATTERN.finditer(debug_delta_text):
            try:
                observed_run_id = json.loads(match.group(1))
            except (TypeError, ValueError, json.JSONDecodeError):
                continue
            if not isinstance(observed_run_id, str):
                continue
            if expected_run_id and observed_run_id != expected_run_id:
                continue
            if match.group(2) in GAMEPLAY_HUD_MOVE_WIDGETS and \
                    match.group(3) in GAMEPLAY_HUD_WIELD_WIDGETS:
                rendered_hud = True
                break
        if rendered_hud:
            # High-resolution macOS captures can intermittently lose every
            # tiny HUD label.  A native Move/Wield trace bound to this launch
            # proves that the current game rendered its gameplay HUD.  The
            # surrounding classifier still rejects native action/main-menu
            # overlays and visible errors, and foreign or malformed traces do
            # not reach this path.
            body_marker_types.append("native_rendered_hud_fallback")
            status_marker_types.append("native_rendered_hud_fallback")
            sidebar_columns = (
                re.search(r"\bactivit\w*\s*:", screen_text, re.IGNORECASE)
                and re.search(r"\blighting\s*:", screen_text, re.IGNORECASE)
            )
            if sidebar_columns:
                body_marker_types.append("native_rendered_hud_sidebar_fallback")
    blocking_overlay_markers = [
        line
        for line in lines
        if any(pattern.fullmatch(line) for pattern in STARTUP_BLOCKING_OVERLAY_PATTERNS)
    ]
    action_menu_events = STARTUP_ACTION_MENU_TRACE_PATTERN.findall(debug_delta_text)
    if action_menu_events and action_menu_events[-1] == "open":
        blocking_overlay_markers.append("native_action_menu_dispatch")
    if startup_main_menu_overlay_is_active( debug_delta_text ):
        blocking_overlay_markers.append("native_main_menu_overlay")
    blocking_overlay_present = bool(blocking_overlay_markers)
    gameplay_hud_present = (
        len(body_marker_types) >= 1
        and len(status_marker_types) >= 1
        and not blocking_overlay_present
    )
    debug_error_lines = startup_error_log_lines(debug_delta_text)
    normalized_warnings = [str(warning).strip() for warning in capture_warnings if str(warning).strip()]
    raw_black_capture_warning = any("solid black" in warning.lower() for warning in normalized_warnings)
    # Peekaboo's bridge can call Cataclysm's deliberately dark tiles canvas
    # "solid black" even when the delivered PNG contains the HUD and map.  A
    # warning alone is therefore not a capture verdict.  Treat it as a black
    # capture only when this exact image does not itself yield both required
    # HUD evidence classes.  Native render traces are intentionally excluded:
    # they prove the game rendered, not that this capture contained pixels.
    captured_hud_evidenced = bool(body_markers and status_markers)
    black_capture_warning = raw_black_capture_warning and not captured_hud_evidenced
    visible_error_popup = bool(error_markers)
    startup_error_logged = bool(debug_error_lines)

    if visible_error_popup:
        classification = "red_visible_error_popup"
    elif startup_error_logged:
        classification = "red_startup_error_logged"
    elif blocking_overlay_present:
        classification = "yellow_blocking_overlay_present"
    elif gameplay_hud_present:
        classification = "green_gameplay_hud_present"
    else:
        classification = "yellow_gameplay_hud_absent"
    return {
        "classification": classification,
        "gameplay_hud_present": gameplay_hud_present,
        "visible_error_popup": visible_error_popup,
        "startup_error_logged": startup_error_logged,
        "blocking_overlay_present": blocking_overlay_present,
        "blocking_overlay_markers": blocking_overlay_markers,
        "error_screen_markers": error_markers,
        "hud_body_markers": body_markers,
        "hud_body_marker_types": body_marker_types,
        "hud_status_markers": status_markers,
        "hud_status_marker_types": status_marker_types,
        "debug_error_lines": debug_error_lines,
        "capture_warnings": normalized_warnings,
        "raw_black_capture_warning": raw_black_capture_warning,
        "captured_hud_evidenced": captured_hud_evidenced,
        "black_capture_warning": black_capture_warning,
        "ocr_ok": bool(ocr_payload.get("ok")),
        "ocr_line_count": len(lines),
        "rule": "A clean startup needs at least one body label and one map-sidebar-only status label, with no blocking modal overlay; visible debug/error UI is red.",
    }


def capture_startup_screen_probe(
    run_dir: Path,
    label: str,
    screen_summary: Dict[str, Any],
    debug_delta_path: Path,
    gameplay_hud_run_id: str = "",
) -> Dict[str, Any]:
    png_path = Path(str(screen_summary.get("png_path", "")))
    if png_path.is_file():
        ocr_payload = run_screen_ocr(png_path)
    else:
        ocr_payload = {
            "ok": False,
            "error": f"startup screenshot is missing: {png_path}",
            "lines": [],
        }
    ocr_path = run_dir / f"{label}.startup_screen_ocr.json"
    ocr_path.write_text(json.dumps(ocr_payload, indent=2, ensure_ascii=False) + "\n", encoding="utf-8")
    debug_delta_text = debug_delta_path.read_text(encoding="utf-8", errors="replace") if debug_delta_path.is_file() else ""
    probe = startup_screen_probe_classification(
        ocr_payload=ocr_payload,
        capture_warnings=screen_summary.get("capture_warnings", []),
        debug_delta_text=debug_delta_text,
        gameplay_hud_run_id=gameplay_hud_run_id,
    )
    probe.update({
        "source_png": str(png_path),
        "ocr_artifact": str(ocr_path),
        "debug_delta_artifact": str(debug_delta_path) if debug_delta_path.is_file() else "",
        "native_run_id": gameplay_hud_run_id,
    })
    probe_path = run_dir / f"{label}.startup_screen_probe.json"
    probe["artifact_path"] = str(probe_path)
    probe_path.write_text(json.dumps(probe, indent=2, ensure_ascii=False) + "\n", encoding="utf-8")
    return probe


def capture_final_startup_evidence(
    *,
    profile: str,
    debug_start_size: int,
    run_dir: Path,
    screen_summary: Dict[str, Any],
    label: str,
    serial: int,
    pid: int = 0,
    debug_identity: Optional[Dict[str, Any]] = None,
    gameplay_hud_run_id: str = "",
) -> Dict[str, Any]:
    """Classify the final log delta and screenshot without sending input.

    This same path is used for success, process exit, and timeout so a late log
    error or a still-visible modal is always preserved in the result.  The
    classified offset deliberately stops before an incomplete trailing line;
    a caller that continues into feature steps can then re-read the completed
    line instead of losing it at the phase boundary.
    """

    debug_artifact = run_dir / "debug.final.log"
    # Give the screen classifier the native trace captured before OCR; it uses
    # the trace to distinguish a real HUD from a stale visual frame.
    capture_stable_final_debug_delta(
        profile,
        debug_start_size,
        run_dir,
        serial,
        artifact_name=debug_artifact.name,
        expected_identity=debug_identity,
    )
    screen_probe = capture_startup_screen_probe(
        run_dir,
        label,
        screen_summary,
        debug_artifact,
        gameplay_hud_run_id,
    )
    # Re-read from the original boundary so errors emitted during OCR are part
    # of this same final-startup classification.
    debug_capture = capture_stable_final_debug_delta(
        profile,
        debug_start_size,
        run_dir,
        serial,
        artifact_name=debug_artifact.name,
        expected_identity=debug_identity,
    )
    error_lines = debug_capture.get("error_evidence_lines", [])
    if isinstance(error_lines, list) and error_lines:
        screen_probe["startup_error_logged"] = True
        screen_probe["debug_error_lines"] = error_lines
        screen_probe["debug_delta_artifact"] = str(debug_artifact)
        if not screen_probe.get("visible_error_popup"):
            screen_probe["classification"] = "red_startup_error_logged"
        probe_artifact_value = str(screen_probe.get("artifact_path", "")).strip()
        if probe_artifact_value:
            write_json(Path(probe_artifact_value), screen_probe)
    screen_summary["startup_screen_probe"] = screen_probe
    process_alive = pid_is_alive(pid) if pid > 0 else None
    tail_classified = bool(debug_capture.get("tail_classified", True))
    return {
        "debug_capture": debug_capture,
        "screen_probe": screen_probe,
        "debug_delta_recorded": bool(debug_capture.get("artifact_path")),
        "debug_error_recorded": bool(debug_capture.get("error_evidence_lines")),
        "visible_error_popup_recorded": bool(screen_probe.get("visible_error_popup")),
        "process_alive": process_alive,
        "debug_tail_classified": tail_classified,
        "safe_for_startup": process_alive is not False and tail_classified,
        "classified_size": int(debug_capture.get("current_size", debug_start_size) or 0),
        "raw_current_size": int(debug_capture.get("raw_current_size", debug_start_size) or 0),
        "debug_log_identity": debug_capture.get("current_identity", {}),
        "rule": "Final startup evidence is classified on success, process exit, and timeout; classification never dismisses dialogs or sends keys.",
    }


def apply_direct_child_liveness(
    final_evidence: Dict[str, Any],
    process: subprocess.Popen[Any],
) -> bool:
    """Use the owned Popen status so an unreaped zombie is never called live."""

    process_alive = process.poll() is None
    final_evidence["process_alive"] = process_alive
    final_evidence["safe_for_startup"] = bool(
        process_alive and final_evidence.get("debug_tail_classified", False)
    )
    return process_alive


def capture_screen_text_artifact(
    run_dir: Path,
    label: str,
    capture: Dict[str, Any],
    tail_lines: int = 8,
) -> Dict[str, Any]:
    screen_summary = capture.get("screen_summary", {}) if isinstance(capture.get("screen_summary"), dict) else {}
    png_path_value = str(screen_summary.get("png_path", "")).strip()
    if not png_path_value:
        return {
            "kind": "screen_text_capture",
            "label": label,
            "ok": False,
            "error": "capture did not include a png_path",
        }

    png_path = Path(png_path_value)
    ocr_payload = run_screen_ocr(png_path)
    text_json_path = run_dir / f"{label}.screen_text.json"
    text_txt_path = run_dir / f"{label}.screen_text.txt"
    text_json_path.write_text(json.dumps(ocr_payload, indent=2, ensure_ascii=False) + "\n", encoding="utf-8")

    raw_lines = ocr_payload.get("lines", []) if isinstance(ocr_payload, dict) else []
    if isinstance(raw_lines, list):
        lines = [str(line).strip() for line in raw_lines if str(line).strip()]
    else:
        lines = []
    tail = lines[-max(1, int(tail_lines)):] if lines else []
    text_txt_path.write_text("\n".join(tail).rstrip() + ("\n" if tail else ""), encoding="utf-8")

    result = {
        "kind": "screen_text_capture",
        "label": label,
        "ok": bool(ocr_payload.get("ok")),
        "source_png": str(png_path),
        "json_path": str(text_json_path),
        "text_path": str(text_txt_path),
        "line_count": len(lines),
        "tail_line_count": len(tail),
        "tail_lines": tail,
    }
    if not ocr_payload.get("ok"):
        result["error"] = str(ocr_payload.get("error", "OCR failed"))
    return result


def persist_interruption_scan_artifacts(
    scan_dir: Path,
    run_dir: Path,
    evidence_label: str,
) -> List[str]:
    artifacts: List[str] = []
    for source in sorted(scan_dir.iterdir(), key=lambda path: path.name):
        if not source.is_file():
            continue
        suffix = source.name[len("scan"):] if source.name.startswith("scan") else f".{source.name}"
        destination = run_dir / f"{evidence_label}{suffix}"
        shutil.copy2(source, destination)
        artifacts.append(str(destination))
    return artifacts


def acknowledge_blocking_interruptions(
    pid: int,
    run_dir: Path,
    label: str,
    *,
    max_acknowledgements: int = 6,
    delay_ms: int = 200,
    settle_seconds: float = 0.35,
    stop_on_unknown: bool = False,
    continue_after_contaminating: bool = False,
    persist_clear_scan: bool = False,
    suppress_retained_shadow_warning: bool = False,
    suppress_inactive_structured_shadow_warning: bool = False,
    structured_popup_trace_log: Optional[Path] = None,
    structured_popup_trace_start_offset: int = 0,
    semantic_ui_trace_log: Optional[Path] = None,
    semantic_ui_trace_start_offset: int = 0,
    semantic_ui_expectation: Optional[Mapping[str, Any]] = None,
    allowed_classifications: Optional[Set[str]] = None,
    response_key_overrides: Optional[Dict[str, str]] = None,
    allow_map_editor_save_and_quit: bool = False,
    allow_hostile_auto_move_cancel: bool = False,
    declared_hostile_auto_move_continuation: Optional[Mapping[str, str]] = None,
    ordinary_wait_save_and_quit_guard: bool = False,
) -> Dict[str, Any]:
    acknowledgements: List[Dict[str, Any]] = []
    scan_count = 0
    release_blocking = False
    contaminating = False
    suppress_retained_portal_notice_once = False
    suppress_retained_shadow_warning_once = suppress_retained_shadow_warning
    portal_notice_family = {"portal_storm_notice", "partial_portal_storm_notice"}
    shadow_warning_family = {
        "shadow_warning_wilderness_flavor_popup",
        "partial_lifeless_grass_wilderness_flavor_popup",
    }
    acknowledged_structured_event_offsets: Set[int] = set()
    semantic_broker = SemanticInterruptionBroker(
        max_attempts=max(1, int(max_acknowledgements))
    )

    while True:
        scan_count += 1
        with tempfile.TemporaryDirectory(prefix="interrupt-scan-", dir=str(run_dir)) as temp_path:
            scan_dir = Path(temp_path)
            capture = capture_screenshot(pid, scan_dir, "scan")
            screen_text = capture_screen_text_artifact(scan_dir, "scan", capture, tail_lines=48)
            semantic_ui = read_active_semantic_ui_trace(
                semantic_ui_trace_log, semantic_ui_trace_start_offset
            )
            if max_acknowledgements > 0 and semantic_ui is not None:
                expected = dict(semantic_ui_expectation or {})
                expected_instance_id = str(expected.get("instance_id", ""))
                expected_intent = str(expected.get("intent", ""))
                expected_action = str(expected.get("action", ""))
                if semantic_ui is not None:
                    expected_instance_id = expected_instance_id or str(semantic_ui.get("instance_id", ""))
                    expected_intent = expected_intent or str(semantic_ui.get("intent", ""))
                    expected_action = expected_action or (
                        str(semantic_ui.get("valid_actions", [""])[0])
                        if semantic_ui.get("valid_actions") else ""
                    )

                def read_semantic_context() -> Optional[Mapping[str, Any]]:
                    return read_active_semantic_ui_trace(
                        semantic_ui_trace_log, semantic_ui_trace_start_offset
                    )

                def send_semantic_action(instance_id: str, action: str) -> None:
                    peekaboo_press_sequence(pid, [action], delay_ms=delay_ms)

                def observe_semantic_progress(postcondition: str) -> bool:
                    if settle_seconds > 0:
                        time.sleep(settle_seconds)
                    progress = read_active_semantic_ui_trace(
                        semantic_ui_trace_log, semantic_ui_trace_start_offset,
                        include_progress=True,
                    )
                    return bool(
                        progress
                        and progress.get("event") == "progress"
                        and progress.get("postcondition") == postcondition
                    )

                broker_result = semantic_broker.recover(
                    expected_intent=expected_intent,
                    expected_instance_id=expected_instance_id,
                    action=expected_action,
                    read_context=read_semantic_context,
                    send_action=send_semantic_action,
                    observe_progress=observe_semantic_progress,
                    expected_destination=expected.get("destination"),
                )
                semantic_classification = {
                    "status": "clear" if broker_result.status == "recovered" else "unknown_prompt",
                    "classification": "semantic_ui_recovered" if broker_result.status == "recovered"
                    else "semantic_ui_recovery_rejected",
                    "response_key": broker_result.action or "",
                    "provenance": "semantic_ui_trace",
                    "semantic_broker": broker_result.as_dict(),
                    "screen_text_diagnostic": screen_text,
                }
                if broker_result.status != "recovered":
                    return {
                        "status": "blocked_semantic_ui_recovery",
                        "scan_count": scan_count,
                        "acknowledgement_count": len(acknowledgements),
                        "acknowledgements": acknowledgements,
                        "final_classification": semantic_classification,
                        "final_artifacts": [],
                        "release_blocking": release_blocking,
                        "contaminating": contaminating,
                    }
                acknowledgements.append({
                    "index": len(acknowledgements) + 1,
                    "classification": semantic_classification,
                    "response_key": broker_result.action,
                    "artifacts": [],
                })
                return {
                    "status": "semantic_recovered",
                    "scan_count": scan_count,
                    "acknowledgement_count": len(acknowledgements),
                    "acknowledgements": acknowledgements,
                    "final_classification": semantic_classification,
                    "final_artifacts": [],
                    "release_blocking": release_blocking,
                    "contaminating": contaminating,
                }
            if ordinary_wait_save_and_quit_guard:
                classification = classify_ordinary_wait_interruption(
                    screen_text,
                    semantic_ui_trace_log=semantic_ui_trace_log,
                    semantic_ui_trace_start_offset=semantic_ui_trace_start_offset,
                    declared_hostile_auto_move_continuation=
                    declared_hostile_auto_move_continuation,
                )
            else:
                classification = classify_blocking_interruption(
                    screen_text,
                    allow_map_editor_save_and_quit=allow_map_editor_save_and_quit,
                    allow_hostile_auto_move_cancel=allow_hostile_auto_move_cancel,
                )
            structured_popup = read_active_eoc_popup_trace(
                structured_popup_trace_log,
                structured_popup_trace_start_offset,
            )
            structured_popup_trace_is_bounded = (
                structured_popup_trace_log is not None
                and structured_popup_trace_log.exists()
                and 0 <= structured_popup_trace_start_offset <=
                structured_popup_trace_log.stat().st_size
                and structured_popup_trace_log.stat().st_size -
                structured_popup_trace_start_offset <= EOC_POPUP_TRACE_READ_CAP_BYTES
            )
            structured_popup_ocr_compatible = (
                str(classification.get("status", "")) in {"clear", "unobservable"}
                or str(classification.get("classification", "")) in
                shadow_warning_family
            )
            if structured_popup is not None and structured_popup_ocr_compatible:
                structured_classification = classify_blocking_interruption({
                    "ok": True,
                    "text": str(structured_popup.get("message", "")),
                })
                structured_event_offset = int(structured_popup.get("event_offset", -1) or -1)
                structured_safe = (
                    str(structured_classification.get("status", "")) == "known_prompt"
                    and bool(str(structured_classification.get("response_key", "")))
                    and not bool(structured_classification.get("release_blocking", False))
                    and not bool(structured_classification.get("contaminating", False))
                    and not bool(structured_popup.get("truncated", False))
                )
                if structured_safe and structured_event_offset not in acknowledged_structured_event_offsets:
                    classification = {
                        **structured_classification,
                        "provenance": "structured_eoc_popup_trace",
                        "structured_popup_trace": structured_popup,
                    }
                else:
                    classification = {
                        **structured_classification,
                        "status": "unknown_prompt",
                        "classification": "structured_eoc_popup_not_auto_acknowledged",
                        "response_key": "",
                        "provenance": "structured_eoc_popup_trace",
                        "structured_popup_trace": structured_popup,
                        "structured_classification": structured_classification,
                        "structured_rejection": (
                            "already_acknowledged_without_return"
                            if structured_event_offset in acknowledged_structured_event_offsets
                            else "not_existing_safe_classification"
                        ),
                    }
            structured_activity_query = read_active_activity_query_trace(
                structured_popup_trace_log,
                structured_popup_trace_start_offset,
            )
            ocr_status = str(classification.get("status", ""))
            ocr_classification = str(classification.get("classification", ""))
            activity_query_ocr_compatible = (
                ocr_status in {"clear", "unobservable"}
                or ocr_classification == "partial_activity_distraction_prompt"
            )
            if structured_activity_query is not None and activity_query_ocr_compatible:
                structured_classification = classify_blocking_interruption({
                    "ok": True,
                    "text": "Open manager\nIgnore this distraction and continue",
                })
                structured_event_offset = int(
                    structured_activity_query.get("event_offset", -1) or -1
                )
                structured_safe = (
                    str(structured_classification.get("status", "")) == "known_prompt"
                    and str(structured_classification.get("response_key", "")) == "I"
                    and str(structured_activity_query.get("action", "")) == "none"
                    and str(structured_activity_query.get("type", ""))
                    in ACTIVITY_QUERY_TRACE_TYPES
                    and not bool(structured_activity_query.get("truncated", False))
                )
                if structured_safe and \
                        structured_event_offset not in acknowledged_structured_event_offsets:
                    classification = {
                        **structured_classification,
                        "provenance": "structured_activity_distraction_query_trace",
                        "response_action": "IGNORE",
                        "structured_activity_query_trace": structured_activity_query,
                    }
                else:
                    classification = {
                        **structured_classification,
                        "status": "unknown_prompt",
                        "classification": "structured_activity_query_not_auto_acknowledged",
                        "response_key": "",
                        "provenance": "structured_activity_distraction_query_trace",
                        "structured_activity_query_trace": structured_activity_query,
                        "structured_classification": structured_classification,
                        "structured_rejection": (
                            "already_acknowledged_without_return"
                            if structured_event_offset in acknowledged_structured_event_offsets
                            else "malformed_or_truncated_active_query"
                        ),
                    }
            status = str(classification.get("status", "unobservable"))
            classification_name = str(classification.get("classification", ""))
            if suppress_inactive_structured_shadow_warning and \
                    structured_popup_trace_is_bounded and structured_popup is None and \
                    classification_name in shadow_warning_family:
                classification = {
                    **classification,
                    "status": "clear",
                    "classification": "inactive_structured_popup_text_retained_on_hud",
                    "response_key": "",
                    "release_blocking": False,
                    "contaminating": False,
                    "suppressed_classification": classification_name,
                    "provenance": "bounded_structured_eoc_popup_trace",
                    "structured_popup_trace_start_offset":
                    structured_popup_trace_start_offset,
                }
                status = "clear"
                classification_name = str(classification["classification"])
            if suppress_retained_shadow_warning_once and \
                    classification_name in shadow_warning_family:
                classification = {
                    **classification,
                    "status": "clear",
                    "classification": "acknowledged_prompt_text_retained_on_hud",
                    "response_key": "",
                    "release_blocking": False,
                    "contaminating": False,
                    "suppressed_classification": classification_name,
                }
                status = "clear"
                suppress_retained_shadow_warning_once = False
            if suppress_retained_portal_notice_once and classification_name in portal_notice_family:
                classification = {
                    **classification,
                    "status": "clear",
                    "classification": "acknowledged_prompt_text_retained_on_hud",
                    "response_key": "",
                    "release_blocking": False,
                    "contaminating": False,
                    "suppressed_classification": classification_name,
                }
                status = "clear"
                suppress_retained_portal_notice_once = False

            if status == "known_prompt":
                evidence_label = f"{label}.interruption_{len(acknowledgements) + 1:02d}.before"
                artifacts = persist_interruption_scan_artifacts(scan_dir, run_dir, evidence_label)
            elif acknowledgements or status in {"unsafe_prompt", "unknown_prompt"} or persist_clear_scan:
                evidence_label = f"{label}.interruption_final"
                artifacts = persist_interruption_scan_artifacts(scan_dir, run_dir, evidence_label)
            else:
                artifacts = []

        release_blocking = release_blocking or bool(classification.get("release_blocking", False))
        contaminating = contaminating or bool(classification.get("contaminating", False))

        if status == "known_prompt" and allowed_classifications is not None and \
                classification_name not in allowed_classifications:
            classification = {
                **classification,
                "status": "unknown_prompt",
                "classification": "structured_wait_prompt_not_authorized",
                "response_key": "",
                "rejected_classification": classification_name,
            }
            status = "unknown_prompt"
        if status == "known_prompt" and response_key_overrides is not None:
            override = response_key_overrides.get(classification_name, "")
            if override:
                classification = {**classification, "response_key": override}

        if status == "known_prompt":
            current_release_blocking = bool(classification.get("release_blocking", False))
            current_contaminating = bool(classification.get("contaminating", False))
            if len(acknowledgements) >= max_acknowledgements:
                return {
                    "status": "blocked_acknowledgement_limit",
                    "scan_count": scan_count,
                    "acknowledgement_count": len(acknowledgements),
                    "acknowledgements": acknowledgements,
                    "final_classification": classification,
                    "final_artifacts": artifacts,
                    "release_blocking": release_blocking,
                    "contaminating": contaminating,
                }
            response_key = str(classification.get("response_key", ""))
            if not response_key:
                raise SystemExit("Known blocking interruption did not provide a response key")
            peekaboo_press_sequence(pid, [response_key], delay_ms=delay_ms)
            structured_trace = classification.get("structured_popup_trace")
            if isinstance(structured_trace, dict):
                acknowledged_structured_event_offsets.add(
                    int(structured_trace.get("event_offset", -1) or -1)
                )
            structured_activity_trace = classification.get("structured_activity_query_trace")
            if isinstance(structured_activity_trace, dict):
                acknowledged_structured_event_offsets.add(
                    int(structured_activity_trace.get("event_offset", -1) or -1)
                )
            if settle_seconds > 0:
                time.sleep(settle_seconds)
            acknowledgements.append({
                "index": len(acknowledgements) + 1,
                "classification": classification,
                "response_key": response_key,
                "native_response_receipt": (
                    {
                        **dict(classification["continuation_receipt"]),
                        "response_key": response_key,
                    }
                    if isinstance(classification.get("continuation_receipt"), Mapping)
                    else None
                ),
                "artifacts": artifacts,
            })
            if current_release_blocking or (
                current_contaminating and not continue_after_contaminating
            ):
                return {
                    "status": (
                        "acknowledged_release_blocking"
                        if release_blocking
                        else "acknowledged_contaminating"
                    ),
                    "scan_count": scan_count,
                    "acknowledgement_count": len(acknowledgements),
                    "acknowledgements": acknowledgements,
                    "final_classification": classification,
                    "final_artifacts": artifacts,
                    "release_blocking": release_blocking,
                    "contaminating": contaminating,
                }
            if current_contaminating and classification_name == "portal_storm_notice":
                suppress_retained_portal_notice_once = True
            if classification_name == "shadow_warning_wilderness_flavor_popup":
                suppress_retained_shadow_warning_once = True
            continue

        blocked = status in {"unsafe_prompt", "unknown_prompt"} and stop_on_unknown
        return {
            "status": f"blocked_{status}" if blocked else status,
            "scan_count": scan_count,
            "acknowledgement_count": len(acknowledgements),
            "acknowledgements": acknowledgements,
            "final_classification": classification,
            "final_artifacts": artifacts,
            "release_blocking": release_blocking,
            "contaminating": contaminating,
        }


def recover_harmless_wilderness_flavor_wait(
    pid: int,
    run_dir: Path,
    label: str,
    *,
    delay_ms: int,
    action_trace_log: Optional[Path],
    action_trace_start_offset: int,
) -> Dict[str, Any]:
    """Recover exactly the owner-approved flavor popup then continue-wait query."""
    popup = acknowledge_blocking_interruptions(
        pid, run_dir, f"{label}.flavor_popup", max_acknowledgements=1,
        delay_ms=delay_ms, stop_on_unknown=True,
        structured_popup_trace_log=action_trace_log,
        structured_popup_trace_start_offset=action_trace_start_offset,
        semantic_ui_trace_log=action_trace_log,
        semantic_ui_trace_start_offset=action_trace_start_offset,
        semantic_ui_expectation={"intent": "eoc_popup", "action": "space"},
        allowed_classifications={"shadow_warning_wilderness_flavor_popup"},
        response_key_overrides={"shadow_warning_wilderness_flavor_popup": "space"},
    )
    if popup.get("status") == "clear":
        return {"status": "clear", "acknowledgement_count": 0, "acknowledgements": []}
    popup_acks = popup.get("acknowledgements", [])
    if popup.get("status") not in {"clear", "blocked_acknowledgement_limit", "blocked_unknown_prompt"} or len(popup_acks) != 1 or \
            popup_acks[0].get("response_key") != "space" or \
            popup_acks[0].get("classification", {}).get("provenance") not in {
                "structured_eoc_popup_trace", "semantic_ui_trace"
            }:
        return {**popup, "status": "blocked_harmless_flavor_popup_sequence"}
    activity = acknowledge_blocking_interruptions(
        pid, run_dir, f"{label}.continue_wait", max_acknowledgements=1,
        delay_ms=delay_ms, stop_on_unknown=True,
        structured_popup_trace_log=action_trace_log,
        structured_popup_trace_start_offset=action_trace_start_offset,
        semantic_ui_trace_log=action_trace_log,
        semantic_ui_trace_start_offset=action_trace_start_offset,
        semantic_ui_expectation={"intent": "eoc_popup", "action": "space"},
        allowed_classifications={
            "activity_distraction_prompt",
            "tired_wait_continue_prompt",
        },
    )
    activity_acks = activity.get("acknowledgements", [])
    activity_trace = activity_acks[0].get("classification", {}).get("structured_activity_query_trace", {}) \
        if len(activity_acks) == 1 else {}
    if activity.get("status") != "clear" or len(activity_acks) != 1 or \
            activity_acks[0].get("response_key") != "I" or activity_trace.get("type") != "eoc":
        return {**activity, "status": "blocked_harmless_flavor_continue_sequence"}
    return {
        "status": "recovered_harmless_flavor_wait_sequence",
        "acknowledgement_count": 2,
        "response_keys": ["space", "I"],
        "acknowledgements": popup_acks + activity_acks,
        "wait_continues_proof": "pending_authoritative_post_input_artifact",
    }


def normalize_screen_text_patterns(raw_value: Any) -> List[str]:
    if isinstance(raw_value, str):
        return [raw_value.strip()] if raw_value.strip() else []
    if not isinstance(raw_value, list):
        return []
    return [str(value).strip() for value in raw_value if str(value).strip()]


def normalize_ocr_phrase(text: str) -> str:
    return re.sub(r"\s+", " ", str(text)).strip().lower()


def spatial_ocr_row_texts(payload: Dict[str, Any]) -> List[str]:
    """Reconstruct OCR rows from overlapping vertical bounding intervals."""

    raw_observations = payload.get("observations", [])
    if not isinstance(raw_observations, list):
        return []
    observations: List[Tuple[float, float, float, int, str]] = []
    for index, raw_observation in enumerate(raw_observations):
        if not isinstance(raw_observation, dict):
            continue
        text = str(raw_observation.get("text", "")).strip()
        try:
            x = float(raw_observation.get("x"))
            y = float(raw_observation.get("y"))
            height = float(raw_observation.get("h"))
        except (TypeError, ValueError):
            continue
        if not text or height <= 0:
            continue
        observations.append((x, y, y + height, index, text))
    if len(observations) < 2:
        return []

    vertical_boundaries = sorted({
        boundary
        for _, top, bottom, _, _ in observations
        for boundary in (top, bottom)
    })
    row_texts: List[str] = []
    seen: Set[str] = set()
    for lower, upper in zip(vertical_boundaries, vertical_boundaries[1:]):
        if upper <= lower:
            continue
        scanline = (lower + upper) / 2.0
        row = sorted(
            (
                (x, index, text)
                for x, top, bottom, index, text in observations
                if top < scanline < bottom
            ),
            key=lambda entry: (entry[0], entry[1]),
        )
        if len(row) < 2:
            continue
        row_text = " ".join(text for _, _, text in row)
        normalized_row = normalize_ocr_phrase(row_text)
        if normalized_row and normalized_row not in seen:
            seen.add(normalized_row)
            row_texts.append(row_text)
    return row_texts


def find_screen_text_matches(screen_text_report: Dict[str, Any], patterns: List[str]) -> List[Dict[str, str]]:
    if not patterns:
        return []
    json_path_value = str(screen_text_report.get("json_path", "")).strip()
    if not json_path_value:
        return []
    try:
        payload = json.loads(Path(json_path_value).read_text(encoding="utf-8"))
    except Exception:
        return []

    raw_lines = payload.get("lines", []) if isinstance(payload, dict) else []
    lines = [str(line).strip() for line in raw_lines if str(line).strip()] if isinstance(raw_lines, list) else []
    raw_text = str(payload.get("text", "")).strip() if isinstance(payload, dict) else ""
    literal_haystacks = lines + ([raw_text] if raw_text else [])
    spatial_haystacks = spatial_ocr_row_texts(payload)
    matches: List[Dict[str, str]] = []
    for pattern in patterns:
        needle = pattern.lower()
        for line in literal_haystacks:
            if needle in line.lower():
                matches.append({"pattern": pattern, "line": line})
                break
        else:
            spatial_needle = normalize_ocr_phrase(pattern)
            for row_text in spatial_haystacks:
                if spatial_needle in normalize_ocr_phrase(row_text):
                    matches.append({
                        "pattern": pattern,
                        "line": row_text,
                        "source": "spatial_ocr_row",
                    })
                    break
    return matches


def apply_screen_text_abort_guard(
    report: Dict[str, Any],
    step: Dict[str, Any],
    screen_text_report: Dict[str, Any],
) -> bool:
    patterns = normalize_screen_text_patterns(step.get("abort_if_text_contains", []))
    matches = find_screen_text_matches(screen_text_report, patterns)
    if not matches:
        return False
    report["abort"] = {
        "status": "aborted_by_screen_text_guard",
        "verdict": str(step.get("abort_verdict", "inconclusive_screen_text_guard")),
        "reason": str(step.get("abort_reason", "screen text matched abort guard")),
        "patterns": patterns,
        "matches": matches,
    }
    return True


def evaluate_screen_text_expectation(
    screen_text_report: Dict[str, Any],
    patterns: List[str],
) -> Dict[str, Any]:
    matches = find_screen_text_matches(screen_text_report, patterns)
    matched_patterns = {str(match.get("pattern", "")) for match in matches}
    missing = [pattern for pattern in patterns if pattern not in matched_patterns]
    return {
        "status": "matched" if patterns and not missing else ("not_requested" if not patterns else "missing"),
        "patterns": patterns,
        "matches": matches,
        "missing": missing,
        "source": str(screen_text_report.get("json_path", "") or screen_text_report.get("source_png", "")),
    }


def evaluate_screen_text_or_rendered_hud_expectation(
    screen_text_report: Dict[str, Any],
    patterns: List[str],
    rendered_hud_identity: Any,
    *,
    action_trace_log: Optional[Path],
    run_id: str,
    screen_summary: Mapping[str, Any],
    startup_overlay_recovery: Any,
    trace_start_offset: int = 0,
) -> Dict[str, Any]:
    """Keep literal text strict, with narrowly bound native equivalents."""
    text_expectation = evaluate_screen_text_expectation(screen_text_report, patterns)
    if str(text_expectation.get("status", "")) != "missing":
        return text_expectation
    if patterns == ["Case Sensitive"]:
        save_quit_confirmation = evaluate_semantic_ui_expectation(
            action_trace_log,
            trace_start_offset,
            {"intent": "save_quit_confirmation", "valid_actions": ["Y"]},
            run_id=run_id,
        )
        save_quit_issues = [str(issue) for issue in save_quit_confirmation.get("issues", [])]
        # The event itself is retained and bound to the live run.  A capped
        # historical prefix cannot invalidate an open event in that tail: a
        # later native return would also be in the same retained tail.
        tail_bound_confirmation = save_quit_issues == ["trace_read_truncated"] and \
            isinstance(save_quit_confirmation.get("observed"), Mapping) and \
            str(save_quit_confirmation["observed"].get("event", "")) == "open"
        if str(save_quit_confirmation.get("status", "")) == "green" or tail_bound_confirmation:
            return {
                **text_expectation,
                "status": "matched",
                "missing": [],
                "ocr_missing": text_expectation.get("missing", []),
                "match_provenance": "native_save_quit_confirmation_trace",
                "native_trace_tail_bound": tail_bound_confirmation,
                "semantic_ui_confirmation": save_quit_confirmation,
            }
    if rendered_hud_identity is None:
        return text_expectation
    if isinstance(rendered_hud_identity, str):
        rendered_hud_identity = [rendered_hud_identity]
    if not isinstance(rendered_hud_identity, list):
        return {
            **text_expectation,
            "rendered_hud_identity": {
                "status": "blocked",
                "verdict": "blocked_rendered_gameplay_hud_identity",
                "reason": "the declared gameplay HUD identity has an invalid schema",
                "provenance": "native_gameplay_hud_render_trace",
            },
        }
    rendered_expectation = evaluate_rendered_gameplay_hud_identity(
        action_trace_log,
        run_id,
        screen_text_report,
        screen_summary,
        rendered_hud_identity,
        startup_overlay_recovery,
        trace_start_offset,
    )
    if str(rendered_expectation.get("status", "")) != "green":
        return {**text_expectation, "rendered_hud_identity": rendered_expectation}
    return {
        **text_expectation,
        "status": "matched",
        "missing": [],
        "ocr_missing": text_expectation.get("missing", []),
        "match_provenance": "native_gameplay_hud_render_trace",
        "rendered_hud_identity": rendered_expectation,
    }


def evaluate_bound_startup_gameplay_hud_verdict(
    expectation: Any, startup_screen_probe: Any, runtime_binding: Any,
    runtime_screen: Any, *, semantic_run_id: str, registry_authority: Any,
    scenario_source_sha256: str, expected_process_pid: int = 0,
    previous_process_pid: int = 0,
) -> Dict[str, Any]:
    """Verify semantic startup HUD authority without promoting OCR text."""
    expected = expectation if isinstance(expectation, Mapping) else {}
    expected_classification = str(expected.get("classification", "green_gameplay_hud_present")).strip()
    probe = startup_screen_probe if isinstance(startup_screen_probe, Mapping) else {}
    binding = runtime_binding if isinstance(runtime_binding, Mapping) else {}
    screen = runtime_screen if isinstance(runtime_screen, Mapping) else {}
    observed_runtime = screen.get("runtime_binding_observed")
    observed_runtime = observed_runtime if isinstance(observed_runtime, Mapping) else {}
    authority = registry_authority if isinstance(registry_authority, Mapping) else {}
    issues: List[str] = []
    if not probe:
        issues.append("missing_startup_semantic_verdict")
    if str(probe.get("classification", "")) != expected_classification:
        issues.append("nongameplay_or_contradictory_startup_verdict")
    if probe.get("gameplay_hud_present") is not True:
        issues.append("gameplay_hud_not_present")
    if probe.get("visible_error_popup") is not False or probe.get("startup_error_logged") is not False or probe.get("blocking_overlay_present") is not False:
        issues.append("contradictory_startup_verdict")
    if str(probe.get("native_run_id", "")) != semantic_run_id or not semantic_run_id:
        issues.append("wrong_or_missing_native_run_binding")
    observed_process_pid = int(screen.get("capture_process_pid", 0) or 0)
    if expected_process_pid <= 0 or observed_process_pid != expected_process_pid:
        issues.append("wrong_or_missing_captured_process_binding")
    if previous_process_pid > 0 and expected_process_pid == previous_process_pid:
        issues.append("post_relaunch_process_was_not_replaced")
    if binding.get("ok") is not True or binding.get("schema") != 1:
        issues.append("missing_runtime_binding")
    executable_sha256 = str(binding.get("executable_sha256", "")).lower()
    source_sha256 = str(binding.get("runtime_source_sha256", "")).lower()
    if not executable_sha256 or not source_sha256:
        issues.append("incomplete_runtime_binding")
    if screen.get("runtime_binding_status") != "matched" or str(observed_runtime.get("executable_sha256", "")).lower() != executable_sha256 or str(observed_runtime.get("runtime_source_sha256", "")).lower() != source_sha256:
        issues.append("stale_or_wrong_executable_binding")
    authority_kind = str(authority.get("authority", ""))
    authority_binding_id = str(authority.get("binding_id", "")).lower()
    if authority_kind not in {"registry", "certification"} or not str(authority.get("authority_id", "")):
        issues.append("missing_registry_authority")
    if authority_kind == "registry" and authority_binding_id != executable_sha256:
        issues.append("wrong_registry_executable_binding")
    if authority_kind == "certification" and (
            str(authority.get("evidence_class", "")) != "automated continuous-round certification" or
            len(authority_binding_id) != 64
    ):
        issues.append("wrong_certification_round_binding")
    if not scenario_source_sha256 or str(authority.get("source_sha256", "")).lower() != scenario_source_sha256.lower():
        issues.append("stale_or_wrong_scenario_source_binding")
    return {
        "status": "green" if not issues else "red",
        "expected_classification": expected_classification,
        "classification": str(probe.get("classification", "")),
        "native_run_id": str(probe.get("native_run_id", "")),
        "semantic_run_id": semantic_run_id,
        "process_binding": {
            "expected_process_pid": expected_process_pid,
            "observed_capture_process_pid": observed_process_pid,
            "previous_process_pid": previous_process_pid,
        },
        "runtime_binding": {"executable_sha256": executable_sha256, "runtime_source_sha256": source_sha256, "screen_status": screen.get("runtime_binding_status", "")},
        "registry_authority": {"authority": authority_kind, "authority_id": str(authority.get("authority_id", "")), "binding_id": authority_binding_id, "run_id": str(authority.get("run_id", "")), "source_sha256": str(authority.get("source_sha256", ""))},
        "scenario_source_sha256": scenario_source_sha256,
        "issues": issues,
        "provenance": "run_bound_semantic_startup_gameplay_hud_verdict",
        "ocr_authority": "non_authoritative",
    }


def apply_screen_text_expectation_abort_guard(
    report: Dict[str, Any],
    step: Dict[str, Any],
    text_expectation: Dict[str, Any],
) -> bool:
    if not bool(step.get("abort_on_screen_text_expectation_failure", False)):
        return False
    if str(text_expectation.get("status", "")).strip() != "missing":
        return False
    report["abort"] = {
        "status": "aborted_by_screen_text_expectation_guard",
        "verdict": str(step.get("abort_verdict", "red_step_expected_screen_text_missing")),
        "reason": str(step.get("abort_reason", "required screen text was missing")),
        "patterns": text_expectation.get("patterns", []),
        "missing": text_expectation.get("missing", []),
        "matches": text_expectation.get("matches", []),
        "source": str(text_expectation.get("source", "")),
    }
    return True


def screen_summary_path(screen_summary: Dict[str, Any]) -> str:
    return str(screen_summary.get("png_path", "") or screen_summary.get("path", ""))



def metadata_checkpoint_verdict(metadata: Dict[str, Any]) -> Tuple[str, List[str]]:
    if not metadata:
        return "yellow_step_no_immediate_screen_or_metadata", ["no_screen_or_metadata_artifact"]
    status = str(metadata.get("status", "")).strip()
    if status in {"required_state_present", "required_fields_present"}:
        return "green_step_metadata_required_state_present", []
    if status in {
        "required_state_missing",
        "required_fields_missing",
        "required_items_missing",
        "required_furniture_missing",
        "required_terrain_missing",
        "required_traps_missing",
        "required_radiation_missing",
    }:
        issues = []
        if metadata.get("missing_required_terrain"):
            issues.append("missing_required_terrain")
        if metadata.get("missing_required_fields"):
            issues.append("missing_required_fields")
        if metadata.get("missing_required_items"):
            issues.append("missing_required_items")
        if metadata.get("missing_required_weapon"):
            issues.append("missing_required_weapon")
        if metadata.get("missing_required_weapon_ammo"):
            issues.append("missing_required_weapon_ammo")
        if metadata.get("missing_required_furniture"):
            issues.append("missing_required_furniture")
        if metadata.get("missing_required_traps"):
            issues.append("missing_required_traps")
        if metadata.get("missing_required_radiation"):
            issues.append("missing_required_radiation")
        for forbidden_key in (
            "observed_forbidden_terrain",
            "observed_forbidden_fields",
            "observed_forbidden_items",
            "observed_forbidden_furniture",
            "observed_forbidden_traps",
            "observed_forbidden_radiation",
            "observed_forbidden_monsters",
        ):
            if metadata.get(forbidden_key):
                issues.append(forbidden_key)
        if metadata.get("missing_required_monsters"):
            issues.append("missing_required_monsters")
        if metadata.get("missing_required_hordes"):
            issues.append("missing_required_hordes")
        if metadata.get("missing_required_npcs"):
            issues.append("missing_required_npcs")
        if metadata.get("missing_required_new_npcs"):
            issues.append("missing_required_new_npcs")
        if metadata.get("missing_required_npc_count_delta"):
            issues.append("missing_required_npc_count_delta")
        if metadata.get("missing_required_npc_count"):
            issues.append("missing_required_npc_count")
        if metadata.get("missing_required_weather"):
            issues.append("missing_required_weather")
        if metadata.get("missing_required_points_ms"):
            issues.append("missing_required_points_ms")
        if metadata.get("missing_required_min_delta_turns"):
            issues.append("missing_required_min_delta_turns")
        if metadata.get("missing_required_time_of_day"):
            issues.append("missing_required_time_of_day")
        missing_fields = metadata.get("missing_required_fields")
        if isinstance(missing_fields, list):
            for missing_field in missing_fields:
                if str(missing_field) not in issues:
                    issues.append(str(missing_field))
        return "red_step_metadata_required_state_missing", issues or [status]
    if status == "failed":
        return "blocked_step_metadata_probe_failed", ["metadata_probe_failed"]
    if status == "baseline_recorded":
        return "green_step_metadata_baseline_recorded", []
    if status == "scanned":
        return "yellow_step_metadata_scanned_without_required_state", ["metadata_no_required_state"]
    return "yellow_step_metadata_inconclusive", ["metadata_status_inconclusive"]


def r014_native_semantic_bootstrap_metadata(
    *, profile: str, run_dir: Path, run_id: str, start_offset: int,
    press_trace_offset: int, required_state: str, required_actions: Sequence[str],
    frame: Optional[Mapping[str, Any]] = None,
) -> Dict[str, Any]:
    """Bind startup to the one native HUD/world-ready semantic frame."""
    artifact_path = Path(run_dir) / "semantic.native.log"
    metadata: Dict[str, Any] = {
        "artifact_kind": "r014_native_semantic_bootstrap_frame",
        "artifact_path": str(artifact_path),
        "gameplay_credit": False,
        "provenance": "native_semantic_step_trace",
        "run_id": str(run_id),
        "required_state": str(required_state),
        "required_actions": list(required_actions),
        "press_trace_offset": int(press_trace_offset),
    }
    if frame is None:
        try:
            frame = current_semantic_step_frame(
                profile=profile, run_dir=run_dir, run_id=run_id, start_offset=start_offset,
            )
        except (OSError, ValueError) as exc:
            return {**metadata, "status": "scanned", "reason": "native_frame_unavailable", "error": str(exc)}
    frame_id = str(frame.get("frame_id", "")).strip()
    frame_offset = int(frame.get("_event_offset", -1) or -1)
    actions = frame.get("valid_actions", [])
    if not isinstance(actions, list):
        actions = []
    metadata.update({
        "frame_id": frame_id,
        "frame_run_id": str(frame.get("run_id", "")),
        "frame_state": str(frame.get("state", "")),
        "frame_trace_offset": frame_offset,
        "advertised_actions": list(actions),
        "frame_producer": str(frame.get("producer", "")),
        "initial_world_ready": frame.get("initial_world_ready"),
    })
    if not frame_id or metadata["frame_run_id"] != str(run_id):
        return {**metadata, "status": "scanned", "reason": "wrong_run_or_missing_frame"}
    if frame_offset < int(press_trace_offset):
        return {**metadata, "status": "scanned", "reason": "stale_frame"}
    if metadata["frame_state"] != str(required_state):
        return {**metadata, "status": "scanned", "reason": "wrong_state"}
    if metadata["frame_producer"] != "hud_world_ready" or \
            metadata["initial_world_ready"] is not True:
        return {**metadata, "status": "scanned", "reason": "not_initial_hud_world_ready_frame"}
    missing_actions = [action for action in required_actions if action not in actions]
    if missing_actions:
        return {**metadata, "status": "scanned", "reason": "incomplete_actions", "missing_actions": missing_actions}
    return {**metadata, "status": "required_state_present"}


def initial_hud_world_frame_counts(
    *, profile: str, trace_offset: int, run_id: str,
) -> tuple[int, int]:
    """Count only explicit initial HUD/world frames in the current log slice."""
    if trace_offset < 0:
        return 0, 0
    try:
        source = semantic_step_source_trace(profile)
        effective_offset = semantic_step_effective_source_offset(source, trace_offset)
        with source.open("rb") as handle:
            handle.seek(effective_offset)
            body = handle.read(SEMANTIC_STEP_MAX_BYTES + 1)
    except OSError:
        return 0, 0
    if len(body) > SEMANTIC_STEP_MAX_BYTES:
        return 0, 0
    matching = 0
    foreign = 0
    for raw_line in body.splitlines():
        marker = raw_line.find(SEMANTIC_STEP_PREFIX.encode("utf-8"))
        if marker < 0:
            continue
        try:
            event = json.loads(raw_line[marker + len(SEMANTIC_STEP_PREFIX):])
        except (TypeError, ValueError, json.JSONDecodeError):
            return 0, 1
        if not isinstance(event, Mapping) or event.get("event") != "frame" or \
                event.get("producer") != "hud_world_ready" or \
                event.get("initial_world_ready") is not True:
            continue
        if str(event.get("run_id", "")) == str(run_id):
            matching += 1
        else:
            foreign += 1
    return matching, foreign


def first_initial_hud_world_frame_after_boundary(
    *, profile: str, trace_offset: int, run_id: str, required_state: str,
    required_actions: Sequence[str],
) -> Dict[str, Any]:
    """Retain the first eligible one-shot HUD frame in this launch's trace slice."""
    if trace_offset < 0:
        raise ValueError("initial HUD frame trace boundary is invalid")
    try:
        source = semantic_step_source_trace(profile)
        effective_offset = semantic_step_effective_source_offset(source, trace_offset)
        with source.open("rb") as handle:
            handle.seek(effective_offset)
            body = handle.read(SEMANTIC_STEP_MAX_BYTES + 1)
    except OSError as exc:
        raise ValueError("initial HUD frame trace is unavailable") from exc
    if len(body) > SEMANTIC_STEP_MAX_BYTES:
        raise ValueError("initial HUD frame trace exceeds the semantic trace limit")

    candidate: Dict[str, Any] | None = None
    matching = 0
    foreign = 0
    mismatched_producer = 0
    cursor = 0
    for raw_line in body.splitlines(keepends=True):
        marker = raw_line.find(SEMANTIC_STEP_PREFIX.encode("utf-8"))
        if marker >= 0:
            try:
                event = json.loads(raw_line[marker + len(SEMANTIC_STEP_PREFIX):])
            except (TypeError, ValueError, json.JSONDecodeError) as exc:
                raise ValueError("initial HUD frame trace is malformed") from exc
            if isinstance(event, Mapping) and event.get("event") == "frame" and \
                    event.get("initial_world_ready") is True:
                if str(event.get("run_id", "")) != str(run_id):
                    foreign += 1
                elif event.get("producer") != "hud_world_ready":
                    mismatched_producer += 1
                else:
                    matching += 1
                    if candidate is None:
                        candidate = dict(event)
                        candidate["_event_offset"] = effective_offset + cursor + marker
        cursor += len(raw_line)

    if foreign:
        raise ValueError("initial HUD frame belongs to a different run")
    if mismatched_producer:
        raise ValueError("initial HUD frame producer is mismatched")
    if matching != 1 or candidate is None:
        raise ValueError("initial HUD frame is absent or duplicated")
    if candidate.get("state") != required_state:
        raise ValueError("initial HUD frame state is mismatched")
    actions = candidate.get("valid_actions")
    if not isinstance(actions, list) or any(action not in actions for action in required_actions):
        raise ValueError("initial HUD frame actions are incomplete")
    return candidate


def await_r014_native_semantic_bootstrap(
    *, profile: str, run_dir: Path, run_id: str, required_state: str,
    required_actions: Sequence[str], timeout_seconds: float, poll_seconds: float,
    trace_start_offset: int = 0, require_initial_hud_world_ready_frame: bool = False,
) -> Dict[str, Any]:
    """Await the launcher's first same-run semantic frame without sending input.

    The native producer runs at the ordinary player-input boundary. Its frame
    can precede the startup trace cursor, so this bootstrap reads the current
    log generation and uses the native run ID as its isolation boundary. It
    never guesses a key in an arbitrary startup modal.
    """
    deadline = time.monotonic() + max( 0.0, timeout_seconds )
    attempts = 0
    last_metadata: Dict[str, Any] = {}
    while True:
        attempts += 1
        try:
            effective_trace_offset = semantic_step_effective_source_offset(
                semantic_step_source_trace(profile), trace_start_offset
            )
            frame = first_initial_hud_world_frame_after_boundary(
                profile=profile, trace_offset=trace_start_offset, run_id=run_id,
                required_state=required_state, required_actions=required_actions,
            ) if require_initial_hud_world_ready_frame else current_semantic_step_frame(
                profile=profile, run_dir=run_dir, run_id=run_id, start_offset=0,
            )
            last_metadata = r014_native_semantic_bootstrap_metadata(
                profile=profile, run_dir=run_dir, run_id=run_id, start_offset=0,
                press_trace_offset=effective_trace_offset, required_state=required_state,
                required_actions=required_actions, frame=frame,
            )
        except (OSError, ValueError) as exc:
            last_metadata = {
                "status": "scanned", "reason": "native_frame_unavailable", "error": str(exc),
            }
        if last_metadata.get( "status" ) == "required_state_present":
            return {
                **last_metadata,
                "bootstrap": "launcher_first_same_run_semantic_frame",
                "attempts": attempts,
                "timeout_seconds": timeout_seconds,
                "poll_seconds": poll_seconds,
            }
        remaining = deadline - time.monotonic()
        if remaining <= 0:
            return {
                **last_metadata,
                "bootstrap": "launcher_first_same_run_semantic_frame",
                "attempts": attempts,
                "timeout_seconds": timeout_seconds,
                "poll_seconds": poll_seconds,
                "reason": "first_same_run_semantic_frame_timeout",
            }
        time.sleep( min( max( poll_seconds, 0.05 ), remaining ) )


def r014_cockpit_observation_metadata(
    observation: Mapping[str, Any], *, artifact_path: Path, run_id: str,
) -> Dict[str, Any]:
    """Classify a run-bound native observation without using rendered text."""
    metadata: Dict[str, Any] = {
        "artifact_kind": "r014_live_prototype_bootstrap",
        "artifact_path": str(artifact_path),
        "gameplay_credit": False,
        "provenance": "native_cockpit_game_observe",
        "run_id": str(run_id),
    }
    result = observation.get("result") if observation.get("ok") is True else None
    if not isinstance(result, Mapping):
        return {**metadata, "status": "scanned", "reason": "observation_unavailable"}
    observed_run_id = str(result.get("run_id", "")).strip()
    observation_id = str(result.get("observation_id", "")).strip()
    visible_local = result.get("visible_local")
    metadata.update({
        "observed_run_id": observed_run_id,
        "observation_id": observation_id,
        "visible_local_count": len(visible_local) if isinstance(visible_local, list) else 0,
    })
    if observed_run_id != str(run_id) or not observation_id.startswith(f"{run_id}:"):
        return {**metadata, "status": "scanned", "reason": "wrong_run"}
    if not isinstance(visible_local, list) or not visible_local:
        return {**metadata, "status": "scanned", "reason": "empty_visible_observation"}
    return {**metadata, "status": "required_state_present"}


def r014_cockpit_live_session_metadata(
    final: Mapping[str, Any], *, artifact_path: Path, run_id: str, binding_id: str,
    live_status: int,
) -> Dict[str, Any]:
    """Classify only a completed same-run immutable live-session result."""
    metadata: Dict[str, Any] = {
        "artifact_kind": "worker_controlled_live_cockpit_session",
        "artifact_path": str(artifact_path),
        "gameplay_credit": False,
        "provenance": "cockpit_live_final",
        "run_id": str(run_id),
        "binding_id": str(binding_id),
    }
    if live_status != 0 or not artifact_path.is_file():
        return {**metadata, "status": "scanned", "reason": "immutable_final_unavailable"}
    final_run_id = str(final.get("run_id", "")).strip()
    final_binding_id = str(final.get("binding_id", "")).strip()
    transcript = final.get("action_observation_sequence")
    actions = [entry for entry in transcript if isinstance(entry, Mapping) and entry.get("kind") == "action"] \
        if isinstance(transcript, list) else []
    observations = [entry for entry in transcript if isinstance(entry, Mapping) and entry.get("kind") == "observation"] \
        if isinstance(transcript, list) else []
    accepted_actions = [entry for entry in actions if isinstance(entry.get("result"), Mapping) and entry["result"].get("ok") is True]
    metadata.update({
        "final_run_id": final_run_id,
        "final_binding_id": final_binding_id,
        "state": str(final.get("state", "")),
        "action_count": len(actions),
        "accepted_action_count": len(accepted_actions),
        "observation_count": len(observations),
    })
    if final_run_id != str(run_id) or final_binding_id != str(binding_id):
        return {**metadata, "status": "scanned", "reason": "wrong_run_or_binding"}
    if metadata["state"] != "finished":
        return {**metadata, "status": "scanned", "reason": "unfinished_session"}
    if not accepted_actions or len(observations) < 2:
        return {**metadata, "status": "scanned", "reason": "incomplete_live_transaction"}
    return {**metadata, "status": "required_state_present"}


def screen_checkpoint_verdict(
    *,
    screen_summary: Dict[str, Any],
    expected_visible_fact: str,
    text_expectation: Optional[Dict[str, Any]] = None,
    ocr_requested: bool = False,
) -> Tuple[str, List[str]]:
    issues: List[str] = []
    if not screen_summary:
        return "yellow_step_no_immediate_screen_or_metadata", ["no_screen_or_metadata_artifact"]
    if not screen_capture_succeeded(screen_summary):
        return "red_step_screen_capture_failed", ["screen_capture_failed"]
    runtime_version_match = screen_summary.get("version_matches_runtime_paths")
    if runtime_version_match is False:
        issues.append("runtime_version_mismatch")
    elif runtime_version_match is not True:
        issues.append("runtime_version_unproven")

    if not expected_visible_fact:
        issues.append("missing_expected_visible_fact")
    if ocr_requested and text_expectation is None:
        issues.append("ocr_without_expected_text_guard")
    if text_expectation is not None:
        if text_expectation.get("status") == "missing":
            return "red_step_expected_screen_text_missing", issues + ["expected_screen_text_missing"]
        if text_expectation.get("status") == "matched":
            if issues:
                return "yellow_step_screen_text_matched_with_caveats", issues
            return "green_step_screen_text_guarded", issues
        issues.append("screen_text_not_verified")
    elif not ocr_requested:
        issues.append("screen_fact_not_verified")

    return "yellow_step_screen_checkpoint_caveated", issues


def direct_report_checkpoint_verdict(report: Dict[str, Any]) -> Tuple[str, List[str], str]:
    """Return the direct screen/metadata checkpoint verdict and artifact for one step report."""
    metadata_summary = report.get("metadata") if isinstance(report.get("metadata"), dict) else {}
    screen_summary: Dict[str, Any] = {}
    text_expectation: Optional[Dict[str, Any]] = None
    ocr_requested = False
    if isinstance(report.get("screen_after"), dict):
        screen_summary = report["screen_after"]
        if isinstance(report.get("screen_after_text_expectation"), dict):
            text_expectation = report["screen_after_text_expectation"]
        ocr_requested = isinstance(report.get("screen_after_text"), dict)
    elif isinstance(report.get("screen"), dict):
        screen_summary = report["screen"]
        if isinstance(report.get("screen_text_expectation"), dict):
            text_expectation = report["screen_text_expectation"]
        ocr_requested = isinstance(report.get("screen_text"), dict)

    if metadata_summary:
        verdict, issues = metadata_checkpoint_verdict(metadata_summary)
        artifact = str(metadata_summary.get("artifact_path", "")) or "probe.report.json:steps[].metadata"
        return verdict, issues, artifact

    verdict, issues = screen_checkpoint_verdict(
        screen_summary=screen_summary,
        expected_visible_fact=str(report.get("expected_visible_fact", "")).strip(),
        text_expectation=text_expectation,
        ocr_requested=ocr_requested,
    )
    return verdict, issues, screen_summary_path(screen_summary)


def declared_checkpoint_evidence_verdict(report: Mapping[str, Any]) -> Optional[Tuple[str, List[str]]]:
    """Classify an explicitly declared checkpoint by its authoritative owner.

    Rendered frames remain required evidence unless a scenario states both that
    the checkpoint is incidental and which later bound owner proves it.  A
    required checkpoint may use a run-bound semantic HUD verdict, but it never
    becomes green merely because a screenshot was captured.
    """
    declaration = report.get("checkpoint_evidence")
    if not isinstance(declaration, Mapping):
        return None
    classification = str(declaration.get("classification", "")).strip()
    authority = str(declaration.get("authoritative_owner", "")).strip()
    if classification not in {
        "incidental_lifecycle_observation",
        "incidental_bootstrap_observation",
        "required_feature_evidence",
    }:
        return "red_step_checkpoint_evidence_declaration_invalid", [
            "invalid_checkpoint_evidence_classification"
        ]
    if authority not in {
        "bound_startup_semantic_hud",
        "bound_semantic_ui",
        "structured_terminal_gate",
        "post_relaunch_lifecycle",
    }:
        return "red_step_checkpoint_evidence_declaration_invalid", [
            "invalid_checkpoint_evidence_owner"
        ]
    if classification == "required_feature_evidence" and authority != "bound_startup_semantic_hud":
        return "red_step_checkpoint_evidence_declaration_invalid", [
            "required_checkpoint_has_no_supported_authority"
        ]
    if authority == "bound_startup_semantic_hud":
        verdict = report.get("startup_semantic_hud_expectation")
        if not isinstance(verdict, Mapping) or verdict.get("status") != "green":
            return "red_step_required_semantic_hud_missing", [
                "bound_startup_semantic_hud_not_green"
            ]
    elif authority == "bound_semantic_ui":
        verdict = report.get("semantic_ui_expectation")
        if not isinstance(verdict, Mapping) or verdict.get("status") != "green":
            return "red_step_required_semantic_ui_missing", [
                "bound_semantic_ui_not_green"
            ]
    # The structured gate and post-relaunch owners are evaluated after this
    # local ledger.  Their independent final gates remain fail-closed.
    if classification == "required_feature_evidence":
        return "green_step_required_bound_semantic_hud", []
    return "green_step_incidental_checkpoint_owned_elsewhere", []


def auto_step_action_description(report: Dict[str, Any]) -> str:
    kind = str(report.get("kind", "")).strip()
    if kind == "press":
        return "peekaboo press sequence " + json.dumps(report.get("keys", []), ensure_ascii=False)
    if kind == "type":
        return "peekaboo type text" + (" and submit" if report.get("submit") else "")
    if kind == "capture":
        return "capture screenshot / optional OCR"
    if kind in {"long_wait", "wait_action"}:
        return "open bounded wait menu and select duration"
    if kind == "advance_turns":
        return f"send one-turn wait key {int(report.get('count', 0) or 0)} time(s)"
    if kind == "wait":
        return f"sleep wall-clock {report.get('seconds', '')} second(s)"
    if kind == "audit_log_contains":
        return "scan harness debug log delta for required UI trace patterns"
    if kind == "audit_log_not_contains":
        return "scan harness debug log delta and require forbidden trace patterns to be absent"
    if kind == "audit_player_message_log_contains":
        return "scan saved player message log for narrow decisive in-game message lines"
    if kind.startswith("debug_"):
        return f"debug helper primitive {kind}"
    return kind or "scenario step"


def step_interruption_flags(report: Dict[str, Any]) -> Dict[str, bool]:
    handlers: List[Dict[str, Any]] = []
    portal_storm_allowed = bool(report.get("portal_storm_allowed", False))
    direct = report.get("interruption_handling")
    if isinstance(direct, dict):
        handlers.append(direct)
    timing = report.get("timing")
    if isinstance(timing, dict):
        portal_storm_allowed = portal_storm_allowed or bool(
            timing.get("portal_storm_allowed", False)
        )
        for batch in timing.get("batches", []):
            if not isinstance(batch, dict):
                continue
            handlers.extend(
                handler
                for handler in batch.get("interruption_reports", [])
                if isinstance(handler, dict)
            )
    return {
        "release_blocking": any(bool(handler.get("release_blocking", False)) for handler in handlers),
        "contaminating": not portal_storm_allowed and any(
            bool(handler.get("contaminating", False)) for handler in handlers
        ),
    }


def adaptive_semantic_receipt_chain_status(report: Mapping[str, Any]) -> Dict[str, Any]:
    """Accept adaptive progress only from the saved, bound native receipt chain."""
    session = report.get("semantic_session")
    progress = report.get("semantic_progress")
    receipts = report.get("semantic_receipts")
    next_frame = report.get("next_semantic_frame")
    if not isinstance(session, Mapping) or not isinstance(progress, Mapping):
        return {"proved": False, "reason": "semantic_session_or_progress_missing"}
    run_id = str(session.get("run_id", "")).strip()
    session_id = str(session.get("session_id", "")).strip()
    required_actions = [str(action).strip() for action in session.get("required_action_chain", []) if str(action).strip()]
    required_interruptions = [str(action).strip() for action in session.get("required_interrupt_action_chain", []) if str(action).strip()]
    recovery_contract = session.get("recovery_contract")
    if recovery_contract is not None and not isinstance(recovery_contract, Mapping):
        return {"proved": False, "reason": "semantic_recovery_contract_malformed"}
    recovery_actions = [
        str(action).strip()
        for action in recovery_contract.get("actions", [])
        if str(action).strip()
    ] if isinstance(recovery_contract, Mapping) else []
    if not run_id or not session_id or not required_actions:
        return {"proved": False, "reason": "semantic_receipt_identity_or_requirements_missing"}
    if not isinstance(receipts, list):
        return {"proved": False, "reason": "semantic_receipts_missing"}
    accepted_actions: Set[str] = set()
    accepted_receipts: List[Mapping[str, Any]] = []
    for receipt in receipts:
        if not isinstance(receipt, Mapping) or receipt.get("accepted") is not True:
            continue
        action_id = str(receipt.get("action_id", "")).strip()
        frame_id = str(receipt.get("frame_id", "")).strip()
        native = receipt.get("native_receipt")
        response = receipt.get("semantic_response")
        if str(receipt.get("run_id", "")).strip() != run_id or str(receipt.get("session_id", "")).strip() != session_id or not action_id or not frame_id or not isinstance(native, Mapping) or not isinstance(response, Mapping) or not isinstance(receipt.get("next_frame"), Mapping):
            continue
        if native.get("accepted") is True and response.get("accepted") is True and str(native.get("frame_id", "")).strip() == frame_id and str(native.get("action_id", "")).strip() == action_id and str(response.get("frame_id", "")).strip() == frame_id and str(response.get("action_id", "")).strip() == action_id:
            accepted_actions.add(action_id)
            accepted_receipts.append(receipt)
    missing = [action for action in required_actions + required_interruptions + recovery_actions if action not in accepted_actions]
    if missing:
        return {"proved": False, "reason": "accepted_receipt_missing", "missing_actions": missing}
    if progress.get("action_chain_proved") is not True or \
            progress.get("interruption_receipts_proved") is not True:
        return {"proved": False, "reason": "semantic_progress_summary_unproved"}
    recovery_modal_identity = ""
    if isinstance(recovery_contract, Mapping):
        issuer_action = str(recovery_contract.get("issuer_action", "")).strip()
        modal_state = str(recovery_contract.get("modal_state", "")).strip()
        modal_owner = str(recovery_contract.get("modal_owner", "")).strip()
        if not issuer_action or not modal_state or not modal_owner or not recovery_actions:
            return {"proved": False, "reason": "semantic_recovery_contract_incomplete"}
        issuer = next((receipt for receipt in accepted_receipts
                       if str(receipt.get("action_id", "")).strip() == issuer_action), None)
        modal = issuer.get("next_frame") if isinstance(issuer, Mapping) else None
        if not isinstance(modal, Mapping):
            return {"proved": False, "reason": "native_recovery_modal_missing"}
        recovery_modal_identity = str(modal.get("frame_id", "")).strip()
        if not recovery_modal_identity or modal.get("state") != modal_state or \
                modal.get("provenance") != modal_owner:
            return {"proved": False, "reason": "native_recovery_modal_mismatch"}
        for action in recovery_actions:
            recovery = next((receipt for receipt in accepted_receipts
                             if str(receipt.get("action_id", "")).strip() == action), None)
            current = recovery.get("current_frame") if isinstance(recovery, Mapping) else None
            if not isinstance(current, Mapping) or \
                    str(recovery.get("frame_id", "")).strip() != recovery_modal_identity or \
                    str(current.get("frame_id", "")).strip() != recovery_modal_identity or \
                    current.get("state") != modal_state or \
                    current.get("provenance") != modal_owner or \
                    action not in current.get("valid_actions", []):
                return {"proved": False, "reason": "native_recovery_receipt_unbound"}
    if not isinstance(next_frame, Mapping) or next_frame.get("state") != "world":
        return {"proved": False, "reason": "fresh_world_postcondition_missing"}
    return {
        "proved": True,
        "reason": "accepted_receipt_chain",
        **({"recovery_modal_identity": recovery_modal_identity} if recovery_modal_identity else {}),
    }


def adaptive_semantic_interrupt_contract(
    step: Mapping[str, Any],
) -> Tuple[List[str], List[str]]:
    """Separate conditional recovery capabilities from required occurrences."""
    adaptive_actions = [
        str(item).strip() for item in step.get("adaptive_interrupt_actions", [])
        if str(item).strip()
    ]
    required_actions = [
        str(item).strip() for item in step.get("required_interrupt_action_chain", [])
        if str(item).strip()
    ]
    return adaptive_actions, required_actions


def adaptive_semantic_materiality_waivers(report: Mapping[str, Any]) -> List[Dict[str, Any]]:
    """Record only proved non-occurrence of an optional recovery branch.

    An advertised recovery capability is not evidence that its triggering
    interruption occurred.  This evaluator may waive only the absent optional
    action after the required transaction and fresh-world postcondition are
    independently proved.  Any abort or explicit requirement remains red.
    """
    session = report.get("semantic_session")
    progress = report.get("semantic_progress")
    next_frame = report.get("next_semantic_frame")
    if not isinstance(session, Mapping) or not isinstance(progress, Mapping) or \
            not isinstance(next_frame, Mapping) or isinstance(report.get("abort"), Mapping):
        return []
    if progress.get("action_chain_proved") is not True or \
            progress.get("interruption_receipts_proved") is not True or \
            progress.get("optional_interrupt_scan_complete") is not True or \
            next_frame.get("state") != "world":
        return []

    optional_actions = [
        str(action).strip()
        for action in session.get("adaptive_interrupt_actions", [])
        if str(action).strip()
    ]
    required_actions = {
        str(action).strip()
        for action in session.get("required_interrupt_action_chain", [])
        if str(action).strip()
    }
    recovery_contract = session.get("recovery_contract")
    if isinstance(recovery_contract, Mapping):
        required_actions.update(
            str(action).strip()
            for action in recovery_contract.get("actions", [])
            if str(action).strip()
        )
    receipts = report.get("semantic_receipts")
    if not isinstance(receipts, list):
        return []
    run_id = str(session.get("run_id", "")).strip()
    session_id = str(session.get("session_id", "")).strip()
    if not run_id or not session_id:
        return []
    accepted_actions = {
        str(receipt.get("action_id", "")).strip()
        for receipt in receipts
        if isinstance(receipt, Mapping) and receipt.get("accepted") is True
        and str(receipt.get("run_id", "")).strip() == run_id
        and str(receipt.get("session_id", "")).strip() == session_id
    }
    observed_recovery_actions = {
        str(interruption.get("action_id", "")).strip()
        for interruption in report.get("native_activity_distraction_interruptions", [])
        if isinstance(interruption, Mapping)
        and interruption.get("status") == "recovered"
        and str(interruption.get("action_id", "")).strip()
    }

    waivers: List[Dict[str, Any]] = []
    for action_id in optional_actions:
        if action_id in required_actions or action_id in accepted_actions or \
                action_id in observed_recovery_actions:
            continue
        waiver = {
            "schema": "caol-materiality-waiver-v1",
            "original_failure": {
                "kind": "optional_recovery_action_absent",
                "action_id": action_id,
            },
            "materiality_decision": "proved_non_causal",
            "positive_evidence": {
                "trigger_observed": False,
                "action_explicitly_required": False,
                "required_action_chain_proved": True,
                "required_recovery_proved": True,
                "optional_interrupt_scan_complete": True,
                "fresh_postcondition_state": "world",
                "run_id": run_id,
                "session_id": session_id,
            },
            "protected_surfaces_affected": [],
            "continuation_rationale": (
                "The native interruption never occurred; its recovery action was optional, "
                "while the required transaction and fresh-world postcondition were proved."
            ),
            "preserves_original_failure": True,
            "evidence_effect": "none",
        }
        waiver["waiver_id"] = hashlib.sha256(
            json.dumps(waiver, sort_keys=True, separators=(",", ":")).encode("utf-8")
        ).hexdigest()
        waivers.append(waiver)
    return waivers


def collect_materiality_waivers(report: Mapping[str, Any]) -> List[Dict[str, Any]]:
    """Expose every exercised step waiver once at the report boundary."""
    waivers: List[Dict[str, Any]] = []
    seen: Set[str] = set()
    for step in report.get("steps", []):
        if not isinstance(step, Mapping):
            continue
        for waiver in step.get("materiality_waivers", []):
            if not isinstance(waiver, Mapping):
                continue
            waiver_id = str(waiver.get("waiver_id", "")).strip()
            if not waiver_id or waiver_id in seen:
                continue
            seen.add(waiver_id)
            waivers.append(dict(waiver))
    return waivers


def pending_adaptive_semantic_recovery(report: Mapping[str, Any]) -> Optional[Dict[str, Any]]:
    """Name a current advertised recovery that must outlive report finalization."""
    for step in report.get("steps", []):
        if not isinstance(step, Mapping) or step.get("kind") != "adaptive_semantic_window":
            continue
        session = step.get("semantic_session")
        receipts = step.get("semantic_receipts")
        if not isinstance(session, Mapping) or not isinstance(receipts, list):
            continue
        run_id = str(session.get("run_id", "")).strip()
        session_id = str(session.get("session_id", "")).strip()
        required = [str(action).strip() for action in session.get("required_interrupt_action_chain", []) if str(action).strip()]
        recovery_contract = session.get("recovery_contract")
        if isinstance(recovery_contract, Mapping):
            required.extend(
                str(action).strip() for action in recovery_contract.get("actions", [])
                if str(action).strip()
            )
        if not run_id or not session_id or not required:
            continue
        accepted = {str(receipt.get("action_id", "")).strip() for receipt in receipts if isinstance(receipt, Mapping) and receipt.get("accepted") is True and str(receipt.get("run_id", "")).strip() == run_id and str(receipt.get("session_id", "")).strip() == session_id}
        for receipt in reversed(receipts):
            if not isinstance(receipt, Mapping) or receipt.get("accepted") is not True:
                continue
            frame = receipt.get("next_frame")
            if not isinstance(frame, Mapping):
                continue
            pending = [action for action in required if action in {str(value).strip() for value in frame.get("valid_actions", [])} and action not in accepted]
            if pending:
                return {"step_label": str(step.get("label", "")), "run_id": run_id, "session_id": session_id, "issuing_frame_id": str(frame.get("frame_id", "")), "required_actions": pending}
    return None


def r023_relative_movement_step_verdict(
    descriptor: Mapping[str, Any], final: Mapping[str, Any], metadata: Mapping[str, Any],
) -> Tuple[str, List[str]]:
    """Classify one zero-credit R-023 route without accepting its sibling.

    This remains deliberately local: final registry ingestion owns source/binding
    and process cleanup, while this classifier proves that the selected live
    authority produced one exact relative-operation receipt chain.
    """
    operation = str(descriptor.get("relative_movement_operation", "")).strip()
    expected_action = f"game.{operation}"
    failures: List[str] = []
    transcript = final.get("action_observation_sequence")
    movement_result: Mapping[str, Any] = {}
    if not isinstance(transcript, list):
        failures.append("r023_missing_ordered_transcript")
    else:
        matching = [entry for entry in transcript if isinstance(entry, Mapping) and
                    entry.get("kind") == operation and isinstance(entry.get("result"), Mapping)]
        native_actions = [entry for entry in transcript if isinstance(entry, Mapping) and
                          entry.get("kind") == "action" and isinstance(entry.get("result"), Mapping)]
        sibling = [entry for entry in transcript if isinstance(entry, Mapping) and
                   entry.get("kind") in {"raw_move_relative", "guarded_move_relative"} and
                   entry.get("kind") != operation]
        if not matching and native_actions and not sibling:
            # The live bridge records each native cardinal dispatch as an
            # action entry; the selected descriptor is the sole owner of its
            # enclosing relative operation.
            matching = native_actions
        if not matching or sibling:
            failures.append("r023_operation_not_exactly_selected")
        elif isinstance(matching[0].get("result"), Mapping) and matching[0].get("kind") == operation:
            movement_result = matching[0]["result"]
    if descriptor.get("live_operations") != [expected_action]:
        failures.append("r023_live_authority_allows_fallback")
    detail = final.get("stop_detail")
    packet = movement_result if movement_result else detail if isinstance(detail, Mapping) else {}
    receipts = packet.get("native_receipts") if isinstance(packet, Mapping) else None
    partial = packet.get("partial_progress") if isinstance(packet, Mapping) else None
    planned = packet.get("planned_steps") if isinstance(packet, Mapping) else None
    bound = packet.get("derived_bound") if isinstance(packet, Mapping) else None
    terminal = packet.get("terminal_absolute_ms") if isinstance(packet, Mapping) else None
    valid_position = lambda value: isinstance(value, list) and len(value) == 3 and all(
        isinstance(component, int) and not isinstance(component, bool) for component in value)
    if not isinstance(receipts, list) or not isinstance(partial, int) or isinstance(partial, bool) or \
            not isinstance(planned, int) or isinstance(planned, bool) or partial != len(receipts) or \
            partial < 0 or planned < partial:
        failures.append("r023_partial_progress_or_receipts_unbound")
    else:
        expected_before = packet.get("origin_absolute_ms") if isinstance(packet, Mapping) else None
        for receipt in receipts:
            native = receipt.get("native_receipt") if isinstance(receipt, Mapping) else None
            next_frame = receipt.get("next_frame") if isinstance(receipt, Mapping) else None
            next_observation = next_frame.get("observation") if isinstance(next_frame, Mapping) else None
            next_avatar = next_observation.get("avatar") if isinstance(next_observation, Mapping) else None
            frame_after = next_avatar.get("absolute_ms") if isinstance(next_avatar, Mapping) else None
            if not isinstance(native, Mapping) or native.get("outcome") != "moved" or \
                    native.get("coordinate_space") != "absolute_ms" or \
                    not valid_position(native.get("before_absolute_ms")) or \
                    not valid_position(native.get("expected_absolute_ms")) or \
                    not valid_position(native.get("after_absolute_ms")) or \
                    native.get("before_absolute_ms") != expected_before or \
                    native.get("after_absolute_ms") != native.get("expected_absolute_ms") or \
                    frame_after != native.get("after_absolute_ms"):
                failures.append("r023_coordinate_space_receipt_frame_mismatch")
                break
            expected_before = native.get("after_absolute_ms")
    if not isinstance(bound, Mapping) or bound.get("unit") != "steps" or \
            not isinstance(bound.get("maximum"), int) or isinstance(bound.get("maximum"), bool) or \
            bound.get("maximum", 0) < planned:
        failures.append("r023_derived_bound_unproved")
    if not valid_position(packet.get("origin_absolute_ms") if isinstance(packet, Mapping) else None) or \
            not valid_position(packet.get("target_absolute_ms") if isinstance(packet, Mapping) else None) or \
            not valid_position(terminal):
        failures.append("r023_terminal_position_unproved")
    stop_reason = str(final.get("stop_reason", "")).strip()
    if stop_reason == "target_reached":
        if partial != planned or terminal != packet.get("target_absolute_ms"):
            failures.append("r023_target_terminal_mismatch")
    elif stop_reason.endswith("_receipt_mismatch"):
        # A native receipt that claims a move but whose fresh terminal frame
        # remains elsewhere is the first causal divergence, not a passable
        # partial-movement result.
        failures.append("r023_native_receipt_postcondition_mismatch")
    elif not stop_reason.startswith(f"{operation}_") and stop_reason not in {"binding_drift", "derived_bound_exhausted"}:
        failures.append("r023_stop_reason_not_exact")
    cleanup = final.get("cleanup")
    if not isinstance(cleanup, Mapping) or cleanup.get("status") != "deferred_to_scenario_terminalization":
        failures.append("r023_cleanup_not_owned_by_terminalization")
    if metadata.get("gameplay_credit") is not False:
        failures.append("r023_zero_credit_effect_missing")
    return ("green_step_r023_relative_movement_receipt" if not failures else
            "yellow_step_r023_relative_movement_receipt_unbound", failures)


def cockpit_live_session_step_verdict(
    report: Mapping[str, Any], *, wec_authority: Mapping[str, Any],
    report_binding_id: str, scenario_source_sha256: str,
) -> Tuple[str, List[str]]:
    """Recognize only a fully bound worker cockpit local-proof boundary.

    A cockpit final is not ordinary metadata: it is the worker's explicit
    terminal transaction.  It earns a green ledger row only when its session
    and final agree, its event watermark belongs to that same run and step,
    and the enclosing registry authority still binds this report, source, and
    complete runtime binding.  Every other cockpit-shaped row remains
    non-authoritative.
    """
    descriptor = report.get( "cockpit_live_session", {} )
    descriptor = descriptor.get( "descriptor", {} ) if isinstance( descriptor, Mapping ) else {}
    final = report.get( "cockpit_live_session", {} )
    final = final.get( "final", {} ) if isinstance( final, Mapping ) else {}
    watermark = report.get( "structured_event_watermark", {} )
    metadata = report.get( "metadata", {} )
    label = str( report.get( "label", "" ) ).strip()
    index = report.get( "index" )
    descriptor_run_id = str( descriptor.get( "run_id", "" ) ).strip()
    descriptor_binding_id = str( descriptor.get( "binding_id", "" ) ).strip()
    if str(descriptor.get("relative_movement_operation", "")).strip() in {
            "raw_move_relative", "guarded_move_relative"}:
        return r023_relative_movement_step_verdict(descriptor, final, metadata if isinstance(metadata, Mapping) else {})
    failures: List[str] = []
    if descriptor.get( "schema" ) != "caol-cockpit-live-session-v1" or \
            descriptor.get( "entry_mode" ) != "cockpit_live_session":
        failures.append( "missing_or_invalid_cockpit_descriptor" )
    if not descriptor_run_id or not descriptor_binding_id or not str(
            descriptor.get( "bridge_binding_id", "" ) ).strip():
        failures.append( "missing_cockpit_run_or_binding" )
    if final.get( "schema" ) != "caol-cockpit-live-final-v1" or \
            str( final.get( "run_id", "" ) ).strip() != descriptor_run_id or \
            str( final.get( "binding_id", "" ) ).strip() != descriptor_binding_id:
        failures.append( "final_not_bound_to_cockpit_session" )
    stop_detail = final.get( "stop_detail", {} )
    matrix = stop_detail.get( "r019_acceptance_matrix" ) if isinstance( stop_detail, Mapping ) else None
    drift = stop_detail.get( "binding_drift_receipt" ) if isinstance( stop_detail, Mapping ) else None
    hostile_stop = stop_detail.get( "r019_hostile_stop_receipt" ) if isinstance( stop_detail, Mapping ) else None
    r019_binding_drift_control = (
        final.get( "state" ) == "finished" and final.get( "stop_reason" ) == "binding_drift" and
        isinstance( matrix, Mapping ) and matrix.get( "role" ) == "off:enabled" and
        isinstance( drift, Mapping ) and
        drift.get( "schema" ) == "caol-r019-binding-drift-terminal-receipt-v1" and
        drift.get( "stop_reason" ) == "binding_drift" and
        drift.get( "native_dispatch_after_drift" ) is False and
        drift.get( "native_dispatch_count_after_drift" ) == 0 and
        drift.get( "guarded_recipe_dispatch_count" ) == 0 and
        drift.get( "guarded_handling_count" ) == 0 and drift.get( "hidden_batching" ) is False and
        isinstance( drift.get( "before" ), Mapping ) and
        isinstance( drift.get( "after" ), Mapping ) and
        drift["before"].get( "identity" ) == "runtime_binding" and
        str( drift["before"].get( "hash", "" ) ).strip() and
        drift["after"].get( "identity" ) == "runtime_binding" and
        str( drift["after"].get( "hash", "" ) ).strip() and
        drift["before"].get( "hash" ) != drift["after"].get( "hash" ) and
        isinstance( drift.get( "supported_drift_mutation_receipt" ), Mapping ) and
        str( drift.get( "attempted_action", "" ) ).strip()
    )
    r019_off_hostile_interruption_control = (
        final.get( "state" ) == "finished" and final.get( "stop_reason" ) == "hostile_spotted_near" and
        isinstance( matrix, Mapping ) and matrix.get( "role" ) == "off:master_enabled" and
        isinstance( hostile_stop, Mapping ) and
        hostile_stop.get( "schema" ) == "caol-r019-off-hostile-stop-receipt-v1" and
        hostile_stop.get( "type" ) == "hostile_spotted_near" and
        hostile_stop.get( "advertised_action" ) == "activity.ignore" and
        hostile_stop.get( "advertised_action_dispatched" ) is False and
        hostile_stop.get( "continuation_stopped" ) is True and
        str( hostile_stop.get( "post_stop_observation_id", "" ) ).strip() and
        isinstance( hostile_stop.get( "pre_wait_game_minutes" ), ( int, float ) ) and
        not isinstance( hostile_stop.get( "pre_wait_game_minutes" ), bool ) and
        isinstance( hostile_stop.get( "interruption_game_minutes" ), ( int, float ) ) and
        not isinstance( hostile_stop.get( "interruption_game_minutes" ), bool ) and
        isinstance( hostile_stop.get( "partial_progress" ), ( int, float ) ) and
        not isinstance( hostile_stop.get( "partial_progress" ), bool ) and
        hostile_stop.get( "partial_progress" ) > 0 and
        hostile_stop.get( "interruption_game_minutes" ) - hostile_stop.get( "pre_wait_game_minutes" ) ==
        hostile_stop.get( "partial_progress" ) and
        isinstance( matrix.get( "off_switch_receipt" ), Mapping ) and
        matrix["off_switch_receipt"].get( "switch" ) == "master_enabled" and
        matrix["off_switch_receipt"].get( "native_dispatch_count" ) == 0 and
        matrix["off_switch_receipt"].get( "guarded_recipe_dispatch_count" ) == 0 and
        matrix["off_switch_receipt"].get( "guarded_handling_count" ) == 0 and
        matrix["off_switch_receipt"].get( "hidden_batching" ) is False and
        matrix["off_switch_receipt"].get( "native_receipt_actions" ) == [
            "world.wait", "wait.duration_menu", "wait.1m",
        ] and
        matrix["off_switch_receipt"].get( "primitive_native_dispatch_count" ) == 3
    )
    terminal_control = r019_binding_drift_control or r019_off_hostile_interruption_control
    if not terminal_control and (
            final.get( "state" ) != "finished" or final.get( "stop_reason" ) != "target_predicate_proved" ):
        failures.append( "cockpit_target_not_explicitly_proved" )
    target_receipt = final.get( "target_receipt" )
    if target_receipt is None and isinstance( stop_detail, Mapping ):
        target_receipt = stop_detail.get( "target_receipt" )
    if not terminal_control and ( not isinstance( target_receipt, Mapping ) or \
            target_receipt.get( "schema" ) != "caol-cockpit-target-receipt-v1" or \
            str( target_receipt.get( "run_id", "" ) ).strip() != descriptor_run_id or \
            str( target_receipt.get( "binding_id", "" ) ).strip() != descriptor_binding_id or \
            str( target_receipt.get( "step_label", "" ) ).strip() != label or \
            target_receipt.get( "step_index" ) != index or \
            target_receipt.get( "stop_reason" ) != "target_predicate_proved" or \
            not isinstance( stop_detail, Mapping ) or \
            str( target_receipt.get( "observation_id", "" ) ).strip() != str(
                stop_detail.get( "observation_id", "" )
            ).strip() ):
        failures.append( "cockpit_target_receipt_not_bound_to_run_and_step" )
    transcript = final.get( "action_observation_sequence" )
    if not isinstance( transcript, list ) or not any(
            isinstance( entry, Mapping ) and entry.get( "kind" ) == "action" and
            isinstance( entry.get( "result" ), Mapping ) and entry["result"].get( "ok" ) is True
            for entry in transcript ) or sum(
                isinstance( entry, Mapping ) and entry.get( "kind" ) == "observation"
                for entry in transcript ) < 2:
        failures.append( "cockpit_transaction_incomplete" )
    if not isinstance( watermark, Mapping ) or str( watermark.get( "run_id", "" ) ).strip() != descriptor_run_id or \
            str( watermark.get( "step_label", "" ) ).strip() != label or watermark.get( "step_index" ) != index:
        failures.append( "cockpit_local_boundary_not_same_run" )
    metadata_is_bound_live_artifact = isinstance( metadata, Mapping ) and \
        metadata.get( "artifact_kind" ) == "worker_controlled_live_cockpit_session" and \
        str( metadata.get( "descriptor_ref", "" ) ).strip() and str(
            metadata.get( "final_report_ref", "" ) ).strip()
    expected_gameplay_credit = False if terminal_control else True
    if not metadata_is_bound_live_artifact or metadata.get( "gameplay_credit" ) is not expected_gameplay_credit:
        failures.append( "cockpit_final_artifacts_unavailable" )
    if wec_authority.get( "authority" ) != "registry" or not str(
            wec_authority.get( "authority_id", "" ) ).strip() or \
            str( wec_authority.get( "binding_id", "" ) ).strip() != report_binding_id or \
            str( wec_authority.get( "source_sha256", "" ) ).strip() != scenario_source_sha256:
        failures.append( "cockpit_authority_not_bound_to_report_source_and_executable" )
    if failures:
        return "yellow_step_cockpit_local_proof_unbound", failures
    return "green_step_cockpit_local_proof", []


def build_probe_step_ledger(
    step_reports: List[Dict[str, Any]], *, wec_authority: Optional[Mapping[str, Any]] = None,
    report_binding_id: str = "", scenario_source_sha256: str = "",
    structured_gate_evidence: Optional[Mapping[str, Any]] = None,
) -> List[Dict[str, Any]]:
    ledger: List[Dict[str, Any]] = []
    reports_by_label = {
        str(report.get("label", "")).strip(): (position, report)
        for position, report in enumerate(step_reports)
    }
    for position, report in enumerate(step_reports):
        label = str(report.get("label", "")).strip()
        kind = str(report.get("kind", "")).strip().lower()
        expected_visible_fact = str(report.get("expected_visible_fact", "")).strip()
        screen_summary: Dict[str, Any] = {}
        metadata_summary: Dict[str, Any] = {}
        text_expectation: Optional[Dict[str, Any]] = None
        ocr_requested = False

        if isinstance(report.get("metadata"), dict):
            metadata_summary = report["metadata"]
        if isinstance(report.get("screen_after"), dict):
            screen_summary = report["screen_after"]
            if isinstance(report.get("screen_after_text_expectation"), dict):
                text_expectation = report["screen_after_text_expectation"]
            ocr_requested = isinstance(report.get("screen_after_text"), dict)
        elif isinstance(report.get("screen"), dict):
            screen_summary = report["screen"]
            if isinstance(report.get("screen_text_expectation"), dict):
                text_expectation = report["screen_text_expectation"]
            ocr_requested = isinstance(report.get("screen_text"), dict)

        issues: List[str] = []
        deferred_evidence_artifact = ""
        interruption_flags = step_interruption_flags(report)
        if isinstance(report.get("abort"), dict) and report["abort"].get("guard") == "metadata":
            verdict, issues = metadata_checkpoint_verdict(metadata_summary)
            if not verdict.startswith(("red", "blocked")):
                verdict = "red_step_aborted_by_metadata_guard"
            issues = issues + ["metadata_abort_guard"]
        elif isinstance(report.get("abort"), dict):
            verdict = "red_step_aborted_by_screen_text_guard"
            issues.append("screen_text_abort_guard")
        elif interruption_flags["release_blocking"]:
            verdict = "red_step_acknowledged_release_blocking_popup"
            issues.append("release_blocking_popup_acknowledged")
        elif interruption_flags["contaminating"]:
            verdict = "yellow_step_acknowledged_contaminating_popup"
            issues.append("contaminating_popup_acknowledged")
        elif kind in {"long_wait", "wait_action"} and isinstance(report.get("wait_step_ledger"), dict):
            wait_verdict = str(report["wait_step_ledger"].get("verdict", ""))
            if wait_verdict.startswith("green"):
                verdict = "green_wait_step_proven"
            elif wait_verdict.startswith("blocked"):
                verdict = "blocked_wait_step_unproven"
            else:
                verdict = "yellow_wait_step_unproven"
            issues.extend(str(issue) for issue in report["wait_step_ledger"].get("issues", []))
        elif kind == "adaptive_semantic_window":
            if adaptive_semantic_receipt_chain_status(report)["proved"]:
                verdict = "green_adaptive_semantic_transaction_proven"
            else:
                verdict = "red_adaptive_semantic_transaction_unproved"
                issues.append("adaptive_semantic_transaction_unproved")
        elif kind == "debug_spawn_monster" and isinstance(metadata_summary, Mapping) and \
                metadata_summary.get("artifact_kind") == "native_debug_setup_intervention":
            required = {
                "schema": "caol-native-debug-spawn-monster-receipt-v1",
                "gameplay_credit": False,
                "intervention": "debug_spawn_monster",
                "spawn_count": 1,
            }
            native = metadata_summary.get("native_receipt")
            authority = metadata_summary.get("transaction_authority")
            cleanup_link = metadata_summary.get("cleanup_link")
            if any(metadata_summary.get(key) != value for key, value in required.items()) or \
                    not str(metadata_summary.get("creature_id", "")).strip() or \
                    not isinstance(metadata_summary.get("target_offset"), list) or \
                    len(metadata_summary["target_offset"]) != 3 or \
                    not isinstance(native, Mapping) or native.get("accepted") is not True or \
                    not isinstance(authority, Mapping) or authority.get("authority") != "registry" or \
                    authority.get("binding_id") != report_binding_id or \
                    authority.get("source_sha256") != scenario_source_sha256 or \
                    not isinstance(cleanup_link, Mapping) or cleanup_link.get("owner") != "finalize_scenario_report" or \
                    cleanup_link.get("required") is not True:
                verdict = "yellow_step_setup_intervention_receipt_unbound"
                issues.append("native_debug_setup_receipt_missing_or_contradictory")
            else:
                verdict = "green_step_setup_intervention_receipt"
        elif kind == "r021_direct_hp_setter" and isinstance(metadata_summary, Mapping):
            native = metadata_summary.get("native_receipt")
            cleanup = metadata_summary.get("cleanup_receipt")
            changed = metadata_summary.get("changed_creature_identities")
            if metadata_summary.get("artifact_kind") == "r021_direct_hp_setter" and \
                    metadata_summary.get("gameplay_credit") is False and \
                    isinstance(native, Mapping) and native.get("accepted") is True and \
                    native.get("hp_after") == 0 and \
                    isinstance(changed, list) and len(changed) == 1 and \
                    isinstance(cleanup, Mapping) and cleanup.get("accepted") is True and \
                    str(metadata_summary.get("artifact_path", "")).strip():
                verdict = "green_step_r021_native_direct_hp_transaction"
            else:
                verdict = "red_step_r021_native_direct_hp_transaction_unbound"
                issues.append("r021_native_receipt_snapshot_or_cleanup_missing")
        elif kind == "r022_item_spawn_bridge" and isinstance(metadata_summary, Mapping):
            transaction = metadata_summary.get("transaction")
            native = metadata_summary.get("native_receipt")
            cleanup = metadata_summary.get("cleanup_receipt")
            runtime = metadata_summary.get("runtime_binding")
            identities = native.get("identities") if isinstance(native, Mapping) else None
            declared_item_state = isinstance(transaction, Mapping) and \
                isinstance(transaction.get("transaction_id"), str) and bool(transaction.get("transaction_id")) and \
                isinstance(transaction.get("type"), str) and bool(transaction.get("type")) and \
                isinstance(transaction.get("quantity"), int) and not isinstance(transaction.get("quantity"), bool) and \
                transaction.get("quantity") > 0 and \
                isinstance(transaction.get("charges"), int) and not isinstance(transaction.get("charges"), bool) and \
                transaction.get("charges") >= 0 and \
                isinstance(transaction.get("damage"), int) and not isinstance(transaction.get("damage"), bool) and \
                transaction.get("damage") >= 0 and \
                isinstance(transaction.get("owner"), str) and bool(transaction.get("owner")) and \
                isinstance(transaction.get("destination_offset_ms"), list) and \
                len(transaction.get("destination_offset_ms")) == 3 and \
                all(type(value) is int for value in transaction.get("destination_offset_ms"))
            exact_transaction = declared_item_state and \
                isinstance(native, Mapping) and isinstance(cleanup, Mapping) and \
                isinstance(runtime, Mapping) and isinstance(identities, list) and \
                native.get("transaction_id") == transaction.get("transaction_id") and \
                native.get("type") == transaction.get("type") and \
                native.get("quantity") == transaction.get("quantity") and \
                native.get("charges") == transaction.get("charges") and \
                native.get("damage") == transaction.get("damage") and \
                native.get("owner") == transaction.get("owner") and \
                native.get("destination_offset_ms") == transaction.get("destination_offset_ms") and \
                cleanup.get("transaction_id") == transaction.get("transaction_id") and \
                len(identities) == transaction.get("quantity") and \
                {identity.get("ordinal") for identity in identities if isinstance(identity, Mapping)} == \
                set(range(transaction.get("quantity", -1))) and \
                all(isinstance(identity, Mapping) and identity.get("type") == transaction.get("type") and \
                    identity.get("charges") == transaction.get("charges") and \
                    identity.get("damage") == transaction.get("damage") and \
                    identity.get("owner") == transaction.get("owner") for identity in identities)
            if metadata_summary.get("artifact_kind") == "r022_item_spawn_transaction" and \
                    metadata_summary.get("bridge_owner") == "openclaw_harness_r022_item_spawn_bridge" and \
                    metadata_summary.get("gameplay_credit") is False and \
                    metadata_summary.get("evidence_effect") == "none_for_debug_fixture_transaction" and \
                    str(metadata_summary.get("run_id", "")).strip() == str(report.get("run_id", "")).strip() and \
                    str(report.get("run_id", "")).strip() and exact_transaction and \
                    native.get("accepted") is True and native.get("audit_passed") is True and \
                    native.get("zero_credit") is True and cleanup.get("accepted") is True and \
                    cleanup.get("audit_passed") is True and cleanup.get("zero_credit") is True and \
                    cleanup.get("removed") == transaction.get("quantity") and \
                    cleanup.get("retained_untagged") == 0 and str(runtime.get("source", "")).strip() and \
                    str(runtime.get("executable", "")).strip() and str(metadata_summary.get("artifact_path", "")).strip():
                verdict = "green_step_r022_native_item_spawn_transaction"
            else:
                verdict = "red_step_r022_native_item_spawn_transaction_unbound"
                issues.append("r022_native_receipt_cleanup_or_binding_missing_or_contradictory")
        elif kind == "cockpit_act" and isinstance(metadata_summary, Mapping) and \
                isinstance(metadata_summary.get("r019_hostile_interruption"), Mapping):
            interruption = metadata_summary["r019_hostile_interruption"]
            gates = (structured_gate_evidence or {}).get("gates", []) if isinstance(structured_gate_evidence, Mapping) else []
            source_bound = any(
                isinstance(gate, Mapping) and gate.get("id") == "r019_off_interruption_source_bound" and
                gate.get("status") == "green" for gate in gates
            )
            matching_setup = any(
                isinstance(candidate.get("metadata"), Mapping) and
                candidate["metadata"].get("artifact_kind") == "native_debug_setup_intervention" and
                candidate["metadata"].get("run_id") == metadata_summary.get("run_id") and
                candidate["metadata"].get("creature_id") == interruption.get("creature_id") and
                candidate["metadata"].get("target_offset") == interruption.get("target_offset") and
                candidate["metadata"].get("native_receipt", {}).get("accepted") is True
                for candidate in step_reports
            )
            if source_bound and matching_setup and interruption.get("type") == "hostile_spotted_near" and \
                    interruption.get("advertised_action") == "activity.ignore" and \
                    interruption.get("advertised_action_dispatched") is False and \
                    metadata_summary.get("gameplay_credit") is False:
                verdict = "green_step_r019_hostile_interruption_receipt"
            else:
                verdict = "yellow_step_r019_hostile_interruption_receipt_unbound"
                issues.append("r019_hostile_interruption_requires_source_gate_and_matching_native_setup_receipt")
        elif kind == "cockpit_live_session":
            verdict, issues = cockpit_live_session_step_verdict(
                report,
                wec_authority=wec_authority if isinstance( wec_authority, Mapping ) else {},
                report_binding_id=report_binding_id,
                scenario_source_sha256=scenario_source_sha256,
            )
        elif declared_checkpoint_evidence_verdict(report) is not None:
            verdict, issues = declared_checkpoint_evidence_verdict(report) or ("", [])
        elif metadata_summary:
            verdict, issues = metadata_checkpoint_verdict(metadata_summary)
        elif str(report.get("proof_deferred_to_label", "")).strip():
            deferred_label = str(report.get("proof_deferred_to_label", "")).strip()
            target_entry = reports_by_label.get(deferred_label)
            if target_entry and target_entry[0] > position:
                _, target_report = target_entry
                target_verdict, target_issues, deferred_evidence_artifact = direct_report_checkpoint_verdict(target_report)
                if target_verdict.startswith("green"):
                    verdict = "green_step_proof_deferred_to_guard"
                    issues = []
                elif target_verdict.startswith(("red", "blocked")):
                    verdict = "red_step_deferred_guard_failed"
                    issues = ["deferred_guard_failed"] + target_issues
                else:
                    verdict = "yellow_step_deferred_guard_incomplete"
                    issues = ["deferred_guard_incomplete"] + target_issues
            elif target_entry:
                verdict = "yellow_step_deferred_guard_not_later"
                issues = ["deferred_guard_not_later"]
            else:
                verdict = "yellow_step_deferred_guard_missing"
                issues = ["deferred_guard_missing"]
        else:
            verdict, issues = screen_checkpoint_verdict(
                screen_summary=screen_summary,
                expected_visible_fact=expected_visible_fact,
                text_expectation=text_expectation,
                ocr_requested=ocr_requested,
            )

        evidence_artifact = deferred_evidence_artifact
        if not evidence_artifact:
            evidence_artifact = screen_summary_path(screen_summary)
        if not evidence_artifact and metadata_summary:
            evidence_artifact = str(metadata_summary.get("artifact_path", "")) or "probe.report.json:steps[].metadata"
        if not evidence_artifact and kind in {"long_wait", "wait_action"}:
            evidence_artifact = str(report.get("wait_step_ledger", {}).get("wait_menu_artifact", ""))
        if not evidence_artifact and kind == "adaptive_semantic_window":
            evidence_artifact = "probe.report.json:steps[].semantic_receipts"
        if not evidence_artifact:
            evidence_artifact = "probe.report.json:steps"

        ledger.append({
            "index": report.get("index"),
            "primitive_step": label,
            "kind": kind,
            "preconditions": str(report.get("preconditions", "previous scenario gate allowed this step; profile/world/fixture from probe contract")),
            "action": str(report.get("action_description", "") or auto_step_action_description(report)),
            "expected_immediate_state": str(report.get("expected_immediate_state", "") or expected_visible_fact or "step-local state must be observed before this can support feature proof"),
            "evidence_artifact": evidence_artifact,
            "expected_visible_fact": expected_visible_fact,
            "screen_text_expectation": text_expectation or {},
            "metadata_expectation": {
                "required_terrain": metadata_summary.get("required_terrain", []),
                "required_fields": metadata_summary.get("required_fields", []),
                "required_items": metadata_summary.get("required_items", []),
                "required_furniture": metadata_summary.get("required_furniture", []),
                "required_traps": metadata_summary.get("required_traps", []),
                "required_radiation": metadata_summary.get("required_radiation", []),
                "required_monsters": metadata_summary.get("required_monsters", []),
                "required_npcs": metadata_summary.get("required_npcs", []),
                "required_new_npcs": metadata_summary.get("required_new_npcs", []),
                "required_observed_npc_count_delta": metadata_summary.get("required_observed_npc_count_delta"),
                "required_observed_npc_count": metadata_summary.get("required_observed_npc_count"),
                "observed_npc_count": metadata_summary.get("observed_npc_count"),
                "observed_npc_count_delta": metadata_summary.get("observed_npc_count_delta"),
                "missing_required_terrain": metadata_summary.get("missing_required_terrain", []),
                "missing_required_fields": metadata_summary.get("missing_required_fields", []),
                "missing_required_items": metadata_summary.get("missing_required_items", []),
                "missing_required_furniture": metadata_summary.get("missing_required_furniture", []),
                "missing_required_traps": metadata_summary.get("missing_required_traps", []),
                "missing_required_radiation": metadata_summary.get("missing_required_radiation", []),
                "missing_required_monsters": metadata_summary.get("missing_required_monsters", []),
                "missing_required_npcs": metadata_summary.get("missing_required_npcs", []),
                "missing_required_new_npcs": metadata_summary.get("missing_required_new_npcs", []),
                "missing_required_npc_count_delta": metadata_summary.get("missing_required_npc_count_delta", False),
                "missing_required_npc_count": metadata_summary.get("missing_required_npc_count", False),
                "missing_required_weather": metadata_summary.get("missing_required_weather", []),
                "required_weapon": metadata_summary.get("required_weapon", ""),
                "observed_weapon": metadata_summary.get("observed_weapon", ""),
                "required_weapon_ammo_type": metadata_summary.get("required_weapon_ammo_type", ""),
                "required_weapon_ammo_min": metadata_summary.get("required_weapon_ammo_min", 0),
                "observed_weapon_ammo_remaining": metadata_summary.get("observed_weapon_ammo_remaining", 0),
                "missing_required_weapon": metadata_summary.get("missing_required_weapon", []),
                "missing_required_weapon_ammo": metadata_summary.get("missing_required_weapon_ammo", []),
                "required_weather_id": metadata_summary.get("required_weather_id", ""),
                "required_temperature_f": metadata_summary.get("required_temperature_f"),
                "required_bandit_fields": metadata_summary.get("required_fields", {}),
                "required_min_delta_turns": metadata_summary.get("required_min_delta_turns"),
                "observed_delta_turns": metadata_summary.get("observed_delta_turns"),
                "missing_required_min_delta_turns": metadata_summary.get("missing_required_min_delta_turns", False),
                "active_member_scan_error": metadata_summary.get("active_member_scan_error", ""),
            } if metadata_summary else {},
            "proof_deferred_to_label": str(report.get("proof_deferred_to_label", "")),
            "failure_rule": str(report.get("failure_rule", "missing/wrong screen, failed OCR guard, stale runtime, or absent state metadata makes this non-green")),
            "next_step_gate": str(report.get("next_step_gate", "next step may run mechanically, but feature closure requires this ledger row to be green")),
            "issues": issues,
            "verdict": verdict,
            "materiality_waivers": report.get("materiality_waivers", []),
        })
    return ledger


def summarize_probe_step_ledger(step_ledger: List[Dict[str, Any]]) -> Dict[str, Any]:
    verdicts = [str(row.get("verdict", "")) for row in step_ledger]
    red_or_blocked = [row for row in step_ledger if str(row.get("verdict", "")).startswith(("red", "blocked"))]
    yellow = [row for row in step_ledger if str(row.get("verdict", "")).startswith("yellow")]
    green = [row for row in step_ledger if str(row.get("verdict", "")).startswith("green")]
    if red_or_blocked:
        status = "red_step_local_proof_failed"
    elif yellow:
        status = "yellow_step_local_proof_incomplete"
    elif step_ledger and len(green) == len(step_ledger):
        status = "green_step_local_proof"
    else:
        status = "no_feature_steps"
    return {
        "status": status,
        "count": len(step_ledger),
        "green_count": len(green),
        "yellow_count": len(yellow),
        "red_or_blocked_count": len(red_or_blocked),
        "verdicts": verdicts,
        "non_green_steps": [
            {
                "label": str(row.get("primitive_step", "")),
                "verdict": str(row.get("verdict", "")),
                "issues": row.get("issues", []),
            }
            for row in step_ledger if not str(row.get("verdict", "")).startswith("green")
        ],
        "review_rule": "Artifact matches are not feature proof unless every scenario step has green step-local proof.",
    }


def render_blink_compare(
    run_dir: Path,
    label: str,
    frame_names: List[str],
    *,
    scale: int = 1,
    frame_delay_ms: int = 450,
) -> Dict[str, Any]:
    frame_paths = [(run_dir / str(name)).resolve() for name in frame_names]
    missing_inputs = [str(path) for path in frame_paths if not path.exists()]
    ffmpeg_path = shutil.which("ffmpeg")
    output_path = run_dir / f"{label}.gif"
    concat_path = run_dir / f"{label}.ffconcat"
    report: Dict[str, Any] = {
        "kind": "blink_compare",
        "label": label,
        "inputs": [str(path) for path in frame_paths],
        "output_path": str(output_path),
        "scale": max(1, int(scale)),
        "frame_delay_ms": max(50, int(frame_delay_ms)),
        "ffconcat_path": str(concat_path),
    }
    if missing_inputs:
        report.update({
            "ok": False,
            "reason": "missing_inputs",
            "missing_inputs": missing_inputs,
        })
        return report
    if not ffmpeg_path:
        report.update({
            "ok": False,
            "reason": "missing_ffmpeg",
        })
        return report

    frame_delay_seconds = report["frame_delay_ms"] / 1000.0
    concat_lines = ["ffconcat version 1.0"]
    for frame_path in frame_paths:
        concat_lines.append(f"file '{frame_path}'")
        concat_lines.append(f"duration {frame_delay_seconds:.3f}")
    concat_lines.append(f"file '{frame_paths[-1]}'")
    concat_path.write_text("\n".join(concat_lines) + "\n", encoding="utf-8")

    scale_filter = "null"
    if report["scale"] > 1:
        scale_filter = f"scale=iw*{report['scale']}:ih*{report['scale']}:flags=neighbor"
    filter_complex = (
        f"[0:v]{scale_filter},split[s0][s1];"
        "[s0]palettegen=stats_mode=diff[p];"
        "[s1][p]paletteuse"
    )
    cmd = [
        ffmpeg_path,
        "-y",
        "-f",
        "concat",
        "-safe",
        "0",
        "-i",
        str(concat_path),
        "-vsync",
        "vfr",
        "-filter_complex",
        filter_complex,
        "-loop",
        "0",
        str(output_path),
    ]
    proc = subprocess.run(
        cmd,
        capture_output=True,
        text=True,
        check=False,
    )
    report.update({
        "ok": proc.returncode == 0,
        "command": cmd,
        "returncode": proc.returncode,
        "stdout": proc.stdout,
        "stderr": proc.stderr,
    })
    if proc.returncode != 0 and output_path.exists():
        output_path.unlink()
    return report


def render_derived_screens(run_dir: Path, specs: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
    reports: List[Dict[str, Any]] = []
    for index, spec in enumerate(specs, start=1):
        if not isinstance(spec, dict):
            reports.append({
                "ok": False,
                "kind": "invalid",
                "label": f"derived_screen_{index:02d}",
                "reason": "spec_not_object",
            })
            continue
        kind = str(spec.get("kind", "")).strip().lower()
        label = str(spec.get("label", f"derived_screen_{index:02d}")).strip() or f"derived_screen_{index:02d}"
        if kind == "blink_compare":
            raw_frames = spec.get("frames", [])
            frame_names = [str(frame).strip() for frame in raw_frames if str(frame).strip()] if isinstance(raw_frames, list) else []
            reports.append(
                render_blink_compare(
                    run_dir,
                    label,
                    frame_names,
                    scale=int(spec.get("scale", 1) or 1),
                    frame_delay_ms=int(spec.get("frame_delay_ms", 450) or 450),
                )
            )
            continue
        reports.append({
            "ok": False,
            "kind": kind or "unknown",
            "label": label,
            "reason": "unsupported_kind",
        })
    return reports


def kill_existing_game_processes() -> List[int]:
    proc = subprocess.run(["pgrep", "-f", "cataclysm-(tiles|tlg-tiles)"], capture_output=True, text=True, check=False)
    pids: List[int] = []
    for line in proc.stdout.splitlines():
        line = line.strip()
        if not line:
            continue
        try:
            pid = int(line)
        except ValueError:
            continue
        if pid == os.getpid():
            continue
        pids.append(pid)
    for pid in pids:
        subprocess.run(["kill", str(pid)], check=False, capture_output=True, text=True)
    if pids:
        time.sleep(1.0)
        for pid in pids:
            subprocess.run(["kill", "-9", str(pid)], check=False, capture_output=True, text=True)
    return pids


def certification_startup_lease_context(
    args: argparse.Namespace,
    *,
    executable: Path,
    target_world: str,
) -> Optional[Dict[str, Any]]:
    """Resolve the explicit certification-only lease inputs before process launch.

    Ordinary probes retain their existing global legacy cleanup path.  A bound
    certification run instead owns only the exact world/process named by its
    sealed manifest and registry path.
    """
    registry_path = str(getattr(args, "certification_registry", "") or "").strip()
    manifest_path = str(getattr(args, "certification_round_manifest", "") or "").strip()
    lease_id = str(getattr(args, "certification_lease_id", "") or "").strip()
    recheck_path = str(getattr(args, "certification_recheck_inputs", "") or "").strip()
    supplied = (registry_path, manifest_path, lease_id)
    if not any(supplied):
        return None
    if not all(supplied):
        raise SystemExit(
            "certification startup requires explicit --certification-registry, "
            "--certification-round-manifest, and --certification-lease-id"
        )
    try:
        manifest = load_certification_manifest(manifest_path)
        authoritative = manifest["binding"]["authoritative_components"]
        sealed_executable = Path(str(authoritative["executable"]["path"])).resolve()
        sealed_world = Path(str(authoritative["world_save"]["world"])).name
        if sealed_executable != executable.resolve():
            raise CertificationLeaseError("sealed manifest executable does not match the startup executable")
        if sealed_world != str(target_world).strip():
            raise CertificationLeaseError("sealed manifest world does not match the startup world")
        supplied_event_stream = str(getattr(args, "harness_run_id", "") or "").strip()
        if hasattr(args, "harness_run_id") and supplied_event_stream != str(manifest["event_stream_id"]):
            raise CertificationLeaseError("sealed manifest event stream does not match the startup run ID")
        executable_sha256 = path_sha256(executable)
        connection = open_registry(registry_path)
    except (CertificationLeaseError, KeyError, OSError, ValueError) as exc:
        raise SystemExit(f"certification startup lease rejected: {exc}") from exc
    return {
        "connection": connection,
        "manifest": manifest,
        "lease_id": lease_id,
        "recheck_inputs_path": recheck_path,
        "executable_path": str(executable.resolve()),
        "executable_sha256": executable_sha256,
        "inspector": SystemProcessInspector(),
    }


def certification_save_child_environment(context: Mapping[str, Any]) -> Dict[str, str]:
    """Inject the registry-issued save capability only into the game child."""
    capability = os.environ.get("OPENCLAW_CERTIFICATION_SAVE_CAPABILITY", "")
    manifest = context["manifest"]
    if not verify_certification_save_capability(
            context["connection"], round_id=str(manifest["round_id"]), capability=capability):
        raise CertificationLeaseError("certification save capability is absent or does not match the registry commitment")
    chain = _certification_world_save_chain(context["connection"], manifest)
    if not chain.get("ok"):
        raise CertificationLeaseError("certification save chain is not current")
    accepted = chain["accepted"]
    # The production save owner receives only sealed predecessor facts and
    # hashes its completed world tree before writing the receipt.
    return {
        "OPENCLAW_CERTIFICATION_ROUND_ID": str(manifest["round_id"]),
        "OPENCLAW_CERTIFICATION_LEASE_ID": str(context["lease_id"]),
        "OPENCLAW_CERTIFICATION_SAVE_CAPABILITY": capability,
        "OPENCLAW_CERTIFICATION_SAVE_SEQUENCE": str(int(chain["save_sequence"]) + 1),
        "OPENCLAW_CERTIFICATION_PREVIOUS_WORLD_TREE_SHA256": accepted["world_tree_sha256"],
        "OPENCLAW_CERTIFICATION_PREVIOUS_WORLD_SAVE_SHA256": accepted["world_save_sha256"],
    }


def _certification_recheck_producer_inputs(path_text: str) -> Dict[str, Any]:
    """Load the explicit current-input adapter used to recheck a sealed round.

    The adapter names current installed inputs; it does not carry a binding ID
    or any sealed value.  ``compare_round_manifest`` recomputes every identity
    from these inputs, so a caller cannot make a stale manifest pass by merely
    echoing its binding ID back into the command line.
    """
    path = Path(path_text).expanduser().resolve()
    try:
        raw = json.loads(path_text) if str(path_text).lstrip().startswith("{") else json.loads(path.read_text(encoding="utf-8"))
    except (OSError, UnicodeDecodeError, json.JSONDecodeError) as exc:
        raise CertificationLeaseError(f"certification recheck inputs are unreadable: {path}: {exc}") from exc
    if not isinstance(raw, dict):
        raise CertificationLeaseError("certification recheck inputs must be an object")
    required = {
        "repo_root", "executable", "runtime_paths", "data_config_roots",
        "harness_roots", "scenario_path", "fixture_path", "profile_path",
        "world_dir", "player_save", "saved_player_payload",
    }
    missing = sorted(required - set(raw))
    if missing:
        raise CertificationLeaseError(
            "certification recheck inputs are missing: " + ", ".join(missing)
        )
    if not isinstance(raw["runtime_paths"], list) or not all(
            isinstance(value, str) and value.strip() for value in raw["runtime_paths"]):
        raise CertificationLeaseError("certification recheck runtime_paths must be a non-empty string list")
    for name in ("data_config_roots", "harness_roots"):
        if not isinstance(raw[name], list) or not raw[name]:
            raise CertificationLeaseError(f"certification recheck {name} must be a non-empty list")
    for name in ("saved_player_payload",):
        if not isinstance(raw[name], dict):
            raise CertificationLeaseError(f"certification recheck {name} must be an object")
    return {
        "repo_root": Path(str(raw["repo_root"])).expanduser().resolve(),
        "executable": Path(str(raw["executable"])).expanduser().resolve(),
        "runtime_paths": list(raw["runtime_paths"]),
        "data_config_roots": [Path(str(value)).expanduser().resolve()
                              for value in raw["data_config_roots"]],
        "harness_roots": [Path(str(value)).expanduser().resolve()
                          for value in raw["harness_roots"]],
        "scenario_path": Path(str(raw["scenario_path"])).expanduser().resolve(),
        "fixture_path": Path(str(raw["fixture_path"])).expanduser().resolve(),
        "profile_path": Path(str(raw["profile_path"])).expanduser().resolve(),
        "world_dir": Path(str(raw["world_dir"])).expanduser().resolve(),
        "player_save": str(raw["player_save"]),
        "saved_player_payload": raw["saved_player_payload"],
        "ecology_audit": raw.get("ecology_audit"),
    }


def capture_certification_inputs(path_text: str) -> Dict[str, Any]:
    """Capture player and ecology identities from declared run artifacts.

    The production certification command accepts paths to artifacts captured
    by the selected run.  It does not accept caller-supplied passed objects.
    """
    path = Path(path_text).expanduser().resolve()
    try:
        raw = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, UnicodeDecodeError, json.JSONDecodeError) as exc:
        raise CertificationLeaseError(f"certification capture manifest is unreadable: {path}: {exc}") from exc
    if not isinstance(raw, dict):
        raise CertificationLeaseError("certification capture manifest must be an object")
    captures = raw.get("captured_artifacts")
    if not isinstance(captures, dict):
        raise CertificationLeaseError("certification launch requires captured_artifacts paths")
    if "saved_player_payload" in raw or "ecology_audit" in raw:
        raise CertificationLeaseError("certification launch rejects caller-supplied identity objects")
    captured: Dict[str, Any] = {}
    for key in ("saved_player_payload",):
        artifact = captures.get(key)
        if not isinstance(artifact, str) or not artifact.strip():
            raise CertificationLeaseError(f"captured artifact path is missing: {key}")
        artifact_path = Path(artifact).expanduser().resolve()
        try:
            value = json.loads(artifact_path.read_text(encoding="utf-8"))
        except (OSError, UnicodeDecodeError, json.JSONDecodeError) as exc:
            raise CertificationLeaseError(f"captured artifact is unreadable: {key}: {artifact_path}: {exc}") from exc
        if not isinstance(value, dict):
            raise CertificationLeaseError(f"captured artifact must be an object: {key}")
        captured[key] = value
    source = dict(raw)
    source.pop("captured_artifacts", None)
    source.update(captured)
    # Ecology is a post-start artifact.  Its absence is the required clean
    # preflight state; a supplied ecology audit is accepted only by the
    # explicit post-start binding transition.
    return _certification_recheck_producer_inputs(json.dumps(source, ensure_ascii=False))


def derive_registry_owned_certification_inputs(scenario_name: str) -> Dict[str, Any]:
    """Derive certification preflight solely from the installed scenario footing.

    This runs before the game process exists.  It intentionally reads the
    installed save for player identity and mutation checks, but never asks for
    ecology actors or lifecycle/receipt artifacts; those belong to the run.
    """
    scenario = load_scenario(scenario_name)
    profile = resolve_startup_config_profile(scenario, str(scenario.get("profile", "")))
    fixture_name = str(scenario.get("fixture", "")).strip()
    fixture_profile = str(scenario.get("fixture_profile", profile)).strip() or profile
    if not fixture_name:
        raise CertificationLeaseError("certification preflight fixture is missing")
    fixture_path = profile_fixture_root(resolve_profile_name(fixture_profile)) / fixture_name
    if not fixture_path.resolve().is_relative_to(fixtures_root().resolve()):
        raise CertificationLeaseError("certification fixture path escapes fixture root")
    world_name = str(scenario.get("world", "")).strip()
    world_root = save_dir_for_profile(profile).resolve()
    world_dir = (world_root / world_name).resolve()
    if not world_name or not world_dir.is_relative_to(world_root) or not world_dir.is_dir():
        raise CertificationLeaseError("certification preflight world is missing or escaped")
    player_save = str(scenario.get("installed_save_player", "")).strip()
    selected_save, save_path, payload, _ = load_saved_player_payload(world_dir, player_save)
    if selected_save != player_save:
        raise CertificationLeaseError("installed player save does not match scenario declaration")
    player = payload.get("player")
    if not isinstance(player, Mapping):
        raise CertificationLeaseError("installed player payload has no stable player object")
    stable_id = player.get("character_id", player.get("id", player.get("name")))
    if stable_id in (None, ""):
        raise CertificationLeaseError("installed player payload has no stable identity")
    required = list(scenario.get("required_stabilizer_traits", ()))
    observed = set(player.get("traits", ())) if isinstance(player.get("traits"), list) else set()
    missing = [trait for trait in required if trait not in observed]
    if missing:
        raise CertificationLeaseError("installed player mutations are missing: " + ", ".join(missing))
    scenario_path_value = scenario_path(scenario_name).resolve()
    profile_path = profile_config_path(profile).resolve()
    executable = detect_executable().resolve()
    return {
        "repo_root": repo_root(), "executable": executable,
        "runtime_paths": list(RUNTIME_RELEVANT_PATHS),
        "data_config_roots": [repo_root() / "data"],
        "harness_roots": [repo_root() / "tools" / "openclaw_harness"],
        "scenario_path": scenario_path_value, "fixture_path": (fixture_path / "manifest.json").resolve(),
        "profile_path": profile_path, "world_dir": world_dir,
        "player_save": selected_save, "saved_player_payload": payload,
    }


def _certification_plain(value: Any) -> Any:
    if isinstance(value, Mapping):
        return {key: _certification_plain(item) for key, item in value.items()}
    if isinstance(value, (list, tuple)):
        return [_certification_plain(item) for item in value]
    return value


def _certification_world_save_fact(world_save: Mapping[str, Any]) -> Dict[str, str]:
    """Return the complete mutable-world fact used by the round progression chain."""
    tree = world_save.get("tree") if isinstance(world_save, Mapping) else None
    tree_sha256 = str(tree.get("sha256", "") if isinstance(tree, Mapping) else "").strip()
    if len(tree_sha256) != 64:
        raise CertificationLeaseError("world/save identity has no complete tree digest")
    return {
        "world_tree_sha256": tree_sha256,
        "world_save_sha256": tree_sha256,
    }


def _certification_world_save_chain(
    connection: sqlite3.Connection, manifest: Mapping[str, Any],
) -> Dict[str, Any]:
    """Derive the only accepted mutable-world successor from registry history."""
    sealed_world = manifest["binding"]["authoritative_components"]["world_save"]
    accepted = _certification_world_save_fact(sealed_world)
    save_sequence = 0
    rows = connection.execute(
        "SELECT event_sequence,event_stream_id,details_json FROM certification_round_lifecycle "
        "WHERE round_id = ? AND event_kind = 'world_save_progressed' ORDER BY event_sequence",
        (str(manifest["round_id"]),),
    ).fetchall()
    for row in rows:
        if str(row["event_stream_id"]) != str(manifest["event_stream_id"]):
            return {"ok": False, "reason": "world_save_progression_event_stream_mismatch"}
        try:
            details = json.loads(str(row["details_json"]))
        except json.JSONDecodeError:
            return {"ok": False, "reason": "world_save_progression_details_invalid"}
        if not isinstance(details, dict):
            return {"ok": False, "reason": "world_save_progression_details_invalid"}
        if details.get("event_stream_id") != str(manifest["event_stream_id"]):
            return {"ok": False, "reason": "world_save_progression_receipt_other_stream"}
        expected_sequence = save_sequence + 1
        if details.get("save_sequence") != expected_sequence:
            return {"ok": False, "reason": "world_save_progression_sequence_gap"}
        previous = {
            key: str(details.get("previous_" + key, ""))
            for key in ("world_tree_sha256", "world_save_sha256")
        }
        current = {
            key: str(details.get("current_" + key, ""))
            for key in ("world_tree_sha256", "world_save_sha256")
        }
        if previous != accepted:
            return {"ok": False, "reason": "world_save_progression_predecessor_mismatch"}
        if any(len(value) != 64 for value in current.values()) or current == previous:
            return {"ok": False, "reason": "world_save_progression_successor_invalid"}
        accepted = current
        save_sequence = expected_sequence
    return {"ok": True, "accepted": accepted, "save_sequence": save_sequence}


def _certification_bound_process_identity(
    connection: sqlite3.Connection, manifest: Mapping[str, Any], lease_id: str,
) -> str:
    """Read the last bound process identity; caller input never supplies it."""
    row = connection.execute(
        "SELECT process_identity FROM certification_round_lease_history "
        "WHERE round_id = ? AND lease_id = ? ORDER BY event_sequence DESC LIMIT 1",
        (str(manifest["round_id"]), str(lease_id)),
    ).fetchone()
    return str(row["process_identity"]) if row is not None else ""


def _certification_bound_process_pid(
    connection: sqlite3.Connection, manifest: Mapping[str, Any], lease_id: str,
) -> int:
    """Read the PID from the exact active lease receipt, if one exists."""
    row = connection.execute(
        "SELECT details_json FROM certification_round_lease_history "
        "WHERE round_id = ? AND lease_id = ? ORDER BY event_sequence DESC LIMIT 1",
        (str(manifest["round_id"]), str(lease_id)),
    ).fetchone()
    if row is None:
        return 0
    try:
        details = json.loads(str(row["details_json"]))
    except json.JSONDecodeError:
        return 0
    pid = details.get("pid", 0) if isinstance(details, Mapping) else 0
    return int(pid) if isinstance(pid, int) and pid > 0 else 0


def _certification_save_receipt(
    context: Mapping[str, Any], *, manifest: Mapping[str, Any],
    chain: Mapping[str, Any], current: Mapping[str, str],
) -> Dict[str, Any]:
    """Consume one game-event-stream save receipt for the next world successor."""
    path_text = str(context.get("event_stream_path", "") or "").strip()
    if not path_text:
        return {"ok": False, "reason": "world_save_progression_receipt_path_missing"}
    polled = read_transition_event_stream(Path(path_text), str(manifest["event_stream_id"]))
    if polled.get("diagnostics"):
        return {"ok": False, "reason": "world_save_progression_receipt_stream_invalid"}
    expected_sequence = int(chain["save_sequence"]) + 1
    process_identity = _certification_bound_process_identity(
        context["connection"], manifest, str(context.get("lease_id", "")))
    if not process_identity:
        return {"ok": False, "reason": "world_save_progression_receipt_lease_missing"}
    matches: List[Mapping[str, Any]] = []
    for event in polled.get("events", []):
        receipt = event.get("certification_save_receipt")
        if not isinstance(receipt, Mapping):
            continue
        if (event.get("domain") == "certification" and event.get("transition") == "save_receipt" and
                event.get("outcome") == "committed"):
            matches.append(receipt)
    if len(matches) != 1:
        return {"ok": False, "reason": "world_save_progression_receipt_missing_or_ambiguous"}
    receipt = matches[0]
    if "authentication" in receipt:
        return {"ok": False, "reason": "world_save_progression_receipt_legacy_authentication_forbidden"}
    expected = {
        "round_id": str(manifest["round_id"]),
        "event_stream_id": str(manifest["event_stream_id"]),
        "lease_id": str(context.get("lease_id", "")),
        "save_sequence": expected_sequence,
        **{"previous_" + key: value for key, value in chain["accepted"].items()},
        **{"current_" + key: value for key, value in current.items()},
    }
    if any(receipt.get(key) != value for key, value in expected.items()):
        return {"ok": False, "reason": "world_save_progression_receipt_identity_or_digest_mismatch"}
    bound_pid = _certification_bound_process_pid(
        context["connection"], manifest, str(context.get("lease_id", "")),
    )
    if receipt.get("process_identity") != process_identity and (
            not bound_pid or receipt.get("process_pid") != bound_pid):
        return {"ok": False, "reason": "world_save_progression_receipt_process_mismatch"}
    capability = str(
        context.get("save_capability", "") or
        os.environ.get("OPENCLAW_CERTIFICATION_SAVE_CAPABILITY", "")
    ).strip()
    if not verify_certification_save_capability(
            context["connection"], round_id=str(manifest["round_id"]), capability=capability):
        return {"ok": False, "reason": "world_save_progression_receipt_proof_unavailable"}
    proof = str(receipt.get("proof", "") or "").strip().lower()
    canonical_facts = "\n".join([
        str(receipt.get("round_id", "")),
        str(receipt.get("lease_id", "")),
        str(receipt.get("save_sequence", "")),
        str(receipt.get("previous_world_tree_sha256", "")),
        str(receipt.get("previous_world_save_sha256", "")),
        str(receipt.get("current_world_tree_sha256", "")),
        str(receipt.get("current_world_save_sha256", "")),
        str(receipt.get("process_pid", "")),
    ])
    expected_proof = hmac.new(
        capability.encode("utf-8"), canonical_facts.encode("utf-8"), hashlib.sha256
    ).hexdigest()
    if not proof:
        return {"ok": False, "reason": "world_save_progression_receipt_authentication_rejected"}
    if not hmac.compare_digest(proof, expected_proof):
        return {"ok": False, "reason": "world_save_progression_receipt_proof_rejected"}
    # Capabilities prove origin but are never copied to a lifecycle row or
    # report.  The raw event stream remains the game-produced evidence.
    persisted_receipt = dict(receipt)
    persisted_receipt.pop("proof", None)
    return {"ok": True, "receipt": persisted_receipt}


def certification_record_world_save_progression(
    context: Mapping[str, Any], *, event_stream_id: str,
) -> Dict[str, Any]:
    """Accept exactly one persisted ordinary-save successor for a round.

    This is the only path that moves the mutable world/save fact past the
    sealed generation-zero digest.  A game-owned append-only event receipt
    must prove the next predecessor/successor digest chain; same-path bytes or
    caller JSON cannot authorize progression.
    """
    manifest = context["manifest"]
    connection = context["connection"]
    register_certification_round(connection, manifest)
    def reject(reason: str, **details: Any) -> Dict[str, Any]:
        row = connection.execute(
            "SELECT COALESCE(MAX(event_sequence), 0) + 1 FROM certification_round_lifecycle WHERE round_id = ?",
            (str(manifest["round_id"]),),
        ).fetchone()
        lifecycle_sequence = int(row[0])
        append_certification_lifecycle_event(
            connection,
            round_id=str(manifest["round_id"]),
            event_sequence=lifecycle_sequence,
            event_kind="world_save_progression_rejected",
            details={"reason": reason, **details},
        )
        invalidation = invalidate_certification_round(
            connection,
            round_id=str(manifest["round_id"]),
            reason="world_save_progression_rejected",
            component_name="world_save",
            observed_sequence=lifecycle_sequence,
        )
        return {"ok": False, "reason": reason, "first_mismatch": "world_save",
                "lifecycle_sequence": lifecycle_sequence,
                "invalidation": invalidation, **details}
    if event_stream_id != str(manifest["event_stream_id"]):
        return reject("world_save_progression_event_stream_mismatch")
    chain = _certification_world_save_chain(connection, manifest)
    if not chain.get("ok"):
        return reject(str(chain["reason"]))
    try:
        inputs = _certification_recheck_producer_inputs(context["recheck_inputs_path"])
        current_binding = authoritative_identity_binding(**inputs)
        comparison = compare_round_manifest(
            manifest,
            round_id=str(manifest["round_id"]),
            scenario_lineage_id=str(manifest["scenario_lineage_id"]),
            authority_id=str(manifest["authority_id"]),
            authority_kind=str(manifest["authority_kind"]),
            event_stream_id=str(manifest["event_stream_id"]),
            **inputs,
        )
        current = _certification_world_save_fact(
            current_binding["authoritative_components"]["world_save"]
        )
    except Exception as exc:
        return reject("world_save_progression_recheck_failed", error=str(exc))
    mismatches = set(comparison.get("mismatches", []))
    if mismatches - {"world_save", "binding_id"}:
        return reject("world_save_progression_binding_drift", mismatches=sorted(mismatches))
    if current == chain["accepted"]:
        return reject("world_save_progression_not_advanced")
    receipt = _certification_save_receipt(
        context, manifest=manifest, chain=chain, current=current,
    )
    if not receipt.get("ok"):
        return reject(str(receipt["reason"]))
    row = connection.execute(
        "SELECT COALESCE(MAX(event_sequence), 0) + 1 FROM certification_round_lifecycle WHERE round_id = ?",
        (str(manifest["round_id"]),),
    ).fetchone()
    lifecycle_sequence = int(row[0])
    save_sequence = int(chain["save_sequence"]) + 1
    append_certification_lifecycle_event(
        connection,
        round_id=str(manifest["round_id"]),
        event_sequence=lifecycle_sequence,
        event_kind="world_save_progressed",
        details={
            "save_sequence": save_sequence,
            "event_stream_id": event_stream_id,
            **{"previous_" + key: value for key, value in chain["accepted"].items()},
            **{"current_" + key: value for key, value in current.items()},
            "game_save_receipt": receipt["receipt"],
        },
    )
    return {"ok": True, "save_sequence": save_sequence,
            "lifecycle_sequence": lifecycle_sequence, "accepted": current}


def certification_recheck_round(
    context: Mapping[str, Any], *, segment: str,
) -> Dict[str, Any]:
    """Recompute a sealed round before an evidence-bearing segment.

    The registry is the lifecycle owner: every recheck receives the next
    immutable sequence, and the first failed component invalidates only this
    round.  Focused artifacts remain outside these tables and are untouched.
    """
    manifest = context["manifest"]
    connection = context["connection"]
    register_certification_round(connection, manifest)
    try:
        inputs = _certification_recheck_producer_inputs(context["recheck_inputs_path"])
        current_binding = authoritative_identity_binding(**inputs)
        result = compare_round_manifest(
            manifest,
            round_id=str(manifest["round_id"]),
            scenario_lineage_id=str(manifest["scenario_lineage_id"]),
            authority_id=str(manifest["authority_id"]),
            authority_kind=str(manifest["authority_kind"]),
            event_stream_id=str(manifest["event_stream_id"]),
            **inputs,
        )
        chain = _certification_world_save_chain(connection, manifest)
        current_world = _certification_world_save_fact(
            current_binding["authoritative_components"]["world_save"]
        )
        # Opening a disposable declared world can cause the selected game
        # process to persist its initial save before the first feature gate.
        # Bind that one process-owned successor to the active lease so the
        # first evidence segment starts from the actual run state.  Every
        # later successor still requires the authenticated game save receipt.
        if (
                segment == "initial_evidence_segment"
                and chain.get("ok")
                and set(result.get("mismatches", [])) <= {"world_save", "binding_id"}
                and current_world != chain["accepted"]
                and _certification_bound_process_identity(
                    connection, manifest, str(context.get("lease_id", ""))
                )
        ):
            lifecycle_row = connection.execute(
                "SELECT COALESCE(MAX(event_sequence), 0) + 1 "
                "FROM certification_round_lifecycle WHERE round_id = ?",
                (str(manifest["round_id"]),),
            ).fetchone()
            lifecycle_sequence = int(lifecycle_row[0])
            append_certification_lifecycle_event(
                connection,
                round_id=str(manifest["round_id"]),
                event_sequence=lifecycle_sequence,
                event_kind="world_save_progressed",
                details={
                    "save_sequence": int(chain["save_sequence"]) + 1,
                    "event_stream_id": str(manifest["event_stream_id"]),
                    **{"previous_" + key: value for key, value in chain["accepted"].items()},
                    **{"current_" + key: value for key, value in current_world.items()},
                    "startup_process_observation": True,
                },
            )
            chain = _certification_world_save_chain(connection, manifest)
            result["mismatches"] = [
                mismatch for mismatch in result.get("mismatches", [])
                if mismatch not in {"world_save", "binding_id"}
            ]
        if not chain.get("ok"):
            result = {"ok": False, "mismatches": ["world_save"], "error": chain["reason"]}
        elif current_world != chain["accepted"]:
            mismatches = list(result.get("mismatches", []))
            if "world_save" not in mismatches:
                mismatches.append("world_save")
            result = {"ok": False, "mismatches": order_certification_mismatches(mismatches),
                      "error": "world_save_progression_not_accepted"}
        else:
            mismatches = [
                mismatch for mismatch in result.get("mismatches", [])
                if mismatch not in {"world_save", "binding_id"}
            ]
            result = {
                "ok": not mismatches,
                "mismatches": order_certification_mismatches(mismatches),
                "world_save_progression": chain,
            }
    except Exception as exc:
        result = {"ok": False, "mismatches": ["recheck_inputs"], "error": str(exc)}
    result["mismatches"] = order_certification_mismatches(result.get("mismatches", []))
    result["first_mismatch"] = first_certification_mismatch(result["mismatches"])
    row = connection.execute(
        "SELECT COALESCE(MAX(event_sequence), 0) + 1 FROM certification_round_lifecycle WHERE round_id = ?",
        (str(manifest["round_id"]),),
    ).fetchone()
    sequence = int(row[0])
    event_kind = "segment_rechecked" if result.get("ok") else "segment_recheck_failed"
    append_certification_lifecycle_event(
        connection,
        round_id=str(manifest["round_id"]),
        event_sequence=sequence,
        event_kind=event_kind,
        details={"segment": segment, "recheck": result},
    )
    if not result.get("ok"):
        mismatches = result.get("mismatches", [])
        component = first_certification_mismatch(mismatches) or "recheck_inputs"
        invalidation = invalidate_certification_round(
            connection,
            round_id=str(manifest["round_id"]),
            reason="binding_recheck_failed",
            component_name=component,
            observed_sequence=sequence,
        )
        return {"ok": False, "segment": segment, "sequence": sequence,
                "first_mismatch": component,
                "recheck": result, "invalidation": invalidation}
    return {"ok": True, "segment": segment, "sequence": sequence, "recheck": result}


def certification_recheck_evidence_segment(args: argparse.Namespace, *, segment: str) -> Optional[Dict[str, Any]]:
    """Open the registry only long enough to bind one probe evidence segment."""
    registry_path = str(getattr(args, "certification_registry", "") or "").strip()
    manifest_path = str(getattr(args, "certification_round_manifest", "") or "").strip()
    lease_id = str(getattr(args, "certification_lease_id", "") or "").strip()
    recheck_path = str(getattr(args, "certification_recheck_inputs", "") or "").strip()
    supplied = (registry_path, manifest_path, lease_id, recheck_path)
    if not any(supplied):
        return None
    if not all(supplied):
        return {
            "ok": False,
            "segment": segment,
            "recheck": {"ok": False, "mismatches": ["certification_arguments"]},
        }
    connection = open_registry(registry_path)
    try:
        return certification_recheck_round({
            "connection": connection,
            "manifest": load_certification_manifest(manifest_path),
            "lease_id": lease_id,
            "recheck_inputs_path": recheck_path,
        }, segment=segment)
    finally:
        connection.close()


def validate_enabled_api_runtime(options: Dict[str, str]) -> None:
    if not llm_api_mode_enabled(options):
        return

    python_cmd, python_label, python_source = resolve_game_runtime_python(options)
    if not python_cmd:
        raise RuntimeError(
            "API LLM is enabled, but its Python runner is unavailable "
            f"({python_label or 'no resolved interpreter'}; {python_source})."
        )
    try:
        import_check = subprocess.run(
            python_cmd + ["-c", "import any_llm"],
            capture_output=True,
            text=True,
            check=False,
        )
    except OSError as error:
        raise RuntimeError(
            f"API LLM Python runner could not start ({python_label}): {error}"
        ) from error
    if import_check.returncode != 0:
        detail_text = (import_check.stderr or import_check.stdout).strip()
        detail = detail_text.splitlines()[0] if detail_text else "import any_llm failed"
        raise RuntimeError(
            f"API LLM Python runner is incomplete ({python_label}): {detail}"
        )


def game_child_environment(profile: str) -> Dict[str, str]:
    options = load_game_options(profile)
    validate_enabled_api_runtime(options)
    provision, child_overlay = provision_llm_api_key_environment(options)
    if provision["status"] in {"missing", "missing_env_name"}:
        env_name = provision["env_var"] or "LLM_INTENT_API_KEY_ENV"
        raise RuntimeError(
            "API LLM is enabled, but its credential is unavailable "
            f"({env_name}; status={provision['status']}; source={provision['source'] or 'none'}). "
            "Store it with the harness before launching."
        )
    env = os.environ.copy()
    env.update(child_overlay)
    env["OPENCLAW_HARNESS_UI_TRACE"] = "1"
    return env


def wait_input_trace_child_environment(enabled: bool, run_id: str) -> Dict[str, str]:
    """Return the one-run diagnostic gate for the native wait-input trace."""
    if not enabled:
        return {}
    selected_run_id = str(run_id).strip()
    if not selected_run_id:
        raise ValueError("wait-input tracing requires a bound harness run ID")
    return {"OPENCLAW_HARNESS_WAIT_INPUT_TRACE_RUN_ID": selected_run_id}


def semantic_run_binding_child_environment(run_id: str) -> Dict[str, str]:
    """Bind native semantic producers to this exact launch before they can emit."""
    bound_run_id = str(run_id).strip()
    if not bound_run_id:
        raise ValueError("semantic emission requires a bound harness run ID")
    return {"OPENCLAW_HARNESS_SEMANTIC_RUN_ID": bound_run_id}


def native_preview_segment_requests(steps: Sequence[Mapping[str, Any]]) -> str:
    """Serialize declared zero-credit native-preview segment starts for one child.

    The production UI consumes the resulting destination-to-start map only while
    UI tracing is enabled.  A duplicate destination would make the request
    ambiguous, so selection fails before a game process is started.
    """
    requests: list[str] = []
    destinations: set[tuple[int, int, int]] = set()
    for step in steps:
        if str(step.get("kind", "")).strip().lower() != "ordinary_overmap_route_constructor":
            continue
        start = step.get("native_preview_segment_start_omt")
        if start is None:
            continue
        destination = step.get("destination_omt")
        if not isinstance(start, list) or not isinstance(destination, list) or \
                len(start) != 3 or len(destination) != 3 or any(
                    isinstance(value, bool) or not isinstance(value, int)
                    for value in [*start, *destination]
                ):
            raise ValueError(
                "native preview segment requests need integer start and destination OMTs"
            )
        destination_key = tuple(destination)
        if destination_key in destinations:
            raise ValueError("native preview segment destinations must be unique")
        destinations.add(destination_key)
        requests.append(
            ",".join(str(value) for value in start) + ">" +
            ",".join(str(value) for value in destination)
        )
    return ";".join(requests)


WAIT_DIAGNOSTIC_ACTIVATION_FILENAME = "wait-diagnostic.activation.json"
WAIT_DIAGNOSTIC_RECORDS_FILENAME = "wait-diagnostic.records.jsonl"
WAIT_DIAGNOSTIC_SEAL_FILENAME = "wait-diagnostic.seal.json"


def _wait_diagnostic_paths(run_dir: Path) -> Tuple[Path, Path, Path]:
    return (
        run_dir / WAIT_DIAGNOSTIC_ACTIVATION_FILENAME,
        run_dir / WAIT_DIAGNOSTIC_RECORDS_FILENAME,
        run_dir / WAIT_DIAGNOSTIC_SEAL_FILENAME,
    )


def _wait_diagnostic_registry_authority(raw_receipt: str) -> Dict[str, str]:
    try:
        receipt = json.loads(raw_receipt) if raw_receipt else {}
    except (TypeError, json.JSONDecodeError):
        receipt = {}
    if not isinstance(receipt, Mapping):
        receipt = {}
    return {
        "kind": str(receipt.get("authority_kind", "none") or "none"),
        "token_id": str(receipt.get("token_id", "") or ""),
        "registry_path": str(receipt.get("registry_path", "") or ""),
    }


def initialize_wait_diagnostic_ledger(
    run_dir: Path, *, enabled: bool, run_id: str, executable: Path,
    registry_launch_receipt: str = "",
) -> Dict[str, Any]:
    """Create a durable, pre-input receipt stream for one native-wait probe.

    This is deliberately diagnostic-only.  It proves that the observer was
    activated and can retain an explicit absence; it never credits wait or
    gameplay behaviour.
    """
    if not enabled:
        return {"status": "disabled"}
    selected_run_id = str(run_id).strip()
    if not selected_run_id:
        raise ValueError("wait diagnostics require a bound harness run ID")
    activation_path, records_path, seal_path = _wait_diagnostic_paths(run_dir)
    if activation_path.exists() or records_path.exists() or seal_path.exists():
        raise RuntimeError("wait diagnostic ledger already exists for this run")
    executable_sha256, executable_error = sha256_file(executable)
    source = runtime_source_binding()
    activation = {
        "schema": "caol-wait-diagnostic-v1",
        "kind": "activation",
        "run_id": selected_run_id,
        "run_dir": str(run_dir.resolve()),
        "executable": {"path": str(executable.resolve()), "sha256": executable_sha256,
                       "error": executable_error},
        "source": {"sha256": str(source.get("sha256", "")),
                   "worktree_changes": list(source.get("worktree_changes", []))},
        "registry_authority": _wait_diagnostic_registry_authority(registry_launch_receipt),
        "credit": "none; zero-credit diagnostic bootstrap",
        "required_request_fields": [
            "semantic_frame", "sdl_delivery", "input_context", "action_resolution",
            "wait_dispatch", "focus_or_top_level", "activity", "turn_and_game_minute",
            "scheduler_or_game_loop", "process_liveness", "cleanup",
        ],
    }
    write_json(activation_path, activation)
    with records_path.open("x", encoding="utf-8") as stream:
        stream.write(json.dumps({**activation, "sequence": 0}, ensure_ascii=False) + "\n")
    return {"status": "activated", "activation_path": str(activation_path),
            "records_path": str(records_path), "run_id": selected_run_id}


def append_wait_diagnostic_record(run_dir: Path, record: Mapping[str, Any]) -> Dict[str, Any]:
    """Append one bound request observation, rejecting stale or sealed streams."""
    activation_path, records_path, seal_path = _wait_diagnostic_paths(run_dir)
    if not activation_path.exists() or not records_path.exists():
        return {"status": "missing_activation"}
    if seal_path.exists():
        return {"status": "post_cleanup_rejected"}
    try:
        activation = json.loads(activation_path.read_text(encoding="utf-8"))
    except (OSError, UnicodeError, json.JSONDecodeError):
        return {"status": "invalid_activation"}
    if not isinstance(activation, Mapping):
        return {"status": "invalid_activation"}
    payload = dict(record)
    if str(payload.get("run_id", "")) != str(activation.get("run_id", "")):
        return {"status": "wrong_run_rejected"}
    required = ["request_id", "phase", *activation.get("required_request_fields", [])]
    missing = [key for key in required if key not in payload]
    if missing:
        return {"status": "incomplete_record_rejected", "missing": missing}
    try:
        existing = [json.loads(line) for line in records_path.read_text(encoding="utf-8").splitlines()]
    except OSError:
        return {"status": "records_unreadable"}
    except json.JSONDecodeError:
        return {"status": "records_invalid"}
    request_id = str(payload["request_id"])
    existing_phases = [str(item.get("phase", "")) for item in existing
                       if str(item.get("request_id", "")) == request_id]
    if payload["phase"] == "result" and existing_phases != ["before_input"]:
        return {"status": "reordered_record_rejected"}
    if payload["phase"] == "before_input" and existing_phases:
        return {"status": "duplicate_request_rejected"}
    if payload["phase"] not in {"before_input", "result"}:
        return {"status": "unknown_record_phase_rejected"}
    payload["sequence"] = len(existing)
    payload["schema"] = "caol-wait-diagnostic-v1"
    payload["binding"] = {
        "source": activation.get("source", {}),
        "executable": activation.get("executable", {}),
        "registry_authority": activation.get("registry_authority", {}),
    }
    payload["credit"] = "none; diagnostic tracing only"
    with records_path.open("a", encoding="utf-8") as stream:
        stream.write(json.dumps(payload, ensure_ascii=False) + "\n")
    return {"status": "retained", "sequence": payload["sequence"], "path": str(records_path)}


def seal_wait_diagnostic_ledger(run_dir: Path, cleanup: Mapping[str, Any]) -> Dict[str, Any]:
    """Seal the append-only diagnostic stream after accepted cleanup."""
    activation_path, records_path, seal_path = _wait_diagnostic_paths(run_dir)
    if not activation_path.exists() and not records_path.exists():
        return {"status": "not_enabled"}
    if not activation_path.exists() or not records_path.exists():
        return {"status": "incomplete_records"}
    if seal_path.exists():
        return {"status": "already_sealed", "seal_path": str(seal_path)}
    try:
        records = [json.loads(line) for line in records_path.read_text(encoding="utf-8").splitlines()]
    except (OSError, UnicodeError, json.JSONDecodeError):
        return {"status": "incomplete_records"}
    phases_by_request: Dict[str, List[str]] = {}
    for record in records[1:]:
        request_id = str(record.get("request_id", ""))
        if request_id:
            phases_by_request.setdefault(request_id, []).append(str(record.get("phase", "")))
    incomplete = sorted(request_id for request_id, phases in phases_by_request.items()
                        if phases != ["before_input", "result"])
    if incomplete:
        return {"status": "incomplete_records", "request_ids": incomplete}
    payload = {
        "schema": "caol-wait-diagnostic-v1",
        "kind": "cleanup_seal",
        "records_sha256": sha256_file(records_path)[0],
        "cleanup": dict(cleanup),
        "credit": "none; zero-credit diagnostic bootstrap",
    }
    write_json(seal_path, payload)
    return {"status": "sealed", "seal_path": str(seal_path), **payload}


def wait_diagnostic_request_record(
    *, run_id: str, request_id: str, phase: str, semantic_frame: str,
    pid: int, trace: Optional[Mapping[str, Any]] = None,
) -> Dict[str, Any]:
    """Normalize one honest native-wait observation without inventing missing facts."""
    trace = trace if isinstance(trace, Mapping) else {}
    trace_status = str(trace.get("status", "not_observed"))
    return {
        "kind": "native_wait_request",
        "run_id": run_id,
        "request_id": request_id,
        "phase": phase,
        "semantic_frame": semantic_frame or "unobserved",
        "sdl_delivery": {"status": trace_status,
                         "count": int(trace.get("sdl_event_count", 0) or 0)},
        "input_context": {"status": trace_status,
                          "resolution_count": int(trace.get("resolution_count", 0) or 0)},
        "action_resolution": {"status": trace_status,
                              "action": str(trace.get("resolved_action", ""))},
        "wait_dispatch": {"status": trace_status,
                          "count": int(trace.get("dispatch_count", 0) or 0)},
        "focus_or_top_level": {"status": "not_observed"},
        "activity": {"status": "not_observed"},
        "turn_and_game_minute": {"status": "not_observed"},
        "scheduler_or_game_loop": {"status": "not_observed"},
        "process_liveness": {"pid": pid, "alive": pid_is_alive(pid)},
        "cleanup": {"status": "pending"},
    }


def classify_wait_input_trace(
    path: Path,
    start_offset: int,
    *,
    run_id: str,
) -> Dict[str, Any]:
    """Classify the native path reached by one run-bound wait input."""
    try:
        with path.open("r", encoding="utf-8", errors="replace") as trace_file:
            trace_file.seek(max(0, start_offset))
            lines = trace_file.readlines()
    except OSError:
        lines = []

    selected = str(run_id).strip()
    trace_lines = [
        line.rstrip("\n")
        for line in lines
        if "openclaw_harness_wait_input_trace:" in line
    ]
    matching_lines = [line for line in trace_lines if f'run_id="{selected}"' in line]
    foreign_lines = [line for line in trace_lines if line not in matching_lines]
    sdl_lines = [line for line in matching_lines if "component=sdl_input" in line]
    resolution_lines = [line for line in matching_lines if "component=input_resolution" in line]
    dispatch_lines = [line for line in matching_lines if "component=action_dispatch" in line]
    menu_lines = [line for line in matching_lines if "component=wait_menu" in line]
    result: Dict[str, Any] = {
        "run_id": selected,
        "trace_line_count": len(matching_lines),
        "sdl_event_count": len(sdl_lines),
        "resolution_count": len(resolution_lines),
        "dispatch_count": len(dispatch_lines),
        "menu_selection_count": len(menu_lines),
        "lines": matching_lines,
        "credit": "none; diagnostic tracing only",
    }
    if not sdl_lines:
        result["status"] = "foreign_run_only" if foreign_lines else "missing_sdl_event"
        result["first_divergence"] = "raw_sdl_event_delivery"
        return result
    if not resolution_lines:
        result["status"] = "input_context_not_reached"
        result["first_divergence"] = "input_context_normalization"
        return result

    resolution = resolution_lines[-1]
    rejection_match = re.search(r"rejection_reason=([^\s]+)", resolution)
    action_match = re.search(r'resolved_action="([^"]*)"', resolution)
    rejection = rejection_match.group(1) if rejection_match else "unrecorded"
    action = action_match.group(1) if action_match else ""
    result["resolution"] = resolution
    result["resolved_action"] = action
    result["rejection_reason"] = rejection
    if menu_lines:
        result["status"] = "wait_menu_selected"
        result["first_divergence"] = "wait_activity"
        result["menu_selection"] = menu_lines[-1]
    elif rejection == "none" and action == "wait":
        if dispatch_lines:
            result["status"] = "wait_dispatched"
            result["first_divergence"] = "wait_menu_or_activity"
        else:
            result["status"] = "action_dispatch_not_observed"
            result["first_divergence"] = "final_game_action_dispatch"
    else:
        result["status"] = rejection
        result["first_divergence"] = "default_mode_action_resolution"
    return result


def bind_transition_event_stream(
    run_dir: Path,
    *,
    run_id: str = "",
    event_path: str = "",
) -> Dict[str, str]:
    """Create the explicit run binding consumed by the game child."""
    resolved_run_id = str(run_id).strip() or uuid.uuid4().hex
    resolved_path = Path(event_path).expanduser() if str(event_path).strip() else run_dir / TRANSITION_EVENT_FILENAME
    resolved_path = resolved_path.resolve()
    ensure_dir(resolved_path.parent)
    resolved_path.touch(exist_ok=True)
    return {"run_id": resolved_run_id, "event_path": str(resolved_path)}


def launch_game(
    profile: str,
    target_world: str,
    run_dir: Path,
    *,
    artifact_run_dir: Optional[Path] = None,
    child_environment: Optional[Dict[str, str]] = None,
    scenario: str = "",
    harness_new_world: str = "",
    harness_raw_seed: str = "",
    transition_event_run_id: str = "",
    transition_event_path: str = "",
) -> subprocess.Popen[str]:
    exe = detect_executable()
    cmd = build_game_command(
        exe,
        profile,
        target_world,
        harness_new_world=harness_new_world,
        harness_raw_seed=harness_raw_seed,
    )
    env = dict(child_environment or game_child_environment(profile))
    env["OPENCLAW_HARNESS_RUN_DIR"] = str((artifact_run_dir or run_dir).resolve())
    env["OPENCLAW_HARNESS_PROFILE"] = profile
    env["OPENCLAW_HARNESS_WORLD"] = target_world
    binding = bind_transition_event_stream(
        run_dir, run_id=transition_event_run_id, event_path=transition_event_path
    )
    env["OPENCLAW_HARNESS_RUN_ID"] = binding["run_id"]
    # This opt-in tag gates the native R-019 lifecycle stream to the exact
    # launch binding.  It is diagnostic-only and never changes report credit.
    if env.get("OPENCLAW_HARNESS_R019_LIFECYCLE_ACTOR_ID", "").strip():
        env["OPENCLAW_HARNESS_R019_LIFECYCLE_RUN_ID"] = binding["run_id"]
    env.update(semantic_run_binding_child_environment(binding["run_id"]))
    env["OPENCLAW_HARNESS_TRANSITION_EVENT_PATH"] = binding["event_path"]
    env.pop("OPENCLAW_HARNESS_SCENARIO", None)
    if scenario:
        env["OPENCLAW_HARNESS_SCENARIO"] = scenario
    stdout_log = (run_dir / "game.stdout.log").open("w", encoding="utf-8")
    stderr_log = (run_dir / "game.stderr.log").open("w", encoding="utf-8")
    return subprocess.Popen(cmd, cwd=str(repo_root()), stdout=stdout_log, stderr=stderr_log, text=True, env=env)


def build_game_command(
    executable: Path,
    profile: str,
    target_world: str,
    *,
    harness_new_world: str = "",
    harness_raw_seed: str = "",
) -> List[str]:
    cmd = [str(executable), "--userdir", f".userdata/{profile}/"]
    if harness_new_world:
        cmd.extend(["--harness-new-world", harness_new_world, "--harness-raw-seed", harness_raw_seed])
    elif target_world:
        cmd.extend(["--world", target_world])
    return cmd


def startup_gui_automation_required(strategy: str) -> bool:
    """Whether startup owns Peekaboo permission, focus, and input steps."""
    return strategy != "harness_new_world"


def pid_command(pid: int) -> str:
    try:
        proc = subprocess.run(
            ["ps", "-p", str(pid), "-o", "command="],
            capture_output=True,
            text=True,
            check=False,
            timeout=2.0,
        )
    except (PermissionError, subprocess.TimeoutExpired):
        return ""
    return proc.stdout.strip()


def _utc_timestamp(epoch_seconds: float) -> str:
    return datetime.fromtimestamp(
        float(epoch_seconds), tz=timezone.utc
    ).isoformat(timespec="milliseconds")


def observe_bound_process_exit(
    pid: int,
    timeout_seconds: float,
    *,
    expected_command: str,
    poll_seconds: float = 0.1,
) -> Dict[str, Any]:
    """Observe native exit for one exact PID/command pair.

    A PID disappearing is not enough for a qualification receipt: the command
    must be captured while the bound process is alive and remain unchanged at
    every live sample.  The returned ``native_exit`` state is the only state
    that may support relaunch; timeout, unavailable identity, and PID reuse
    remain fail-closed.  ``poll_seconds`` is recorded as the scheduling
    uncertainty, so callers can derive the smallest honest observation window
    from the measured native shutdown rather than crediting cleanup.
    """
    started_epoch = time.time()
    started_monotonic = time.monotonic()
    expected = str(expected_command or "").strip()
    result: Dict[str, Any] = {
        "pid": int(pid),
        "expected_command": expected,
        "started_at": _utc_timestamp(started_epoch),
        "started_epoch_seconds": started_epoch,
        "poll_seconds": float(poll_seconds),
        "scheduling_uncertainty_seconds": float(poll_seconds),
        "observations": [],
    }
    if pid <= 0 or not expected:
        result.update({
            "status": "identity_unavailable",
            "reason": "exact PID and live command identity are required",
        })
        return result

    deadline = started_monotonic + max(float(timeout_seconds), 0.0)
    while True:
        sampled_epoch = time.time()
        alive = pid_is_alive(pid)
        command = pid_command(pid) if alive else ""
        observation = {
            "sampled_at": _utc_timestamp(sampled_epoch),
            "sampled_epoch_seconds": sampled_epoch,
            "pid": int(pid),
            "alive": bool(alive),
            "command": command,
        }
        result["observations"].append(observation)
        if alive and command != expected:
            result.update({
                "status": "wrong_process_identity",
                "reason": "PID remained alive but command identity changed",
                "observed_command": command,
                "identity_mismatch_at": observation["sampled_at"],
                "elapsed_seconds": time.monotonic() - started_monotonic,
            })
            return result
        if not alive:
            result.update({
                "status": "native_exit",
                "native_shutdown_at": observation["sampled_at"],
                "native_shutdown_epoch_seconds": sampled_epoch,
                "elapsed_seconds": time.monotonic() - started_monotonic,
            })
            return result
        if time.monotonic() >= deadline:
            result.update({
                "status": "timeout",
                "elapsed_seconds": time.monotonic() - started_monotonic,
                "deadline_at": _utc_timestamp(started_epoch + max(float(timeout_seconds), 0.0)),
            })
            return result
        time.sleep(max(float(poll_seconds), 0.0))


def derive_terminal_exit_observation_window(
    native_shutdown_elapsed_seconds: Sequence[float],
    *,
    scheduling_uncertainty_seconds: float,
    safety_ceiling_seconds: float,
) -> Dict[str, Any]:
    """Derive a minimal measured window while enforcing a separate ceiling."""
    measurements = [float(value) for value in native_shutdown_elapsed_seconds
                    if isinstance(value, (int, float)) and float(value) >= 0]
    uncertainty = float(scheduling_uncertainty_seconds)
    ceiling = float(safety_ceiling_seconds)
    if not measurements or uncertainty < 0 or ceiling <= 0:
        return {
            "status": "insufficient_measurement",
            "measured_native_shutdown_elapsed_seconds": measurements,
            "scheduling_uncertainty_seconds": uncertainty,
            "safety_ceiling_seconds": ceiling,
        }
    measured = max(measurements)
    window = measured + uncertainty
    return {
        "status": "within_safety_ceiling" if window <= ceiling else "exceeds_safety_ceiling",
        "measured_native_shutdown_elapsed_seconds": measurements,
        "measured_native_shutdown_elapsed_max_seconds": measured,
        "scheduling_uncertainty_seconds": uncertainty,
        "derived_observation_window_seconds": window,
        "safety_ceiling_seconds": ceiling,
    }


def pid_is_alive(pid: int) -> bool:
    if pid <= 0:
        return False
    # The harness owns its launched game process.  On POSIX, an exited child
    # remains addressable until reaped, so kill(pid, 0) alone mistakes a
    # native save-and-quit zombie for a live process and blocks relaunch.
    if os.name == "posix":
        try:
            reaped_pid, _ = os.waitpid(pid, os.WNOHANG)
            if reaped_pid == pid:
                return False
        except ChildProcessError:
            # A non-child PID is still checked with the portable probe below.
            pass
    try:
        os.kill(pid, 0)
    except ProcessLookupError:
        return False
    except PermissionError:
        return True
    return True


def wait_for_pid_exit(pid: int, timeout_seconds: float) -> bool:
    deadline = time.monotonic() + max(timeout_seconds, 0.0)
    while time.monotonic() < deadline:
        if not pid_is_alive(pid):
            return True
        time.sleep(0.1)
    return not pid_is_alive(pid)


def cleanup_game_process(pid: int, *, grace_seconds: float = 2.0) -> Dict[str, Any]:
    cleanup_started_epoch = time.time()
    info: Dict[str, Any] = {
        "pid": pid,
        "grace_seconds": grace_seconds,
        "cleanup_started_at": _utc_timestamp(cleanup_started_epoch),
        "cleanup_started_epoch_seconds": cleanup_started_epoch,
        "native_exit_credit": False,
    }
    if pid <= 0:
        info["status"] = "invalid_pid"
        info["cleanup_finished_at"] = _utc_timestamp(time.time())
        return info

    command = pid_command(pid)
    info["command"] = command
    if not command:
        if not pid_is_alive(pid):
            info["status"] = "already_exited"
            info["cleanup_finished_at"] = _utc_timestamp(time.time())
            return info
        info["command_lookup"] = "unavailable"
    elif not re.search(r"(?:Cataclysm-AOL|cataclysm-(?:tiles|tlg-tiles))(?:\.exe)?(?:\s|$)", command):
        info["status"] = "skipped_non_cataclysm_process"
        info["cleanup_finished_at"] = _utc_timestamp(time.time())
        return info

    try:
        os.kill(pid, signal.SIGTERM)
        info["signal"] = "SIGTERM"
    except ProcessLookupError:
        info["status"] = "already_exited"
        info["cleanup_finished_at"] = _utc_timestamp(time.time())
        return info
    except PermissionError:
        info["status"] = "permission_denied"
        info["cleanup_finished_at"] = _utc_timestamp(time.time())
        return info

    if wait_for_pid_exit(pid, grace_seconds):
        info["status"] = "terminated"
        info["cleanup_finished_at"] = _utc_timestamp(time.time())
        return info

    try:
        os.kill(pid, signal.SIGKILL)
        info["signal"] = "SIGKILL"
    except ProcessLookupError:
        info["status"] = "terminated_during_kill_escalation"
        info["cleanup_finished_at"] = _utc_timestamp(time.time())
        return info
    except PermissionError:
        info["status"] = "permission_denied_on_kill"
        info["cleanup_finished_at"] = _utc_timestamp(time.time())
        return info

    info["status"] = "killed" if wait_for_pid_exit(pid, 1.0) else "still_running_after_kill"
    info["cleanup_finished_at"] = _utc_timestamp(time.time())
    return info


def harness_save_ready(returncode: int, marker: Dict[str, Any], baseline_mtime: float) -> bool:
    """A harness world is ready only after clean exit and a newer save marker."""
    if returncode != 0 or not isinstance(marker, dict):
        return False
    return float(marker.get("mtime", 0.0) or 0.0) > float(baseline_mtime or 0.0)


def harness_process_ready(
    returncode: int,
    marker: Dict[str, Any],
    baseline_mtime: float,
    debug_error_evidence_count: int,
) -> bool:
    """Classify the completed process without hiding newly captured debug errors."""
    return (
        harness_save_ready(returncode, marker, baseline_mtime)
        and debug_error_evidence_count == 0
    )


def harness_feasibility_artifact_path(run_dir: Path) -> Path:
    return run_dir / "harness_new_world_feasibility.json"


def load_harness_feasibility_artifact(run_dir: Path) -> Dict[str, Any]:
    try:
        value = json.loads(harness_feasibility_artifact_path(run_dir).read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError):
        return {}
    return value if isinstance(value, dict) else {}


def harness_feasibility_candidate_row_ready(row: Any) -> bool:
    if not isinstance(row, dict):
        return False
    outcome = row.get("outcome")
    target = row.get("target_omt")
    read = row.get("read")
    if (
        not isinstance(row.get("lead_id"), str)
        or not row.get("lead_id")
        or row.get("selector") != "non_frontier"
        or outcome not in {"selected", "rejected"}
        or not isinstance(row.get("analyzer_record"), str)
        or not isinstance(target, dict)
        or not all(isinstance(target.get(axis), int) for axis in ("x", "y", "z"))
        or not isinstance(read, dict)
        or not isinstance(read.get("reachable"), bool)
        or not isinstance(read.get("complete_route_cost"), int)
        or not isinstance(read.get("max_segment_risk"), int)
        or not isinstance(read.get("summary"), str)
        or not isinstance(read.get("watch_geography_supplied"), bool)
        or not isinstance(read.get("watch_candidates"), list)
        or not isinstance(read.get("watch_shared_route"), list)
    ):
        return False
    if outcome == "selected":
        watch = row.get("watch")
        return (
            isinstance(watch, dict)
            and all(isinstance(watch.get(axis), int) for axis in ("x", "y", "z"))
            and isinstance(row.get("watch_route_cost"), int)
            and row["watch_route_cost"] >= 0
            and read["reachable"]
            and row["watch_route_cost"] == read["complete_route_cost"]
        )
    return row.get("watch") is None and row.get("watch_route_cost") == -1


def harness_feasibility_artifact_ready(artifact: Dict[str, Any], expected_raw_seed: str = "") -> bool:
    rows = artifact.get("candidate_rows")
    budget_before = artifact.get("route_watch_budget_before")
    budget_after = artifact.get("route_watch_budget_after")
    budget_used = artifact.get("route_watch_budget_used")
    before = artifact.get("persistent_ecology_state_before")
    after = artifact.get("persistent_ecology_state_after")
    player = artifact.get("player_omt")
    anchor = artifact.get("natural_bandit_site_anchor")
    nearest = artifact.get("natural_bandit_site_nearest_omt")
    distance = artifact.get("natural_bandit_site_distance_omt")
    point_fields_ready = all(
        isinstance(point, dict)
        and all(isinstance(point.get(axis), int) for axis in ("x", "y", "z"))
        for point in (player, anchor, nearest)
    )
    measured_distance = (
        math.hypot(nearest["x"] - player["x"], nearest["y"] - player["y"])
        if point_fields_ready
        else math.inf
    )
    return (
        artifact.get("artifact_kind") == "harness_new_world_feasibility"
        and artifact.get("artifact_version") == 1
        and (not expected_raw_seed or str(artifact.get("raw_seed", "")) == expected_raw_seed)
        and bool(artifact.get("natural_bandit_site_found"))
        and isinstance(artifact.get("natural_bandit_site_id"), str)
        and bool(artifact.get("natural_bandit_site_id"))
        and point_fields_ready
        and isinstance(distance, (int, float))
        and math.isfinite(distance)
        and math.isclose(distance, measured_distance, rel_tol=1e-6, abs_tol=1e-6)
        and artifact.get("bootstrap_radius_omt") == 40
        and distance <= 40
        and isinstance(before, str)
        and bool(before)
        and before == after
        and artifact.get("persistent_ecology_unchanged") is True
        and isinstance(artifact.get("bootstrap_created_sites"), int)
        and artifact.get("bootstrap_created_sites") >= 1
        and isinstance(artifact.get("bootstrap_recognized_tiles"), int)
        and artifact.get("bootstrap_recognized_tiles") >= 1
        and artifact.get("structural_scan_budget") == 12
        and isinstance(artifact.get("structural_scan_budget_used"), int)
        and 0 <= artifact.get("structural_scan_budget_used") <= 12
        and isinstance(artifact.get("structural_scan_sites_considered"), int)
        and artifact.get("structural_scan_sites_considered") >= 1
        and isinstance(artifact.get("structural_scan_candidates_sampled"), int)
        and artifact.get("structural_scan_candidates_sampled") >= 2
        and isinstance(artifact.get("structural_scan_notes"), list)
        and isinstance(artifact.get("candidate_prefix_limit"), int)
        and 2 <= artifact.get("candidate_prefix_limit") <= 6
        and isinstance(rows, list)
        and len(rows) == artifact.get("candidate_prefix_limit")
        and all(harness_feasibility_candidate_row_ready(row) for row in rows)
        and len({row.get("lead_id") for row in rows}) == len(rows)
        and budget_before == 8
        and isinstance(budget_after, int)
        and 0 <= budget_after <= budget_before
        and budget_used == budget_before - budget_after
        and all(row.get("watch_budget_before") == budget_before for row in rows)
        and all(row.get("watch_budget_after") == budget_after for row in rows)
    )


def harness_world_owner_path(profile: str, world_name: str) -> Path:
    return save_dir_for_profile(profile) / world_name / ".openclaw-harness-owner"


def harness_world_owned_by_run(profile: str, world_name: str, run_dir: Path) -> bool:
    owner_path = harness_world_owner_path(profile, world_name)
    try:
        return owner_path.is_file() and owner_path.read_text(encoding="utf-8") == str(run_dir.resolve())
    except OSError:
        return False


def cleanup_harness_world(profile: str, world_name: str, run_dir: Path) -> Dict[str, Any]:
    """Remove a target only when the product marker proves this run owns it."""
    save_root = save_dir_for_profile(profile)
    world_dir = save_root / world_name
    result: Dict[str, Any] = {
        "world": world_name,
        "path": str(world_dir),
        "status": "absent",
    }
    if not world_dir.exists() and not world_dir.is_symlink():
        return result
    if not harness_world_owned_by_run(profile, world_name, run_dir):
        result["status"] = "skipped_unowned_world"
        return result
    try:
        if world_dir.is_symlink() or world_dir.resolve().parent != save_root.resolve():
            result["status"] = "skipped_unsafe_path"
            return result
        shutil.rmtree(world_dir)
        result["status"] = "removed"
    except OSError as error:
        result["status"] = "remove_failed"
        result["error"] = str(error)
    return result


def load_fixture_manifest(path: Path) -> Dict[str, Any]:
    manifest_path = path / "manifest.json"
    if not manifest_path.exists():
        return {}
    return json.loads(manifest_path.read_text(encoding="utf-8"))


def normalize_fixture_save_transforms(raw_value: Any, *, manifest_path: Path) -> List[Dict[str, Any]]:
    if raw_value in (None, ""):
        return []
    if not isinstance(raw_value, list):
        raise SystemExit(f"Fixture save_transforms must be a list: {manifest_path}")

    transforms: List[Dict[str, Any]] = []
    for index, raw in enumerate(raw_value, start=1):
        if not isinstance(raw, dict):
            raise SystemExit(f"Fixture save_transforms[{index}] must be an object: {manifest_path}")
        kind = str(raw.get("kind", "")).strip().lower()
        player_save = str(raw.get("player_save", "")).strip()

        if kind == "bandit_active_sortie_clock":
            site_id = str(raw.get("site_id", "")).strip()
            active_job_type = str(raw.get("active_job_type", "scout")).strip() or "scout"
            try:
                started_minutes = int(raw.get("active_sortie_started_minutes", 0))
                local_contact_minutes = int(raw.get("active_sortie_local_contact_minutes", started_minutes))
            except (TypeError, ValueError):
                raise SystemExit(
                    f"Fixture save_transforms[{index}] needs integer active sortie minutes in {manifest_path}"
                )
            transforms.append({
                "kind": kind,
                "site_id": site_id,
                "active_job_type": active_job_type,
                "active_sortie_started_minutes": started_minutes,
                "active_sortie_local_contact_minutes": local_contact_minutes,
            })
            continue

        if kind == "bandit_projection_leases":
            npc_ids = sorted({int(value) for value in raw.get("npc_ids", [])})
            if not npc_ids or not str(raw.get("site_id", "")).strip() or not str(raw.get("activity_id", "")).strip():
                raise SystemExit(f"Fixture save_transforms[{index}] needs site_id, activity_id, and npc_ids in {manifest_path}")
            transforms.append({
                "kind": kind,
                "player_save": player_save,
                "site_id": str(raw["site_id"]).strip(),
                "activity_id": str(raw["activity_id"]).strip(),
                "owner": str(raw.get("owner", "local")).strip(),
                "generation": int(raw.get("generation", 1)),
                "handoff_epoch": int(raw.get("handoff_epoch", 1)),
                "last_advanced_minutes": int(raw.get("last_advanced_minutes", 0)),
                "npc_ids": npc_ids,
            })
            continue

        if not player_save:
            raise SystemExit(f"Fixture save_transforms[{index}] needs player_save in {manifest_path}")

        if kind == "remove_inherited_shadow_flavor_producer_global_eocs":
            unexpected_keys = sorted(set(raw) - {"kind", "player_save"})
            if unexpected_keys:
                raise SystemExit(
                    f"Fixture save_transforms[{index}] remove_inherited_shadow_flavor_producer_global_eocs "
                    f"has unexpected keys {unexpected_keys} in {manifest_path}"
                )
            transforms.append({"kind": kind, "player_save": player_save})
            continue

        if kind == "scheduled_global_eoc":
            unexpected_keys = sorted(set(raw) - {"kind", "player_save", "eoc", "offset_seconds"})
            if unexpected_keys:
                raise SystemExit(
                    f"Fixture save_transforms[{index}] scheduled_global_eoc has unexpected keys "
                    f"{unexpected_keys} in {manifest_path}"
                )
            eoc = str(raw.get("eoc", "")).strip()
            if not eoc:
                raise SystemExit(f"Fixture save_transforms[{index}] scheduled_global_eoc needs eoc in {manifest_path}")
            try:
                offset_seconds = int(raw.get("offset_seconds"))
            except (TypeError, ValueError):
                raise SystemExit(
                    f"Fixture save_transforms[{index}] scheduled_global_eoc needs integer offset_seconds "
                    f"in {manifest_path}"
                )
            if offset_seconds <= 0:
                raise SystemExit(
                    f"Fixture save_transforms[{index}] scheduled_global_eoc offset_seconds must be > 0 "
                    f"in {manifest_path}"
                )
            transforms.append({
                "kind": kind,
                "player_save": player_save,
                "eoc": eoc,
                "offset_seconds": offset_seconds,
            })
            continue

        if kind == "player_mutations":
            mutations = normalize_string_list(raw.get("mutations", []))
            if not mutations:
                raise SystemExit(f"Fixture save_transforms[{index}] needs mutations in {manifest_path}")
            transforms.append({
                "kind": kind,
                "player_save": player_save,
                "mutations": mutations,
            })
            continue

        if kind == "player_remove_addiction":
            unexpected_keys = sorted(set(raw) - {
                "kind", "player_save", "addiction_type", "expected_intensity", "expected_sated",
            })
            if unexpected_keys:
                raise SystemExit(
                    f"Fixture save_transforms[{index}] player_remove_addiction has unexpected keys "
                    f"{unexpected_keys} in {manifest_path}"
                )
            addiction_type = str(raw.get("addiction_type", "") or "").strip()
            if not addiction_type:
                raise SystemExit(
                    f"Fixture save_transforms[{index}] player_remove_addiction needs addiction_type in {manifest_path}"
                )
            try:
                expected_intensity = int(raw.get("expected_intensity"))
                expected_sated = int(raw.get("expected_sated"))
            except (TypeError, ValueError):
                raise SystemExit(
                    f"Fixture save_transforms[{index}] player_remove_addiction needs integer "
                    f"expected_intensity/expected_sated in {manifest_path}"
                )
            transforms.append({
                "kind": kind,
                "player_save": player_save,
                "addiction_type": addiction_type,
                "expected_intensity": expected_intensity,
                "expected_sated": expected_sated,
            })
            continue

        if kind == "clear_avatar_auto_move":
            unexpected_keys = sorted(set(raw) - {"kind", "player_save"})
            if unexpected_keys:
                raise SystemExit(
                    f"Fixture save_transforms[{index}] clear_avatar_auto_move has unexpected "
                    f"keys {unexpected_keys} in {manifest_path}"
                )
            transforms.append({"kind": kind, "player_save": player_save})
            continue

        if kind == "player_items":
            storage = str(raw.get("storage", "legacy_top_level_inv")).strip().lower()
            supported_storage = {"legacy_top_level_inv", "live_accessible_worn_pocket", "live_accessible_wielded"}
            if storage not in supported_storage:
                raise SystemExit(
                    f"Fixture save_transforms[{index}] player_items storage must be one of "
                    f"{sorted(supported_storage)} in {manifest_path}"
                )
            items_raw = raw.get("items", [])
